(function(g){g.__QURAN_DATA=g.__QURAN_DATA||{};g.__QURAN_DATA["tamil-026"]={"sura":26,"name_ar":"الشعراء","name_en":"Ash-Shu'ara","verses":227,"source":"https://www.tamililquran.com/tafsiribnkathir.php","count":227,"missing":[],"data":{"1":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=9\" class=\"link\">26:9</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:9 ஐ பார்க்கவும்"},"2":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=9\" class=\"link\">26:9</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:9 ஐ பார்க்கவும்"},"3":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=9\" class=\"link\">26:9</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:9 ஐ பார்க்கவும்"},"4":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=9\" class=\"link\">26:9</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:9 ஐ பார்க்கவும்"},"5":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=9\" class=\"link\">26:9</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:9 ஐ பார்க்கவும்"},"6":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=9\" class=\"link\">26:9</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:9 ஐ பார்க்கவும்"},"7":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=9\" class=\"link\">26:9</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:9 ஐ பார்க்கவும்"},"8":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=9\" class=\"link\">26:9</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:9 ஐ பார்க்கவும்"},"9":{"html":"<strong>சூரா அஷ்ஷுஅரா (கவிஞர்கள்) மக்காவில் அருளப்பட்டது</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾بِسْمِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.<br />\r\n<br />\r\n<strong>குர்ஆனும், நிராகரிப்பாளர்கள் புறக்கணிப்பதும்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾</span> <span class=\"quran-arabic-font text-success\">طسم</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(தா, ஸீன், மீம்.)<br />\r\n<br />\r\nஸூரதுல் பகராவின் விளக்கவுரையின் ஆரம்பத்தில், சில ஸூராக்களின் தொடக்கத்தில் வரும் (முகத்தஆத்) எழுத்துகளைப் பற்றி நாம் விவாதித்துள்ளோம். அல்லாஹ்வின் கூற்று: <span class=\"quran-arabic-font text-success\">﴾تِلْكَ</span> <span class=\"quran-arabic-font text-success\">ءايَاتُ</span> <span class=\"quran-arabic-font text-success\">الْكِتَـبِ</span> <span class=\"quran-arabic-font text-success\">الْمُبِينِ﴿</span><br />\r\n<br />\r\n(இவை தெளிவான வேதத்தின் வசனங்களாகும்.) அதாவது, இவை தெளிவான திருக்குர்ஆனின் வசனங்களாகும். இது சத்தியத்திற்கும் அசத்தியத்திற்கும் இடையிலும், நேர்வழிக்கும் வழிகேட்டிற்கும் இடையிலும் தெளிவுபடுத்தக்கூடிய, ஐயமற்ற வேதமாகும். <span class=\"quran-arabic-font text-success\">﴾لَعَلَّكَ</span> <span class=\"quran-arabic-font text-success\">بَـخِعٌ</span> <span class=\"quran-arabic-font text-success\">نَّفْسَكَ﴿</span><br />\r\n<br />\r\n(நீர் உம்மைக் கொன்றுவிடுவீரோ!) அதாவது, அவர்கள் நேர்வழி பெற வேண்டும் என்ற உமது பேரார்வத்தினாலும், அவர்கள் மீது நீர் கொண்ட கவலையினாலும் உம்மையே நீர் அழித்துக் கொள்வீரோ! <span class=\"quran-arabic-font text-success\">﴾أَلاَّ</span> <span class=\"quran-arabic-font text-success\">يَكُونُواْ</span> <span class=\"quran-arabic-font text-success\">مُؤْمِنِينَ﴿</span><br />\r\n<br />\r\n(அவர்கள் நம்பிக்கை கொள்ளவில்லை என்பதற்காக.) இங்கே அல்லாஹ், தன் மீது நம்பிக்கை கொள்ளாத நிராகரிப்பாளர்கள் குறித்து வருந்தும் தனது தூதருக்கு (ஸல்) ஆறுதல் கூறுகிறான். இது பின்வரும் வசனங்களைப் போன்றதாகும்: <span class=\"quran-arabic-font text-success\">﴾فَلاَ</span> <span class=\"quran-arabic-font text-success\">تَذْهَبْ</span> <span class=\"quran-arabic-font text-success\">نَفْسُكَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">حَسَرَتٍ﴿</span><br />\r\n<br />\r\n(ஆகவே, அவர்களுக்காகக் கவலைப்பட்டு உமது உயிரை மாய்த்துக் கொள்ள வேண்டாம்.) (<a href=\"qurandisp.php?sura=35&ayah=8\" class=\"link\">35:8</a>). <span class=\"quran-arabic-font text-success\">﴾فَلَعَلَّكَ</span> <span class=\"quran-arabic-font text-success\">بَـخِعٌ</span> <span class=\"quran-arabic-font text-success\">نَّفْسَكَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">ءَاثَـرِهِمْ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">لَّمْ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُواْ</span> <span class=\"quran-arabic-font text-success\">بِهَـذَا</span> <span class=\"quran-arabic-font text-success\">الْحَدِيثِ</span> <span class=\"quran-arabic-font text-success\">أَسَفاً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(இந்தச் செய்தியை (குர்ஆனை) அவர்கள் நம்பாவிட்டால், அவர்களின் பின்னே கவலையினால் உம்மை நீரே அழித்துக் கொள்வீரோ!) (<a href=\"qurandisp.php?sura=18&ayah=6\" class=\"link\">18:6</a>). முஜாஹித், இக்ரிமா, கதாதா, அதிய்யா, அத்-தஹ்ஹாக், அல்-ஹசன் மற்றும் பிற அறிஞர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾لَعَلَّكَ</span> <span class=\"quran-arabic-font text-success\">بَـخِعٌ</span> <span class=\"quran-arabic-font text-success\">نَّفْسَكَ﴿</span><br />\r\n<br />\r\n(நீர் உம்மையே அழித்துக் கொள்வீரோ,) என்பதன் பொருள் 'உம்மையே மாய்த்துக் கொள்வீரோ' என்பதாகும். பின்னர் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾إِن</span> <span class=\"quran-arabic-font text-success\">نَّشَأْ</span> <span class=\"quran-arabic-font text-success\">نُنَزِّلْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">السَّمَآءِ</span> <span class=\"quran-arabic-font text-success\">ءَايَةً</span> <span class=\"quran-arabic-font text-success\">فَظَلَّتْ</span> <span class=\"quran-arabic-font text-success\">أَعْنَـقُهُمْ</span> <span class=\"quran-arabic-font text-success\">لَهَا</span> <span class=\"quran-arabic-font text-success\">خَـضِعِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நாம் நாடினால், அவர்கள் மீது வானத்திலிருந்து ஓர் அத்தாட்சியை இறக்குவோம்; அப்பொழுது அதற்குக் கீழ்ப்படிந்து அவர்களின் கழுத்துகள் தாழ்ந்துவிடும்.) இதன் பொருள், 'நாம் நாடியிருந்தால், அவர்களைக் கட்டாயமாக ஈமான் கொள்ளச் செய்யும் ஓர் அத்தாட்சியை இறக்கியிருப்போம். ஆனால், நாம் அவ்வாறு செய்யமாட்டோம். ஏனெனில், ஒருவன் தனது சுய விருப்பத்தின் அடிப்படையிலேயே அன்றி நம்பிக்கை கொள்வதை நாம் விரும்புவதில்லை.' அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَلَوْ</span> <span class=\"quran-arabic-font text-success\">شَآءَ</span> <span class=\"quran-arabic-font text-success\">رَبُّكَ</span> <span class=\"quran-arabic-font text-success\">لآمَنَ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الاٌّرْضِ</span> <span class=\"quran-arabic-font text-success\">كُلُّهُمْ</span> <span class=\"quran-arabic-font text-success\">جَمِيعًا</span> <span class=\"quran-arabic-font text-success\">أَفَأَنتَ</span> <span class=\"quran-arabic-font text-success\">تُكْرِهُ</span> <span class=\"quran-arabic-font text-success\">النَّاسَ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">يَكُونُواْ</span> <span class=\"quran-arabic-font text-success\">مُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(உமது இறைவன் நாடியிருந்தால், பூமியில் உள்ளவர்கள் அனைவரும் ஒன்றாக ஈமான் கொண்டிருப்பார்கள். அப்படியிருக்க, மக்கள் ஈமான் கொள்பவர்களாக மாறும் வரை நீர் அவர்களைக் கட்டாயப்படுத்துவீரா?) (<a href=\"qurandisp.php?sura=10&ayah=99\" class=\"link\">10:99</a>) <span class=\"quran-arabic-font text-success\">﴾وَلَوْ</span> <span class=\"quran-arabic-font text-success\">شَآءَ</span> <span class=\"quran-arabic-font text-success\">رَبُّكَ</span> <span class=\"quran-arabic-font text-success\">لَجَعَلَ</span> <span class=\"quran-arabic-font text-success\">النَّاسَ</span> <span class=\"quran-arabic-font text-success\">أُمَّةً</span> <span class=\"quran-arabic-font text-success\">وَاحِدَةً﴿</span><br />\r\n<br />\r\n(உமது இறைவன் நாடியிருந்தால், நிச்சயமாக மனிதர்களை ஒரே சமுதாயமாக ஆக்கியிருப்பான்...) (<a href=\"qurandisp.php?sura=11&ayah=118\" class=\"link\">11:118</a>). ஆனால் அல்லாஹ்வின் நாட்டம் செயல்பட்டுவிட்டது, அவனது விதி நிறைவேறிவிட்டது. மேலும் அவனது அத்தாட்சிகள் தூதர்களை அனுப்பியதன் மூலமும், அவர்களுக்கு வேதங்களை வஹீயாக (இறைச்செய்தியாக) அருளியதன் மூலமும் மனிதர்களுக்குக் கிடைத்துவிட்டன. பின்னர் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَمَا</span> <span class=\"quran-arabic-font text-success\">يَأْتِيهِم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">ذِكْرٍ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَـنِ</span> <span class=\"quran-arabic-font text-success\">مُحْدَثٍ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">عَنْهُ</span> <span class=\"quran-arabic-font text-success\">مُعْرِضِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அளவற்ற அருளாளனிடமிருந்து புத்தம் புதிய வஹீயாக (இறைச்செய்தியாக) ஒரு நினைவுறுத்தல் அவர்களிடம் வரும்போதெல்லாம், அவர்கள் அதைப் புறக்கணிக்காமல் இருந்ததில்லை.) இதன் பொருள், ஒவ்வொரு முறையும் வானத்திலிருந்து அவர்களுக்கு ஒரு வேதம் அருளப்படும்போது, மக்களில் பெரும்பாலோர் அதைப் புறக்கணிக்கின்றனர். அல்லாஹ் கூறுவது போல: <span class=\"quran-arabic-font text-success\">﴾وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَكْثَرُ</span> <span class=\"quran-arabic-font text-success\">النَّاسِ</span> <span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">حَرَصْتَ</span> <span class=\"quran-arabic-font text-success\">بِمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நீர் எவ்வளவு பேரார்வம் கொண்டாலும் மனிதர்களில் பெரும்பாலோர் நம்பிக்கை கொள்ள மாட்டார்கள்.) (<a href=\"qurandisp.php?sura=12&ayah=103\" class=\"link\">12:103</a>) <span class=\"quran-arabic-font text-success\">﴾يَا</span> <span class=\"quran-arabic-font text-success\">حَسْرَةً</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْعِبَادِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَأْتِيهِمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">رَّسُولٍ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">يَسْتَهْزِءُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அந்த அடியார்களுக்குக் கைசேதமே! அவர்களிடம் எந்தவொரு தூதர் வந்தாலும், அவர்கள் அவரைப் பரிகசிக்காமல் இருந்ததில்லை.) (<a href=\"qurandisp.php?sura=36&ayah=30\" class=\"link\">36:30</a>) <span class=\"quran-arabic-font text-success\">﴾ثُمَّ</span> <span class=\"quran-arabic-font text-success\">أَرْسَلْنَا</span> <span class=\"quran-arabic-font text-success\">رُسُلَنَا</span> <span class=\"quran-arabic-font text-success\">تَتْرَى</span> <span class=\"quran-arabic-font text-success\">كُلَّ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">جَآءَ</span> <span class=\"quran-arabic-font text-success\">أُمَّةً</span> <span class=\"quran-arabic-font text-success\">رَّسُولُهَا</span> <span class=\"quran-arabic-font text-success\">كَذَّبُوهُ﴿</span><br />\r\n<br />\r\n(பின்னர் நாம் நமது தூதர்களை ஒருவருக்குப் பின் ஒருவராகத் தொடர்ச்சியாக அனுப்பினோம். ஒவ்வொரு சமுதாயத்திடமும் அவர்களின் தூதர் வந்தபோதெல்லாம், அவர்கள் அவரைப் பொய்யாக்கினார்கள்...) (<a href=\"qurandisp.php?sura=23&ayah=44\" class=\"link\">23:44</a>). அல்லாஹ் இங்கே கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾فَقَدْ</span> <span class=\"quran-arabic-font text-success\">كَذَّبُواْ</span> <span class=\"quran-arabic-font text-success\">فَسَيَأْتِيهِمْ</span> <span class=\"quran-arabic-font text-success\">أَنبَـؤُا</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">يَسْتَهْزِءُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிச்சயமாக அவர்கள் (சத்தியத்தைப்) பொய்யாக்கினார்கள். ஆகவே, அவர்கள் எதைப் பரிகசித்துக் கொண்டிருந்தார்களோ அதன் செய்திகள் விரைவில் அவர்களுக்கு வந்து சேரும்.) இதன் பொருள், தங்களிடம் வந்த சத்தியத்தை அவர்கள் மறுத்தனர்; எனவே இந்த மறுப்பின் விளைவுகளைப் பற்றிய செய்திகளைச் சற்று காலத்திற்குப் பிறகு அவர்கள் அறிந்து கொள்வார்கள். <span class=\"quran-arabic-font text-success\">﴾وَسَيَعْلَمْ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ظَلَمُواْ</span> <span class=\"quran-arabic-font text-success\">أَىَّ</span> <span class=\"quran-arabic-font text-success\">مُنقَلَبٍ</span> <span class=\"quran-arabic-font text-success\">يَنقَلِبُونَ﴿</span><br />\r\n<br />\r\n(அநீதி இழைத்தவர்கள் தாம் எத்தகைய இடத்திற்குத் திரும்பிச் செல்வோம் என்பதை விரைவில் அறிந்து கொள்வார்கள்.) (<a href=\"qurandisp.php?sura=26&ayah=227\" class=\"link\">26:227</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَوَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَرَوْاْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">الاٌّرْضِ</span> <span class=\"quran-arabic-font text-success\">كَمْ</span> <span class=\"quran-arabic-font text-success\">أَنبَتْنَا</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">زَوْجٍ</span> <span class=\"quran-arabic-font text-success\">كَرِيمٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(பூமியை அவர்கள் பார்க்கவில்லையா? அதில் ஒவ்வொரு சங்கையான (தாவர) ஜோடியிலிருந்தும் நாம் எவ்வளவு முளைக்கச் செய்திருக்கிறோம்?)<br />\r\n<br />\r\nபின்னர், தனது தூதரை (ஸல்) எதிர்க்கத் துணிந்தவர்களுக்கும், தனது வேதத்தை நிராகரிப்பவர்களுக்கும் அல்லாஹ் கூறுகிறான் - அவனே யாவற்றையும் அடக்கி ஆள்பவன், மிகைத்தவன், பேராற்றல் மிக்கவன். அவனே பூமியைப் படைத்து, அதில் ஒவ்வொரு நல்ல வகையான பயிர்களையும், கனிகளையும், கால்நடைகளையும் வளரச் செய்தான். அஷ்-ஷஅபீயிடமிருந்து ஒரு மனிதர் வழியாக சுஃப்யான் அத்-தவ்ரீ அறிவிக்கின்றார்கள்: \"மனிதர்கள் பூமியின் விளைபொருளாவார்கள். எனவே, எவர் சொர்க்கத்தில் நுழைகிறாரோ அவர் நல்லவர் மற்றும் கண்ணியமானவர்; எவர் நரகத்தில் நுழைகிறாரோ அவர் இழிந்தவர் மற்றும் கீழ்த்தரமானவர்.\" <span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">لآيَةً</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">أَكْثَرُهُم</span> <span class=\"quran-arabic-font text-success\">مُّؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிச்சயமாக இதில் ஓர் அத்தாட்சி இருக்கிறது; ஆனால், அவர்களில் பெரும்பாலோர் நம்பிக்கை கொள்பவர்களாக இல்லை.) அதாவது, அனைத்துப் பொருட்களையும் படைத்தவனின் ஆற்றலுக்கு இது ஒரு சான்றாகும். அவன் பூமியை விரித்தான், வானத்தை விதானமாக உயர்த்தினான். இவ்வளவு இருந்தும், மக்களில் பெரும்பாலோர் ஈமான் கொள்வதில்லை; மாறாக அவனையும், அவனது தூதர்களையும், அவனது வேதங்களையும் அவர்கள் மறுக்கிறார்கள். மேலும் அவன் தடை செய்தவற்றைச் செய்வதன் மூலம் அவனது கட்டளைகளை மீறுகிறார்கள். அவனது கூற்று: <span class=\"quran-arabic-font text-success\">﴾وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">رَبَّكَ</span> <span class=\"quran-arabic-font text-success\">لَهُوَ</span> <span class=\"quran-arabic-font text-success\">الْعَزِيزُ﴿</span><br />\r\n<br />\r\n(மேலும் நிச்சயமாக உமது இறைவன், அவனே மிகைத்தவன்;) இதன் பொருள், அவன் அனைத்துப் பொருட்களின் மீதும் பேராற்றல் கொண்டவன், அவற்றை அடக்கி ஆள்பவன். <span class=\"quran-arabic-font text-success\">﴾الرَّحِيمُ﴿</span><br />\r\n<br />\r\n(நிகரற்ற அன்புடையோன்.) இதன் பொருள், அவன் தனது படைப்புகளின் மீது கருணை உள்ளவன். பாவம் செய்பவனைத் தண்டிப்பதற்கு அவன் அவசரப்படுவதில்லை; மாறாக, அவன் தவ்பா (மன்னிப்பு) செய்வதற்கு அவகாசம் அளிக்கிறான். அவன் திருந்தாவிட்டால், அவனை அவன் ஒரு கடுமையான தண்டனையால் பிடிப்பான். அபுல் ஆலியா, கதாதா, அர்-ரபீஃ பின் அனஸ் மற்றும் இப்னு இஸ்ஹாக் ஆகியோர் கூறினார்கள்: \"தனது கட்டளைகளை மீறி, தன்னைத் தவிர மற்றவர்களை வணங்குபவர்களைத் தண்டிப்பதில் அவன் மிகைத்தவன்.\" ஸயீத் பின் ஜுபைர் (ரழி) கூறினார்கள்: \"தன்னிடம் பாவமன்னிப்புக் கோரித் திரும்புபவர்களிடம் அவன் நிகரற்ற கருணையுடையவன்.\"<br />\r\n<br />","text":"சூரா அஷ்ஷுஅரா (கவிஞர்கள்) மக்காவில் அருளப்பட்டது\n\r\n\n\r\n﴾بِسْمِ اللَّهِ الرَّحْمَـنِ الرَّحِيمِ ﴿\n\r\n\n\r\nஅளவற்ற அருளாளனும், நிகரற்ற அன்புடையோனுமாகிய அல்லாஹ்வின் பெயரால்.\n\r\n\n\r\nகுர்ஆனும், நிராகரிப்பாளர்கள் புறக்கணிப்பதும்\n\r\n\n\r\n﴾ طسم ﴿\n\r\n\n\r\n(தா, ஸீன், மீம்.)\n\r\n\n\r\nஸூரதுல் பகராவின் விளக்கவுரையின் ஆரம்பத்தில், சில ஸூராக்களின் தொடக்கத்தில் வரும் (முகத்தஆத்) எழுத்துகளைப் பற்றி நாம் விவாதித்துள்ளோம். அல்லாஹ்வின் கூற்று: ﴾تِلْكَ ءايَاتُ الْكِتَـبِ الْمُبِينِ﴿\n\r\n\n\r\n(இவை தெளிவான வேதத்தின் வசனங்களாகும்.) அதாவது, இவை தெளிவான திருக்குர்ஆனின் வசனங்களாகும். இது சத்தியத்திற்கும் அசத்தியத்திற்கும் இடையிலும், நேர்வழிக்கும் வழிகேட்டிற்கும் இடையிலும் தெளிவுபடுத்தக்கூடிய, ஐயமற்ற வேதமாகும். ﴾لَعَلَّكَ بَـخِعٌ نَّفْسَكَ﴿\n\r\n\n\r\n(நீர் உம்மைக் கொன்றுவிடுவீரோ!) அதாவது, அவர்கள் நேர்வழி பெற வேண்டும் என்ற உமது பேரார்வத்தினாலும், அவர்கள் மீது நீர் கொண்ட கவலையினாலும் உம்மையே நீர் அழித்துக் கொள்வீரோ! ﴾أَلاَّ يَكُونُواْ مُؤْمِنِينَ﴿\n\r\n\n\r\n(அவர்கள் நம்பிக்கை கொள்ளவில்லை என்பதற்காக.) இங்கே அல்லாஹ், தன் மீது நம்பிக்கை கொள்ளாத நிராகரிப்பாளர்கள் குறித்து வருந்தும் தனது தூதருக்கு (ஸல்) ஆறுதல் கூறுகிறான். இது பின்வரும் வசனங்களைப் போன்றதாகும்: ﴾فَلاَ تَذْهَبْ نَفْسُكَ عَلَيْهِمْ حَسَرَتٍ﴿\n\r\n\n\r\n(ஆகவே, அவர்களுக்காகக் கவலைப்பட்டு உமது உயிரை மாய்த்துக் கொள்ள வேண்டாம்.) (35:8). ﴾فَلَعَلَّكَ بَـخِعٌ نَّفْسَكَ عَلَى ءَاثَـرِهِمْ إِن لَّمْ يُؤْمِنُواْ بِهَـذَا الْحَدِيثِ أَسَفاً ﴿\n\r\n\n\r\n(இந்தச் செய்தியை (குர்ஆனை) அவர்கள் நம்பாவிட்டால், அவர்களின் பின்னே கவலையினால் உம்மை நீரே அழித்துக் கொள்வீரோ!) (18:6). முஜாஹித், இக்ரிமா, கதாதா, அதிய்யா, அத்-தஹ்ஹாக், அல்-ஹசன் மற்றும் பிற அறிஞர்கள் கூறினார்கள்: ﴾لَعَلَّكَ بَـخِعٌ نَّفْسَكَ﴿\n\r\n\n\r\n(நீர் உம்மையே அழித்துக் கொள்வீரோ,) என்பதன் பொருள் 'உம்மையே மாய்த்துக் கொள்வீரோ' என்பதாகும். பின்னர் அல்லாஹ் கூறுகிறான்: ﴾إِن نَّشَأْ نُنَزِّلْ عَلَيْهِمْ مِّنَ السَّمَآءِ ءَايَةً فَظَلَّتْ أَعْنَـقُهُمْ لَهَا خَـضِعِينَ ﴿\n\r\n\n\r\n(நாம் நாடினால், அவர்கள் மீது வானத்திலிருந்து ஓர் அத்தாட்சியை இறக்குவோம்; அப்பொழுது அதற்குக் கீழ்ப்படிந்து அவர்களின் கழுத்துகள் தாழ்ந்துவிடும்.) இதன் பொருள், 'நாம் நாடியிருந்தால், அவர்களைக் கட்டாயமாக ஈமான் கொள்ளச் செய்யும் ஓர் அத்தாட்சியை இறக்கியிருப்போம். ஆனால், நாம் அவ்வாறு செய்யமாட்டோம். ஏனெனில், ஒருவன் தனது சுய விருப்பத்தின் அடிப்படையிலேயே அன்றி நம்பிக்கை கொள்வதை நாம் விரும்புவதில்லை.' அல்லாஹ் கூறுகிறான்: ﴾وَلَوْ شَآءَ رَبُّكَ لآمَنَ مَن فِى الاٌّرْضِ كُلُّهُمْ جَمِيعًا أَفَأَنتَ تُكْرِهُ النَّاسَ حَتَّى يَكُونُواْ مُؤْمِنِينَ ﴿\n\r\n\n\r\n(உமது இறைவன் நாடியிருந்தால், பூமியில் உள்ளவர்கள் அனைவரும் ஒன்றாக ஈமான் கொண்டிருப்பார்கள். அப்படியிருக்க, மக்கள் ஈமான் கொள்பவர்களாக மாறும் வரை நீர் அவர்களைக் கட்டாயப்படுத்துவீரா?) (10:99) ﴾وَلَوْ شَآءَ رَبُّكَ لَجَعَلَ النَّاسَ أُمَّةً وَاحِدَةً﴿\n\r\n\n\r\n(உமது இறைவன் நாடியிருந்தால், நிச்சயமாக மனிதர்களை ஒரே சமுதாயமாக ஆக்கியிருப்பான்...) (11:118). ஆனால் அல்லாஹ்வின் நாட்டம் செயல்பட்டுவிட்டது, அவனது விதி நிறைவேறிவிட்டது. மேலும் அவனது அத்தாட்சிகள் தூதர்களை அனுப்பியதன் மூலமும், அவர்களுக்கு வேதங்களை வஹீயாக (இறைச்செய்தியாக) அருளியதன் மூலமும் மனிதர்களுக்குக் கிடைத்துவிட்டன. பின்னர் அல்லாஹ் கூறுகிறான்: ﴾وَمَا يَأْتِيهِم مِّن ذِكْرٍ مِّنَ الرَّحْمَـنِ مُحْدَثٍ إِلاَّ كَانُواْ عَنْهُ مُعْرِضِينَ ﴿\n\r\n\n\r\n(அளவற்ற அருளாளனிடமிருந்து புத்தம் புதிய வஹீயாக (இறைச்செய்தியாக) ஒரு நினைவுறுத்தல் அவர்களிடம் வரும்போதெல்லாம், அவர்கள் அதைப் புறக்கணிக்காமல் இருந்ததில்லை.) இதன் பொருள், ஒவ்வொரு முறையும் வானத்திலிருந்து அவர்களுக்கு ஒரு வேதம் அருளப்படும்போது, மக்களில் பெரும்பாலோர் அதைப் புறக்கணிக்கின்றனர். அல்லாஹ் கூறுவது போல: ﴾وَمَآ أَكْثَرُ النَّاسِ وَلَوْ حَرَصْتَ بِمُؤْمِنِينَ ﴿\n\r\n\n\r\n(நீர் எவ்வளவு பேரார்வம் கொண்டாலும் மனிதர்களில் பெரும்பாலோர் நம்பிக்கை கொள்ள மாட்டார்கள்.) (12:103) ﴾يَا حَسْرَةً عَلَى الْعِبَادِ مَا يَأْتِيهِمْ مِّن رَّسُولٍ إِلاَّ كَانُواْ بِهِ يَسْتَهْزِءُونَ ﴿\n\r\n\n\r\n(அந்த அடியார்களுக்குக் கைசேதமே! அவர்களிடம் எந்தவொரு தூதர் வந்தாலும், அவர்கள் அவரைப் பரிகசிக்காமல் இருந்ததில்லை.) (36:30) ﴾ثُمَّ أَرْسَلْنَا رُسُلَنَا تَتْرَى كُلَّ مَا جَآءَ أُمَّةً رَّسُولُهَا كَذَّبُوهُ﴿\n\r\n\n\r\n(பின்னர் நாம் நமது தூதர்களை ஒருவருக்குப் பின் ஒருவராகத் தொடர்ச்சியாக அனுப்பினோம். ஒவ்வொரு சமுதாயத்திடமும் அவர்களின் தூதர் வந்தபோதெல்லாம், அவர்கள் அவரைப் பொய்யாக்கினார்கள்...) (23:44). அல்லாஹ் இங்கே கூறுகிறான்: ﴾فَقَدْ كَذَّبُواْ فَسَيَأْتِيهِمْ أَنبَـؤُا مَا كَانُواْ بِهِ يَسْتَهْزِءُونَ ﴿\n\r\n\n\r\n(நிச்சயமாக அவர்கள் (சத்தியத்தைப்) பொய்யாக்கினார்கள். ஆகவே, அவர்கள் எதைப் பரிகசித்துக் கொண்டிருந்தார்களோ அதன் செய்திகள் விரைவில் அவர்களுக்கு வந்து சேரும்.) இதன் பொருள், தங்களிடம் வந்த சத்தியத்தை அவர்கள் மறுத்தனர்; எனவே இந்த மறுப்பின் விளைவுகளைப் பற்றிய செய்திகளைச் சற்று காலத்திற்குப் பிறகு அவர்கள் அறிந்து கொள்வார்கள். ﴾وَسَيَعْلَمْ الَّذِينَ ظَلَمُواْ أَىَّ مُنقَلَبٍ يَنقَلِبُونَ﴿\n\r\n\n\r\n(அநீதி இழைத்தவர்கள் தாம் எத்தகைய இடத்திற்குத் திரும்பிச் செல்வோம் என்பதை விரைவில் அறிந்து கொள்வார்கள்.) (26:227).\n\r\n\n\r\n﴾أَوَلَمْ يَرَوْاْ إِلَى الاٌّرْضِ كَمْ أَنبَتْنَا فِيهَا مِن كُلِّ زَوْجٍ كَرِيمٍ ﴿\n\r\n\n\r\n(பூமியை அவர்கள் பார்க்கவில்லையா? அதில் ஒவ்வொரு சங்கையான (தாவர) ஜோடியிலிருந்தும் நாம் எவ்வளவு முளைக்கச் செய்திருக்கிறோம்?)\n\r\n\n\r\nபின்னர், தனது தூதரை (ஸல்) எதிர்க்கத் துணிந்தவர்களுக்கும், தனது வேதத்தை நிராகரிப்பவர்களுக்கும் அல்லாஹ் கூறுகிறான் - அவனே யாவற்றையும் அடக்கி ஆள்பவன், மிகைத்தவன், பேராற்றல் மிக்கவன். அவனே பூமியைப் படைத்து, அதில் ஒவ்வொரு நல்ல வகையான பயிர்களையும், கனிகளையும், கால்நடைகளையும் வளரச் செய்தான். அஷ்-ஷஅபீயிடமிருந்து ஒரு மனிதர் வழியாக சுஃப்யான் அத்-தவ்ரீ அறிவிக்கின்றார்கள்: \"மனிதர்கள் பூமியின் விளைபொருளாவார்கள். எனவே, எவர் சொர்க்கத்தில் நுழைகிறாரோ அவர் நல்லவர் மற்றும் கண்ணியமானவர்; எவர் நரகத்தில் நுழைகிறாரோ அவர் இழிந்தவர் மற்றும் கீழ்த்தரமானவர்.\" ﴾إِنَّ فِى ذَلِكَ لآيَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ ﴿\n\r\n\n\r\n(நிச்சயமாக இதில் ஓர் அத்தாட்சி இருக்கிறது; ஆனால், அவர்களில் பெரும்பாலோர் நம்பிக்கை கொள்பவர்களாக இல்லை.) அதாவது, அனைத்துப் பொருட்களையும் படைத்தவனின் ஆற்றலுக்கு இது ஒரு சான்றாகும். அவன் பூமியை விரித்தான், வானத்தை விதானமாக உயர்த்தினான். இவ்வளவு இருந்தும், மக்களில் பெரும்பாலோர் ஈமான் கொள்வதில்லை; மாறாக அவனையும், அவனது தூதர்களையும், அவனது வேதங்களையும் அவர்கள் மறுக்கிறார்கள். மேலும் அவன் தடை செய்தவற்றைச் செய்வதன் மூலம் அவனது கட்டளைகளை மீறுகிறார்கள். அவனது கூற்று: ﴾وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ﴿\n\r\n\n\r\n(மேலும் நிச்சயமாக உமது இறைவன், அவனே மிகைத்தவன்;) இதன் பொருள், அவன் அனைத்துப் பொருட்களின் மீதும் பேராற்றல் கொண்டவன், அவற்றை அடக்கி ஆள்பவன். ﴾الرَّحِيمُ﴿\n\r\n\n\r\n(நிகரற்ற அன்புடையோன்.) இதன் பொருள், அவன் தனது படைப்புகளின் மீது கருணை உள்ளவன். பாவம் செய்பவனைத் தண்டிப்பதற்கு அவன் அவசரப்படுவதில்லை; மாறாக, அவன் தவ்பா (மன்னிப்பு) செய்வதற்கு அவகாசம் அளிக்கிறான். அவன் திருந்தாவிட்டால், அவனை அவன் ஒரு கடுமையான தண்டனையால் பிடிப்பான். அபுல் ஆலியா, கதாதா, அர்-ரபீஃ பின் அனஸ் மற்றும் இப்னு இஸ்ஹாக் ஆகியோர் கூறினார்கள்: \"தனது கட்டளைகளை மீறி, தன்னைத் தவிர மற்றவர்களை வணங்குபவர்களைத் தண்டிப்பதில் அவன் மிகைத்தவன்.\" ஸயீத் பின் ஜுபைர் (ரழி) கூறினார்கள்: \"தன்னிடம் பாவமன்னிப்புக் கோரித் திரும்புபவர்களிடம் அவன் நிகரற்ற கருணையுடையவன்.\""},"10":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=22\" class=\"link\">26:22</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:22 ஐ பார்க்கவும்"},"11":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=22\" class=\"link\">26:22</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:22 ஐ பார்க்கவும்"},"12":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=22\" class=\"link\">26:22</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:22 ஐ பார்க்கவும்"},"13":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=22\" class=\"link\">26:22</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:22 ஐ பார்க்கவும்"},"14":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=22\" class=\"link\">26:22</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:22 ஐ பார்க்கவும்"},"15":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=22\" class=\"link\">26:22</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:22 ஐ பார்க்கவும்"},"16":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=22\" class=\"link\">26:22</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:22 ஐ பார்க்கவும்"},"17":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=22\" class=\"link\">26:22</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:22 ஐ பார்க்கவும்"},"18":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=22\" class=\"link\">26:22</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:22 ஐ பார்க்கவும்"},"19":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=22\" class=\"link\">26:22</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:22 ஐ பார்க்கவும்"},"20":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=22\" class=\"link\">26:22</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:22 ஐ பார்க்கவும்"},"21":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=22\" class=\"link\">26:22</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:22 ஐ பார்க்கவும்"},"22":{"html":"<strong>மூஸாவுக்கும் ஃபிர்அவ்னுக்கும் இடையில்</strong><br />\r\n<br />\r\nஅல்லாஹ் தனது அடியாரும், இம்ரானின் மகனும், இறைத்தூதருமான மூஸா (அலை) அவர்களுக்கு இட்ட கட்டளையைப் பற்றி இங்கே கூறுகிறான். அல்லாஹ் அவர்களை மலையின் வலது பக்கத்திலிருந்து அழைத்து, அவர்களோடு உரையாடி, அவர்களைத் தேர்ந்தெடுத்து, ஃபிர்அவ்னிடமும் அவனது மக்களிடமும் செல்லுமாறு கட்டளையிட்டான். அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَإِذْ</span> <span class=\"quran-arabic-font text-success\">نَادَى</span> <span class=\"quran-arabic-font text-success\">رَبُّكَ</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span> <span class=\"quran-arabic-font text-success\">أَنِ</span> <span class=\"quran-arabic-font text-success\">ائْتِ</span> <span class=\"quran-arabic-font text-success\">الْقَوْمَ</span> <span class=\"quran-arabic-font text-success\">الظَّالِمِينَ</span> - <span class=\"quran-arabic-font text-success\">قَوْمَ</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنَ</span> <span class=\"quran-arabic-font text-success\">أَلا</span> <span class=\"quran-arabic-font text-success\">يَتَّقُونَ</span> - <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">إِنِّى</span> <span class=\"quran-arabic-font text-success\">أَخَافُ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يُكَذِّبُونِ</span> - <span class=\"quran-arabic-font text-success\">وَيَضِيقُ</span> <span class=\"quran-arabic-font text-success\">صَدْرِى</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يَنطَلِقُ</span> <span class=\"quran-arabic-font text-success\">لِسَانِى</span> <span class=\"quran-arabic-font text-success\">فَأَرْسِلْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">هَارُونَ</span> - <span class=\"quran-arabic-font text-success\">وَلَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَىَّ</span> <span class=\"quran-arabic-font text-success\">ذَنبٌ</span> <span class=\"quran-arabic-font text-success\">فَأَخَافُ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَقْتُلُونِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(உமது இறைவன் மூஸாவை அழைத்து, \"அநீதி இழைக்கும் மக்களிடம் செல்வீராக. ஃபிர்அவ்னின் மக்களிடம் (செல்வீராக); அவர்கள் (அல்லாஹ்வுக்கு) அஞ்சமாட்டார்களா?\" என்று கூறியபோது (நினைவுகூறுவீராக). அவர் கூறினார்: \"என் இறைவனே! நிச்சயமாக அவர்கள் என்னை மறுப்பார்கள் என்று நான் பயப்படுகிறேன். மேலும், எனது நெஞ்சம் நெருக்கடிக்குள்ளாகிறது, எனது நாவும் சரளமாகப் பேசவில்லை. எனவே, ஹாரூனுக்கும் (வஹீயை) அனுப்புவாயாக. மேலும், அவர்கள் என் மீது ஒரு குற்றச்சாட்டையும் வைத்துள்ளனர்; எனவே அவர்கள் என்னைக் கொன்று விடுவார்களோ என்று நான் அஞ்சுகிறேன்.\") எனவே, மூஸா (அலை) அவர்கள் இச்சிரமங்களைத் தமக்கு நீக்கிடுமாறு அல்லாஹ்விடம் வேண்டினார்கள். ஸூரா தாஹாவில் அவர்கள் கூறியதைப் போல:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">اشْرَحْ</span> <span class=\"quran-arabic-font text-success\">لِى</span> <span class=\"quran-arabic-font text-success\">صَدْرِى</span> - <span class=\"quran-arabic-font text-success\">وَيَسِّرْ</span> <span class=\"quran-arabic-font text-success\">لِى</span> <span class=\"quran-arabic-font text-success\">أَمْرِى</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மூஸா (அலை) அவர்கள் கூறினார்கள்: \"என் இறைவனே! எனக்காக எனது நெஞ்சத்தை விரிவாக்கி வைப்பாயாக. எனது காரியத்தை எனக்கு எளிதாக்கி வைப்பாயாக.\") (<a href=\"qurandisp.php?sura=20&ayah=25\" class=\"link\">20:25</a>-26) ...என்று அல்லாஹ் கூறும் வரை:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَدْ</span> <span class=\"quran-arabic-font text-success\">أُوتِيتَ</span> <span class=\"quran-arabic-font text-success\">سُؤْلَكَ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">مُوسَى﴿</span><br />\r\n<br />\r\n(மூஸாவே! உமது வேண்டுகோள் உமக்கு வழங்கப்பட்டுவிட்டது!) (<a href=\"qurandisp.php?sura=20&ayah=36\" class=\"link\">20:36</a>)<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَىَّ</span> <span class=\"quran-arabic-font text-success\">ذَنبٌ</span> <span class=\"quran-arabic-font text-success\">فَأَخَافُ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَقْتُلُونِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும், அவர்கள் என் மீது ஒரு குற்றச்சாட்டையும் வைத்துள்ளனர்; எனவே அவர்கள் என்னைக் கொன்று விடுவார்களோ என்று நான் அஞ்சுகிறேன்.) ஏனெனில், அவர் ஓர் எகிப்தியரைக் கொன்றிருந்தார்; இதுவே அவர் எகிப்து நாட்டை விட்டு வெளியேறியதற்குக் காரணமாக அமைந்தது.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">كَلاَّ﴿</span><br />\r\n<br />\r\n((அதற்கு அல்லாஹ்,) \"அப்படியல்ல!\" என்று கூறினான்.) இதுபோன்ற எதற்கும் பயப்பட வேண்டாம் என்று அல்லாஹ் அவர்களிடம் கூறினான். இது பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾سَنَشُدُّ</span> <span class=\"quran-arabic-font text-success\">عَضُدَكَ</span> <span class=\"quran-arabic-font text-success\">بِأَخِيكَ</span> <span class=\"quran-arabic-font text-success\">وَنَجْعَلُ</span> <span class=\"quran-arabic-font text-success\">لَكُمَا</span> <span class=\"quran-arabic-font text-success\">سُلْطَانًا﴿</span><br />\r\n<br />\r\n(அல்லாஹ் கூறினான்: \"உமது சகோதரரைக் கொண்டு உமது தோளை நாம் பலப்படுத்துவோம்; உங்கள் இருவருக்கும் அதிகாரத்தை வழங்குவோம்.\") அதாவது, அத்தாட்சி (ஆதாரம்);<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَلاَ</span> <span class=\"quran-arabic-font text-success\">يَصِلُونَ</span> <span class=\"quran-arabic-font text-success\">إِلَيْكُمَا</span> <span class=\"quran-arabic-font text-success\">بِآيَاتِنَا</span> <span class=\"quran-arabic-font text-success\">أَنتُمَا</span> <span class=\"quran-arabic-font text-success\">وَمَنِ</span> <span class=\"quran-arabic-font text-success\">اتَّبَعَكُمَا</span> <span class=\"quran-arabic-font text-success\">الْغَالِبُونَ﴿</span><br />\r\n<br />\r\n(\"எனவே, நமது அத்தாட்சிகளைக் கொண்டு அவர்களால் உங்களை நெருங்க முடியாது; நீங்களும் உங்களைப் பின்பற்றுபவர்களுமே வெற்றியாளர்கள்.\") (<a href=\"qurandisp.php?sura=28&ayah=35\" class=\"link\">28:35</a>),<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَاذْهَبَا</span> <span class=\"quran-arabic-font text-success\">بِآيَاتِنَا</span> <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">مَعَكُمْ</span> <span class=\"quran-arabic-font text-success\">مُّسْتَمِعُونَ﴿</span><br />\r\n<br />\r\n(\"நீங்கள் இருவரும் நமது அத்தாட்சிகளுடன் செல்லுங்கள். நிச்சயமாக நாம் உங்களுடன் இருந்து செவியேற்போம்.\") இது பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّنِى</span> <span class=\"quran-arabic-font text-success\">مَعَكُمَآ</span> <span class=\"quran-arabic-font text-success\">أَسْمَعُ</span> <span class=\"quran-arabic-font text-success\">وَأَرَى﴿</span><br />\r\n<br />\r\n(\"நிச்சயமாக நான் உங்கள் இருவருடனும் இருக்கிறேன்; நான் செவியேற்கிறேன், பார்க்கிறேன்.\") (<a href=\"qurandisp.php?sura=20&ayah=46\" class=\"link\">20:46</a>). அதாவது, \"எனது பாதுகாப்பு, பராமரிப்பு, பேராதரவு மற்றும் உதவியுடன் நான் உங்களுடன் இருப்பேன்\" என்று பொருள்.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَأْتِيَا</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنَ</span> <span class=\"quran-arabic-font text-success\">فَقُولا</span> <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">رَسُولُ</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">الْعَـلَمِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(\"எனவே, நீங்கள் இருவரும் ஃபிர்அவ்னிடம் சென்று: 'நிச்சயமாக நாங்கள் அகிலங்களின் இறைவனுடைய தூதராவோம்' என்று கூறுங்கள்.\") இது பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّا</span> <span class=\"quran-arabic-font text-success\">رَسُولاَ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ﴿</span><br />\r\n<br />\r\n(\"நிச்சயமாக நாங்கள் இருவரும் உமது இறைவனுடைய தூதர்கள்.\") (<a href=\"qurandisp.php?sura=20&ayah=47\" class=\"link\">20:47</a>). அதாவது, \"நாங்கள் இருவரும் உன்னிடம் அனுப்பப்பட்டுள்ளோம்\" என்று பொருள்.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَنْ</span> <span class=\"quran-arabic-font text-success\">أَرْسِلْ</span> <span class=\"quran-arabic-font text-success\">مَعَنَا</span> <span class=\"quran-arabic-font text-success\">بَنِى</span> <span class=\"quran-arabic-font text-success\">إِسْرَائِيلَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(\"எனவே, இஸ்ரவேல் சந்ததியினரை எங்களுடன் அனுப்பி விடு.\") அதாவது, \"அவர்களைப் போகவிடு, உனது சிறையிருப்பிலிருந்தும், அடிமைத்தனத்திலிருந்தும், சித்திரவதையிலிருந்தும் அவர்களை விடுவி. ஏனெனில் அவர்கள் அல்லாஹ்வின் மீது நம்பிக்கை கொண்ட அடியார்கள்; அவனுக்கே அர்ப்பணிக்கப்பட்டவர்கள். ஆனால், உன்னிடம் அவர்கள் இழிவான சித்திரவதைக்கு உள்ளாக்கப்படுகிறார்கள்.\" மூஸா (அலை) அவர்கள் இதனை அவனிடம் கூறியபோது, ஃபிர்அவ்ன் அவரை அலட்சியப்படுத்தி, முற்றிலும் புறக்கணித்தான். அவரை இகழ்ச்சியாகவும் தாழ்வாகவும் கருதி இவ்வாறு கூறினான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَلَمْ</span> <span class=\"quran-arabic-font text-success\">نُرَبِّكَ</span> <span class=\"quran-arabic-font text-success\">فِينَا</span> <span class=\"quran-arabic-font text-success\">وَلِيداً﴿</span><br />\r\n<br />\r\n(\"உம்மை ஒரு குழந்தையாக எங்களிடையே நாம் வளர்க்கவில்லையா?\") அதாவது, \"எங்களிடையே, எங்களது இல்லத்தில், எங்களது அரவணைப்பில் உம்மை நாம் வளர்த்தோம்; பல ஆண்டுகளாக உமக்கு உணவளித்து உபகாரங்கள் செய்தோம். ஆனால், அத்தனையையும் மறந்து எங்களது கருணைக்கு நீ இவ்வாறு பதிலளித்தாய்: எங்களது ஆட்களில் ஒருவரைக் கொன்றாய், உமக்குச் செய்த உபகாரங்களை நீ மறுத்துவிட்டாய்.\" எனவே அவன் அவரிடம் கூறினான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَأَنتَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْكَافِرِينَ﴿</span><br />\r\n<br />\r\n(\"மேலும், நீர் நன்றிகெட்டவர்களில் ஒருவராக இருக்கிறீர்.\") அதாவது, செய்த உபகாரங்களை மறுப்பவர்களில் ஒருவராக இருக்கிறார் என்று பொருள். இது இப்னு அப்பாஸ் (ரழி) மற்றும் அப்துர் ரஹ்மான் பின் ஸைத் பின் அஸ்லம் ஆகியோரின் கருத்தாகும்; இப்னு ஜரீர் அவர்களும் இதனையே விரும்பத்தக்க கருத்தாகக் குறிப்பிட்டுள்ளார்.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">فَعَلْتُهَآ</span> <span class=\"quran-arabic-font text-success\">إِذاً﴿</span><br />\r\n<br />\r\n((மூஸா (அலை) அவர்கள்) கூறினார்கள்: \"நான் அதனை அப்போது செய்தேன்...\") அதாவது, அந்த நேரத்தில்,<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَأَنَاْ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الضَّآلِّينَ﴿</span><br />\r\n<br />\r\n(\"அப்போது நான் அறியாதவர்களில் ஒருவனாக இருந்தேன்.\") அதாவது, \"எனக்கு வஹீ (இறைச்செய்தி) அருளப்படுவதற்கு முன்பும், அல்லாஹ் என்னை ஒரு நபியாகத் தேர்ந்தெடுத்து இந்தத் தூதுத்துவத்துடன் அனுப்புவதற்கு முன்பும் நான் அவ்வாறு இருந்தேன்.\"<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَفَرَرْتُ</span> <span class=\"quran-arabic-font text-success\">مِنكُمْ</span> <span class=\"quran-arabic-font text-success\">لَمَّا</span> <span class=\"quran-arabic-font text-success\">خِفْتُكُمْ</span> <span class=\"quran-arabic-font text-success\">فَوَهَبَ</span> <span class=\"quran-arabic-font text-success\">لِى</span> <span class=\"quran-arabic-font text-success\">رَبِّى</span> <span class=\"quran-arabic-font text-success\">حُكْماً</span> <span class=\"quran-arabic-font text-success\">وَجَعَلَنِى</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُرْسَلِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(\"எனவே, நான் உங்களுக்குப் பயந்தபோது உங்களிடமிருந்து தப்பியோடினேன். பின்னர் என் இறைவன் எனக்கு ஞானத்தை (ஹுக்ம்) வழங்கி, என்னைத் தூதர்களில் ஒருவராக ஆக்கினான்.\") அதாவது, \"அந்தப் பழைய நிலை முடிந்துவிட்டது; இப்போது புதிய நிலை ஏற்பட்டுள்ளது. இப்போது அல்லாஹ் என்னை உன்னிடம் அனுப்பியுள்ளான். நீ அவனுக்குக் கீழ்ப்படிந்தால் பாதுகாப்படைவாய்; இல்லையெனில் நீ அழிக்கப்படுவாய்.\" பிறகு மூஸா (அலை) அவர்கள் கூறினார்கள்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَتِلْكَ</span> <span class=\"quran-arabic-font text-success\">نِعْمَةٌ</span> <span class=\"quran-arabic-font text-success\">تَمُنُّهَا</span> <span class=\"quran-arabic-font text-success\">عَلَىَّ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">عَبَّدتَّ</span> <span class=\"quran-arabic-font text-success\">بَنِى</span> <span class=\"quran-arabic-font text-success\">إِسْرَائِيلَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(\"நீர் இஸ்ரவேல் சந்ததியினரை அடிமைப்படுத்தி வைத்திருக்கும் நிலையில், நீர் எனக்குச் செய்ததாகச் சொல்லும் அந்த உபகாரத்தை என் மீது குத்திக்காட்டுகிறீரா?\") அதாவது, \"என்னை வளர்த்ததற்காக நீர் செய்த உபகாரங்கள் எதுவாக இருந்தாலும், இஸ்ரவேல் சந்ததியினரை அடிமைப்படுத்தி, அவர்களைக் கடின உழைப்புக்கு உட்படுத்தியதன் மூலம் நீர் செய்த தீமைக்கு முன்னால் அவை ஒன்றுமில்லை. அவர்களில் ஒரு மனிதருக்கு நீர் செய்த உபகாரத்திற்கும், அவர்கள் அனைவருக்கும் நீர் செய்த தீமைக்கும் இடையில் ஏதாவது ஒப்பீடு உண்டா? என்னைப் பற்றி நீர் குறிப்பிடும் உபகாரமானது, அவர்களுக்கு நீர் செய்துள்ள கொடுமைகளுடன் ஒப்பிடும்போது ஒன்றுமே இல்லை.\"<br />\r\n<br />\r\n<br />\r\n<br />","text":"மூஸாவுக்கும் ஃபிர்அவ்னுக்கும் இடையில்\n\r\n\n\r\nஅல்லாஹ் தனது அடியாரும், இம்ரானின் மகனும், இறைத்தூதருமான மூஸா (அலை) அவர்களுக்கு இட்ட கட்டளையைப் பற்றி இங்கே கூறுகிறான். அல்லாஹ் அவர்களை மலையின் வலது பக்கத்திலிருந்து அழைத்து, அவர்களோடு உரையாடி, அவர்களைத் தேர்ந்தெடுத்து, ஃபிர்அவ்னிடமும் அவனது மக்களிடமும் செல்லுமாறு கட்டளையிட்டான். அல்லாஹ் கூறுகிறான்:\n\r\n﴾وَإِذْ نَادَى رَبُّكَ مُوسَى أَنِ ائْتِ الْقَوْمَ الظَّالِمِينَ - قَوْمَ فِرْعَوْنَ أَلا يَتَّقُونَ - قَالَ رَبِّ إِنِّى أَخَافُ أَن يُكَذِّبُونِ - وَيَضِيقُ صَدْرِى وَلاَ يَنطَلِقُ لِسَانِى فَأَرْسِلْ إِلَى هَارُونَ - وَلَهُمْ عَلَىَّ ذَنبٌ فَأَخَافُ أَن يَقْتُلُونِ ﴿\n\r\n\n\r\n(உமது இறைவன் மூஸாவை அழைத்து, \"அநீதி இழைக்கும் மக்களிடம் செல்வீராக. ஃபிர்அவ்னின் மக்களிடம் (செல்வீராக); அவர்கள் (அல்லாஹ்வுக்கு) அஞ்சமாட்டார்களா?\" என்று கூறியபோது (நினைவுகூறுவீராக). அவர் கூறினார்: \"என் இறைவனே! நிச்சயமாக அவர்கள் என்னை மறுப்பார்கள் என்று நான் பயப்படுகிறேன். மேலும், எனது நெஞ்சம் நெருக்கடிக்குள்ளாகிறது, எனது நாவும் சரளமாகப் பேசவில்லை. எனவே, ஹாரூனுக்கும் (வஹீயை) அனுப்புவாயாக. மேலும், அவர்கள் என் மீது ஒரு குற்றச்சாட்டையும் வைத்துள்ளனர்; எனவே அவர்கள் என்னைக் கொன்று விடுவார்களோ என்று நான் அஞ்சுகிறேன்.\") எனவே, மூஸா (அலை) அவர்கள் இச்சிரமங்களைத் தமக்கு நீக்கிடுமாறு அல்லாஹ்விடம் வேண்டினார்கள். ஸூரா தாஹாவில் அவர்கள் கூறியதைப் போல:\n\r\n﴾قَالَ رَبِّ اشْرَحْ لِى صَدْرِى - وَيَسِّرْ لِى أَمْرِى ﴿\n\r\n\n\r\n(மூஸா (அலை) அவர்கள் கூறினார்கள்: \"என் இறைவனே! எனக்காக எனது நெஞ்சத்தை விரிவாக்கி வைப்பாயாக. எனது காரியத்தை எனக்கு எளிதாக்கி வைப்பாயாக.\") (20:25-26) ...என்று அல்லாஹ் கூறும் வரை:\n\r\n﴾قَدْ أُوتِيتَ سُؤْلَكَ يَا مُوسَى﴿\n\r\n\n\r\n(மூஸாவே! உமது வேண்டுகோள் உமக்கு வழங்கப்பட்டுவிட்டது!) (20:36)\n\r\n﴾وَلَهُمْ عَلَىَّ ذَنبٌ فَأَخَافُ أَن يَقْتُلُونِ ﴿\n\r\n\n\r\n(மேலும், அவர்கள் என் மீது ஒரு குற்றச்சாட்டையும் வைத்துள்ளனர்; எனவே அவர்கள் என்னைக் கொன்று விடுவார்களோ என்று நான் அஞ்சுகிறேன்.) ஏனெனில், அவர் ஓர் எகிப்தியரைக் கொன்றிருந்தார்; இதுவே அவர் எகிப்து நாட்டை விட்டு வெளியேறியதற்குக் காரணமாக அமைந்தது.\n\r\n﴾قَالَ كَلاَّ﴿\n\r\n\n\r\n((அதற்கு அல்லாஹ்,) \"அப்படியல்ல!\" என்று கூறினான்.) இதுபோன்ற எதற்கும் பயப்பட வேண்டாம் என்று அல்லாஹ் அவர்களிடம் கூறினான். இது பின்வரும் வசனத்தைப் போன்றது:\n\r\n﴾سَنَشُدُّ عَضُدَكَ بِأَخِيكَ وَنَجْعَلُ لَكُمَا سُلْطَانًا﴿\n\r\n\n\r\n(அல்லாஹ் கூறினான்: \"உமது சகோதரரைக் கொண்டு உமது தோளை நாம் பலப்படுத்துவோம்; உங்கள் இருவருக்கும் அதிகாரத்தை வழங்குவோம்.\") அதாவது, அத்தாட்சி (ஆதாரம்);\n\r\n﴾فَلاَ يَصِلُونَ إِلَيْكُمَا بِآيَاتِنَا أَنتُمَا وَمَنِ اتَّبَعَكُمَا الْغَالِبُونَ﴿\n\r\n\n\r\n(\"எனவே, நமது அத்தாட்சிகளைக் கொண்டு அவர்களால் உங்களை நெருங்க முடியாது; நீங்களும் உங்களைப் பின்பற்றுபவர்களுமே வெற்றியாளர்கள்.\") (28:35),\n\r\n﴾فَاذْهَبَا بِآيَاتِنَا إِنَّا مَعَكُمْ مُّسْتَمِعُونَ﴿\n\r\n\n\r\n(\"நீங்கள் இருவரும் நமது அத்தாட்சிகளுடன் செல்லுங்கள். நிச்சயமாக நாம் உங்களுடன் இருந்து செவியேற்போம்.\") இது பின்வரும் வசனத்தைப் போன்றது:\n\r\n﴾إِنَّنِى مَعَكُمَآ أَسْمَعُ وَأَرَى﴿\n\r\n\n\r\n(\"நிச்சயமாக நான் உங்கள் இருவருடனும் இருக்கிறேன்; நான் செவியேற்கிறேன், பார்க்கிறேன்.\") (20:46). அதாவது, \"எனது பாதுகாப்பு, பராமரிப்பு, பேராதரவு மற்றும் உதவியுடன் நான் உங்களுடன் இருப்பேன்\" என்று பொருள்.\n\r\n﴾فَأْتِيَا فِرْعَوْنَ فَقُولا إِنَّا رَسُولُ رَبِّ الْعَـلَمِينَ ﴿\n\r\n\n\r\n(\"எனவே, நீங்கள் இருவரும் ஃபிர்அவ்னிடம் சென்று: 'நிச்சயமாக நாங்கள் அகிலங்களின் இறைவனுடைய தூதராவோம்' என்று கூறுங்கள்.\") இது பின்வரும் வசனத்தைப் போன்றது:\n\r\n﴾إِنَّا رَسُولاَ رَبِّكَ﴿\n\r\n\n\r\n(\"நிச்சயமாக நாங்கள் இருவரும் உமது இறைவனுடைய தூதர்கள்.\") (20:47). அதாவது, \"நாங்கள் இருவரும் உன்னிடம் அனுப்பப்பட்டுள்ளோம்\" என்று பொருள்.\n\r\n﴾أَنْ أَرْسِلْ مَعَنَا بَنِى إِسْرَائِيلَ ﴿\n\r\n\n\r\n(\"எனவே, இஸ்ரவேல் சந்ததியினரை எங்களுடன் அனுப்பி விடு.\") அதாவது, \"அவர்களைப் போகவிடு, உனது சிறையிருப்பிலிருந்தும், அடிமைத்தனத்திலிருந்தும், சித்திரவதையிலிருந்தும் அவர்களை விடுவி. ஏனெனில் அவர்கள் அல்லாஹ்வின் மீது நம்பிக்கை கொண்ட அடியார்கள்; அவனுக்கே அர்ப்பணிக்கப்பட்டவர்கள். ஆனால், உன்னிடம் அவர்கள் இழிவான சித்திரவதைக்கு உள்ளாக்கப்படுகிறார்கள்.\" மூஸா (அலை) அவர்கள் இதனை அவனிடம் கூறியபோது, ஃபிர்அவ்ன் அவரை அலட்சியப்படுத்தி, முற்றிலும் புறக்கணித்தான். அவரை இகழ்ச்சியாகவும் தாழ்வாகவும் கருதி இவ்வாறு கூறினான்:\n\r\n﴾أَلَمْ نُرَبِّكَ فِينَا وَلِيداً﴿\n\r\n\n\r\n(\"உம்மை ஒரு குழந்தையாக எங்களிடையே நாம் வளர்க்கவில்லையா?\") அதாவது, \"எங்களிடையே, எங்களது இல்லத்தில், எங்களது அரவணைப்பில் உம்மை நாம் வளர்த்தோம்; பல ஆண்டுகளாக உமக்கு உணவளித்து உபகாரங்கள் செய்தோம். ஆனால், அத்தனையையும் மறந்து எங்களது கருணைக்கு நீ இவ்வாறு பதிலளித்தாய்: எங்களது ஆட்களில் ஒருவரைக் கொன்றாய், உமக்குச் செய்த உபகாரங்களை நீ மறுத்துவிட்டாய்.\" எனவே அவன் அவரிடம் கூறினான்:\n\r\n﴾وَأَنتَ مِنَ الْكَافِرِينَ﴿\n\r\n\n\r\n(\"மேலும், நீர் நன்றிகெட்டவர்களில் ஒருவராக இருக்கிறீர்.\") அதாவது, செய்த உபகாரங்களை மறுப்பவர்களில் ஒருவராக இருக்கிறார் என்று பொருள். இது இப்னு அப்பாஸ் (ரழி) மற்றும் அப்துர் ரஹ்மான் பின் ஸைத் பின் அஸ்லம் ஆகியோரின் கருத்தாகும்; இப்னு ஜரீர் அவர்களும் இதனையே விரும்பத்தக்க கருத்தாகக் குறிப்பிட்டுள்ளார்.\n\r\n﴾قَالَ فَعَلْتُهَآ إِذاً﴿\n\r\n\n\r\n((மூஸா (அலை) அவர்கள்) கூறினார்கள்: \"நான் அதனை அப்போது செய்தேன்...\") அதாவது, அந்த நேரத்தில்,\n\r\n﴾وَأَنَاْ مِنَ الضَّآلِّينَ﴿\n\r\n\n\r\n(\"அப்போது நான் அறியாதவர்களில் ஒருவனாக இருந்தேன்.\") அதாவது, \"எனக்கு வஹீ (இறைச்செய்தி) அருளப்படுவதற்கு முன்பும், அல்லாஹ் என்னை ஒரு நபியாகத் தேர்ந்தெடுத்து இந்தத் தூதுத்துவத்துடன் அனுப்புவதற்கு முன்பும் நான் அவ்வாறு இருந்தேன்.\"\n\r\n﴾فَفَرَرْتُ مِنكُمْ لَمَّا خِفْتُكُمْ فَوَهَبَ لِى رَبِّى حُكْماً وَجَعَلَنِى مِنَ الْمُرْسَلِينَ ﴿\n\r\n\n\r\n(\"எனவே, நான் உங்களுக்குப் பயந்தபோது உங்களிடமிருந்து தப்பியோடினேன். பின்னர் என் இறைவன் எனக்கு ஞானத்தை (ஹுக்ம்) வழங்கி, என்னைத் தூதர்களில் ஒருவராக ஆக்கினான்.\") அதாவது, \"அந்தப் பழைய நிலை முடிந்துவிட்டது; இப்போது புதிய நிலை ஏற்பட்டுள்ளது. இப்போது அல்லாஹ் என்னை உன்னிடம் அனுப்பியுள்ளான். நீ அவனுக்குக் கீழ்ப்படிந்தால் பாதுகாப்படைவாய்; இல்லையெனில் நீ அழிக்கப்படுவாய்.\" பிறகு மூஸா (அலை) அவர்கள் கூறினார்கள்:\n\r\n﴾وَتِلْكَ نِعْمَةٌ تَمُنُّهَا عَلَىَّ أَنْ عَبَّدتَّ بَنِى إِسْرَائِيلَ ﴿\n\r\n\n\r\n(\"நீர் இஸ்ரவேல் சந்ததியினரை அடிமைப்படுத்தி வைத்திருக்கும் நிலையில், நீர் எனக்குச் செய்ததாகச் சொல்லும் அந்த உபகாரத்தை என் மீது குத்திக்காட்டுகிறீரா?\") அதாவது, \"என்னை வளர்த்ததற்காக நீர் செய்த உபகாரங்கள் எதுவாக இருந்தாலும், இஸ்ரவேல் சந்ததியினரை அடிமைப்படுத்தி, அவர்களைக் கடின உழைப்புக்கு உட்படுத்தியதன் மூலம் நீர் செய்த தீமைக்கு முன்னால் அவை ஒன்றுமில்லை. அவர்களில் ஒரு மனிதருக்கு நீர் செய்த உபகாரத்திற்கும், அவர்கள் அனைவருக்கும் நீர் செய்த தீமைக்கும் இடையில் ஏதாவது ஒப்பீடு உண்டா? என்னைப் பற்றி நீர் குறிப்பிடும் உபகாரமானது, அவர்களுக்கு நீர் செய்துள்ள கொடுமைகளுடன் ஒப்பிடும்போது ஒன்றுமே இல்லை.\""},"23":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=28\" class=\"link\">26:28</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:28 ஐ பார்க்கவும்"},"24":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=28\" class=\"link\">26:28</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:28 ஐ பார்க்கவும்"},"25":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=28\" class=\"link\">26:28</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:28 ஐ பார்க்கவும்"},"26":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=28\" class=\"link\">26:28</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:28 ஐ பார்க்கவும்"},"27":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=28\" class=\"link\">26:28</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:28 ஐ பார்க்கவும்"},"28":{"html":"<strong>ஃபிர்அவ்னின் இறைநிராகரிப்பு, எல்லை மீறல், அநீதி மற்றும் உண்மையை மறுத்தல் ஆகியவை குறித்து அல்லாஹ் பின்வருமாறு கூறுகிறான்:</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنُ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">رَبُّ</span> <span class=\"quran-arabic-font text-success\">الْعَـالَمِينَ﴿</span><br />\r\n<br />\r\n(ஃபிர்அவ்ன் கேட்டான்:) \"அகிலங்களின் (ஆலமீன்) இறைவன் என்றால் என்ன?\" காரணம், அவன் தன் மக்களிடம் இவ்வாறு கூறிவந்தான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾مَا</span> <span class=\"quran-arabic-font text-success\">عَلِمْتُ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">إِلَـهٍ</span> <span class=\"quran-arabic-font text-success\">غَيْرِى﴿</span><br />\r\n<br />\r\n\"என்னைத் தவிர உங்களுக்கு வேறு இறைவன் இருப்பதாக நான் அறியவில்லை.\" (<a href=\"qurandisp.php?sura=28&ayah=38\" class=\"link\">28:38</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَاسْتَخَفَّ</span> <span class=\"quran-arabic-font text-success\">قَوْمَهُ</span> <span class=\"quran-arabic-font text-success\">فَأَطَاعُوهُ﴿</span><br />\r\n<br />\r\n\"இவ்வாறு அவன் தன் மக்களை முட்டாளாக்கினான்; அவர்களும் அவனுக்குக் கீழ்ப்படிந்தார்கள்.\" (<a href=\"qurandisp.php?sura=43&ayah=54\" class=\"link\">43:54</a>) அவர்கள் படைப்பாளனை (அவன் தூயவன்) மறுப்பவர்களாக இருந்தார்கள்; ஃபிர்அவ்னைத் தவிர தங்களுக்கு வேறு இறைவன் இல்லை என்று நம்பினார்கள். மூஸா (அலை) அவர்களிடம், \"நான் அகிலங்களின் இறைவனுடைய தூதராவேன்\" என்று கூறியபோது, ஃபிர்அவ்ன் அவரிடம், \"என்னைத் தவிர அகிலங்களின் இறைவன் என்று நீ யாரைக் குறிப்பிடுகிறாய்?\" என்று கேட்டான். முற்கால அறிஞர்களும் (ஸலஃபுகள்), பிற்கால இமாம்களும் இவ்வாறுதான் இதற்கு விளக்கம் அளித்துள்ளனர். அஸ்-ஸுத்தி அவர்கள் கூறினார்கள்: \"இந்த வசனம் பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">فَمَن</span> <span class=\"quran-arabic-font text-success\">رَّبُّكُمَا</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span> - <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">رَبُّنَا</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">أَعْطَى</span> <span class=\"quran-arabic-font text-success\">كُلَّ</span> <span class=\"quran-arabic-font text-success\">شَىءٍ</span> <span class=\"quran-arabic-font text-success\">خَلْقَهُ</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">هَدَى</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n((ஃபிர்அவ்ன்) கேட்டான்: \"மூஸாவே! உங்கள் இருவருடைய இறைவன் யார்?\" மூஸா (அலை) கூறினார்கள்: \"எங்கள் இறைவன் ஒவ்வொரு பொருளுக்கும் அதன் உருவத்தையும் இயல்பையும் வழங்கி, பின்னர் அதற்கு நேர்வழியும் காட்டினான்.\") (<a href=\"qurandisp.php?sura=20&ayah=49\" class=\"link\">20:49</a>-50) இது அல்லாஹ்வின் தன்மையைப் பற்றியோ அல்லது அவனது சாரத்தைப் பற்றியோ கேட்கப்பட்ட கேள்வி என்று கருதும் தத்துவஞானிகளும் பிறரும் தவறாகப் புரிந்து கொண்டுள்ளனர். ஃபிர்அவ்ன் அடிப்படையில் படைப்பாளனை நம்பவே இல்லை; எனவே, படைப்பாளனின் தன்மையைக் குறித்துக் கேட்கும் நிலையில் அவன் இருக்கவில்லை. அவனுக்கு எதிராகப் போதிய ஆதாரங்களும் சான்றுகளும் நிரூபிக்கப்பட்டிருந்த போதும், ஒரு படைப்பாளன் இருப்பதை அவன் முற்றிலுமாக மறுத்தான் என்பதுதான் இதன் பொருளில் இருந்து தெளிவாகிறது. ஆலமீன்களின் இறைவனைப் பற்றி ஃபிர்அவ்ன் கேட்டபோது, மூஸா (அலை) கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">رَبُّ</span> <span class=\"quran-arabic-font text-success\">السَّمَاوَاتِ</span> <span class=\"quran-arabic-font text-success\">وَالْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمَآ﴿</span><br />\r\n<br />\r\n(அதற்கு மூஸா (அலை) கூறினார்கள்:) \"அவன் வானங்கள், பூமி மற்றும் இவற்றுக்கு இடைப்பட்ட அனைத்திற்கும் இறைவனாவான்...\" அதாவது, இவை அனைத்தையும் படைத்தவன், அவற்றின் அதிபதி மற்றும் அவற்றைக் கட்டுப்படுத்துபவன். அவனுக்கு இணையோ துணையோ எவருமில்லை. அவனே அனைத்தையும் படைத்தவன். மேலுலகங்களையும், அவற்றில் உள்ள கோள்கள், நட்சத்திரங்கள் மற்றும் நிலையாகவும் நகர்ந்தும் பிரகாசிக்கக்கூடிய விண்பொருட்களையும் அவன் அறிவான். கீழுலகங்களையும், அவற்றில் உள்ள கடல்கள், கண்டங்கள், மலைகள், மரங்கள், விலங்குகள், செடிகள் மற்றும் கனிகளையும் அவன் அறிவான். இவ்விரு உலகங்களுக்கும் இடைப்பட்ட காற்று, பறவைகள் மற்றும் விண்வெளியில் உள்ள அனைத்தையும் அவன் அறிவான். இவை அனைத்தும் அவனுக்குப் பணிந்தும் அடங்கியும் இருக்கின்றன.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِن</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">مُّوقِنِينَ﴿</span><br />\r\n<br />\r\n(நீங்கள் உறுதியாக நம்புபவர்களாக இருந்தால்.) அதாவது, உங்களுக்கு நம்பிக்கை கொள்ளும் உள்ளங்களும் தெளிவான பார்வையும் இருந்தால் (இதை உணரலாம்). இதைக் கேட்ட ஃபிர்அவ்ன், மூஸா (அலை) அவர்களை ஏளனம் செய்யும் விதமாகத் தன்னைச் சுற்றியிருந்த தன் நாட்டுத் தலைவர்களையும் பிரமுகர்களையும் நோக்கி இவ்வாறு கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَلاَ</span> <span class=\"quran-arabic-font text-success\">تَسْتَمِعُونَ﴿</span><br />\r\n<br />\r\n(\"நீங்கள் செவியுறவில்லையா?\") அதாவது, \"என்னைத் தவிர உங்களுக்கு வேறு ஒரு இறைவன் இருப்பதாக இந்த மனிதன் கூறுவதைக் கேட்டு நீங்கள் வியப்படையவில்லையா?\" என்று கேட்டான். மூஸா (அலை) அவர்கள் தொடர்ந்தார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">رَبُّكُمْ</span> <span class=\"quran-arabic-font text-success\">وَرَبُّ</span> <span class=\"quran-arabic-font text-success\">آبَآئِكُمُ</span> <span class=\"quran-arabic-font text-success\">الْأَوَّلِينَ﴿</span><br />\r\n<br />\r\n\"(அவனே) உங்கள் இறைவனும், உங்களுடைய முன்னோர்களான உங்கள் தந்தைமார்களின் இறைவனுமாவான்!\" அதாவது, உங்களையும் ஃபிர்அவ்னுக்கு முந்தைய காலத்தில் வாழ்ந்த உங்கள் முன்னோர்களையும் படைத்தவன் அவனே.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالَ﴿</span><br />\r\n<br />\r\n(அவன் கூறினான்) அதாவது ஃபிர்அவ்ன் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">رَسُولَكُمُ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">أُرْسِلَ</span> <span class=\"quran-arabic-font text-success\">إِلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">لَمَجْنُونٌ﴿</span><br />\r\n<br />\r\n\"நிச்சயமாக உங்களிடம் அனுப்பப்பட்ட உங்களுடைய இந்தத் தூதர் ஒரு பைத்தியக்காரரே!\" அதாவது, \"என்னைத் தவிர வேறு ஒரு இறைவன் இருக்கிறார் என்று இவர் கூறுவதில் எந்தப் பொருளுமில்லை\" (என்றான்).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالَ﴿</span><br />\r\n<br />\r\n(மூஸா (அலை) அவர்கள்), யாருடைய உள்ளங்களில் ஃபிர்அவ்ன் சந்தேகத்தை விதைக்க முயன்றானோ அவர்களுக்குப் பதில் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">رَبُّ</span> <span class=\"quran-arabic-font text-success\">الْمَشْرِقِ</span> <span class=\"quran-arabic-font text-success\">وَالْمَغْرِبِ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">بَيْنَهُمَآ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">تَعْقِلُونَ﴿</span><br />\r\n<br />\r\n\"அவன் கிழக்கிற்கும் மேற்கிற்கும், அவற்றுக்கிடையே உள்ளவைக்கும் இறைவனாவான். நீங்கள் சிந்தித்துப் புரிந்துகொள்பவர்களாக இருந்தால் (இதை உணர்வீர்கள்)!\" அதாவது, விண்பொருட்கள் உதிக்கும் இடமாகக் கிழக்கையும், அவை மறையும் இடமாக மேற்கையும் அவனே ஆக்கினான். நிலையாகவும் நகர்ந்தும் இருக்கும் அனைத்து விண்பொருட்களையும் அவன் இந்த ஒழுங்கமைப்பிற்கு உட்படுத்தியுள்ளான். ஃபிர்அவ்ன் கூறுவது போல அவனே உங்கள் இறைவனாகவும் கடவுளாகவும் இருந்தால், இந்த அமைப்பை மாற்றி, விண்பொருட்களைக் கிழக்கில் மறையவும் மேற்கில் உதிக்கவும் செய்யட்டும். இது பின்வரும் வசனத்தைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَلَمْ</span> <span class=\"quran-arabic-font text-success\">تَرَ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">حَآجَّ</span> <span class=\"quran-arabic-font text-success\">إِبْرَاهِيمَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">رَبِّهِ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">آتَـهُ</span> <span class=\"quran-arabic-font text-success\">اللَّهُ</span> <span class=\"quran-arabic-font text-success\">الْمُلْكَ</span> <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">إِبْرَاهِيمُ</span> <span class=\"quran-arabic-font text-success\">رَبِّيَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">أُحْيِي</span> <span class=\"quran-arabic-font text-success\">وَيُمِيتُ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">أَنَا</span> <span class=\"quran-arabic-font text-success\">أُحْيِي</span> <span class=\"quran-arabic-font text-success\">وَأُمِيتُ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">إِبْرَاهِيمُ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">يَأْتِى</span> <span class=\"quran-arabic-font text-success\">بِالشَّمْسِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمَشْرِقِ</span> <span class=\"quran-arabic-font text-success\">فَأْتِ</span> <span class=\"quran-arabic-font text-success\">بِهَا</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمَغْرِبِ﴿</span><br />\r\n<br />\r\n(அல்லாஹ் தனக்கு அரச அதிகாரத்தைக் கொடுத்திருந்த காரணத்தினால், இப்ராஹீமிடம் (அலை) அவருடைய இறைவனைப் பற்றித் தர்க்கம் செய்தவனை நீர் பார்த்தீரா? \"என் இறைவன் உயிர் கொடுப்பவனாகவும் மரணிக்கச் செய்பவனாகவும் இருக்கிறான்\" என்று இப்ராஹீம் (அலை) கூறியபோது, \"நானும் உயிர் கொடுக்கிறேன், மரணிக்கச் செய்கிறேன்\" என்று அவன் கூறினான். அதற்கு இப்ராஹீம் (அலை), \"நிச்சயமாக அல்லாஹ் சூரியனைக் கிழக்கில் உதிக்கச் செய்கிறான்; நீ அதை மேற்கில் உதிக்கச் செய்\" என்று கூறினார்.) (<a href=\"qurandisp.php?sura=2&ayah=258\" class=\"link\">2:258</a>) இவ்வாறு விவாதத்தில் ஃபிர்அவ்ன் தோற்கடிக்கப்பட்டபோது, மூஸா (அலை) அவர்களை எதிர்கொள்ளத் தனது அதிகாரத்தையும் பலத்தையும் பயன்படுத்துவதே சரியெனக் கருதினான். எனவே அவன் கூறியதை அல்லாஹ் இவ்வாறு கூறுகிறான்:<br />\r\n<br />","text":"ஃபிர்அவ்னின் இறைநிராகரிப்பு, எல்லை மீறல், அநீதி மற்றும் உண்மையை மறுத்தல் ஆகியவை குறித்து அல்லாஹ் பின்வருமாறு கூறுகிறான்:\n\r\n\n\r\n﴾قَالَ فِرْعَوْنُ وَمَا رَبُّ الْعَـالَمِينَ﴿\n\r\n\n\r\n(ஃபிர்அவ்ன் கேட்டான்:) \"அகிலங்களின் (ஆலமீன்) இறைவன் என்றால் என்ன?\" காரணம், அவன் தன் மக்களிடம் இவ்வாறு கூறிவந்தான்:\n\r\n\n\r\n﴾مَا عَلِمْتُ لَكُمْ مِّنْ إِلَـهٍ غَيْرِى﴿\n\r\n\n\r\n\"என்னைத் தவிர உங்களுக்கு வேறு இறைவன் இருப்பதாக நான் அறியவில்லை.\" (28:38)\n\r\n\n\r\n﴾فَاسْتَخَفَّ قَوْمَهُ فَأَطَاعُوهُ﴿\n\r\n\n\r\n\"இவ்வாறு அவன் தன் மக்களை முட்டாளாக்கினான்; அவர்களும் அவனுக்குக் கீழ்ப்படிந்தார்கள்.\" (43:54) அவர்கள் படைப்பாளனை (அவன் தூயவன்) மறுப்பவர்களாக இருந்தார்கள்; ஃபிர்அவ்னைத் தவிர தங்களுக்கு வேறு இறைவன் இல்லை என்று நம்பினார்கள். மூஸா (அலை) அவர்களிடம், \"நான் அகிலங்களின் இறைவனுடைய தூதராவேன்\" என்று கூறியபோது, ஃபிர்அவ்ன் அவரிடம், \"என்னைத் தவிர அகிலங்களின் இறைவன் என்று நீ யாரைக் குறிப்பிடுகிறாய்?\" என்று கேட்டான். முற்கால அறிஞர்களும் (ஸலஃபுகள்), பிற்கால இமாம்களும் இவ்வாறுதான் இதற்கு விளக்கம் அளித்துள்ளனர். அஸ்-ஸுத்தி அவர்கள் கூறினார்கள்: \"இந்த வசனம் பின்வரும் வசனத்தைப் போன்றது:\n\r\n\n\r\n﴾قَالَ فَمَن رَّبُّكُمَا يَا مُوسَى - قَالَ رَبُّنَا الَّذِى أَعْطَى كُلَّ شَىءٍ خَلْقَهُ ثُمَّ هَدَى ﴿\n\r\n\n\r\n((ஃபிர்அவ்ன்) கேட்டான்: \"மூஸாவே! உங்கள் இருவருடைய இறைவன் யார்?\" மூஸா (அலை) கூறினார்கள்: \"எங்கள் இறைவன் ஒவ்வொரு பொருளுக்கும் அதன் உருவத்தையும் இயல்பையும் வழங்கி, பின்னர் அதற்கு நேர்வழியும் காட்டினான்.\") (20:49-50) இது அல்லாஹ்வின் தன்மையைப் பற்றியோ அல்லது அவனது சாரத்தைப் பற்றியோ கேட்கப்பட்ட கேள்வி என்று கருதும் தத்துவஞானிகளும் பிறரும் தவறாகப் புரிந்து கொண்டுள்ளனர். ஃபிர்அவ்ன் அடிப்படையில் படைப்பாளனை நம்பவே இல்லை; எனவே, படைப்பாளனின் தன்மையைக் குறித்துக் கேட்கும் நிலையில் அவன் இருக்கவில்லை. அவனுக்கு எதிராகப் போதிய ஆதாரங்களும் சான்றுகளும் நிரூபிக்கப்பட்டிருந்த போதும், ஒரு படைப்பாளன் இருப்பதை அவன் முற்றிலுமாக மறுத்தான் என்பதுதான் இதன் பொருளில் இருந்து தெளிவாகிறது. ஆலமீன்களின் இறைவனைப் பற்றி ஃபிர்அவ்ன் கேட்டபோது, மூஸா (அலை) கூறினார்கள்:\n\r\n\n\r\n﴾قَالَ رَبُّ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَآ﴿\n\r\n\n\r\n(அதற்கு மூஸா (அலை) கூறினார்கள்:) \"அவன் வானங்கள், பூமி மற்றும் இவற்றுக்கு இடைப்பட்ட அனைத்திற்கும் இறைவனாவான்...\" அதாவது, இவை அனைத்தையும் படைத்தவன், அவற்றின் அதிபதி மற்றும் அவற்றைக் கட்டுப்படுத்துபவன். அவனுக்கு இணையோ துணையோ எவருமில்லை. அவனே அனைத்தையும் படைத்தவன். மேலுலகங்களையும், அவற்றில் உள்ள கோள்கள், நட்சத்திரங்கள் மற்றும் நிலையாகவும் நகர்ந்தும் பிரகாசிக்கக்கூடிய விண்பொருட்களையும் அவன் அறிவான். கீழுலகங்களையும், அவற்றில் உள்ள கடல்கள், கண்டங்கள், மலைகள், மரங்கள், விலங்குகள், செடிகள் மற்றும் கனிகளையும் அவன் அறிவான். இவ்விரு உலகங்களுக்கும் இடைப்பட்ட காற்று, பறவைகள் மற்றும் விண்வெளியில் உள்ள அனைத்தையும் அவன் அறிவான். இவை அனைத்தும் அவனுக்குப் பணிந்தும் அடங்கியும் இருக்கின்றன.\n\r\n\n\r\n﴾إِن كُنتُمْ مُّوقِنِينَ﴿\n\r\n\n\r\n(நீங்கள் உறுதியாக நம்புபவர்களாக இருந்தால்.) அதாவது, உங்களுக்கு நம்பிக்கை கொள்ளும் உள்ளங்களும் தெளிவான பார்வையும் இருந்தால் (இதை உணரலாம்). இதைக் கேட்ட ஃபிர்அவ்ன், மூஸா (அலை) அவர்களை ஏளனம் செய்யும் விதமாகத் தன்னைச் சுற்றியிருந்த தன் நாட்டுத் தலைவர்களையும் பிரமுகர்களையும் நோக்கி இவ்வாறு கூறினான்:\n\r\n\n\r\n﴾أَلاَ تَسْتَمِعُونَ﴿\n\r\n\n\r\n(\"நீங்கள் செவியுறவில்லையா?\") அதாவது, \"என்னைத் தவிர உங்களுக்கு வேறு ஒரு இறைவன் இருப்பதாக இந்த மனிதன் கூறுவதைக் கேட்டு நீங்கள் வியப்படையவில்லையா?\" என்று கேட்டான். மூஸா (அலை) அவர்கள் தொடர்ந்தார்கள்:\n\r\n\n\r\n﴾قَالَ رَبُّكُمْ وَرَبُّ آبَآئِكُمُ الْأَوَّلِينَ﴿\n\r\n\n\r\n\"(அவனே) உங்கள் இறைவனும், உங்களுடைய முன்னோர்களான உங்கள் தந்தைமார்களின் இறைவனுமாவான்!\" அதாவது, உங்களையும் ஃபிர்அவ்னுக்கு முந்தைய காலத்தில் வாழ்ந்த உங்கள் முன்னோர்களையும் படைத்தவன் அவனே.\n\r\n\n\r\n﴾قَالَ﴿\n\r\n\n\r\n(அவன் கூறினான்) அதாவது ஃபிர்அவ்ன் கூறினான்:\n\r\n\n\r\n﴾إِنَّ رَسُولَكُمُ الَّذِى أُرْسِلَ إِلَيْكُمْ لَمَجْنُونٌ﴿\n\r\n\n\r\n\"நிச்சயமாக உங்களிடம் அனுப்பப்பட்ட உங்களுடைய இந்தத் தூதர் ஒரு பைத்தியக்காரரே!\" அதாவது, \"என்னைத் தவிர வேறு ஒரு இறைவன் இருக்கிறார் என்று இவர் கூறுவதில் எந்தப் பொருளுமில்லை\" (என்றான்).\n\r\n\n\r\n﴾قَالَ﴿\n\r\n\n\r\n(மூஸா (அலை) அவர்கள்), யாருடைய உள்ளங்களில் ஃபிர்அவ்ன் சந்தேகத்தை விதைக்க முயன்றானோ அவர்களுக்குப் பதில் கூறினார்கள்:\n\r\n\n\r\n﴾قَالَ رَبُّ الْمَشْرِقِ وَالْمَغْرِبِ وَمَا بَيْنَهُمَآ إِن كُنتُمْ تَعْقِلُونَ﴿\n\r\n\n\r\n\"அவன் கிழக்கிற்கும் மேற்கிற்கும், அவற்றுக்கிடையே உள்ளவைக்கும் இறைவனாவான். நீங்கள் சிந்தித்துப் புரிந்துகொள்பவர்களாக இருந்தால் (இதை உணர்வீர்கள்)!\" அதாவது, விண்பொருட்கள் உதிக்கும் இடமாகக் கிழக்கையும், அவை மறையும் இடமாக மேற்கையும் அவனே ஆக்கினான். நிலையாகவும் நகர்ந்தும் இருக்கும் அனைத்து விண்பொருட்களையும் அவன் இந்த ஒழுங்கமைப்பிற்கு உட்படுத்தியுள்ளான். ஃபிர்அவ்ன் கூறுவது போல அவனே உங்கள் இறைவனாகவும் கடவுளாகவும் இருந்தால், இந்த அமைப்பை மாற்றி, விண்பொருட்களைக் கிழக்கில் மறையவும் மேற்கில் உதிக்கவும் செய்யட்டும். இது பின்வரும் வசனத்தைப் போன்றதாகும்:\n\r\n\n\r\n﴾أَلَمْ تَرَ إِلَى الَّذِي حَآجَّ إِبْرَاهِيمَ فِي رَبِّهِ أَنْ آتَـهُ اللَّهُ الْمُلْكَ إِذْ قَالَ إِبْرَاهِيمُ رَبِّيَ الَّذِى أُحْيِي وَيُمِيتُ قَالَ أَنَا أُحْيِي وَأُمِيتُ قَالَ إِبْرَاهِيمُ فَإِنَّ اللَّهَ يَأْتِى بِالشَّمْسِ مِنَ الْمَشْرِقِ فَأْتِ بِهَا مِنَ الْمَغْرِبِ﴿\n\r\n\n\r\n(அல்லாஹ் தனக்கு அரச அதிகாரத்தைக் கொடுத்திருந்த காரணத்தினால், இப்ராஹீமிடம் (அலை) அவருடைய இறைவனைப் பற்றித் தர்க்கம் செய்தவனை நீர் பார்த்தீரா? \"என் இறைவன் உயிர் கொடுப்பவனாகவும் மரணிக்கச் செய்பவனாகவும் இருக்கிறான்\" என்று இப்ராஹீம் (அலை) கூறியபோது, \"நானும் உயிர் கொடுக்கிறேன், மரணிக்கச் செய்கிறேன்\" என்று அவன் கூறினான். அதற்கு இப்ராஹீம் (அலை), \"நிச்சயமாக அல்லாஹ் சூரியனைக் கிழக்கில் உதிக்கச் செய்கிறான்; நீ அதை மேற்கில் உதிக்கச் செய்\" என்று கூறினார்.) (2:258) இவ்வாறு விவாதத்தில் ஃபிர்அவ்ன் தோற்கடிக்கப்பட்டபோது, மூஸா (அலை) அவர்களை எதிர்கொள்ளத் தனது அதிகாரத்தையும் பலத்தையும் பயன்படுத்துவதே சரியெனக் கருதினான். எனவே அவன் கூறியதை அல்லாஹ் இவ்வாறு கூறுகிறான்:"},"29":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=37\" class=\"link\">26:37</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:37 ஐ பார்க்கவும்"},"30":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=37\" class=\"link\">26:37</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:37 ஐ பார்க்கவும்"},"31":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=37\" class=\"link\">26:37</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:37 ஐ பார்க்கவும்"},"32":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=37\" class=\"link\">26:37</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:37 ஐ பார்க்கவும்"},"33":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=37\" class=\"link\">26:37</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:37 ஐ பார்க்கவும்"},"34":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=37\" class=\"link\">26:37</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:37 ஐ பார்க்கவும்"},"35":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=37\" class=\"link\">26:37</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:37 ஐ பார்க்கவும்"},"36":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=37\" class=\"link\">26:37</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:37 ஐ பார்க்கவும்"},"37":{"html":"<strong>அறிவுப்பூர்வமான ஆதாரத்திற்குப் பிறகு, ஃபிர்அவ்ன் பலத்தைப் பிரயோகிக்கிறான்</strong><br />\r\n<br />\r\nஃபிர்அவ்னுக்கு எதிராகத் தெளிவான மற்றும் அறிவுப்பூர்வமான ஆதாரங்கள் நிலைநாட்டப்பட்டபோது, இனி விவாதிக்க இடமில்லை என்று கருதிய அவன், மூஸா (அலை) அவர்களுக்கு எதிராகப் பலத்தைப் பிரயோகிக்க முற்பட்டான். எனவே அவன் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾لَئِنِ</span> <span class=\"quran-arabic-font text-success\">اتَّخَذْتَ</span> <span class=\"quran-arabic-font text-success\">إِلَـٰهًا</span> <span class=\"quran-arabic-font text-success\">غَيْرِى</span> <span class=\"quran-arabic-font text-success\">لَأَجْعَلَنَّكَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمَسْجُونِينَ﴿</span><br />\r\n<br />\r\n(\"நீர் என்னையன்றி வேறு ஒரு கடவுளைத் தேர்ந்தெடுத்தால், நிச்சயமாக உம்மைச் சிறைப்பட்டவர்களில் ஒருவராக்குவேன்.\") இதற்கு மூஸா (அலை) அவர்கள் பதிலளித்தார்கள்: <span class=\"quran-arabic-font text-success\">﴾أَوَلَوْ</span> <span class=\"quran-arabic-font text-success\">جِئْتُكَ</span> <span class=\"quran-arabic-font text-success\">بِشَىءٍ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٍ﴿</span><br />\r\n<br />\r\n(\"நான் உம்மிடம் தெளிவான ஆதாரத்தைக் கொண்டு வந்தாலுமா?\") அதாவது, தெளிவான மற்றும் உறுதியான சான்று. <span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">فَأْتِ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كُنتَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الصَّادِقِينَ</span> - <span class=\"quran-arabic-font text-success\">فَأَلْقَى</span> <span class=\"quran-arabic-font text-success\">عَصَاهُ</span> <span class=\"quran-arabic-font text-success\">فَإِذَا</span> <span class=\"quran-arabic-font text-success\">هِىَ</span> <span class=\"quran-arabic-font text-success\">ثُعْبَانٌ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٌ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(ஃபிர்அவ்ன் கூறினான்: \"நீர் உண்மையாளராக இருந்தால், அதைக் கொண்டு வாரும்!\" எனவே அவர் தமது கைத்தடியைப் போட்டார். உடனே அது ஒரு பெரும் பாம்பாகத் தென்பட்டது.) அதாவது அது பிரம்மாண்டமான உடல், பெரிய வாய் மற்றும் பயங்கரமான தோற்றத்துடன் மிகத் தெளிவாகவும் வெளிப்படையாகவும் இருந்தது. <span class=\"quran-arabic-font text-success\">﴾وَنَزَعَ</span> <span class=\"quran-arabic-font text-success\">يَدَهُ﴿</span><br />\r\n<br />\r\n(அவர் தமது கையை வெளியே எடுத்தார்,) அதாவது அவரது சட்டையின் உட்பகுதியிலிருந்து, <span class=\"quran-arabic-font text-success\">﴾فَإِذَا</span> <span class=\"quran-arabic-font text-success\">هِىَ</span> <span class=\"quran-arabic-font text-success\">بَيْضَآءُ</span> <span class=\"quran-arabic-font text-success\">لِلنَّاظِرِينَ﴿</span><br />\r\n<br />\r\n(உடனே அது பார்ப்பவர்களுக்கு வெண்மையாகத் தெரிந்தது!) அது சந்திரனின் ஒரு துண்டைப் போலப் பிரகாசித்தது. ஃபிர்அவ்ன் ஏற்கனவே அழிவுக்குரியவனாக இருந்ததால், அவன் பிடிவாதமாக மறுக்க முற்பட்டு, தன்னைச் சுற்றியிருந்த பிரமுகர்களிடம் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">هَـٰذَا</span> <span class=\"quran-arabic-font text-success\">لَسَاحِرٌ</span> <span class=\"quran-arabic-font text-success\">عَلِيمٌ﴿</span><br />\r\n<br />\r\n(\"நிச்சயமாக இவர் தேர்ந்த ஒரு சூனியக்காரர்.\") அதாவது சூனியம் அல்லது செய்வினையில் ஆழ்ந்த அறிவுடையவர். இது அற்புதம் அல்ல, வெறும் சூனியம்தான் என்று அவர்களை நம்ப வைக்க ஃபிர்அவ்ன் முயன்றான். பிறகு அவன் மூஸா (அலை) அவர்களுக்கு எதிராக அவர்களைத் தூண்டிவிட்டு, அவரை எதிர்க்கவும் நிராகரிக்கவும் செய்யும் நோக்கில் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾يُرِيدُ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يُخْرِجَكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">أَرْضِكُمْ</span> <span class=\"quran-arabic-font text-success\">بِسِحْرِهِ</span> <span class=\"quran-arabic-font text-success\">فَمَاذَا</span> <span class=\"quran-arabic-font text-success\">تَأْمُرُونَ﴿</span><br />\r\n<br />\r\n(\"அவர் தனது சூனியத்தின் மூலம் உங்கள் நாட்டை விட்டு உங்களை வெளியேற்ற விரும்புகிறார்... எனவே நீங்கள் என்ன கட்டளையிடுகிறீர்கள்?\") அதாவது 'இவ்வாறு செய்வதன் மூலம் மக்களின் இதயங்களைக் கவர்ந்து அவர்களைத் தன் பக்கம் ஈர்க்கவும், அதன் மூலம் மக்கள் அவருக்கு ஆதரவாகவும் துணையாகவும் மாறி அவரைப் பின்பற்றவும் அவர் விரும்புகிறார். அதன் மூலம் உங்கள் சொந்த நாட்டிலேயே உங்களைத் தோற்கடித்து, நாட்டை உங்களிடமிருந்து கைப்பற்ற நினைக்கிறார். எனவே, நான் என்ன செய்ய வேண்டும் என்று எனக்கு ஆலோசனை கூறுங்கள்.' <span class=\"quran-arabic-font text-success\">﴾قَالُواْ</span> <span class=\"quran-arabic-font text-success\">أَرْجِهْ</span> <span class=\"quran-arabic-font text-success\">وَأَخَاهُ</span> <span class=\"quran-arabic-font text-success\">وَابْعَثْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْمَدَآئِنِ</span> <span class=\"quran-arabic-font text-success\">حَاشِرِينَ</span> - <span class=\"quran-arabic-font text-success\">يَأْتُوكَ</span> <span class=\"quran-arabic-font text-success\">بِكُلِّ</span> <span class=\"quran-arabic-font text-success\">سَحَّارٍ</span> <span class=\"quran-arabic-font text-success\">عَلِيمٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அவர்கள் கூறினார்கள்: \"அவருக்கும் அவருடைய சகோதரருக்கும் சிறிது அவகாசம் கொடுங்கள்; மேலும் நகரங்களுக்குத் திரட்டுபவர்களை அனுப்புங்கள். அவர்கள் தேர்ந்த சூனியக்காரர்கள் அனைவரையும் உம்மிடம் கொண்டு வருவார்கள்.\") அதாவது 'உமது ராஜ்ஜியத்தின் ஒவ்வொரு நகரத்திலிருந்தும் பகுதியிலிருந்தும் அனைத்துச் சூனியக்காரர்களையும் ஒன்று திரட்டும் வரை இவரையும் இவரது சகோதரரையும் தாமதப்படுத்துங்கள். அவர்கள் இவரை எதிர்கொண்டு, இவர் செய்வதைப் போலவே செய்து காட்டட்டும். அதன் பிறகு நீர் இவரைத் தோற்கடித்து வெற்றியடையலாம்.'<br />\r\n<br />\r\nஃபிர்அவ்ன் அவர்கள் ஆலோசனை கூறியபடியே செய்தான். அல்லாஹ் அவர்களுக்கு இவ்வாறு நிகழ வேண்டும் என்று விதித்திருந்தான். மக்கள் அனைவரும் ஓரிடத்தில் ஒன்று கூடவும், அல்லாஹ்வின் அத்தாட்சிகளும் ஆதாரங்களும் அவர்கள் அனைவருக்கும் முன்னால் ஒரே நாளில் வெளிப்படவும் அவன் இவ்வாறு செய்தான்.<br />\r\n<br />","text":"அறிவுப்பூர்வமான ஆதாரத்திற்குப் பிறகு, ஃபிர்அவ்ன் பலத்தைப் பிரயோகிக்கிறான்\n\r\n\n\r\nஃபிர்அவ்னுக்கு எதிராகத் தெளிவான மற்றும் அறிவுப்பூர்வமான ஆதாரங்கள் நிலைநாட்டப்பட்டபோது, இனி விவாதிக்க இடமில்லை என்று கருதிய அவன், மூஸா (அலை) அவர்களுக்கு எதிராகப் பலத்தைப் பிரயோகிக்க முற்பட்டான். எனவே அவன் கூறினான்: ﴾لَئِنِ اتَّخَذْتَ إِلَـٰهًا غَيْرِى لَأَجْعَلَنَّكَ مِنَ الْمَسْجُونِينَ﴿\n\r\n\n\r\n(\"நீர் என்னையன்றி வேறு ஒரு கடவுளைத் தேர்ந்தெடுத்தால், நிச்சயமாக உம்மைச் சிறைப்பட்டவர்களில் ஒருவராக்குவேன்.\") இதற்கு மூஸா (அலை) அவர்கள் பதிலளித்தார்கள்: ﴾أَوَلَوْ جِئْتُكَ بِشَىءٍ مُّبِينٍ﴿\n\r\n\n\r\n(\"நான் உம்மிடம் தெளிவான ஆதாரத்தைக் கொண்டு வந்தாலுமா?\") அதாவது, தெளிவான மற்றும் உறுதியான சான்று. ﴾قَالَ فَأْتِ بِهِ إِن كُنتَ مِنَ الصَّادِقِينَ - فَأَلْقَى عَصَاهُ فَإِذَا هِىَ ثُعْبَانٌ مُّبِينٌ ﴿\n\r\n\n\r\n(ஃபிர்அவ்ன் கூறினான்: \"நீர் உண்மையாளராக இருந்தால், அதைக் கொண்டு வாரும்!\" எனவே அவர் தமது கைத்தடியைப் போட்டார். உடனே அது ஒரு பெரும் பாம்பாகத் தென்பட்டது.) அதாவது அது பிரம்மாண்டமான உடல், பெரிய வாய் மற்றும் பயங்கரமான தோற்றத்துடன் மிகத் தெளிவாகவும் வெளிப்படையாகவும் இருந்தது. ﴾وَنَزَعَ يَدَهُ﴿\n\r\n\n\r\n(அவர் தமது கையை வெளியே எடுத்தார்,) அதாவது அவரது சட்டையின் உட்பகுதியிலிருந்து, ﴾فَإِذَا هِىَ بَيْضَآءُ لِلنَّاظِرِينَ﴿\n\r\n\n\r\n(உடனே அது பார்ப்பவர்களுக்கு வெண்மையாகத் தெரிந்தது!) அது சந்திரனின் ஒரு துண்டைப் போலப் பிரகாசித்தது. ஃபிர்அவ்ன் ஏற்கனவே அழிவுக்குரியவனாக இருந்ததால், அவன் பிடிவாதமாக மறுக்க முற்பட்டு, தன்னைச் சுற்றியிருந்த பிரமுகர்களிடம் கூறினான்: ﴾إِنَّ هَـٰذَا لَسَاحِرٌ عَلِيمٌ﴿\n\r\n\n\r\n(\"நிச்சயமாக இவர் தேர்ந்த ஒரு சூனியக்காரர்.\") அதாவது சூனியம் அல்லது செய்வினையில் ஆழ்ந்த அறிவுடையவர். இது அற்புதம் அல்ல, வெறும் சூனியம்தான் என்று அவர்களை நம்ப வைக்க ஃபிர்அவ்ன் முயன்றான். பிறகு அவன் மூஸா (அலை) அவர்களுக்கு எதிராக அவர்களைத் தூண்டிவிட்டு, அவரை எதிர்க்கவும் நிராகரிக்கவும் செய்யும் நோக்கில் கூறினான்: ﴾يُرِيدُ أَن يُخْرِجَكُمْ مِّنْ أَرْضِكُمْ بِسِحْرِهِ فَمَاذَا تَأْمُرُونَ﴿\n\r\n\n\r\n(\"அவர் தனது சூனியத்தின் மூலம் உங்கள் நாட்டை விட்டு உங்களை வெளியேற்ற விரும்புகிறார்... எனவே நீங்கள் என்ன கட்டளையிடுகிறீர்கள்?\") அதாவது 'இவ்வாறு செய்வதன் மூலம் மக்களின் இதயங்களைக் கவர்ந்து அவர்களைத் தன் பக்கம் ஈர்க்கவும், அதன் மூலம் மக்கள் அவருக்கு ஆதரவாகவும் துணையாகவும் மாறி அவரைப் பின்பற்றவும் அவர் விரும்புகிறார். அதன் மூலம் உங்கள் சொந்த நாட்டிலேயே உங்களைத் தோற்கடித்து, நாட்டை உங்களிடமிருந்து கைப்பற்ற நினைக்கிறார். எனவே, நான் என்ன செய்ய வேண்டும் என்று எனக்கு ஆலோசனை கூறுங்கள்.' ﴾قَالُواْ أَرْجِهْ وَأَخَاهُ وَابْعَثْ فِى الْمَدَآئِنِ حَاشِرِينَ - يَأْتُوكَ بِكُلِّ سَحَّارٍ عَلِيمٍ ﴿\n\r\n\n\r\n(அவர்கள் கூறினார்கள்: \"அவருக்கும் அவருடைய சகோதரருக்கும் சிறிது அவகாசம் கொடுங்கள்; மேலும் நகரங்களுக்குத் திரட்டுபவர்களை அனுப்புங்கள். அவர்கள் தேர்ந்த சூனியக்காரர்கள் அனைவரையும் உம்மிடம் கொண்டு வருவார்கள்.\") அதாவது 'உமது ராஜ்ஜியத்தின் ஒவ்வொரு நகரத்திலிருந்தும் பகுதியிலிருந்தும் அனைத்துச் சூனியக்காரர்களையும் ஒன்று திரட்டும் வரை இவரையும் இவரது சகோதரரையும் தாமதப்படுத்துங்கள். அவர்கள் இவரை எதிர்கொண்டு, இவர் செய்வதைப் போலவே செய்து காட்டட்டும். அதன் பிறகு நீர் இவரைத் தோற்கடித்து வெற்றியடையலாம்.'\n\r\n\n\r\nஃபிர்அவ்ன் அவர்கள் ஆலோசனை கூறியபடியே செய்தான். அல்லாஹ் அவர்களுக்கு இவ்வாறு நிகழ வேண்டும் என்று விதித்திருந்தான். மக்கள் அனைவரும் ஓரிடத்தில் ஒன்று கூடவும், அல்லாஹ்வின் அத்தாட்சிகளும் ஆதாரங்களும் அவர்கள் அனைவருக்கும் முன்னால் ஒரே நாளில் வெளிப்படவும் அவன் இவ்வாறு செய்தான்."},"38":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=48\" class=\"link\">26:48</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:48 ஐ பார்க்கவும்"},"39":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=48\" class=\"link\">26:48</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:48 ஐ பார்க்கவும்"},"40":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=48\" class=\"link\">26:48</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:48 ஐ பார்க்கவும்"},"41":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=48\" class=\"link\">26:48</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:48 ஐ பார்க்கவும்"},"42":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=48\" class=\"link\">26:48</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:48 ஐ பார்க்கவும்"},"43":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=48\" class=\"link\">26:48</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:48 ஐ பார்க்கவும்"},"44":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=48\" class=\"link\">26:48</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:48 ஐ பார்க்கவும்"},"45":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=48\" class=\"link\">26:48</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:48 ஐ பார்க்கவும்"},"46":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=48\" class=\"link\">26:48</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:48 ஐ பார்க்கவும்"},"47":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=48\" class=\"link\">26:48</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:48 ஐ பார்க்கவும்"},"48":{"html":"<strong>மூஸா (அலை) அவர்களுக்கும் சூனியக்காரர்களுக்கும் இடையில்</strong><br />\r\nமூஸா (அலை) அவர்களுக்கும் எகிப்தியர்களுக்கும் இடையே நடந்த உண்மையான சந்திப்பை ஸூரா அல்-அஃராஃப், ஸூரா தாஹா மற்றும் இந்த அத்தியாயத்திலும் அல்லாஹ் விவரிக்கிறான்.<br />\r\n<br />\r\nஎகிப்தியர்கள் தங்களின் பேச்சுகளால் அல்லாஹ்வின் ஒளியை அணைத்துவிட விரும்பினார்கள். ஆனால், நிராகரிப்பாளர்கள் அதனை வெறுத்த போதிலும், தனது ஒளி மேலோங்க வேண்டும் என்பதில் அல்லாஹ் உறுதியாக இருந்தான். இது இறைநிராகரிப்புக்கும் இறைநம்பிக்கைக்கும் (ஈமான்) இடையிலான போராட்டமாகும்; இவை இரண்டும் மோதிக்கொள்ளும் போதெல்லாம், ஈமான்தான் எப்போதும் வெற்றி பெறும்: <span class=\"quran-arabic-font text-success\">﴾بَلْ</span> <span class=\"quran-arabic-font text-success\">نَقْذِفُ</span> <span class=\"quran-arabic-font text-success\">بِالْحَقِّ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْبَاطِلِ</span> <span class=\"quran-arabic-font text-success\">فَيَدْمَغُهُ</span> <span class=\"quran-arabic-font text-success\">فَإِذَا</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">زَاهِقٌ</span> <span class=\"quran-arabic-font text-success\">وَلَكُمُ</span> <span class=\"quran-arabic-font text-success\">الْوَيْلُ</span> <span class=\"quran-arabic-font text-success\">مِمَّا</span> <span class=\"quran-arabic-font text-success\">تَصِفُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(அப்படியல்ல! நாம் சத்தியத்தைக் கொண்டு அசத்தியத்தின் மீது வீசுகிறோம்; அது அதன் தலையைச் சிதறடித்து விடுகிறது; பிறகு அது அழிந்து போகிறது. நீங்கள் (அல்லாஹ்வுக்குப் பொய்யாகக்) கற்பிப்பவற்றின் காரணமாக உங்களுக்குக் கேடுதான்!) (<a href=\"qurandisp.php?sura=21&ayah=18\" class=\"link\">21:18</a>) <span class=\"quran-arabic-font text-success\">﴾وَقُلْ</span> <span class=\"quran-arabic-font text-success\">جَآءَ</span> <span class=\"quran-arabic-font text-success\">الْحَقُّ</span> <span class=\"quran-arabic-font text-success\">وَزَهَقَ</span> <span class=\"quran-arabic-font text-success\">الْبَاطِلُ﴿</span><br />\r\n(மேலும் கூறுவீராக: \"சத்தியம் வந்துவிட்டது, அசத்தியம் அழிந்துவிட்டது.\") (<a href=\"qurandisp.php?sura=17&ayah=81\" class=\"link\">17:81</a>) எகிப்தின் சூனியக்காரர்கள் மாயவித்தையில் மிகவும் கைதேர்ந்தவர்களாக இருந்தனர். தேசத்தின் அனைத்து மூலைகளிலிருந்தும் அவர்களில் ஒரு பெரும் கூட்டம் திரட்டப்பட்டபோது, மக்களும் அந்நாளில் அங்கே ஒன்று கூடினார்கள். அவர்களின் சரியான எண்ணிக்கையை அல்லாஹ் ஒருவன் மட்டுமே அறிவான். அப்போது மக்களில் சிலர் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾لَعَلَّنَا</span> <span class=\"quran-arabic-font text-success\">نَتَّبِعُ</span> <span class=\"quran-arabic-font text-success\">السَّحَرَةَ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">هُمُ</span> <span class=\"quran-arabic-font text-success\">الْغَالِبِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(சூனியக்காரர்கள் வெற்றி பெற்றால் நாம் அவர்களைப் பின்பற்றலாம்.) அவர்கள், ‘சத்தியம் சூனியக்காரர்களிடம் இருந்தாலும் அல்லது மூஸா (அலை) அவர்களிடம் இருந்தாலும் நாம் சத்தியத்தைப் பின்பற்றுவோம்’ என்று கூறவில்லை; ஏனெனில் மக்கள் தங்கள் மன்னனின் மதத்தையே பின்பற்றுபவர்களாக இருந்தனர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَلَمَّا</span> <span class=\"quran-arabic-font text-success\">جَآءَ</span> <span class=\"quran-arabic-font text-success\">السَّحَرَةُ﴿</span><br />\r\n(சூனியக்காரர்கள் வந்தபோது,) அதாவது, அவர்கள் ஃபிர்அவ்னின் அவையை அடைந்தபோது, அவனுக்காக ஒரு விசேஷ மேடை (பந்தல்) அமைக்கப்பட்டிருந்தது. அங்கே அவன் தனது ஊழியர்கள், ஆதரவாளர்கள், நிர்வாகிகள், மாகாணத் தலைவர்கள் மற்றும் தனது ராஜ்ஜியத்தின் வீரர்களை ஒன்று திரட்டியிருந்தான். சூனியக்காரர்கள் ஃபிர்அவ்னுக்கு முன்னால் நின்று, தாங்கள் திரட்டப்பட்ட இந்த விவகாரத்தில் வெற்றி பெற்றால், தங்களை கண்ணியமாக நடத்தி தனக்கு நெருக்கமானவர்களாக ஆக்கிக் கொள்வாயா என்று அவனிடம் கேட்டார்கள். அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَلَمَّا</span> <span class=\"quran-arabic-font text-success\">جَآءَ</span> <span class=\"quran-arabic-font text-success\">السَّحَرَةُ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">لِفِرْعَوْنَ</span> <span class=\"quran-arabic-font text-success\">أَئِنَّ</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">لَأَجْراً</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كُنَّا</span> <span class=\"quran-arabic-font text-success\">نَحْنُ</span> <span class=\"quran-arabic-font text-success\">الْغَالِبِينَ</span> - <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">نَعَمْ</span> <span class=\"quran-arabic-font text-success\">وَإِنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">إِذاً</span> <span class=\"quran-arabic-font text-success\">لَّمِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُقَرَّبِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(\"நாங்கள் வெற்றியாளர்களாக ஆனால், எங்களுக்கு நிச்சயமாகத் தக்க வெகுமதி உண்டா?\" என்று கேட்டார்கள். அதற்கு அவன், \"ஆம்! நிச்சயமாக அப்போது நீங்கள் எனக்கு மிகவும் நெருக்கமானவர்களாய் இருப்பீர்கள்\" என்று கூறினான்.) அதாவது, 'நீங்கள் கேட்பதை விட அதிகமாகவே உங்களுக்கு வழங்கப்படும்; எனக்கு மிக நெருக்கமானவர்களாகவும், என்னுடன் அமரக்கூடியவர்களாகவும் உங்களை ஆக்குவேன்' என்று கூறினான். பிறகு அவர்கள் தங்கள் இடங்களுக்குச் சென்றனர்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالُواْ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span> <span class=\"quran-arabic-font text-success\">إِمَّآ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">تُلْقِيَ</span> <span class=\"quran-arabic-font text-success\">وَإِمَّآ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">نَّكُونَ</span> <span class=\"quran-arabic-font text-success\">أَوَّلَ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">أَلْقَى</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">أَلْقُواْ﴿</span><br />\r\n(அவர்கள் கூறினார்கள்: \"மூஸாவே! நீர் முதலில் எறிகிறீரா? அல்லது நாங்கள் முதலில் எறியட்டுமா?\" அதற்கு (மூஸா (அலை)) அவர்கள், \"இல்லை, நீங்களே (முதலில்) எறியுங்கள்!\" என்று கூறினார்கள்.) (<a href=\"qurandisp.php?sura=20&ayah=65\" class=\"link\">20:65</a>-66). இங்கே இந்தச் சம்பவம் சுருக்கமாக விவரிக்கப்பட்டுள்ளது. மூஸா (அலை) அவர்கள் சூனியக்காரர்களிடம் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَلْقُواْ</span> <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَنتُمْ</span> <span class=\"quran-arabic-font text-success\">مُّلْقُونَ</span> <span class=\"quran-arabic-font text-success\">فَأَلْقَوْاْ</span> <span class=\"quran-arabic-font text-success\">حِبَالَهُمْ</span> <span class=\"quran-arabic-font text-success\">وَعِصِيَّهُمْ</span> <span class=\"quran-arabic-font text-success\">وَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">بِعِزَّةِ</span> <span class=\"quran-arabic-font text-success\">فِرْعَونَ</span> <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">لَنَحْنُ</span> <span class=\"quran-arabic-font text-success\">الْغَالِبُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(\"நீங்கள் எறிய வேண்டியவற்றை எறியுங்கள்!\" என்று கூறினார்கள். உடனே அவர்கள் தங்கள் கயிறுகளையும் தடிகளையும் எறிந்தார்கள்; \"ஃபிர்அவ்னின் கண்ணியத்தின் மீது ஆணையாக! நிச்சயமாக நாங்களே வெற்றியாளர்கள்\" என்று கூறினார்கள்.) அறிவற்ற பாமர மக்கள் ஏதேனும் காரியத்தைச் செய்யும்போது, 'இது இன்னாரின் புண்ணியத்தால் நடந்தது!' என்று கூறுவதைப் போன்றது இது. ஸூரா அல்-அஃராஃபில் அவர்கள் செய்த வித்தையைப் பற்றி அல்லாஹ் இவ்வாறு குறிப்பிடுகிறான்: <span class=\"quran-arabic-font text-success\">﴾سَحَرُواْ</span> <span class=\"quran-arabic-font text-success\">أَعْيُنَ</span> <span class=\"quran-arabic-font text-success\">النَّاسِ</span> <span class=\"quran-arabic-font text-success\">وَاسْتَرْهَبُوهُمْ</span> <span class=\"quran-arabic-font text-success\">وَجَاءُوا</span> <span class=\"quran-arabic-font text-success\">بِسِحْرٍ</span> <span class=\"quran-arabic-font text-success\">عَظِيمٍ﴿</span><br />\r\n(அவர்கள் மக்களின் கண்களைக் கட்டி, அவர்களைப் பீதியடையச் செய்தார்கள்; ஒரு பெரும் சூனியத்தைக் கொண்டு வந்தார்கள்) (<a href=\"qurandisp.php?sura=7&ayah=116\" class=\"link\">7:116</a>). மேலும் ஸூரா தாஹாவில்: <span class=\"quran-arabic-font text-success\">﴾فَإِذَا</span> <span class=\"quran-arabic-font text-success\">حِبَالُهُمْ</span> <span class=\"quran-arabic-font text-success\">وَعِصِيُّهُمْ</span> <span class=\"quran-arabic-font text-success\">يُخَيَّلُ</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">سِحْرِهِمْ</span> <span class=\"quran-arabic-font text-success\">أَنَّهَا</span> <span class=\"quran-arabic-font text-success\">تَسْعَى﴿</span><br />\r\n(அப்போது அவர்களுடைய கயிறுகளும் தடிகளும், அவர்களுடைய சூனியத்தினால் அவருக்கு ஓடுவது போன்று தோன்றின.) அல்லாஹ் இவ்வாறு கூறும் வரை: <span class=\"quran-arabic-font text-success\">﴾وَلاَ</span> <span class=\"quran-arabic-font text-success\">يُفْلِحُ</span> <span class=\"quran-arabic-font text-success\">السَّاحِرُ</span> <span class=\"quran-arabic-font text-success\">حَيْثُ</span> <span class=\"quran-arabic-font text-success\">أَتَى﴿</span><br />\r\n(சூனியக்காரன் எங்கு வந்தாலும் வெற்றி பெறமாட்டான்) (<a href=\"qurandisp.php?sura=20&ayah=69\" class=\"link\">20:69</a>). மேலும் இங்கே அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَأَلْقَى</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span> <span class=\"quran-arabic-font text-success\">عَصَاهُ</span> <span class=\"quran-arabic-font text-success\">فَإِذَا</span> <span class=\"quran-arabic-font text-success\">هِىَ</span> <span class=\"quran-arabic-font text-success\">تَلْقَفُ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَأْفِكُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(பின்னர் மூஸா (அலை) தனது தடியை எறிந்தார்கள்; உடனே அது அவர்கள் கற்பனையாகக் காட்டியவற்றை எல்லாம் விழுங்கியது!) அது நாலாபுறங்களிலிருந்தும் அவற்றைப் பிடித்து விழுங்கியது, எதனையும் விட்டுவைக்கவில்லை. அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَوَقَعَ</span> <span class=\"quran-arabic-font text-success\">الْحَقُّ</span> <span class=\"quran-arabic-font text-success\">وَبَطَلَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يَعْمَلُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(இவ்வாறு சத்தியம் நிலைபெற்றது; அவர்கள் செய்தவை யாவும் வீணாயின.) என்பது முதல் <span class=\"quran-arabic-font text-success\">﴾رَبِّ</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span> <span class=\"quran-arabic-font text-success\">وَهَارُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n(மூஸா மற்றும் ஹாரூனின் இறைவனுக்கே (நாங்கள் ஈமான் கொள்கிறோம்)) (<a href=\"qurandisp.php?sura=7&ayah=118\" class=\"link\">7:118</a>-122) வரை.<br />\r\n<br />\r\nஇது எவ்வித சாக்குப்போக்கிற்கும் இடமளிக்காத அளவுக்கு உறுதியான ஆதாரங்களை முன்வைத்த ஒரு மிக முக்கியமான நிகழ்வாகும். மூஸா (அலை) அவர்களை வென்றுவிடலாம் என்று நம்பியிருந்த ஃபிர்அவ்னின் ஆதரவாளர்கள் அங்கே தோற்கடிக்கப்பட்டார்கள். அந்தத் தருணத்தில் அவர்கள் மூஸா (அலை) அவர்களை நம்பி, அகிலங்களின் இறைவனான அல்லாஹ்வுக்கு ஸஜ்தாவில் (சிரவணக்கத்தில்) விழுந்தார்கள். அவனே மூஸா (அலை) அவர்களையும் ஹாரூன் (அலை) அவர்களையும் சத்தியத்துடனும் தெளிவான அற்புதத்துடனும் அனுப்பினான். உலகம் அதுவரை கண்டிராத ஒரு மாபெரும் தோல்வியை ஃபிர்அவ்ன் சந்தித்தான். எனினும், தெளிவான சான்றுகள் வந்த பின்னரும் அவன் ஆணவத்துடனும் பிடிவாதத்துடனும் இருந்தான்; அவன் மீது அல்லாஹ், வானவர்கள் மற்றும் மனிதர்கள் அனைவரின் சாபமும் உண்டாகட்டும். அவன் தனது ஆணவத்தினால் பொய்யைப் பரப்பத் தொடங்கினான். அவன் அவர்களை அச்சுறுத்தி இவ்வாறு கூறினான்: <span class=\"quran-arabic-font text-success\">﴾إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَكَبِيرُكُمُ</span> <span class=\"quran-arabic-font text-success\">الَّذِي</span> <span class=\"quran-arabic-font text-success\">عَلَّمَكُمُ</span> <span class=\"quran-arabic-font text-success\">السِّحْرَ﴿</span><br />\r\n(நிச்சயமாக இவன் உங்களுக்குச் சூனியத்தைக் கற்றுக்கொடுத்த உங்கள் தலைவன்) (<a href=\"qurandisp.php?sura=20&ayah=71\" class=\"link\">20:71</a>). <span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">هَذَا</span> <span class=\"quran-arabic-font text-success\">لَمَكْرٌ</span> <span class=\"quran-arabic-font text-success\">مَّكَرْتُمُوهُ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْمَدِينَةِ﴿</span><br />\r\n(நிச்சயமாக இது இந்நகரத்தில் நீங்கள் செய்த சூழ்ச்சியாகும்) (<a href=\"qurandisp.php?sura=7&ayah=123\" class=\"link\">7:123</a>).<br />\r\n<br />","text":"மூஸா (அலை) அவர்களுக்கும் சூனியக்காரர்களுக்கும் இடையில்\n\r\nமூஸா (அலை) அவர்களுக்கும் எகிப்தியர்களுக்கும் இடையே நடந்த உண்மையான சந்திப்பை ஸூரா அல்-அஃராஃப், ஸூரா தாஹா மற்றும் இந்த அத்தியாயத்திலும் அல்லாஹ் விவரிக்கிறான்.\n\r\n\n\r\nஎகிப்தியர்கள் தங்களின் பேச்சுகளால் அல்லாஹ்வின் ஒளியை அணைத்துவிட விரும்பினார்கள். ஆனால், நிராகரிப்பாளர்கள் அதனை வெறுத்த போதிலும், தனது ஒளி மேலோங்க வேண்டும் என்பதில் அல்லாஹ் உறுதியாக இருந்தான். இது இறைநிராகரிப்புக்கும் இறைநம்பிக்கைக்கும் (ஈமான்) இடையிலான போராட்டமாகும்; இவை இரண்டும் மோதிக்கொள்ளும் போதெல்லாம், ஈமான்தான் எப்போதும் வெற்றி பெறும்: ﴾بَلْ نَقْذِفُ بِالْحَقِّ عَلَى الْبَاطِلِ فَيَدْمَغُهُ فَإِذَا هُوَ زَاهِقٌ وَلَكُمُ الْوَيْلُ مِمَّا تَصِفُونَ ﴿\n\r\n(அப்படியல்ல! நாம் சத்தியத்தைக் கொண்டு அசத்தியத்தின் மீது வீசுகிறோம்; அது அதன் தலையைச் சிதறடித்து விடுகிறது; பிறகு அது அழிந்து போகிறது. நீங்கள் (அல்லாஹ்வுக்குப் பொய்யாகக்) கற்பிப்பவற்றின் காரணமாக உங்களுக்குக் கேடுதான்!) (21:18) ﴾وَقُلْ جَآءَ الْحَقُّ وَزَهَقَ الْبَاطِلُ﴿\n\r\n(மேலும் கூறுவீராக: \"சத்தியம் வந்துவிட்டது, அசத்தியம் அழிந்துவிட்டது.\") (17:81) எகிப்தின் சூனியக்காரர்கள் மாயவித்தையில் மிகவும் கைதேர்ந்தவர்களாக இருந்தனர். தேசத்தின் அனைத்து மூலைகளிலிருந்தும் அவர்களில் ஒரு பெரும் கூட்டம் திரட்டப்பட்டபோது, மக்களும் அந்நாளில் அங்கே ஒன்று கூடினார்கள். அவர்களின் சரியான எண்ணிக்கையை அல்லாஹ் ஒருவன் மட்டுமே அறிவான். அப்போது மக்களில் சிலர் கூறினார்கள்: ﴾لَعَلَّنَا نَتَّبِعُ السَّحَرَةَ إِن كَانُواْ هُمُ الْغَالِبِينَ ﴿\n\r\n(சூனியக்காரர்கள் வெற்றி பெற்றால் நாம் அவர்களைப் பின்பற்றலாம்.) அவர்கள், ‘சத்தியம் சூனியக்காரர்களிடம் இருந்தாலும் அல்லது மூஸா (அலை) அவர்களிடம் இருந்தாலும் நாம் சத்தியத்தைப் பின்பற்றுவோம்’ என்று கூறவில்லை; ஏனெனில் மக்கள் தங்கள் மன்னனின் மதத்தையே பின்பற்றுபவர்களாக இருந்தனர்.\n\r\n\n\r\n﴾فَلَمَّا جَآءَ السَّحَرَةُ﴿\n\r\n(சூனியக்காரர்கள் வந்தபோது,) அதாவது, அவர்கள் ஃபிர்அவ்னின் அவையை அடைந்தபோது, அவனுக்காக ஒரு விசேஷ மேடை (பந்தல்) அமைக்கப்பட்டிருந்தது. அங்கே அவன் தனது ஊழியர்கள், ஆதரவாளர்கள், நிர்வாகிகள், மாகாணத் தலைவர்கள் மற்றும் தனது ராஜ்ஜியத்தின் வீரர்களை ஒன்று திரட்டியிருந்தான். சூனியக்காரர்கள் ஃபிர்அவ்னுக்கு முன்னால் நின்று, தாங்கள் திரட்டப்பட்ட இந்த விவகாரத்தில் வெற்றி பெற்றால், தங்களை கண்ணியமாக நடத்தி தனக்கு நெருக்கமானவர்களாக ஆக்கிக் கொள்வாயா என்று அவனிடம் கேட்டார்கள். அவர்கள் கூறினார்கள்:\n\r\n\n\r\n﴾فَلَمَّا جَآءَ السَّحَرَةُ قَالُواْ لِفِرْعَوْنَ أَئِنَّ لَنَا لَأَجْراً إِن كُنَّا نَحْنُ الْغَالِبِينَ - قَالَ نَعَمْ وَإِنَّكُمْ إِذاً لَّمِنَ الْمُقَرَّبِينَ ﴿\n\r\n(\"நாங்கள் வெற்றியாளர்களாக ஆனால், எங்களுக்கு நிச்சயமாகத் தக்க வெகுமதி உண்டா?\" என்று கேட்டார்கள். அதற்கு அவன், \"ஆம்! நிச்சயமாக அப்போது நீங்கள் எனக்கு மிகவும் நெருக்கமானவர்களாய் இருப்பீர்கள்\" என்று கூறினான்.) அதாவது, 'நீங்கள் கேட்பதை விட அதிகமாகவே உங்களுக்கு வழங்கப்படும்; எனக்கு மிக நெருக்கமானவர்களாகவும், என்னுடன் அமரக்கூடியவர்களாகவும் உங்களை ஆக்குவேன்' என்று கூறினான். பிறகு அவர்கள் தங்கள் இடங்களுக்குச் சென்றனர்:\n\r\n\n\r\n﴾قَالُواْ يَا مُوسَى إِمَّآ أَن تُلْقِيَ وَإِمَّآ أَن نَّكُونَ أَوَّلَ مَنْ أَلْقَى قَالَ بَلْ أَلْقُواْ﴿\n\r\n(அவர்கள் கூறினார்கள்: \"மூஸாவே! நீர் முதலில் எறிகிறீரா? அல்லது நாங்கள் முதலில் எறியட்டுமா?\" அதற்கு (மூஸா (அலை)) அவர்கள், \"இல்லை, நீங்களே (முதலில்) எறியுங்கள்!\" என்று கூறினார்கள்.) (20:65-66). இங்கே இந்தச் சம்பவம் சுருக்கமாக விவரிக்கப்பட்டுள்ளது. மூஸா (அலை) அவர்கள் சூனியக்காரர்களிடம் கூறினார்கள்:\n\r\n\n\r\n﴾أَلْقُواْ مَآ أَنتُمْ مُّلْقُونَ فَأَلْقَوْاْ حِبَالَهُمْ وَعِصِيَّهُمْ وَقَالُواْ بِعِزَّةِ فِرْعَونَ إِنَّا لَنَحْنُ الْغَالِبُونَ ﴿\n\r\n(\"நீங்கள் எறிய வேண்டியவற்றை எறியுங்கள்!\" என்று கூறினார்கள். உடனே அவர்கள் தங்கள் கயிறுகளையும் தடிகளையும் எறிந்தார்கள்; \"ஃபிர்அவ்னின் கண்ணியத்தின் மீது ஆணையாக! நிச்சயமாக நாங்களே வெற்றியாளர்கள்\" என்று கூறினார்கள்.) அறிவற்ற பாமர மக்கள் ஏதேனும் காரியத்தைச் செய்யும்போது, 'இது இன்னாரின் புண்ணியத்தால் நடந்தது!' என்று கூறுவதைப் போன்றது இது. ஸூரா அல்-அஃராஃபில் அவர்கள் செய்த வித்தையைப் பற்றி அல்லாஹ் இவ்வாறு குறிப்பிடுகிறான்: ﴾سَحَرُواْ أَعْيُنَ النَّاسِ وَاسْتَرْهَبُوهُمْ وَجَاءُوا بِسِحْرٍ عَظِيمٍ﴿\n\r\n(அவர்கள் மக்களின் கண்களைக் கட்டி, அவர்களைப் பீதியடையச் செய்தார்கள்; ஒரு பெரும் சூனியத்தைக் கொண்டு வந்தார்கள்) (7:116). மேலும் ஸூரா தாஹாவில்: ﴾فَإِذَا حِبَالُهُمْ وَعِصِيُّهُمْ يُخَيَّلُ إِلَيْهِ مِن سِحْرِهِمْ أَنَّهَا تَسْعَى﴿\n\r\n(அப்போது அவர்களுடைய கயிறுகளும் தடிகளும், அவர்களுடைய சூனியத்தினால் அவருக்கு ஓடுவது போன்று தோன்றின.) அல்லாஹ் இவ்வாறு கூறும் வரை: ﴾وَلاَ يُفْلِحُ السَّاحِرُ حَيْثُ أَتَى﴿\n\r\n(சூனியக்காரன் எங்கு வந்தாலும் வெற்றி பெறமாட்டான்) (20:69). மேலும் இங்கே அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾فَأَلْقَى مُوسَى عَصَاهُ فَإِذَا هِىَ تَلْقَفُ مَا يَأْفِكُونَ ﴿\n\r\n(பின்னர் மூஸா (அலை) தனது தடியை எறிந்தார்கள்; உடனே அது அவர்கள் கற்பனையாகக் காட்டியவற்றை எல்லாம் விழுங்கியது!) அது நாலாபுறங்களிலிருந்தும் அவற்றைப் பிடித்து விழுங்கியது, எதனையும் விட்டுவைக்கவில்லை. அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾فَوَقَعَ الْحَقُّ وَبَطَلَ مَا كَانُواْ يَعْمَلُونَ ﴿\n\r\n(இவ்வாறு சத்தியம் நிலைபெற்றது; அவர்கள் செய்தவை யாவும் வீணாயின.) என்பது முதல் ﴾رَبِّ مُوسَى وَهَارُونَ ﴿\n\r\n(மூஸா மற்றும் ஹாரூனின் இறைவனுக்கே (நாங்கள் ஈமான் கொள்கிறோம்)) (7:118-122) வரை.\n\r\n\n\r\nஇது எவ்வித சாக்குப்போக்கிற்கும் இடமளிக்காத அளவுக்கு உறுதியான ஆதாரங்களை முன்வைத்த ஒரு மிக முக்கியமான நிகழ்வாகும். மூஸா (அலை) அவர்களை வென்றுவிடலாம் என்று நம்பியிருந்த ஃபிர்அவ்னின் ஆதரவாளர்கள் அங்கே தோற்கடிக்கப்பட்டார்கள். அந்தத் தருணத்தில் அவர்கள் மூஸா (அலை) அவர்களை நம்பி, அகிலங்களின் இறைவனான அல்லாஹ்வுக்கு ஸஜ்தாவில் (சிரவணக்கத்தில்) விழுந்தார்கள். அவனே மூஸா (அலை) அவர்களையும் ஹாரூன் (அலை) அவர்களையும் சத்தியத்துடனும் தெளிவான அற்புதத்துடனும் அனுப்பினான். உலகம் அதுவரை கண்டிராத ஒரு மாபெரும் தோல்வியை ஃபிர்அவ்ன் சந்தித்தான். எனினும், தெளிவான சான்றுகள் வந்த பின்னரும் அவன் ஆணவத்துடனும் பிடிவாதத்துடனும் இருந்தான்; அவன் மீது அல்லாஹ், வானவர்கள் மற்றும் மனிதர்கள் அனைவரின் சாபமும் உண்டாகட்டும். அவன் தனது ஆணவத்தினால் பொய்யைப் பரப்பத் தொடங்கினான். அவன் அவர்களை அச்சுறுத்தி இவ்வாறு கூறினான்: ﴾إِنَّهُ لَكَبِيرُكُمُ الَّذِي عَلَّمَكُمُ السِّحْرَ﴿\n\r\n(நிச்சயமாக இவன் உங்களுக்குச் சூனியத்தைக் கற்றுக்கொடுத்த உங்கள் தலைவன்) (20:71). ﴾إِنَّ هَذَا لَمَكْرٌ مَّكَرْتُمُوهُ فِى الْمَدِينَةِ﴿\n\r\n(நிச்சயமாக இது இந்நகரத்தில் நீங்கள் செய்த சூழ்ச்சியாகும்) (7:123)."},"49":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=51\" class=\"link\">26:51</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:51 ஐ பார்க்கவும்"},"50":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=51\" class=\"link\">26:51</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:51 ஐ பார்க்கவும்"},"51":{"html":"<strong>ஃபிர்அவ்னுக்கும் சூனியக்காரர்களுக்கும் இடையில்</strong><br />\r\n<br />\r\nஅவன் விடுத்த மிரட்டல்கள் அவர்களின் ஈமானையும் (இறைநம்பிக்கை), அல்லாஹ்விற்கு முற்றிலும் பணிவதையும் அதிகரிக்கவே செய்தன. ஏனெனில், அவர்களுடைய இதயங்களிலிருந்து நிராகரிப்பின் திரை விலக்கப்பட்டு, அவர்களுக்கு உண்மை தெளிவாகத் தெரிந்தது. தங்களுடைய மக்கள் அறியாத ஒரு பேருண்மையை அவர்கள் அறிந்திருந்தார்கள்: மூஸா (அலை) அவர்கள் செய்ததை, அல்லாஹ் அவருக்கு உதவாமல் வேறு எந்த மனிதனாலும் செய்திருக்க முடியாது என்பதும், அது அவர் தனது இறைவனிடமிருந்து கொண்டு வந்த சத்தியத்திற்கு ஓர் அத்தாட்சியாகவும் ஆதாரமாகவும் இருந்தது என்பதுமே அதுவாகும். பிறகு ஃபிர்அவ்ன் அவர்களிடம் கூறினான்: <span class=\"quran-arabic-font text-success\">﴾ءَامَنتُمْ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">قَبْلَ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">ءَاذَنَ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ﴿</span><br />\r\n<br />\r\n(நான் உங்களுக்கு அனுமதி அளிப்பதற்கு முன்பே நீங்கள் அவரை நம்பிவிட்டீர்களா?) அதாவது, ‘நீங்கள் செய்த காரியத்திற்கு என்னிடம் அனுமதி கேட்டிருக்க வேண்டும்; என்னிடம் நீங்கள் ஆலோசிக்கவில்லை. நான் உங்களுக்கு அனுமதி அளித்திருந்தால் நீங்கள் அதைச் செய்திருக்கலாம். நான் அனுமதிக்காத போது நீங்கள் அதைச் செய்திருக்கக் கூடாது; ஏனெனில் நானே ஆட்சியாளன், கீழ்ப்படியப்பட வேண்டியவனும் நானே’ என்று அவன் கூறினான். <span class=\"quran-arabic-font text-success\">﴾إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَكَبِيرُكُمُ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">عَلَّمَكُمُ</span> <span class=\"quran-arabic-font text-success\">السِّحْرَ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, அவர்தான் உங்களுக்குச் சூனியத்தைக் கற்றுக் கொடுத்த உங்கள் தலைவர்!) இது ஒரு பிடிவாதமான பேச்சாகும். இது முற்றிலும் அர்த்தமற்றது என்பதை எவரும் புரிந்துகொள்ள முடியும். ஏனெனில், அவர்கள் மூஸா (அலை) அவர்களை அன்றைய தினத்திற்கு முன்பு சந்தித்ததே இல்லை. அப்படியிருக்க, அவர்களுக்குச் சூனியம் கற்றுக்கொடுத்த அவர்களின் தலைவராக அவர் எப்படி இருக்க முடியும்? பகுத்தறிவுள்ள எந்த ஒரு மனிதனும் இவ்வாறு கூறமாட்டான். <span class=\"quran-arabic-font text-success\">﴾فَلَسَوْفَ</span> <span class=\"quran-arabic-font text-success\">تَعْلَمُونَ</span> <span class=\"quran-arabic-font text-success\">لَأُقَطِّعَنَّ</span> <span class=\"quran-arabic-font text-success\">أَيْدِيَكُمْ</span> <span class=\"quran-arabic-font text-success\">وَأَرْجُلَكُم</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">خِلَافٍ</span> <span class=\"quran-arabic-font text-success\">وَلَأُصَلِّبَنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">أَجْمَعِينَ﴿</span> பிறகு, அவர்களின் கைகளையும் கால்களையும் (மாறு கை மாறு கால்) வெட்டி, அவர்களைச் சிலுவையில் அறைந்துவிடுவதாக ஃபிர்அவ்ன் மிரட்டினான். அதற்கு அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾لاَ</span> <span class=\"quran-arabic-font text-success\">ضَيْرَ﴿</span><br />\r\n<br />\r\n(எந்தப் பாதிப்பும் இல்லை!) அதாவது, ‘எந்தப் பிரச்சினையும் இல்லை, அது எங்களுக்குத் தீங்கு செய்யாது, நாங்கள் அதைப் பற்றிக் கவலைப்படவும் மாட்டோம்’ என்று கூறினார்கள். <span class=\"quran-arabic-font text-success\">﴾إِنَّآ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">رَبِّنَا</span> <span class=\"quran-arabic-font text-success\">مُنقَلِبُونَ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, நாம் நம்முடைய இறைவனிடமே திரும்பச் செல்பவர்கள்.) அதாவது, ‘நம் அனைவரின் மீட்சியும் கண்ணியமிக்க அல்லாஹ்விடமே உள்ளது. நன்மையைச் செய்த எவருடைய நற்கூலியையும் அவன் ஒருபோதும் வீணாக்க மாட்டான். நீங்கள் எங்களுக்குச் செய்திருப்பது அவனுக்குத் தெரியாததல்ல. அதற்கு அவன் எங்களுக்கு முழுமையான நற்கூலியை வழங்குவான்’ என்று அவர்கள் கூறினர். மேலும் அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾إِنَّا</span> <span class=\"quran-arabic-font text-success\">نَطْمَعُ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَغْفِرَ</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">رَبُّنَا</span> <span class=\"quran-arabic-font text-success\">خَطَايَانَا﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, எங்கள் இறைவன் எங்களின் பாவங்களை மன்னிக்க வேண்டும் என்று நாங்கள் பெரிதும் நம்புகிறோம்.) அதாவது, ‘நாங்கள் செய்த பாவங்களையும், எங்களைச் செய்யுமாறு நீங்கள் கட்டாயப்படுத்திய சூனியத்தையும் அவன் மன்னிக்க வேண்டும் என விரும்புகிறோம்.’ <span class=\"quran-arabic-font text-success\">﴾أَن</span> <span class=\"quran-arabic-font text-success\">كُنَّآ</span> <span class=\"quran-arabic-font text-success\">أَوَّلَ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ﴿</span><br />\r\n<br />\r\n(ஏனெனில், நாங்கள் இறைநம்பிக்கையாளர்களில் முதன்மையானவர்களாக இருக்கிறோம்.) அதாவது, எங்களுடைய மக்களான எகிப்தியர்களில் நாங்கள் முதன்முதலில் ஈமான் கொண்ட காரணத்தினால் அல்லாஹ் எங்களை மன்னிக்க வேண்டும் என்று விரும்புகிறோம். பிறகு, அவன் அவர்கள் அனைவரையும் கொன்றான். இப்னு அப்பாஸ் (ரலி) உள்ளிட்ட பலர் கூறினார்கள்: “அவர்கள் காலையில் சூனியக்காரர்களாக இருந்தார்கள்; மாலையில் (உயிர் தியாகம் செய்த) ஷஹீதுகளாக ஆகிவிட்டார்கள்.”<br />\r\n<br />","text":"ஃபிர்அவ்னுக்கும் சூனியக்காரர்களுக்கும் இடையில்\n\r\n\n\r\nஅவன் விடுத்த மிரட்டல்கள் அவர்களின் ஈமானையும் (இறைநம்பிக்கை), அல்லாஹ்விற்கு முற்றிலும் பணிவதையும் அதிகரிக்கவே செய்தன. ஏனெனில், அவர்களுடைய இதயங்களிலிருந்து நிராகரிப்பின் திரை விலக்கப்பட்டு, அவர்களுக்கு உண்மை தெளிவாகத் தெரிந்தது. தங்களுடைய மக்கள் அறியாத ஒரு பேருண்மையை அவர்கள் அறிந்திருந்தார்கள்: மூஸா (அலை) அவர்கள் செய்ததை, அல்லாஹ் அவருக்கு உதவாமல் வேறு எந்த மனிதனாலும் செய்திருக்க முடியாது என்பதும், அது அவர் தனது இறைவனிடமிருந்து கொண்டு வந்த சத்தியத்திற்கு ஓர் அத்தாட்சியாகவும் ஆதாரமாகவும் இருந்தது என்பதுமே அதுவாகும். பிறகு ஃபிர்அவ்ன் அவர்களிடம் கூறினான்: ﴾ءَامَنتُمْ لَهُ قَبْلَ أَنْ ءَاذَنَ لَكُمْ﴿\n\r\n\n\r\n(நான் உங்களுக்கு அனுமதி அளிப்பதற்கு முன்பே நீங்கள் அவரை நம்பிவிட்டீர்களா?) அதாவது, ‘நீங்கள் செய்த காரியத்திற்கு என்னிடம் அனுமதி கேட்டிருக்க வேண்டும்; என்னிடம் நீங்கள் ஆலோசிக்கவில்லை. நான் உங்களுக்கு அனுமதி அளித்திருந்தால் நீங்கள் அதைச் செய்திருக்கலாம். நான் அனுமதிக்காத போது நீங்கள் அதைச் செய்திருக்கக் கூடாது; ஏனெனில் நானே ஆட்சியாளன், கீழ்ப்படியப்பட வேண்டியவனும் நானே’ என்று அவன் கூறினான். ﴾إِنَّهُ لَكَبِيرُكُمُ الَّذِى عَلَّمَكُمُ السِّحْرَ﴿\n\r\n\n\r\n(நிச்சயமாக, அவர்தான் உங்களுக்குச் சூனியத்தைக் கற்றுக் கொடுத்த உங்கள் தலைவர்!) இது ஒரு பிடிவாதமான பேச்சாகும். இது முற்றிலும் அர்த்தமற்றது என்பதை எவரும் புரிந்துகொள்ள முடியும். ஏனெனில், அவர்கள் மூஸா (அலை) அவர்களை அன்றைய தினத்திற்கு முன்பு சந்தித்ததே இல்லை. அப்படியிருக்க, அவர்களுக்குச் சூனியம் கற்றுக்கொடுத்த அவர்களின் தலைவராக அவர் எப்படி இருக்க முடியும்? பகுத்தறிவுள்ள எந்த ஒரு மனிதனும் இவ்வாறு கூறமாட்டான். ﴾فَلَسَوْفَ تَعْلَمُونَ لَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَافٍ وَلَأُصَلِّبَنَّكُمْ أَجْمَعِينَ﴿ பிறகு, அவர்களின் கைகளையும் கால்களையும் (மாறு கை மாறு கால்) வெட்டி, அவர்களைச் சிலுவையில் அறைந்துவிடுவதாக ஃபிர்அவ்ன் மிரட்டினான். அதற்கு அவர்கள் கூறினார்கள்: ﴾لاَ ضَيْرَ﴿\n\r\n\n\r\n(எந்தப் பாதிப்பும் இல்லை!) அதாவது, ‘எந்தப் பிரச்சினையும் இல்லை, அது எங்களுக்குத் தீங்கு செய்யாது, நாங்கள் அதைப் பற்றிக் கவலைப்படவும் மாட்டோம்’ என்று கூறினார்கள். ﴾إِنَّآ إِلَى رَبِّنَا مُنقَلِبُونَ﴿\n\r\n\n\r\n(நிச்சயமாக, நாம் நம்முடைய இறைவனிடமே திரும்பச் செல்பவர்கள்.) அதாவது, ‘நம் அனைவரின் மீட்சியும் கண்ணியமிக்க அல்லாஹ்விடமே உள்ளது. நன்மையைச் செய்த எவருடைய நற்கூலியையும் அவன் ஒருபோதும் வீணாக்க மாட்டான். நீங்கள் எங்களுக்குச் செய்திருப்பது அவனுக்குத் தெரியாததல்ல. அதற்கு அவன் எங்களுக்கு முழுமையான நற்கூலியை வழங்குவான்’ என்று அவர்கள் கூறினர். மேலும் அவர்கள் கூறினார்கள்: ﴾إِنَّا نَطْمَعُ أَن يَغْفِرَ لَنَا رَبُّنَا خَطَايَانَا﴿\n\r\n\n\r\n(நிச்சயமாக, எங்கள் இறைவன் எங்களின் பாவங்களை மன்னிக்க வேண்டும் என்று நாங்கள் பெரிதும் நம்புகிறோம்.) அதாவது, ‘நாங்கள் செய்த பாவங்களையும், எங்களைச் செய்யுமாறு நீங்கள் கட்டாயப்படுத்திய சூனியத்தையும் அவன் மன்னிக்க வேண்டும் என விரும்புகிறோம்.’ ﴾أَن كُنَّآ أَوَّلَ الْمُؤْمِنِينَ﴿\n\r\n\n\r\n(ஏனெனில், நாங்கள் இறைநம்பிக்கையாளர்களில் முதன்மையானவர்களாக இருக்கிறோம்.) அதாவது, எங்களுடைய மக்களான எகிப்தியர்களில் நாங்கள் முதன்முதலில் ஈமான் கொண்ட காரணத்தினால் அல்லாஹ் எங்களை மன்னிக்க வேண்டும் என்று விரும்புகிறோம். பிறகு, அவன் அவர்கள் அனைவரையும் கொன்றான். இப்னு அப்பாஸ் (ரலி) உள்ளிட்ட பலர் கூறினார்கள்: “அவர்கள் காலையில் சூனியக்காரர்களாக இருந்தார்கள்; மாலையில் (உயிர் தியாகம் செய்த) ஷஹீதுகளாக ஆகிவிட்டார்கள்.”"},"52":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=59\" class=\"link\">26:59</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:59 ஐ பார்க்கவும்"},"53":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=59\" class=\"link\">26:59</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:59 ஐ பார்க்கவும்"},"54":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=59\" class=\"link\">26:59</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:59 ஐ பார்க்கவும்"},"55":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=59\" class=\"link\">26:59</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:59 ஐ பார்க்கவும்"},"56":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=59\" class=\"link\">26:59</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:59 ஐ பார்க்கவும்"},"57":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=59\" class=\"link\">26:59</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:59 ஐ பார்க்கவும்"},"58":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=59\" class=\"link\">26:59</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:59 ஐ பார்க்கவும்"},"59":{"html":"<strong>எகிப்திலிருந்து இஸ்ரவேல் மக்களின் வெளியேற்றம்</strong><br />\r\n<br />\r\nமூஸா (அலை) அவர்கள் நீண்ட காலம் எகிப்தில் தங்கியிருந்த பிறகும், ஃபிர்அவ்னுக்கும் அவனது தலைவர்களுக்கும் எதிராக அல்லாஹ்வின் அத்தாட்சிகள் நிலைநாட்டப்பட்ட பிறகும், அவர்கள் ஆணவத்துடனும் பிடிவாதத்துடனும் இருந்தனர். எனவே, தண்டனையையும் பழிவாங்குதலையும் தவிர அவர்களுக்கு வேறு வழியில்லாமல் போனது. ஆகவே, இஸ்ரவேல் மக்களை இரவோடு இரவாக எகிப்திலிருந்து வெளியே அழைத்துச் செல்லுமாறும், தான் கட்டளையிடும் இடத்திற்கு அவர்களைக் கூட்டிச் செல்லுமாறும் அல்லாஹ் மூஸா (அலை) அவர்களுக்குக் கட்டளையிட்டான். மூஸா (அலை) அவர்கள் தனது கண்ணியமிக்க இறைவன் கட்டளையிட்டபடியே செய்தார்கள். ஃபிர்அவ்னின் மக்களிடமிருந்து இஸ்ரவேல் மக்கள் ஏராளமான ஆபரணங்களை இரவலாகப் பெற்றுக்கொண்ட பிறகு, மூஸா (அலை) அவர்கள் அவர்களை எகிப்திலிருந்து அழைத்துச் சென்றார்கள். ஒன்றுக்கும் மேற்பட்ட தஃப்ஸீர் அறிஞர்கள் கூறியுள்ளபடி, சந்திரன் உதிக்கும் வேளையில் அவர்கள் வெளியேறினர். அந்த இரவில் சந்திர கிரகணம் ஏற்பட்டதாக முஜாஹித் (ரஹ்) அவர்கள் கூறியுள்ளார்கள். அல்லாஹ்வே மிக அறிந்தவன். மூஸா (அலை) அவர்கள் யூசுஃப் (அலை) அவர்களின் அடக்கஸ்தலத்தைப் பற்றிக் கேட்டபோது, இஸ்ரவேல் சமூகத்தைச் சேர்ந்த ஒரு முதிய பெண்மணி அது இருக்குமிடத்தைக் காட்டினார். எனவே யூசுஃப் (அலை) அவர்களின் உடலின் எஞ்சிய பாகங்களை அவர்கள் தங்களோடு எடுத்துச் சென்றார்கள். அவற்றை மூஸா (அலை) அவர்களே சுமந்து சென்றதாகவும் கூறப்படுகிறது - அவர்கள் இருவர் மீதும் அல்லாஹ்வின் சாந்தி உண்டாவதாக. இஸ்ரவேல் மக்கள் எகிப்தை விட்டு வெளியேறும்போது தனது உடலின் எஞ்சிய பாகங்களைத் தன்னுடனேயே எடுத்துச் செல்ல வேண்டும் என்று யூசுஃப் (அலை) அவர்கள் தனது மரண சாசனத்தில் (வஸிய்யத்) அறிவுறுத்தியிருந்தார்கள்.<br />\r\n<br />\r\nமறுநாள் காலையில், இஸ்ரவேலர்கள் தங்கியிருந்த குடியிருப்புப் பகுதிகளில் எவரையும் காணாதபோது ஃபிர்அவ்ன் மிகுந்த சினங்கொண்டான். அவன் அழிக்கப்பட வேண்டும் என்று அல்லாஹ் ஏற்கனவே விதித்திருந்ததால் அவனது கோபம் மேலும் அதிகரித்தது. அவன் தனது படைகளைத் திரட்டி ஒன்று சேர்ப்பதற்காக உடனடியாகத் தனது நகரங்கள் அனைத்திற்கும் அறிவிப்பாளர்களை அனுப்பினான். அவன் அவர்களை நோக்கி:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">هَـؤُلاءِ﴿</span><br />\r\n(நிச்சயமாக இவர்கள்) அதாவது இஸ்ரவேல் மக்கள்,<br />\r\n<span class=\"quran-arabic-font text-success\">﴾لَشِرْذِمَةٌ</span> <span class=\"quran-arabic-font text-success\">قَلِيلُونَ﴿</span><br />\r\n(ஒரு சிறு கூட்டத்தினரே) அதாவது ஒரு சிறிய குழுவினர் என்று கூறினான்.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَإِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">لَغَائِظُونَ﴿</span><br />\r\n(நிச்சயமாக அவர்கள் நம்மை ஆத்திரமடையச் செய்துள்ளனர்.) இதன் பொருள், \"அவர்களைப் பற்றி நாம் கேள்விப்படும் செய்திகள் ஒவ்வொன்றும் நம்மை வருத்தப்படவும் கோபப்படவும் வைக்கின்றன\" என்பதாகும்.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَإِنَّا</span> <span class=\"quran-arabic-font text-success\">لَجَمِيعٌ</span> <span class=\"quran-arabic-font text-success\">حَاذِرُونَ﴿</span><br />\r\n(ஆனால் நாம் எச்சரிக்கையுடன் இருக்கும் ஒரு பெரும் படையாவோம்.) இதன் பொருள், \"அவர்கள் நமக்குத் துரோகம் செய்யக்கூடும் என்பதால் நாம் எப்போதும் முன்னெச்சரிக்கையுடன் இருக்கிறோம்\" என்பதாகும். ஸலஃபுகளில் சிலர் இதனை, \"நாம் எப்போதும் எச்சரிக்கையாகவும் ஆயுதம் தாங்கியும் இருக்கிறோம். அவர்களின் கடைசி மனிதன் வரை நான் அவர்களை அழிக்க விரும்புகிறேன்; அவர்களின் நிலங்களையும் சொத்துக்களையும் துடைத்தெறிய விரும்புகிறேன்\" என்ற பொருளில் ஓதியுள்ளனர். எத்தகைய தண்டனையை அவன் இஸ்ரவேல் மக்களுக்கு அளிக்க விரும்பினானோ, அதே தண்டனையைக் கொண்டு அல்லாஹ் அவனையும் அவனது படைகளையும் தண்டித்தான்.<br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَأَخْرَجْنَاهُم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">جَنَّاتٍ</span> <span class=\"quran-arabic-font text-success\">وَعُيُونٍ</span> - <span class=\"quran-arabic-font text-success\">وَكُنُوزٍ</span> <span class=\"quran-arabic-font text-success\">وَمَقَامٍ</span> <span class=\"quran-arabic-font text-success\">كَرِيمٍ﴿</span><br />\r\n(எனவே, நாம் அவர்களைத் தோட்டங்களிலிருந்தும், நீரூற்றுகளிலிருந்தும், புதையல்களிலிருந்தும், கண்ணியமான வாழ்விடங்களிலிருந்தும் வெளியேற்றினோம்.) அதாவது, அவர்கள் அந்த அருட்கொடைகளிலிருந்து வெளியேற்றப்பட்டு நரகத்தில் தள்ளப்பட்டனர். இவ்வுலகில் அவர்கள் அனுபவித்த கண்ணியமான இடங்கள், தோட்டங்கள், ஆறுகள், செல்வங்கள், வாழ்வாதாரங்கள், அந்தஸ்து மற்றும் அதிகாரம் ஆகியவற்றை அவர்கள் விட்டுச் சென்றனர்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾كَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">وَأَوْرَثْنَاهَا</span> <span class=\"quran-arabic-font text-success\">بَنِي</span> <span class=\"quran-arabic-font text-success\">إِسْرَائِيلَ﴿</span><br />\r\n(இவ்வாறே, இஸ்ரவேல் மக்களை நாம் அவற்றுக்கு வாரிசுகளாக்கினோம்.)<br />\r\n<br />\r\nஇது பின்வரும் வசனங்களைப் (ஆயத்துகள்) போன்றது:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَأَوْرَثْنَا</span> <span class=\"quran-arabic-font text-success\">الْقَوْمَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَانُوا</span> <span class=\"quran-arabic-font text-success\">يُسْتَضْعَفُونَ</span> <span class=\"quran-arabic-font text-success\">مَشَارِقَ</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">وَمَغَارِبَهَا</span> <span class=\"quran-arabic-font text-success\">الَّتِي</span> <span class=\"quran-arabic-font text-success\">بَارَكْنَا</span> <span class=\"quran-arabic-font text-success\">فِيهَا﴿</span><br />\r\n(மேலும், பலவீனமானவர்களாகக் கருதப்பட்ட அந்த மக்களை, நாம் அருள்வளம் செய்திருந்த பூமியின் கிழக்குப் பகுதிகளுக்கும் அதன் மேற்குப் பகுதிகளுக்கும் வாரிசுகளாக்கினோம்) (<a href=\"qurandisp.php?sura=7&ayah=137\" class=\"link\">7:137</a>).<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَنُرِيدُ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">نَّمُنَّ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">اسْتُضْعِفُوا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">وَنَجْعَلَهُمْ</span> <span class=\"quran-arabic-font text-success\">أَئِمَّةً</span> <span class=\"quran-arabic-font text-success\">وَنَجْعَلَهُمُ</span> <span class=\"quran-arabic-font text-success\">الْوَارِثِينَ</span> - <span class=\"quran-arabic-font text-success\">وَنُمَكِّنَ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">وَنُرِيَ</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنَ</span> <span class=\"quran-arabic-font text-success\">وَهَامَانَ</span> <span class=\"quran-arabic-font text-success\">وَجُنُودَهُمَا</span> <span class=\"quran-arabic-font text-success\">مِنْهُم</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">كَانُوا</span> <span class=\"quran-arabic-font text-success\">يَحْذَرُونَ﴿</span><br />\r\n(மேலும், பூமியில் பலவீனப்படுத்தப்பட்டவர்கள் மீது நாம் பேரருள் புரியவும், அவர்களைத் தலைவர்களாக்கவும், வாரிசுகளாக்கவும் நாம் நாடினோம். மேலும் நாம் அவர்களுக்குப் பூமியில் அதிகாரத்தை வழங்கவும், ஃபிர்அவ்னும், ஹாமானும், அவர்களுடைய படைகளும் எதைப்பற்றி அஞ்சிக் கொண்டிருந்தார்களோ, அதையே அவர்களுக்குக் காட்டவும் (நாடினோம்)) (<a href=\"qurandisp.php?sura=28&ayah=5\" class=\"link\">28:5</a>-6).<br />\r\n<br />\r\n<br />\r\n<br />","text":"எகிப்திலிருந்து இஸ்ரவேல் மக்களின் வெளியேற்றம்\n\r\n\n\r\nமூஸா (அலை) அவர்கள் நீண்ட காலம் எகிப்தில் தங்கியிருந்த பிறகும், ஃபிர்அவ்னுக்கும் அவனது தலைவர்களுக்கும் எதிராக அல்லாஹ்வின் அத்தாட்சிகள் நிலைநாட்டப்பட்ட பிறகும், அவர்கள் ஆணவத்துடனும் பிடிவாதத்துடனும் இருந்தனர். எனவே, தண்டனையையும் பழிவாங்குதலையும் தவிர அவர்களுக்கு வேறு வழியில்லாமல் போனது. ஆகவே, இஸ்ரவேல் மக்களை இரவோடு இரவாக எகிப்திலிருந்து வெளியே அழைத்துச் செல்லுமாறும், தான் கட்டளையிடும் இடத்திற்கு அவர்களைக் கூட்டிச் செல்லுமாறும் அல்லாஹ் மூஸா (அலை) அவர்களுக்குக் கட்டளையிட்டான். மூஸா (அலை) அவர்கள் தனது கண்ணியமிக்க இறைவன் கட்டளையிட்டபடியே செய்தார்கள். ஃபிர்அவ்னின் மக்களிடமிருந்து இஸ்ரவேல் மக்கள் ஏராளமான ஆபரணங்களை இரவலாகப் பெற்றுக்கொண்ட பிறகு, மூஸா (அலை) அவர்கள் அவர்களை எகிப்திலிருந்து அழைத்துச் சென்றார்கள். ஒன்றுக்கும் மேற்பட்ட தஃப்ஸீர் அறிஞர்கள் கூறியுள்ளபடி, சந்திரன் உதிக்கும் வேளையில் அவர்கள் வெளியேறினர். அந்த இரவில் சந்திர கிரகணம் ஏற்பட்டதாக முஜாஹித் (ரஹ்) அவர்கள் கூறியுள்ளார்கள். அல்லாஹ்வே மிக அறிந்தவன். மூஸா (அலை) அவர்கள் யூசுஃப் (அலை) அவர்களின் அடக்கஸ்தலத்தைப் பற்றிக் கேட்டபோது, இஸ்ரவேல் சமூகத்தைச் சேர்ந்த ஒரு முதிய பெண்மணி அது இருக்குமிடத்தைக் காட்டினார். எனவே யூசுஃப் (அலை) அவர்களின் உடலின் எஞ்சிய பாகங்களை அவர்கள் தங்களோடு எடுத்துச் சென்றார்கள். அவற்றை மூஸா (அலை) அவர்களே சுமந்து சென்றதாகவும் கூறப்படுகிறது - அவர்கள் இருவர் மீதும் அல்லாஹ்வின் சாந்தி உண்டாவதாக. இஸ்ரவேல் மக்கள் எகிப்தை விட்டு வெளியேறும்போது தனது உடலின் எஞ்சிய பாகங்களைத் தன்னுடனேயே எடுத்துச் செல்ல வேண்டும் என்று யூசுஃப் (அலை) அவர்கள் தனது மரண சாசனத்தில் (வஸிய்யத்) அறிவுறுத்தியிருந்தார்கள்.\n\r\n\n\r\nமறுநாள் காலையில், இஸ்ரவேலர்கள் தங்கியிருந்த குடியிருப்புப் பகுதிகளில் எவரையும் காணாதபோது ஃபிர்அவ்ன் மிகுந்த சினங்கொண்டான். அவன் அழிக்கப்பட வேண்டும் என்று அல்லாஹ் ஏற்கனவே விதித்திருந்ததால் அவனது கோபம் மேலும் அதிகரித்தது. அவன் தனது படைகளைத் திரட்டி ஒன்று சேர்ப்பதற்காக உடனடியாகத் தனது நகரங்கள் அனைத்திற்கும் அறிவிப்பாளர்களை அனுப்பினான். அவன் அவர்களை நோக்கி:\n\r\n﴾إِنَّ هَـؤُلاءِ﴿\n\r\n(நிச்சயமாக இவர்கள்) அதாவது இஸ்ரவேல் மக்கள்,\n\r\n﴾لَشِرْذِمَةٌ قَلِيلُونَ﴿\n\r\n(ஒரு சிறு கூட்டத்தினரே) அதாவது ஒரு சிறிய குழுவினர் என்று கூறினான்.\n\r\n﴾وَإِنَّهُمْ لَنَا لَغَائِظُونَ﴿\n\r\n(நிச்சயமாக அவர்கள் நம்மை ஆத்திரமடையச் செய்துள்ளனர்.) இதன் பொருள், \"அவர்களைப் பற்றி நாம் கேள்விப்படும் செய்திகள் ஒவ்வொன்றும் நம்மை வருத்தப்படவும் கோபப்படவும் வைக்கின்றன\" என்பதாகும்.\n\r\n﴾وَإِنَّا لَجَمِيعٌ حَاذِرُونَ﴿\n\r\n(ஆனால் நாம் எச்சரிக்கையுடன் இருக்கும் ஒரு பெரும் படையாவோம்.) இதன் பொருள், \"அவர்கள் நமக்குத் துரோகம் செய்யக்கூடும் என்பதால் நாம் எப்போதும் முன்னெச்சரிக்கையுடன் இருக்கிறோம்\" என்பதாகும். ஸலஃபுகளில் சிலர் இதனை, \"நாம் எப்போதும் எச்சரிக்கையாகவும் ஆயுதம் தாங்கியும் இருக்கிறோம். அவர்களின் கடைசி மனிதன் வரை நான் அவர்களை அழிக்க விரும்புகிறேன்; அவர்களின் நிலங்களையும் சொத்துக்களையும் துடைத்தெறிய விரும்புகிறேன்\" என்ற பொருளில் ஓதியுள்ளனர். எத்தகைய தண்டனையை அவன் இஸ்ரவேல் மக்களுக்கு அளிக்க விரும்பினானோ, அதே தண்டனையைக் கொண்டு அல்லாஹ் அவனையும் அவனது படைகளையும் தண்டித்தான்.\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்:\n\r\n﴾فَأَخْرَجْنَاهُم مِّن جَنَّاتٍ وَعُيُونٍ - وَكُنُوزٍ وَمَقَامٍ كَرِيمٍ﴿\n\r\n(எனவே, நாம் அவர்களைத் தோட்டங்களிலிருந்தும், நீரூற்றுகளிலிருந்தும், புதையல்களிலிருந்தும், கண்ணியமான வாழ்விடங்களிலிருந்தும் வெளியேற்றினோம்.) அதாவது, அவர்கள் அந்த அருட்கொடைகளிலிருந்து வெளியேற்றப்பட்டு நரகத்தில் தள்ளப்பட்டனர். இவ்வுலகில் அவர்கள் அனுபவித்த கண்ணியமான இடங்கள், தோட்டங்கள், ஆறுகள், செல்வங்கள், வாழ்வாதாரங்கள், அந்தஸ்து மற்றும் அதிகாரம் ஆகியவற்றை அவர்கள் விட்டுச் சென்றனர்:\n\r\n﴾كَذَلِكَ وَأَوْرَثْنَاهَا بَنِي إِسْرَائِيلَ﴿\n\r\n(இவ்வாறே, இஸ்ரவேல் மக்களை நாம் அவற்றுக்கு வாரிசுகளாக்கினோம்.)\n\r\n\n\r\nஇது பின்வரும் வசனங்களைப் (ஆயத்துகள்) போன்றது:\n\r\n﴾وَأَوْرَثْنَا الْقَوْمَ الَّذِينَ كَانُوا يُسْتَضْعَفُونَ مَشَارِقَ الْأَرْضِ وَمَغَارِبَهَا الَّتِي بَارَكْنَا فِيهَا﴿\n\r\n(மேலும், பலவீனமானவர்களாகக் கருதப்பட்ட அந்த மக்களை, நாம் அருள்வளம் செய்திருந்த பூமியின் கிழக்குப் பகுதிகளுக்கும் அதன் மேற்குப் பகுதிகளுக்கும் வாரிசுகளாக்கினோம்) (7:137).\n\r\n﴾وَنُرِيدُ أَن نَّمُنَّ عَلَى الَّذِينَ اسْتُضْعِفُوا فِي الْأَرْضِ وَنَجْعَلَهُمْ أَئِمَّةً وَنَجْعَلَهُمُ الْوَارِثِينَ - وَنُمَكِّنَ لَهُمْ فِي الْأَرْضِ وَنُرِيَ فِرْعَوْنَ وَهَامَانَ وَجُنُودَهُمَا مِنْهُم مَّا كَانُوا يَحْذَرُونَ﴿\n\r\n(மேலும், பூமியில் பலவீனப்படுத்தப்பட்டவர்கள் மீது நாம் பேரருள் புரியவும், அவர்களைத் தலைவர்களாக்கவும், வாரிசுகளாக்கவும் நாம் நாடினோம். மேலும் நாம் அவர்களுக்குப் பூமியில் அதிகாரத்தை வழங்கவும், ஃபிர்அவ்னும், ஹாமானும், அவர்களுடைய படைகளும் எதைப்பற்றி அஞ்சிக் கொண்டிருந்தார்களோ, அதையே அவர்களுக்குக் காட்டவும் (நாடினோம்)) (28:5-6)."},"60":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=68\" class=\"link\">26:68</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:68 ஐ பார்க்கவும்"},"61":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=68\" class=\"link\">26:68</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:68 ஐ பார்க்கவும்"},"62":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=68\" class=\"link\">26:68</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:68 ஐ பார்க்கவும்"},"63":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=68\" class=\"link\">26:68</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:68 ஐ பார்க்கவும்"},"64":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=68\" class=\"link\">26:68</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:68 ஐ பார்க்கவும்"},"65":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=68\" class=\"link\">26:68</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:68 ஐ பார்க்கவும்"},"66":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=68\" class=\"link\">26:68</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:68 ஐ பார்க்கவும்"},"67":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=68\" class=\"link\">26:68</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:68 ஐ பார்க்கவும்"},"68":{"html":"<strong>ஃபிர்அவ்ன் பின்தொடர்ந்ததும், இஸ்ரவேலர்கள் வெளியேற்றப்பட்டதும், ஃபிர்அவ்னும் அவனது கூட்டத்தினரும் மூழ்கடிக்கப்பட்டதும்</strong><br />\r\n<br />\r\nதஃப்ஸீர் அறிஞர்களில் பலர் (ஒன்றுக்கு மேற்பட்டவர்கள்) கூறுகிறார்கள்: ஃபிர்அவ்ன் ஒரு பெரும் கூட்டத்துடன் புறப்பட்டான். அக்கால எகிப்தின் தலைவர்கள், முழு அரசாங்க இயந்திரம், அதாவது முடிவெடுக்கும் அதிகாரம் கொண்டவர்கள், செல்வாக்கு மிக்கவர்கள், இளவரசர்கள், அமைச்சர்கள், பிரமுகர்கள், தளபதிகள் மற்றும் வீரர்கள் என அனைவரும் அக்கூட்டத்தில் இருந்தனர். <span class=\"quran-arabic-font text-success\">﴾فَأَتْبَعُوهُم</span> <span class=\"quran-arabic-font text-success\">مُّشْرِقِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(எனவே, அவர்கள் சூரிய உதயத்தின்போது அவர்களைப் பின்தொடர்ந்தார்கள்.) அதாவது, சூரிய உதயத்தின்போது அவர்கள் இஸ்ரவேலர்களைச் சென்றடைந்தார்கள். <span class=\"quran-arabic-font text-success\">﴾فَلَمَّا</span> <span class=\"quran-arabic-font text-success\">تَرَآءَا</span> <span class=\"quran-arabic-font text-success\">الْجَمْعَانِ﴿</span><br />\r\n<br />\r\n(இரு கூட்டத்தினரும் ஒருவரையொருவர் நேருக்கு நேர் பார்த்தபோது,) அதாவது, இரு சாராரும் ஒருவரையொருவர் கண்டனர். அந்தச் சமயத்தில், <span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">أَصْحَابُ</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span> <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">لَمُدْرَكُونَ﴿</span><br />\r\n<br />\r\n(மூஸா (அலை) அவர்களின் தோழர்கள், \"நிச்சயமாக நாம் பிடிக்கப்பட்டு விடுவோம்\" என்று கூறினார்கள்.) ஏனெனில், செங்கடலின் கரையில் ஃபிர்அவ்னும் அவனது கூட்டத்தினரும் அவர்களை நெருங்கிவிட்டனர். அவர்களுக்கு முன்னே கடலும், பின்னே ஃபிர்அவ்னும் அவனது படைகளும் இருந்தன. இதனால்தான் அவர்கள் இவ்வாறு கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾فَلَمَّا</span> <span class=\"quran-arabic-font text-success\">تَرَآءَا</span> <span class=\"quran-arabic-font text-success\">الْجَمْعَانِ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">أَصْحَابُ</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span> <span class=\"quran-arabic-font text-success\">إِنَّا</span> <span class=\"quran-arabic-font text-success\">لَمُدْرَكُونَ</span> - <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">كَلاَّ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">مَعِىَ</span> <span class=\"quran-arabic-font text-success\">رَبِّى</span> <span class=\"quran-arabic-font text-success\">سَيَهْدِينِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(\"நிச்சயமாக நாம் பிடிக்கப்பட்டு விடுவோம்.\" அதற்கு (மூஸா (அலை) அவர்கள்), \"அப்படியல்ல! நிச்சயமாக என்னுடன் என் இறைவன் இருக்கிறான்; அவன் எனக்கு நல்வழி காட்டுவான்\" என்று கூறினார்கள்.) அதாவது, 'நீங்கள் அஞ்சுவது எதுவும் உங்களுக்கு நடக்காது. ஏனெனில், உங்களை இங்கு அழைத்து வருமாறு அல்லாஹ்வே எனக்குக் கட்டளையிட்டான்; அவன் தனது வாக்குறுதியை மீறமாட்டான்.' ஹாரூன் (அலை) அவர்கள் முன்னணியில் இருந்தார்கள்; அவர்களுடன் யூஷஃ பின் நூன் (அலை) அவர்களும், ஃபிர்அவ்னின் குடும்பத்தைச் சேர்ந்த ஒரு முஃமினும் (ஈமான் கொண்டவரும்) இருந்தார்கள். மூஸா (அலை) அவர்கள் பின்னால் இருந்தார்கள். தஃப்ஸீர் அறிஞர்களில் பலர் கூறுகிறார்கள்: அவர்கள் என்ன செய்வதென்று தெரியாமல் அங்கே நின்றபோது, யூஷஃ பின் நூன் (அலை) அல்லது ஃபிர்அவ்னின் குடும்பத்தைச் சேர்ந்த அந்த முஃமின், மூஸா (அலை) அவர்களிடம், \"அல்லாஹ்வின் தூதரே! உங்கள் இறைவன் எங்களை இந்த இடத்திற்குத் தான் அழைத்து வரச் சொன்னானா?\" என்று கேட்டார். அதற்கு அவர்கள் \"ஆம்\" என்று கூறினார்கள். பின்னர் ஃபிர்அவ்னும் அவனது படைகளும் மிக நெருக்கத்தில் வந்துவிட்டனர். அந்தத் தருணத்தில், அல்லாஹ் தனது தூதர் மூஸா (அலை) அவர்களிடம் தனது கைத்தடியால் கடலை அடிக்குமாறு கட்டளையிட்டான். அவர்கள் அவ்வாறே அடிக்க, அல்லாஹ்வின் விருப்பப்படி கடல் பிளந்தது. அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾فَأَوْحَيْنَآ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span> <span class=\"quran-arabic-font text-success\">أَنِ</span> <span class=\"quran-arabic-font text-success\">اضْرِب</span> <span class=\"quran-arabic-font text-success\">بِّعَصَاكَ</span> <span class=\"quran-arabic-font text-success\">الْبَحْرَ</span> <span class=\"quran-arabic-font text-success\">فَانفَلَقَ</span> <span class=\"quran-arabic-font text-success\">فَكَانَ</span> <span class=\"quran-arabic-font text-success\">كُلُّ</span> <span class=\"quran-arabic-font text-success\">فِرْقٍ</span> <span class=\"quran-arabic-font text-success\">كَالطَّوْدِ</span> <span class=\"quran-arabic-font text-success\">الْعَظِيمِ﴿</span><br />\r\n<br />\r\n(அது பிளந்தது; (பிளக்கப்பட்ட) ஒவ்வொரு பகுதியும் மாபெரும் மலையைப் போன்று ஆகிவிட்டது.) அதாவது, பிரம்மாண்டமான மலைகளைப் போன்று இருந்தது. இது இப்னு மஸ்ஊத் (ரழி), இப்னு அப்பாஸ் (ரழி), முஹம்மது பின் கஅப், அத்-தஹ்ஹாக், கதாதா மற்றும் பலரது கருத்தாகும். அதா அல்-குராசானி கூறினார்கள்: \"இது இரு மலைகளுக்கு இடையிலான ஒரு கணவாயைக் குறிக்கிறது.\" இப்னு அப்பாஸ் (ரழி) கூறினார்கள்: \"கடல் பன்னிரண்டு பாதைகளாகப் பிரிந்தது; ஒவ்வொரு கோத்திரத்திற்கும் ஒரு பாதை ஒதுக்கப்பட்டது.\" அஸ்-ஸுத்தி மேலும் கூறுகையில், \"அதில் அவர்கள் ஒருவரையொருவர் பார்த்துக் கொள்ளும் வகையில் ஜன்னல்கள் இருந்தன; தண்ணீர் சுவர்களைப் போல எழும்பி நின்றது\" என்றார். கடல் படுகையை நிலத்தைப் போல உலர்ந்ததாக மாற்றுவதற்காக அல்லாஹ் காற்றை அனுப்பினான். அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾فَاضْرِبْ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">طَرِيقاً</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْبَحْرِ</span> <span class=\"quran-arabic-font text-success\">يَبَساً</span> <span class=\"quran-arabic-font text-success\">لاَّ</span> <span class=\"quran-arabic-font text-success\">تَخَافُ</span> <span class=\"quran-arabic-font text-success\">دَرَكاً</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَخْشَى﴿</span><br />\r\n<br />\r\n(மேலும் கடலில் அவர்களுக்காக ஒரு உலர்ந்த பாதையை ஏற்படுத்துவீராக; (எதிரிகளால்) பிடிக்கப்படுவோம் என்று நீர் அஞ்ச வேண்டாம்; (மூழ்கிவிடுவோம் என்று) பயப்படவும் வேண்டாம்.) (<a href=\"qurandisp.php?sura=20&ayah=77\" class=\"link\">20:77</a>). மேலும் இங்கு அவன் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَأَزْلَفْنَا</span> <span class=\"quran-arabic-font text-success\">ثَمَّ</span> <span class=\"quran-arabic-font text-success\">الْآخَرِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(பின்னர் மற்றவர்களையும் அந்த இடத்திற்கு நெருங்கி வரச் செய்தோம்.) இப்னு அப்பாஸ் (ரழி), அதா அல்-குராசானி, கதாதா மற்றும் அஸ்-ஸுத்தி ஆகியோர் கூறுகிறார்கள்: <span class=\"quran-arabic-font text-success\">﴾وَأَزْلَفْنَا﴿</span><br />\r\n<br />\r\n(பின்னர் நாம் நெருங்கச் செய்தோம்) என்பதன் பொருள், \"நாம் ஃபிர்அவ்னையும் அவனது படைகளையும் கடலுக்கு மிக அருகில் கொண்டு வந்தோம்\" என்பதாகும். <span class=\"quran-arabic-font text-success\">﴾وَأَنجَيْنَا</span> <span class=\"quran-arabic-font text-success\">مُوسَى</span> <span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">مَّعَهُ</span> <span class=\"quran-arabic-font text-success\">أَجْمَعِينَ</span> - <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">أَغْرَقْنَا</span> <span class=\"quran-arabic-font text-success\">الْآخَرِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மூஸாவையும் அவருடன் இருந்த அனைவரையும் நாம் காப்பாற்றினோம். பின்னர் மற்றவர்களை நாம் மூழ்கடித்தோம்.) அதாவது: 'மூஸா (அலை) அவர்களையும், இஸ்ரவேலர்களையும், அவர்களது மார்க்கத்தைப் பின்பற்றியவர்களையும் நாம் காப்பாற்றினோம். அவர்களில் எவரும் அழிந்துவிடவில்லை. ஆனால் ஃபிர்அவ்னும் அவனது படைகளும் மூழ்கடிக்கப்பட்டனர். அவர்களில் எவரும் எஞ்சியிருக்கவில்லை; அனைவரும் அழிக்கப்பட்டனர்.' பின்னர் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">لآيَةً﴿</span><br />\r\n<br />\r\n(நிச்சயமாக இதில் ஒரு அத்தாட்சி இருக்கிறது.) அதாவது, ஆச்சரியங்கள் நிறைந்த இந்தக் கதையும், இறைநம்பிக்கை கொண்ட அடியார்களுக்குக் கிடைத்த உதவியும் அல்லாஹ்வின் ஞானத்திற்குத் தெளிவான சான்றாகவும் அத்தாட்சியாகவும் இருக்கின்றன. <span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">لآيَةً</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">أَكْثَرُهُمْ</span> <span class=\"quran-arabic-font text-success\">مُّؤْمِنِينَ</span> - <span class=\"quran-arabic-font text-success\">وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">رَبَّكَ</span> <span class=\"quran-arabic-font text-success\">لَهُوَ</span> <span class=\"quran-arabic-font text-success\">الْعَزِيزُ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمُ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(ஆயினும், அவர்களில் பெரும்பாலோர் நம்பிக்கை கொள்வதில்லை. மேலும், நிச்சயமாக உமது இறைவன், அவன் தான் (யாவரையும்) மிகைத்தவன், மிகக் கருணையாளன்.) இதற்கான விளக்கம் ஏற்கனவே மேலே கூறப்பட்டுள்ளது.<br />\r\n<br />","text":"ஃபிர்அவ்ன் பின்தொடர்ந்ததும், இஸ்ரவேலர்கள் வெளியேற்றப்பட்டதும், ஃபிர்அவ்னும் அவனது கூட்டத்தினரும் மூழ்கடிக்கப்பட்டதும்\n\r\n\n\r\nதஃப்ஸீர் அறிஞர்களில் பலர் (ஒன்றுக்கு மேற்பட்டவர்கள்) கூறுகிறார்கள்: ஃபிர்அவ்ன் ஒரு பெரும் கூட்டத்துடன் புறப்பட்டான். அக்கால எகிப்தின் தலைவர்கள், முழு அரசாங்க இயந்திரம், அதாவது முடிவெடுக்கும் அதிகாரம் கொண்டவர்கள், செல்வாக்கு மிக்கவர்கள், இளவரசர்கள், அமைச்சர்கள், பிரமுகர்கள், தளபதிகள் மற்றும் வீரர்கள் என அனைவரும் அக்கூட்டத்தில் இருந்தனர். ﴾فَأَتْبَعُوهُم مُّشْرِقِينَ ﴿\n\r\n\n\r\n(எனவே, அவர்கள் சூரிய உதயத்தின்போது அவர்களைப் பின்தொடர்ந்தார்கள்.) அதாவது, சூரிய உதயத்தின்போது அவர்கள் இஸ்ரவேலர்களைச் சென்றடைந்தார்கள். ﴾فَلَمَّا تَرَآءَا الْجَمْعَانِ﴿\n\r\n\n\r\n(இரு கூட்டத்தினரும் ஒருவரையொருவர் நேருக்கு நேர் பார்த்தபோது,) அதாவது, இரு சாராரும் ஒருவரையொருவர் கண்டனர். அந்தச் சமயத்தில், ﴾قَالَ أَصْحَابُ مُوسَى إِنَّا لَمُدْرَكُونَ﴿\n\r\n\n\r\n(மூஸா (அலை) அவர்களின் தோழர்கள், \"நிச்சயமாக நாம் பிடிக்கப்பட்டு விடுவோம்\" என்று கூறினார்கள்.) ஏனெனில், செங்கடலின் கரையில் ஃபிர்அவ்னும் அவனது கூட்டத்தினரும் அவர்களை நெருங்கிவிட்டனர். அவர்களுக்கு முன்னே கடலும், பின்னே ஃபிர்அவ்னும் அவனது படைகளும் இருந்தன. இதனால்தான் அவர்கள் இவ்வாறு கூறினார்கள்: ﴾فَلَمَّا تَرَآءَا الْجَمْعَانِ قَالَ أَصْحَابُ مُوسَى إِنَّا لَمُدْرَكُونَ - قَالَ كَلاَّ إِنَّ مَعِىَ رَبِّى سَيَهْدِينِ ﴿\n\r\n\n\r\n(\"நிச்சயமாக நாம் பிடிக்கப்பட்டு விடுவோம்.\" அதற்கு (மூஸா (அலை) அவர்கள்), \"அப்படியல்ல! நிச்சயமாக என்னுடன் என் இறைவன் இருக்கிறான்; அவன் எனக்கு நல்வழி காட்டுவான்\" என்று கூறினார்கள்.) அதாவது, 'நீங்கள் அஞ்சுவது எதுவும் உங்களுக்கு நடக்காது. ஏனெனில், உங்களை இங்கு அழைத்து வருமாறு அல்லாஹ்வே எனக்குக் கட்டளையிட்டான்; அவன் தனது வாக்குறுதியை மீறமாட்டான்.' ஹாரூன் (அலை) அவர்கள் முன்னணியில் இருந்தார்கள்; அவர்களுடன் யூஷஃ பின் நூன் (அலை) அவர்களும், ஃபிர்அவ்னின் குடும்பத்தைச் சேர்ந்த ஒரு முஃமினும் (ஈமான் கொண்டவரும்) இருந்தார்கள். மூஸா (அலை) அவர்கள் பின்னால் இருந்தார்கள். தஃப்ஸீர் அறிஞர்களில் பலர் கூறுகிறார்கள்: அவர்கள் என்ன செய்வதென்று தெரியாமல் அங்கே நின்றபோது, யூஷஃ பின் நூன் (அலை) அல்லது ஃபிர்அவ்னின் குடும்பத்தைச் சேர்ந்த அந்த முஃமின், மூஸா (அலை) அவர்களிடம், \"அல்லாஹ்வின் தூதரே! உங்கள் இறைவன் எங்களை இந்த இடத்திற்குத் தான் அழைத்து வரச் சொன்னானா?\" என்று கேட்டார். அதற்கு அவர்கள் \"ஆம்\" என்று கூறினார்கள். பின்னர் ஃபிர்அவ்னும் அவனது படைகளும் மிக நெருக்கத்தில் வந்துவிட்டனர். அந்தத் தருணத்தில், அல்லாஹ் தனது தூதர் மூஸா (அலை) அவர்களிடம் தனது கைத்தடியால் கடலை அடிக்குமாறு கட்டளையிட்டான். அவர்கள் அவ்வாறே அடிக்க, அல்லாஹ்வின் விருப்பப்படி கடல் பிளந்தது. அல்லாஹ் கூறுகிறான்: ﴾فَأَوْحَيْنَآ إِلَى مُوسَى أَنِ اضْرِب بِّعَصَاكَ الْبَحْرَ فَانفَلَقَ فَكَانَ كُلُّ فِرْقٍ كَالطَّوْدِ الْعَظِيمِ﴿\n\r\n\n\r\n(அது பிளந்தது; (பிளக்கப்பட்ட) ஒவ்வொரு பகுதியும் மாபெரும் மலையைப் போன்று ஆகிவிட்டது.) அதாவது, பிரம்மாண்டமான மலைகளைப் போன்று இருந்தது. இது இப்னு மஸ்ஊத் (ரழி), இப்னு அப்பாஸ் (ரழி), முஹம்மது பின் கஅப், அத்-தஹ்ஹாக், கதாதா மற்றும் பலரது கருத்தாகும். அதா அல்-குராசானி கூறினார்கள்: \"இது இரு மலைகளுக்கு இடையிலான ஒரு கணவாயைக் குறிக்கிறது.\" இப்னு அப்பாஸ் (ரழி) கூறினார்கள்: \"கடல் பன்னிரண்டு பாதைகளாகப் பிரிந்தது; ஒவ்வொரு கோத்திரத்திற்கும் ஒரு பாதை ஒதுக்கப்பட்டது.\" அஸ்-ஸுத்தி மேலும் கூறுகையில், \"அதில் அவர்கள் ஒருவரையொருவர் பார்த்துக் கொள்ளும் வகையில் ஜன்னல்கள் இருந்தன; தண்ணீர் சுவர்களைப் போல எழும்பி நின்றது\" என்றார். கடல் படுகையை நிலத்தைப் போல உலர்ந்ததாக மாற்றுவதற்காக அல்லாஹ் காற்றை அனுப்பினான். அல்லாஹ் கூறுகிறான்: ﴾فَاضْرِبْ لَهُمْ طَرِيقاً فِى الْبَحْرِ يَبَساً لاَّ تَخَافُ دَرَكاً وَلاَ تَخْشَى﴿\n\r\n\n\r\n(மேலும் கடலில் அவர்களுக்காக ஒரு உலர்ந்த பாதையை ஏற்படுத்துவீராக; (எதிரிகளால்) பிடிக்கப்படுவோம் என்று நீர் அஞ்ச வேண்டாம்; (மூழ்கிவிடுவோம் என்று) பயப்படவும் வேண்டாம்.) (20:77). மேலும் இங்கு அவன் கூறுகிறான்: ﴾وَأَزْلَفْنَا ثَمَّ الْآخَرِينَ ﴿\n\r\n\n\r\n(பின்னர் மற்றவர்களையும் அந்த இடத்திற்கு நெருங்கி வரச் செய்தோம்.) இப்னு அப்பாஸ் (ரழி), அதா அல்-குராசானி, கதாதா மற்றும் அஸ்-ஸுத்தி ஆகியோர் கூறுகிறார்கள்: ﴾وَأَزْلَفْنَا﴿\n\r\n\n\r\n(பின்னர் நாம் நெருங்கச் செய்தோம்) என்பதன் பொருள், \"நாம் ஃபிர்அவ்னையும் அவனது படைகளையும் கடலுக்கு மிக அருகில் கொண்டு வந்தோம்\" என்பதாகும். ﴾وَأَنجَيْنَا مُوسَى وَمَن مَّعَهُ أَجْمَعِينَ - ثُمَّ أَغْرَقْنَا الْآخَرِينَ ﴿\n\r\n\n\r\n(மூஸாவையும் அவருடன் இருந்த அனைவரையும் நாம் காப்பாற்றினோம். பின்னர் மற்றவர்களை நாம் மூழ்கடித்தோம்.) அதாவது: 'மூஸா (அலை) அவர்களையும், இஸ்ரவேலர்களையும், அவர்களது மார்க்கத்தைப் பின்பற்றியவர்களையும் நாம் காப்பாற்றினோம். அவர்களில் எவரும் அழிந்துவிடவில்லை. ஆனால் ஃபிர்அவ்னும் அவனது படைகளும் மூழ்கடிக்கப்பட்டனர். அவர்களில் எவரும் எஞ்சியிருக்கவில்லை; அனைவரும் அழிக்கப்பட்டனர்.' பின்னர் அல்லாஹ் கூறுகிறான்: ﴾إِنَّ فِى ذَلِكَ لآيَةً﴿\n\r\n\n\r\n(நிச்சயமாக இதில் ஒரு அத்தாட்சி இருக்கிறது.) அதாவது, ஆச்சரியங்கள் நிறைந்த இந்தக் கதையும், இறைநம்பிக்கை கொண்ட அடியார்களுக்குக் கிடைத்த உதவியும் அல்லாஹ்வின் ஞானத்திற்குத் தெளிவான சான்றாகவும் அத்தாட்சியாகவும் இருக்கின்றன. ﴾إِنَّ فِي ذَلِكَ لآيَةً وَمَا كَانَ أَكْثَرُهُمْ مُّؤْمِنِينَ - وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ ﴿\n\r\n\n\r\n(ஆயினும், அவர்களில் பெரும்பாலோர் நம்பிக்கை கொள்வதில்லை. மேலும், நிச்சயமாக உமது இறைவன், அவன் தான் (யாவரையும்) மிகைத்தவன், மிகக் கருணையாளன்.) இதற்கான விளக்கம் ஏற்கனவே மேலே கூறப்பட்டுள்ளது."},"69":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=77\" class=\"link\">26:77</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:77 ஐ பார்க்கவும்"},"70":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=77\" class=\"link\">26:77</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:77 ஐ பார்க்கவும்"},"71":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=77\" class=\"link\">26:77</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:77 ஐ பார்க்கவும்"},"72":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=77\" class=\"link\">26:77</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:77 ஐ பார்க்கவும்"},"73":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=77\" class=\"link\">26:77</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:77 ஐ பார்க்கவும்"},"74":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=77\" class=\"link\">26:77</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:77 ஐ பார்க்கவும்"},"75":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=77\" class=\"link\">26:77</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:77 ஐ பார்க்கவும்"},"76":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=77\" class=\"link\">26:77</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:77 ஐ பார்க்கவும்"},"77":{"html":"<strong>அல்லாஹ்வின் உற்ற நண்பரான இப்ராஹீம் (அலை) அவர்கள் ஷிர்க்கிற்கு (இணைவைப்பிற்கு) எதிராக எவ்வாறு குரல் கொடுத்தார்கள்</strong><br />\r\n<br />\r\nஇங்கே அல்லாஹ் தனது அடியாரும், தூதரும், உற்ற நண்பரும் (கலீல்), தூய ஏகத்துவவாதிகளின் தலைவருமான இப்ராஹீம் (அலை) அவர்களைப் பற்றி நமக்குக் கூறுகிறான். அல்லாஹ்விடம் உண்மையாக நடப்பது, அவன் மீது முழு நம்பிக்கை (தவக்குல்) வைப்பது, அவனுக்கு எதனையும் இணையாக்காமல் அவனை மட்டுமே வணங்குவது, ஷிர்க்கையும் (இணைவைப்பு) அதைச் செய்பவர்களையும் புறக்கணிப்பது போன்ற இந்த முன்மாதிரியைப் பின்பற்றுவதற்காக, இக்கதையைத் தனது உம்மத்தினருக்கு (சமுதாயத்திற்கு) ஓதிக்காட்டுமாறு அல்லாஹ் தனது தூதர் முஹம்மது (ஸல்) அவர்களுக்குக் கட்டளையிட்டான். இப்ராஹீம் (அலை) அவர்களுக்கு அல்லாஹ் முன்னரே நேர்வழியை வழங்கியிருந்தான். அதாவது, அவர்கள் மிக இளம் வயதிலிருந்தே, மேன்மைமிக்க அல்லாஹ்வுக்கு இணையாகச் சிலைகளை வணங்கி வந்தத் தனது மக்களின் செயல்களைக் கண்டித்து வந்தார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">لِأَبِيهِ</span> <span class=\"quran-arabic-font text-success\">وَقَوْمِهِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تَعْبُدُونَ</span><br />\r\n<br />\r\n(அவர்கள் தனது தந்தை மற்றும் மக்களிடம்: \"நீங்கள் எதை வணங்குகிறீர்கள்?\" என்று கேட்டபோது) அதாவது: நீங்கள் இவ்வளவு தீவிரமாக வழிபடும் இந்தச் சிலைகள் எவை (என்பதாகும்).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">نَعْبُدُ</span> <span class=\"quran-arabic-font text-success\">أَصْنَاماً</span> <span class=\"quran-arabic-font text-success\">فَنَظَلُّ</span> <span class=\"quran-arabic-font text-success\">لَهَا</span> <span class=\"quran-arabic-font text-success\">عَـكِفِينَ</span><br />\r\n<br />\r\n(அதற்கு அவர்கள்: \"நாங்கள் சிலைகளை வணங்குகிறோம்; அவற்றுக்கே நாங்கள் எப்போதும் பணிந்து கிடக்கிறோம்\" என்று கூறினார்கள்.) அதாவது: நாங்கள் அவற்றைத் தொழுவதிலும், பிரார்த்தனை செய்வதிலும் உறுதியாக இருக்கிறோம்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">هَلْ</span> <span class=\"quran-arabic-font text-success\">يَسْمَعُونَكُمْ</span> <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">تَدْعُونَ</span> - <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">يَنفَعُونَكُمْ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">يَضُرُّونَ</span> - <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">وَجَدْنَآ</span> <span class=\"quran-arabic-font text-success\">ءَابَآءَنَا</span> <span class=\"quran-arabic-font text-success\">كَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">يَفْعَلُونَ</span><br />\r\n<br />\r\n(அதற்கு அவர்கள்: \"நீங்கள் அழைக்கும்போது அவை உங்களுக்குச் செவிமடுக்கின்றனவா? அல்லது அவை உங்களுக்கு ஏதேனும் நன்மை செய்கின்றனவா அல்லது தீங்கு விளைவிக்கின்றனவா?\" என்று கேட்டார்கள். அதற்கு அவர்கள்: \"இல்லை, ஆனால் எங்கள் தந்தைமார்கள் இவ்வாறே செய்வதை நாங்கள் கண்டோம்\" என்று கூறினார்கள்.) சிலைகளால் எதனையும் செய்ய முடியாது என்பதை அவர்கள் அறிந்திருந்தார்கள். இருப்பினும், தங்கள் முன்னோர்கள் இதைச் செய்வதைக் கண்டதால், அவர்களது அடிச்சுவடுகளைப் பின்பற்றுவதில் அவர்கள் அவசரப்பட்டார்கள். எனவே, இப்ராஹீம் (அலை) அவர்கள் அவர்களிடம் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">أَفَرَءَيْتُمْ</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">كُنْتُمْ</span> <span class=\"quran-arabic-font text-success\">تَعْبُدُونَ</span> - <span class=\"quran-arabic-font text-success\">أَنتُمْ</span> <span class=\"quran-arabic-font text-success\">وَءَابَآؤُكُمُ</span> <span class=\"quran-arabic-font text-success\">الاٌّقْدَمُونَ</span> - <span class=\"quran-arabic-font text-success\">فَإِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">عَدُوٌّ</span> <span class=\"quran-arabic-font text-success\">لِى</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">رَبَّ</span> <span class=\"quran-arabic-font text-success\">الْعَـلَمِينَ</span><br />\r\n<br />\r\n(நீங்களும் உங்களது மூதாதையர்களும் எதனை வணங்கிக் கொண்டிருந்தீர்கள் என்பதைச் சிந்தித்தீர்களா? அகிலங்களின் இறைவனைத் தவிர, மற்றவை அனைத்தும் எனக்குப் பகைவர்களே! என்று கூறினார்கள்.) அதாவது, 'இந்தச் சிலைகளுக்கு ஏதேனும் ஆற்றலோ அல்லது செல்வாக்கோ இருந்தால், அவை எனக்குத் தீங்கு இழைக்கட்டும். ஏனெனில், நான் அவற்றின் எதிரி; நான் அவற்றைப் பற்றிக் கவலைப்படவோ அல்லது அவற்றைப் பொருட்படுத்தவோ மாட்டேன்.' இது அல்லாஹ் நூஹ் (அலை) அவர்களைப் பற்றி விவரித்ததைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَأَجْمِعُواْ</span> <span class=\"quran-arabic-font text-success\">أَمْرَكُمْ</span> <span class=\"quran-arabic-font text-success\">وَشُرَكَآءَكُمْ</span><br />\r\n<br />\r\n(எனவே, நீங்களும் உங்கள் கூட்டாளிகளும் சேர்ந்து உங்கள் திட்டத்தை உறுதி செய்து கொள்ளுங்கள்) (<a href=\"qurandisp.php?sura=10&ayah=71\" class=\"link\">10:71</a>). மேலும் ஹூத் (அலை) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">نَّقُولُ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">اعْتَرَاكَ</span> <span class=\"quran-arabic-font text-success\">بَعْضُ</span> <span class=\"quran-arabic-font text-success\">ءَالِهَتِنَا</span> <span class=\"quran-arabic-font text-success\">بِسُوءٍ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">إِنِّى</span> <span class=\"quran-arabic-font text-success\">أُشْهِدُ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَاشْهَدُواْ</span> <span class=\"quran-arabic-font text-success\">أَنِّى</span> <span class=\"quran-arabic-font text-success\">بَرِىءٌ</span> <span class=\"quran-arabic-font text-success\">مِّمَّا</span> <span class=\"quran-arabic-font text-success\">تُشْرِكُونَ</span> - <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِهِ</span> <span class=\"quran-arabic-font text-success\">فَكِيدُونِى</span> <span class=\"quran-arabic-font text-success\">جَمِيعًا</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">تُنظِرُونِ</span> - <span class=\"quran-arabic-font text-success\">إِنِّى</span> <span class=\"quran-arabic-font text-success\">تَوَكَّلْتُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">رَبِّى</span> <span class=\"quran-arabic-font text-success\">وَرَبِّكُمْ</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دَآبَّةٍ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">ءاخِذٌ</span> <span class=\"quran-arabic-font text-success\">بِنَاصِيَتِهَآ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">رَبِّى</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">صِرَطٍ</span> <span class=\"quran-arabic-font text-success\">مُّسْتَقِيمٍ</span><br />\r\n<br />\r\n(“எங்கள் கடவுள்களில் சிலர் உமக்குத் தீங்கிழைத்து விட்டார்கள் என்பதைத் தவிர நாங்கள் (வேறெதனையும்) கூறுவதற்கில்லை” (என்று அவர்கள் கூறினார்கள்). அதற்கு அவர்: “அல்லாஹ்வுக்கு இணையாக நீங்கள் எவற்றையெல்லாம் கருதுகிறீர்களோ, அவற்றிலிருந்து நான் விலகியவன் என்பதற்கு அல்லாஹ்வைச் சாட்சியாக்குகிறேன்; நீங்களும் சாட்சியாக இருங்கள். ஆகவே, நீங்கள் அனைவரும் சேர்ந்து எனக்கு எதிராகச் சதி செய்யுங்கள்; எனக்கு எவ்வித அவகாசமும் அளிக்காதீர்கள். எனது இறைவனும் உங்கள் இறைவனுமான அல்லாஹ்வின் மீதே நான் முழு நம்பிக்கை வைத்துள்ளேன். பூமியில் ஊர்ந்து செல்லும் எந்த உயிரினமானாலும் அதன் நெற்றி முடியைப் பிடித்துக் கொண்டிருப்பவனாக (அனைத்தையும் கட்டுப்படுத்துபவனாக) அவன் இருக்கிறான். நிச்சயமாக எனது இறைவன் நேரிய வழியில் இருக்கிறான்.\") (<a href=\"qurandisp.php?sura=11&ayah=54\" class=\"link\">11:54</a>-56). இதேபோல், இப்ராஹீம் (அலை) அவர்களும் அக்கூட்டத்தினரின் தெய்வங்களையும் சிலைகளையும் கண்டித்து இவ்வாறு கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكَيْفَ</span> <span class=\"quran-arabic-font text-success\">أَخَافُ</span> <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَشْرَكْتُمْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَخَافُونَ</span> <span class=\"quran-arabic-font text-success\">أَنَّكُمْ</span> <span class=\"quran-arabic-font text-success\">أَشْرَكْتُم</span> <span class=\"quran-arabic-font text-success\">بِاللَّهِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يُنَزِّلْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">سُلْطَانًا</span><br />\r\n<br />\r\n(நீங்கள் அல்லாஹ்வுக்கு இணைவைத்தவற்றுக்கு நான் எவ்வாறு அஞ்சுவேன்? ஆனால் அல்லாஹ்வுக்கு எதனை இணையாக்குவது பற்றி அவன் உங்களுக்கு எந்த ஆதாரத்தையும் இறக்காத நிலையில், நீங்கள் அவனுக்கு இணைவைப்பது குறித்து அஞ்சவில்லையா?) (<a href=\"qurandisp.php?sura=6&ayah=81\" class=\"link\">6:81</a>). மேலும் அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">كَانَتْ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">أُسْوَةٌ</span> <span class=\"quran-arabic-font text-success\">حَسَنَةٌ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">إِبْرَهِيمَ</span><br />\r\n<br />\r\n(நிச்சயமாக இப்ராஹீம் (அலை) அவர்களிடம் உங்களுக்கு ஒரு அழகிய முன்மாதிரி இருக்கிறது) - அவனது பின்வரும் கூற்று வரை:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">تُؤْمِنُواْ</span> <span class=\"quran-arabic-font text-success\">بِاللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَحْدَهُ</span><br />\r\n<br />\r\n(நீங்கள் அல்லாஹ்வை மட்டுமே நம்பிக்கை கொள்ளும் வரை) (<a href=\"qurandisp.php?sura=60&ayah=4\" class=\"link\">60:4</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِذْ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">إِبْرَهِيمُ</span> <span class=\"quran-arabic-font text-success\">لِأَبِيهِ</span> <span class=\"quran-arabic-font text-success\">وَقَوْمِهِ</span> <span class=\"quran-arabic-font text-success\">إِنَّنِى</span> <span class=\"quran-arabic-font text-success\">بَرَآءٌ</span> <span class=\"quran-arabic-font text-success\">مِّمَّا</span> <span class=\"quran-arabic-font text-success\">تَعْبُدُونَ</span> - <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">فَطَرَنِى</span> <span class=\"quran-arabic-font text-success\">فَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">سَيَهْدِينِ</span> - <span class=\"quran-arabic-font text-success\">وَجَعَلَهَا</span> <span class=\"quran-arabic-font text-success\">كَلِمَةً</span> <span class=\"quran-arabic-font text-success\">بَـقِيَةً</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">عَقِبِهِ</span> <span class=\"quran-arabic-font text-success\">لَعَلَّهُمْ</span> <span class=\"quran-arabic-font text-success\">يَرْجِعُونَ</span><br />\r\n<br />\r\n(இப்ராஹீம் (அலை) அவர்கள் தனது தந்தை மற்றும் மக்களிடம்: \"நிச்சயமாக நீங்கள் வணங்குபவற்றிலிருந்து நான் விலகியவன்; என்னைப்படைத்தவனைத் தவிர. நிச்சயமாக அவன் எனக்கு நேர்வழி காட்டுவான்\" என்று கூறியதை (நினைவு கூருங்கள்). மேலும், அவர்கள் (சத்தியத்திற்குத்) திரும்பி வரும் பொருட்டு, இந்த (ஏகத்துவ) வாக்கியத்தைத் தனது சந்ததியினரிடையே ஒரு நிலைத்திருக்கும் வார்த்தையாக ஆக்கினார்கள்.) (<a href=\"qurandisp.php?sura=43&ayah=26\" class=\"link\">43:26</a>-28). அதாவது: \"லா இலாஹ இல்லல்லாஹ்.\"<br />\r\n<br />\r\n<br />\r\n<br />","text":"அல்லாஹ்வின் உற்ற நண்பரான இப்ராஹீம் (அலை) அவர்கள் ஷிர்க்கிற்கு (இணைவைப்பிற்கு) எதிராக எவ்வாறு குரல் கொடுத்தார்கள்\n\r\n\n\r\nஇங்கே அல்லாஹ் தனது அடியாரும், தூதரும், உற்ற நண்பரும் (கலீல்), தூய ஏகத்துவவாதிகளின் தலைவருமான இப்ராஹீம் (அலை) அவர்களைப் பற்றி நமக்குக் கூறுகிறான். அல்லாஹ்விடம் உண்மையாக நடப்பது, அவன் மீது முழு நம்பிக்கை (தவக்குல்) வைப்பது, அவனுக்கு எதனையும் இணையாக்காமல் அவனை மட்டுமே வணங்குவது, ஷிர்க்கையும் (இணைவைப்பு) அதைச் செய்பவர்களையும் புறக்கணிப்பது போன்ற இந்த முன்மாதிரியைப் பின்பற்றுவதற்காக, இக்கதையைத் தனது உம்மத்தினருக்கு (சமுதாயத்திற்கு) ஓதிக்காட்டுமாறு அல்லாஹ் தனது தூதர் முஹம்மது (ஸல்) அவர்களுக்குக் கட்டளையிட்டான். இப்ராஹீம் (அலை) அவர்களுக்கு அல்லாஹ் முன்னரே நேர்வழியை வழங்கியிருந்தான். அதாவது, அவர்கள் மிக இளம் வயதிலிருந்தே, மேன்மைமிக்க அல்லாஹ்வுக்கு இணையாகச் சிலைகளை வணங்கி வந்தத் தனது மக்களின் செயல்களைக் கண்டித்து வந்தார்கள்.\n\r\n\n\r\nإِذْ قَالَ لِأَبِيهِ وَقَوْمِهِ مَا تَعْبُدُونَ\n\r\n\n\r\n(அவர்கள் தனது தந்தை மற்றும் மக்களிடம்: \"நீங்கள் எதை வணங்குகிறீர்கள்?\" என்று கேட்டபோது) அதாவது: நீங்கள் இவ்வளவு தீவிரமாக வழிபடும் இந்தச் சிலைகள் எவை (என்பதாகும்).\n\r\n\n\r\nقَالُواْ نَعْبُدُ أَصْنَاماً فَنَظَلُّ لَهَا عَـكِفِينَ\n\r\n\n\r\n(அதற்கு அவர்கள்: \"நாங்கள் சிலைகளை வணங்குகிறோம்; அவற்றுக்கே நாங்கள் எப்போதும் பணிந்து கிடக்கிறோம்\" என்று கூறினார்கள்.) அதாவது: நாங்கள் அவற்றைத் தொழுவதிலும், பிரார்த்தனை செய்வதிலும் உறுதியாக இருக்கிறோம்.\n\r\n\n\r\nقَالَ هَلْ يَسْمَعُونَكُمْ إِذْ تَدْعُونَ - أَوْ يَنفَعُونَكُمْ أَوْ يَضُرُّونَ - قَالُواْ بَلْ وَجَدْنَآ ءَابَآءَنَا كَذَلِكَ يَفْعَلُونَ\n\r\n\n\r\n(அதற்கு அவர்கள்: \"நீங்கள் அழைக்கும்போது அவை உங்களுக்குச் செவிமடுக்கின்றனவா? அல்லது அவை உங்களுக்கு ஏதேனும் நன்மை செய்கின்றனவா அல்லது தீங்கு விளைவிக்கின்றனவா?\" என்று கேட்டார்கள். அதற்கு அவர்கள்: \"இல்லை, ஆனால் எங்கள் தந்தைமார்கள் இவ்வாறே செய்வதை நாங்கள் கண்டோம்\" என்று கூறினார்கள்.) சிலைகளால் எதனையும் செய்ய முடியாது என்பதை அவர்கள் அறிந்திருந்தார்கள். இருப்பினும், தங்கள் முன்னோர்கள் இதைச் செய்வதைக் கண்டதால், அவர்களது அடிச்சுவடுகளைப் பின்பற்றுவதில் அவர்கள் அவசரப்பட்டார்கள். எனவே, இப்ராஹீம் (அலை) அவர்கள் அவர்களிடம் கூறினார்கள்:\n\r\n\n\r\nقَالَ أَفَرَءَيْتُمْ مَّا كُنْتُمْ تَعْبُدُونَ - أَنتُمْ وَءَابَآؤُكُمُ الاٌّقْدَمُونَ - فَإِنَّهُمْ عَدُوٌّ لِى إِلاَّ رَبَّ الْعَـلَمِينَ\n\r\n\n\r\n(நீங்களும் உங்களது மூதாதையர்களும் எதனை வணங்கிக் கொண்டிருந்தீர்கள் என்பதைச் சிந்தித்தீர்களா? அகிலங்களின் இறைவனைத் தவிர, மற்றவை அனைத்தும் எனக்குப் பகைவர்களே! என்று கூறினார்கள்.) அதாவது, 'இந்தச் சிலைகளுக்கு ஏதேனும் ஆற்றலோ அல்லது செல்வாக்கோ இருந்தால், அவை எனக்குத் தீங்கு இழைக்கட்டும். ஏனெனில், நான் அவற்றின் எதிரி; நான் அவற்றைப் பற்றிக் கவலைப்படவோ அல்லது அவற்றைப் பொருட்படுத்தவோ மாட்டேன்.' இது அல்லாஹ் நூஹ் (அலை) அவர்களைப் பற்றி விவரித்ததைப் போன்றதாகும்:\n\r\n\n\r\nفَأَجْمِعُواْ أَمْرَكُمْ وَشُرَكَآءَكُمْ\n\r\n\n\r\n(எனவே, நீங்களும் உங்கள் கூட்டாளிகளும் சேர்ந்து உங்கள் திட்டத்தை உறுதி செய்து கொள்ளுங்கள்) (10:71). மேலும் ஹூத் (அலை) அவர்கள் கூறினார்கள்:\n\r\n\n\r\nإِن نَّقُولُ إِلاَّ اعْتَرَاكَ بَعْضُ ءَالِهَتِنَا بِسُوءٍ قَالَ إِنِّى أُشْهِدُ اللَّهِ وَاشْهَدُواْ أَنِّى بَرِىءٌ مِّمَّا تُشْرِكُونَ - مِن دُونِهِ فَكِيدُونِى جَمِيعًا ثُمَّ لاَ تُنظِرُونِ - إِنِّى تَوَكَّلْتُ عَلَى اللَّهِ رَبِّى وَرَبِّكُمْ مَّا مِن دَآبَّةٍ إِلاَّ هُوَ ءاخِذٌ بِنَاصِيَتِهَآ إِنَّ رَبِّى عَلَى صِرَطٍ مُّسْتَقِيمٍ\n\r\n\n\r\n(“எங்கள் கடவுள்களில் சிலர் உமக்குத் தீங்கிழைத்து விட்டார்கள் என்பதைத் தவிர நாங்கள் (வேறெதனையும்) கூறுவதற்கில்லை” (என்று அவர்கள் கூறினார்கள்). அதற்கு அவர்: “அல்லாஹ்வுக்கு இணையாக நீங்கள் எவற்றையெல்லாம் கருதுகிறீர்களோ, அவற்றிலிருந்து நான் விலகியவன் என்பதற்கு அல்லாஹ்வைச் சாட்சியாக்குகிறேன்; நீங்களும் சாட்சியாக இருங்கள். ஆகவே, நீங்கள் அனைவரும் சேர்ந்து எனக்கு எதிராகச் சதி செய்யுங்கள்; எனக்கு எவ்வித அவகாசமும் அளிக்காதீர்கள். எனது இறைவனும் உங்கள் இறைவனுமான அல்லாஹ்வின் மீதே நான் முழு நம்பிக்கை வைத்துள்ளேன். பூமியில் ஊர்ந்து செல்லும் எந்த உயிரினமானாலும் அதன் நெற்றி முடியைப் பிடித்துக் கொண்டிருப்பவனாக (அனைத்தையும் கட்டுப்படுத்துபவனாக) அவன் இருக்கிறான். நிச்சயமாக எனது இறைவன் நேரிய வழியில் இருக்கிறான்.\") (11:54-56). இதேபோல், இப்ராஹீம் (அலை) அவர்களும் அக்கூட்டத்தினரின் தெய்வங்களையும் சிலைகளையும் கண்டித்து இவ்வாறு கூறினார்கள்:\n\r\n\n\r\nوَكَيْفَ أَخَافُ مَآ أَشْرَكْتُمْ وَلاَ تَخَافُونَ أَنَّكُمْ أَشْرَكْتُم بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِ عَلَيْكُمْ سُلْطَانًا\n\r\n\n\r\n(நீங்கள் அல்லாஹ்வுக்கு இணைவைத்தவற்றுக்கு நான் எவ்வாறு அஞ்சுவேன்? ஆனால் அல்லாஹ்வுக்கு எதனை இணையாக்குவது பற்றி அவன் உங்களுக்கு எந்த ஆதாரத்தையும் இறக்காத நிலையில், நீங்கள் அவனுக்கு இணைவைப்பது குறித்து அஞ்சவில்லையா?) (6:81). மேலும் அல்லாஹ் கூறினான்:\n\r\n\n\r\nقَدْ كَانَتْ لَكُمْ أُسْوَةٌ حَسَنَةٌ فِى إِبْرَهِيمَ\n\r\n\n\r\n(நிச்சயமாக இப்ராஹீம் (அலை) அவர்களிடம் உங்களுக்கு ஒரு அழகிய முன்மாதிரி இருக்கிறது) - அவனது பின்வரும் கூற்று வரை:\n\r\n\n\r\nحَتَّى تُؤْمِنُواْ بِاللَّهِ وَحْدَهُ\n\r\n\n\r\n(நீங்கள் அல்லாஹ்வை மட்டுமே நம்பிக்கை கொள்ளும் வரை) (60:4).\n\r\n\n\r\nوَإِذْ قَالَ إِبْرَهِيمُ لِأَبِيهِ وَقَوْمِهِ إِنَّنِى بَرَآءٌ مِّمَّا تَعْبُدُونَ - إِلاَّ الَّذِى فَطَرَنِى فَإِنَّهُ سَيَهْدِينِ - وَجَعَلَهَا كَلِمَةً بَـقِيَةً فِى عَقِبِهِ لَعَلَّهُمْ يَرْجِعُونَ\n\r\n\n\r\n(இப்ராஹீம் (அலை) அவர்கள் தனது தந்தை மற்றும் மக்களிடம்: \"நிச்சயமாக நீங்கள் வணங்குபவற்றிலிருந்து நான் விலகியவன்; என்னைப்படைத்தவனைத் தவிர. நிச்சயமாக அவன் எனக்கு நேர்வழி காட்டுவான்\" என்று கூறியதை (நினைவு கூருங்கள்). மேலும், அவர்கள் (சத்தியத்திற்குத்) திரும்பி வரும் பொருட்டு, இந்த (ஏகத்துவ) வாக்கியத்தைத் தனது சந்ததியினரிடையே ஒரு நிலைத்திருக்கும் வார்த்தையாக ஆக்கினார்கள்.) (43:26-28). அதாவது: \"லா இலாஹ இல்லல்லாஹ்.\""},"78":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=82\" class=\"link\">26:82</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:82 ஐ பார்க்கவும்"},"79":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=82\" class=\"link\">26:82</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:82 ஐ பார்க்கவும்"},"80":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=82\" class=\"link\">26:82</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:82 ஐ பார்க்கவும்"},"81":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=82\" class=\"link\">26:82</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:82 ஐ பார்க்கவும்"},"82":{"html":"<strong>இப்ராஹீம் (அலை) அவர்கள் தம்மீது அல்லாஹ் புரிந்த அருட்கொடைகளைக் குறிப்பிடுதல்</strong><br />\r\n<br />\r\nஇப்ராஹீம் (அலை) அவர்கள் கூறினார்கள்: \"இவற்றைச் செய்பவனைத் தவிர வேறு எவரையும் நான் வணங்கமாட்டேன்: <span class=\"quran-arabic-font text-success\">﴾الَّذِي</span> <span class=\"quran-arabic-font text-success\">خَلَقَنِي</span> <span class=\"quran-arabic-font text-success\">فَهُوَ</span> <span class=\"quran-arabic-font text-success\">يَهْدِينِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அவனே என்னைப் படைத்தான்; அவனே எனக்கு நேர்வழி காட்டுகிறான்.) அவனே படைப்பாளன்; அவன் தன் படைப்புகளுக்குச் சில விஷயங்களை விதித்து, அவற்றை நோக்கி அவர்களை வழிநடத்துகிறான். எனவே, ஒவ்வொரு மனிதனும் தனக்கென விதிக்கப்பட்ட பாதையையே பின்பற்றுகிறான். அல்லாஹ் தான் நாடியவர்களுக்கு நேர்வழி காட்டுகிறான்; தான் நாடியவர்களை வழிகேட்டில் விட்டுவிடுகிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَالَّذِي</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">يُطْعِمُنِي</span> <span class=\"quran-arabic-font text-success\">وَيَسْقِينِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அவனே எனக்கு உணவளிக்கிறான்; அவனே எனக்குப் புகட்டுகிறான்.) அவன் எனது படைப்பாளன்; வானங்களிலும் பூமியிலும் அவன் ஏற்பாடு செய்துள்ளவற்றிலிருந்து எனக்கு வாழ்வாதாரத்தை வழங்குகிறான். அவன் மேகங்களைச் செலுத்தி, மழையைப் பொழியச் செய்கிறான். அதன் மூலம் பூமியை உயிர்ப்பித்து, மனிதர்களுக்கு உணவாக அதன் கனிகளை வெளிப்படுத்துகிறான். அவன் தண்ணீரைத் தூய்மையாகவும் இனிமையாகவும் இறக்குகிறான்; அதன் மூலம் தான் படைத்த விலங்குகள் மற்றும் மனிதர்களில் ஏராளமானோர் தாகம் தணித்துக் கொள்ளச் செய்கிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَإِذَا</span> <span class=\"quran-arabic-font text-success\">مَرِضْتُ</span> <span class=\"quran-arabic-font text-success\">فَهُوَ</span> <span class=\"quran-arabic-font text-success\">يَشْفِينِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நான் நோயுற்றபோது, அவனே எனக்குக் குணமளிக்கிறான்.) இங்கே, நோயை அல்லாஹ்வே விதித்தாலும், அவன் மீதுள்ள மரியாதையின் காரணமாக இப்ராஹீம் (அலை) அவர்கள் நோயைத் தம்மோடு தொடர்புபடுத்திக் கூறினார்கள். இதைப் போன்றே, தொழுகையில் <span class=\"quran-arabic-font text-success\">﴾اهْدِنَا</span> <span class=\"quran-arabic-font text-success\">الصِّرَاطَ</span> <span class=\"quran-arabic-font text-success\">الْمُسْتَقِيمَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(எங்களை நேரான வழியில் நடத்துவாயாக) (<a href=\"qurandisp.php?sura=1&ayah=6\" class=\"link\">1:6</a>) என்று அந்த சூராவின் இறுதிவரை ஓதுமாறு அல்லாஹ் நமக்குக் கட்டளையிடுகிறான். இங்கு அருளும் நேர்வழியும் மேன்மைமிக்க அல்லாஹ்வுடன் தொடர்புபடுத்தப்பட்டுள்ளன; ஆனால் கோபம் தொடர்பான வினைச்சொல்லின் எழுவாய் தவிர்க்கப்பட்டு, வழிகேடு மக்களுடன் தொடர்புபடுத்தப்பட்டுள்ளது. ஜின்கள் பின்வருமாறு கூறியதைப் போன்றதே இதுவும்: <span class=\"quran-arabic-font text-success\">﴾وَأَنَّا</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">نَدْرِي</span> <span class=\"quran-arabic-font text-success\">أَشَرٌّ</span> <span class=\"quran-arabic-font text-success\">أُرِيدَ</span> <span class=\"quran-arabic-font text-success\">بِمَن</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">أَرَادَ</span> <span class=\"quran-arabic-font text-success\">بِهِمْ</span> <span class=\"quran-arabic-font text-success\">رَبُّهُمْ</span> <span class=\"quran-arabic-font text-success\">رَشَدًا</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(\"பூமியில் உள்ளவர்களுக்குத் தீங்கு நாடப்பட்டுள்ளதா அல்லது அவர்களின் இறைவன் அவர்களுக்கு நேர்வழியை நாடுகிறானா என்பதை நாங்கள் அறியமாட்டோம்.\") (<a href=\"qurandisp.php?sura=72&ayah=10\" class=\"link\">72:10</a>). அவ்வாறே இப்ராஹீம் (அலை) அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾وَإِذَا</span> <span class=\"quran-arabic-font text-success\">مَرِضْتُ</span> <span class=\"quran-arabic-font text-success\">فَهُوَ</span> <span class=\"quran-arabic-font text-success\">يَشْفِينِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நான் நோயுற்றபோது, அவனே எனக்குக் குணமளிக்கிறான்.) அதாவது, \"நான் நோய்வாய்ப்படும்போது, குணமடைவதற்குரிய காரணங்களைக் கொண்டு என்னைக் குணப்படுத்துபவன் அவனைத் தவிர வேறு யாருமில்லை.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَالَّذِي</span> <span class=\"quran-arabic-font text-success\">يُمِيتُنِي</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يُحْيِينِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும், அவனே என்னை மரணிக்கச் செய்கிறான்; பிறகு அவனே என்னை உயிர்ப்பிப்பான்.) அவனே உயிரைக் கொடுப்பவனும் மரணத்தை ஏற்படுத்துபவனும் ஆவான். அவனைத் தவிர வேறு எவராலும் இதனைச் செய்ய முடியாது; ஏனெனில் அவனே முதன்முதலில் படைப்பவனும், மீண்டும் உயிர்ப்பிப்பவனும் ஆவான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَالَّذِي</span> <span class=\"quran-arabic-font text-success\">أَطْمَعُ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَغْفِرَ</span> <span class=\"quran-arabic-font text-success\">لِي</span> <span class=\"quran-arabic-font text-success\">خَطِيئَتِي</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الدِّينِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும், கூலி கொடுக்கப்படும் நாளில் என் தவறுகளை அவன் மன்னிப்பான் என்று நான் ஆதரவு வைக்கிறேன்.) அதாவது, இவ்வுலகிலோ அல்லது மறுமையிலோ அவனைத் தவிர வேறு எவராலும் பாவங்களை மன்னிக்க முடியாது. அல்லாஹ்வைத் தவிர பாவங்களை மன்னிப்பவர் யார்? அவன் தான் நாடுவது எதனையும் செய்யக்கூடியவன் ஆவான்.<br />\r\n<br />\r\n<br />\r\n<br />","text":"இப்ராஹீம் (அலை) அவர்கள் தம்மீது அல்லாஹ் புரிந்த அருட்கொடைகளைக் குறிப்பிடுதல்\n\r\n\n\r\nஇப்ராஹீம் (அலை) அவர்கள் கூறினார்கள்: \"இவற்றைச் செய்பவனைத் தவிர வேறு எவரையும் நான் வணங்கமாட்டேன்: ﴾الَّذِي خَلَقَنِي فَهُوَ يَهْدِينِ ﴿\n\r\n\n\r\n(அவனே என்னைப் படைத்தான்; அவனே எனக்கு நேர்வழி காட்டுகிறான்.) அவனே படைப்பாளன்; அவன் தன் படைப்புகளுக்குச் சில விஷயங்களை விதித்து, அவற்றை நோக்கி அவர்களை வழிநடத்துகிறான். எனவே, ஒவ்வொரு மனிதனும் தனக்கென விதிக்கப்பட்ட பாதையையே பின்பற்றுகிறான். அல்லாஹ் தான் நாடியவர்களுக்கு நேர்வழி காட்டுகிறான்; தான் நாடியவர்களை வழிகேட்டில் விட்டுவிடுகிறான்.\n\r\n\n\r\n﴾وَالَّذِي هُوَ يُطْعِمُنِي وَيَسْقِينِ ﴿\n\r\n\n\r\n(அவனே எனக்கு உணவளிக்கிறான்; அவனே எனக்குப் புகட்டுகிறான்.) அவன் எனது படைப்பாளன்; வானங்களிலும் பூமியிலும் அவன் ஏற்பாடு செய்துள்ளவற்றிலிருந்து எனக்கு வாழ்வாதாரத்தை வழங்குகிறான். அவன் மேகங்களைச் செலுத்தி, மழையைப் பொழியச் செய்கிறான். அதன் மூலம் பூமியை உயிர்ப்பித்து, மனிதர்களுக்கு உணவாக அதன் கனிகளை வெளிப்படுத்துகிறான். அவன் தண்ணீரைத் தூய்மையாகவும் இனிமையாகவும் இறக்குகிறான்; அதன் மூலம் தான் படைத்த விலங்குகள் மற்றும் மனிதர்களில் ஏராளமானோர் தாகம் தணித்துக் கொள்ளச் செய்கிறான்.\n\r\n\n\r\n﴾وَإِذَا مَرِضْتُ فَهُوَ يَشْفِينِ ﴿\n\r\n\n\r\n(நான் நோயுற்றபோது, அவனே எனக்குக் குணமளிக்கிறான்.) இங்கே, நோயை அல்லாஹ்வே விதித்தாலும், அவன் மீதுள்ள மரியாதையின் காரணமாக இப்ராஹீம் (அலை) அவர்கள் நோயைத் தம்மோடு தொடர்புபடுத்திக் கூறினார்கள். இதைப் போன்றே, தொழுகையில் ﴾اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ ﴿\n\r\n\n\r\n(எங்களை நேரான வழியில் நடத்துவாயாக) (1:6) என்று அந்த சூராவின் இறுதிவரை ஓதுமாறு அல்லாஹ் நமக்குக் கட்டளையிடுகிறான். இங்கு அருளும் நேர்வழியும் மேன்மைமிக்க அல்லாஹ்வுடன் தொடர்புபடுத்தப்பட்டுள்ளன; ஆனால் கோபம் தொடர்பான வினைச்சொல்லின் எழுவாய் தவிர்க்கப்பட்டு, வழிகேடு மக்களுடன் தொடர்புபடுத்தப்பட்டுள்ளது. ஜின்கள் பின்வருமாறு கூறியதைப் போன்றதே இதுவும்: ﴾وَأَنَّا لَا نَدْرِي أَشَرٌّ أُرِيدَ بِمَن فِي الْأَرْضِ أَمْ أَرَادَ بِهِمْ رَبُّهُمْ رَشَدًا ﴿\n\r\n\n\r\n(\"பூமியில் உள்ளவர்களுக்குத் தீங்கு நாடப்பட்டுள்ளதா அல்லது அவர்களின் இறைவன் அவர்களுக்கு நேர்வழியை நாடுகிறானா என்பதை நாங்கள் அறியமாட்டோம்.\") (72:10). அவ்வாறே இப்ராஹீம் (அலை) அவர்கள் கூறினார்கள்: ﴾وَإِذَا مَرِضْتُ فَهُوَ يَشْفِينِ ﴿\n\r\n\n\r\n(நான் நோயுற்றபோது, அவனே எனக்குக் குணமளிக்கிறான்.) அதாவது, \"நான் நோய்வாய்ப்படும்போது, குணமடைவதற்குரிய காரணங்களைக் கொண்டு என்னைக் குணப்படுத்துபவன் அவனைத் தவிர வேறு யாருமில்லை.\"\n\r\n\n\r\n﴾وَالَّذِي يُمِيتُنِي ثُمَّ يُحْيِينِ ﴿\n\r\n\n\r\n(மேலும், அவனே என்னை மரணிக்கச் செய்கிறான்; பிறகு அவனே என்னை உயிர்ப்பிப்பான்.) அவனே உயிரைக் கொடுப்பவனும் மரணத்தை ஏற்படுத்துபவனும் ஆவான். அவனைத் தவிர வேறு எவராலும் இதனைச் செய்ய முடியாது; ஏனெனில் அவனே முதன்முதலில் படைப்பவனும், மீண்டும் உயிர்ப்பிப்பவனும் ஆவான்.\n\r\n\n\r\n﴾وَالَّذِي أَطْمَعُ أَن يَغْفِرَ لِي خَطِيئَتِي يَوْمَ الدِّينِ ﴿\n\r\n\n\r\n(மேலும், கூலி கொடுக்கப்படும் நாளில் என் தவறுகளை அவன் மன்னிப்பான் என்று நான் ஆதரவு வைக்கிறேன்.) அதாவது, இவ்வுலகிலோ அல்லது மறுமையிலோ அவனைத் தவிர வேறு எவராலும் பாவங்களை மன்னிக்க முடியாது. அல்லாஹ்வைத் தவிர பாவங்களை மன்னிப்பவர் யார்? அவன் தான் நாடுவது எதனையும் செய்யக்கூடியவன் ஆவான்."},"83":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=89\" class=\"link\">26:89</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:89 ஐ பார்க்கவும்"},"84":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=89\" class=\"link\">26:89</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:89 ஐ பார்க்கவும்"},"85":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=89\" class=\"link\">26:89</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:89 ஐ பார்க்கவும்"},"86":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=89\" class=\"link\">26:89</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:89 ஐ பார்க்கவும்"},"87":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=89\" class=\"link\">26:89</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:89 ஐ பார்க்கவும்"},"88":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=89\" class=\"link\">26:89</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:89 ஐ பார்க்கவும்"},"89":{"html":"<strong>இப்ராஹீம் (அலை) அவர்கள் தனக்காகவும் தனது தந்தைக்காகவும் செய்த பிரார்த்தனை</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾رَبِّ</span> <span class=\"quran-arabic-font text-success\">هَبْ</span> <span class=\"quran-arabic-font text-success\">لِى</span> <span class=\"quran-arabic-font text-success\">حُكْماً﴿</span><br />\r\n(என் இறைவனே! எனக்கு ஞானத்தை வழங்குவாயாக!) இங்கே இப்ராஹீம் (அலை) அவர்கள் தனது இறைவனிடம் தனக்கு 'ஹுக்ம்' வழங்குமாறு வேண்டுகிறார்கள். \"இது அறிவைக் குறிக்கிறது\" என்று இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள். <span class=\"quran-arabic-font text-success\">﴾وَأَلْحِقْنِى</span> <span class=\"quran-arabic-font text-success\">بِالصَّـلِحِينَ﴿</span><br />\r\n<br />\r\n(மேலும் என்னை நல்லோர்களுடன் சேர்த்துவிடுவாயாக.) இதன் பொருள், 'இவ்வுலகிலும் மறுமையிலும் என்னை நல்லோர்களில் ஒருவனாக ஆக்குவாயாக' என்பதாகும். இது நபி (ஸல்) அவர்கள் மரணிக்கும் தருவாயில் மூன்று முறை கூறிய வார்த்தைகளைப் போன்றது: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">اللَّهُمَّ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الرَّفِيقِ</span> <span class=\"quran-arabic-font text-success\">الْأَعْلَى</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(யா அல்லாஹ், மேலான தோழருடன் (சொர்க்கத்தில்) சேர்த்துவிடுவாயாக). <span class=\"quran-arabic-font text-success\">﴾وَاجْعَل</span> <span class=\"quran-arabic-font text-success\">لِّى</span> <span class=\"quran-arabic-font text-success\">لِسَانَ</span> <span class=\"quran-arabic-font text-success\">صِدْقٍ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْآخِرِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும், பிற்காலத்தவர்களிடையே எனக்கு நற்பெயரை ஏற்படுத்துவாயாக.) இதன் பொருள், 'எனது மரணத்திற்குப் பிறகு நான் நல்ல முறையில் நினைவுகூரப்பட வேண்டும்; மக்கள் என்னைப் புகழவும், ஒரு முன்மாதிரியாக எடுத்துக்கொள்ளவும் வேண்டும்' என்பதாகும். இது பின்வரும் வசனத்தைப் போன்றது, <span class=\"quran-arabic-font text-success\">﴾وَتَرَكْنَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْآخِرِينَ</span> <span class=\"quran-arabic-font text-success\">سَلَـمٌ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">إِبْرَهِيمَ</span> <span class=\"quran-arabic-font text-success\">كَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">نَجْزِى</span> <span class=\"quran-arabic-font text-success\">الْمُحْسِنِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(பிற்காலத்தவர்களிடையே அவருக்காக (ஒரு நற்பெயரை) நாம் விட்டுவைத்தோம்: \"இப்ராஹீம் மீது ஸலாம் (சாந்தி) உண்டாவதாக. இவ்வாறே நாம் நன்மை செய்பவர்களுக்குக் கூலி வழங்குகிறோம்.\") (<a href=\"qurandisp.php?sura=37&ayah=108\" class=\"link\">37:108</a>-110) <span class=\"quran-arabic-font text-success\">﴾وَاجْعَلْنِى</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">وَرَثَةِ</span> <span class=\"quran-arabic-font text-success\">جَنَّةِ</span> <span class=\"quran-arabic-font text-success\">النَّعِيمِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(இன்பமயமான சொர்க்கத்தின் வாரிசுதாரர்களில் ஒருவனாக என்னை ஆக்குவாயாக.) இதன் பொருள், 'இவ்வுலகில் நான் மறைந்த பிறகு எனக்கு நற்பெயரை வழங்கி, மறுமையிலும் இன்பமயமான சொர்க்கத்தின் வாரிசுதாரர்களில் ஒருவனாக என்னை ஆக்குவாயாக' என்பதாகும். <span class=\"quran-arabic-font text-success\">﴾وَاغْفِرْ</span> <span class=\"quran-arabic-font text-success\">لِأَبِي</span> <span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الضَّالِّينَ﴿</span><br />\r\n<br />\r\n(எனது தந்தையை மன்னிப்பாயாக; நிச்சயமாக அவர் வழிதவறியவர்களில் ஒருவராக இருக்கிறார்)<br />\r\n<br />\r\nஇது பின்வரும் வசனத்தைப் போன்றது, <span class=\"quran-arabic-font text-success\">﴾رَبَّنَا</span> <span class=\"quran-arabic-font text-success\">اغْفِرْ</span> <span class=\"quran-arabic-font text-success\">لِى</span> <span class=\"quran-arabic-font text-success\">وَلِوَالِدَىَّ﴿</span><br />\r\n<br />\r\n(எங்கள் இறைவனே! எனக்கும், எனது பெற்றோருக்கும் மன்னிப்பு அருள்வாயாக) (<a href=\"qurandisp.php?sura=14&ayah=41\" class=\"link\">14:41</a>). ஆனால், இப்ராஹீம் (அலை) அவர்கள் தனது தந்தைக்காக இவ்வாறு வேண்டுவதை பின்னர் நிறுத்திக்கொண்டார்கள். அல்லாஹ் கூறுவது போல: <span class=\"quran-arabic-font text-success\">﴾وَمَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">اسْتِغْفَارُ</span> <span class=\"quran-arabic-font text-success\">إِبْرَهِيمَ</span> <span class=\"quran-arabic-font text-success\">لِأَبِيهِ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">مَّوْعِدَةٍ</span> <span class=\"quran-arabic-font text-success\">وَعَدَهَآ</span> <span class=\"quran-arabic-font text-success\">إِيَّاهُ﴿</span><br />\r\n<br />\r\n(இப்ராஹீம் தனது தந்தைக்காக மன்னிப்புக் கோரியதெல்லாம், அவர் தனது தந்தைக்கு அளித்திருந்த ஒரு வாக்குறுதியின் காரணமாகவே தவிர வேறில்லை) (<a href=\"qurandisp.php?sura=9&ayah=114\" class=\"link\">9:114</a>), எதுவரை என்றால்: <span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">إِبْرَهِيمَ</span> <span class=\"quran-arabic-font text-success\">لأَوَّاهٌ</span> <span class=\"quran-arabic-font text-success\">حَلِيمٌ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக இப்ராஹீம் மிகவும் இரக்கமுள்ளவராகவும், சகிப்புத்தன்மை கொண்டவராகவும் இருந்தார்) (<a href=\"qurandisp.php?sura=9&ayah=114\" class=\"link\">9:114</a>).<br />\r\n<br />\r\nஅல்லாஹ், இப்ராஹீம் (அலை) அவர்கள் தனது தந்தைக்காக மன்னிப்புக் கோருவதைத் தடுத்தான். அவன் கூறுவது போல: <span class=\"quran-arabic-font text-success\">﴾قَدْ</span> <span class=\"quran-arabic-font text-success\">كَانَتْ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">أُسْوَةٌ</span> <span class=\"quran-arabic-font text-success\">حَسَنَةٌ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">إِبْرَهِيمَ</span> <span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">مَعَهُ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக இப்ராஹீமிடமும் அவருடன் இருந்தவர்களிடமும் உங்களுக்கு ஓர் அழகிய முன்மாதிரி இருக்கிறது), அவன் பின்வருமாறு கூறும் வரை: <span class=\"quran-arabic-font text-success\">﴾وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَمْلِكُ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ﴿</span><br />\r\n<br />\r\n(ஆனால் அல்லாஹ்விடமிருந்து உமக்காக எதையும் செய்யும் அதிகாரம் எனக்கில்லை.) (<a href=\"qurandisp.php?sura=60&ayah=4\" class=\"link\">60:4</a>), <span class=\"quran-arabic-font text-success\">﴾وَلاَ</span> <span class=\"quran-arabic-font text-success\">تُخْزِنِى</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يُبْعَثُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(படைப்பினங்கள் எழுப்பப்படும் நாளில் என்னை இழிவுபடுத்தாதே.) இதன் பொருள், 'மறுமை நாளில், ஆதி முதல் அந்தம் வரையுள்ள அனைத்துப் படைப்புகளும் எழுப்பப்படும் நாளில் என்னை இழிவிலிருந்து பாதுகாப்பாயாக' என்பதாகும். அல்-புகாரி பதிவு செய்துள்ளார்கள்: அபூ ஹுரைரா (ரழி) அவர்கள் கூறினார்கள், நபி (ஸல்) அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">إِبْرَاهِيمَ</span> <span class=\"quran-arabic-font text-success\">رَأَى</span> <span class=\"quran-arabic-font text-success\">أَبَاهُ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَةِ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">الْغَبَرَةُ</span> <span class=\"quran-arabic-font text-success\">وَالْقَتَرَة</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மறுமை நாளில் இப்ராஹீம் (அலை) அவர்கள் தனது தந்தையைப் புழுதியும் இருளும் சூழ்ந்தவராகக் காண்பார்கள்.)<br />\r\n<br />\r\nஅபூ ஹுரைரா (ரழி) அவர்கள் அறிவிக்கும் மற்றொரு அறிவிப்பில், நபி (ஸல்) அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">يَلْقَى</span> <span class=\"quran-arabic-font text-success\">إِبْرَاهِيمُ</span> <span class=\"quran-arabic-font text-success\">أَبَاهُ</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُ</span>: <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">إِنَّكَ</span> <span class=\"quran-arabic-font text-success\">وَعَدْتَنِي</span> <span class=\"quran-arabic-font text-success\">أَنَّكَ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تُخْزِينِي</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يُبْعَثُونَ،</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى</span>: <span class=\"quran-arabic-font text-success\">إِنِّي</span> <span class=\"quran-arabic-font text-success\">حَرَّمْتُ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْكَافِرين</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(இப்ராஹீம் (அலை) அவர்கள் தனது தந்தையைச் சந்திப்பார்கள். அப்போது அவர், \"என் இறைவனே! படைப்புகள் எழுப்பப்படும் நாளில் என்னை இழிவுபடுத்த மாட்டாய் என்று எனக்கு நீ வாக்குறுதி அளித்தாயே!\" என்று வேண்டுவார்கள். அதற்கு அல்லாஹ், \"நிச்சயமாக நான் நிராகரிப்பவர்களுக்குச் சொர்க்கத்தைத் தடை செய்துவிட்டேன்\" என்று கூறுவான்.)<br />\r\n<br />\r\nஅவர்கள் (புகாரி) நபிமார்களைப் (அலை) பற்றிய ஹதீஸ்களிலும் இதைப் பதிவு செய்துள்ளார்கள், அதன் வாசகம் பின்வருமாறு: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">يَلْقَى</span> <span class=\"quran-arabic-font text-success\">إِبْرَاهِيمُ</span> <span class=\"quran-arabic-font text-success\">أَبَاهُ</span> <span class=\"quran-arabic-font text-success\">آزَرَ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَةِ،</span> <span class=\"quran-arabic-font text-success\">وَعَلَى</span> <span class=\"quran-arabic-font text-success\">وَجْهِ</span> <span class=\"quran-arabic-font text-success\">آزَرَ</span> <span class=\"quran-arabic-font text-success\">قَتَرَةٌ</span> <span class=\"quran-arabic-font text-success\">وَغَبَرَةٌ،</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">إِبْرَاهِيمُ</span>: <span class=\"quran-arabic-font text-success\">أَلَمْ</span> <span class=\"quran-arabic-font text-success\">أَقُلْ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تَعْصِينِي،</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُ</span> <span class=\"quran-arabic-font text-success\">أَبُوهُ</span>: <span class=\"quran-arabic-font text-success\">فَالْيَوْمَ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">أَعْصِيكَ،</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُ</span> <span class=\"quran-arabic-font text-success\">إِبْرَاهِيمُ</span>: <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">إِنَّكَ</span> <span class=\"quran-arabic-font text-success\">وَعَدْتَنِي</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">تُخْزِيَنِي</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يُبْعَثُونَ،</span> <span class=\"quran-arabic-font text-success\">فَأَيُّ</span> <span class=\"quran-arabic-font text-success\">خِزْيٍ</span> <span class=\"quran-arabic-font text-success\">أَخْزَى</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَبِي</span> <span class=\"quran-arabic-font text-success\">الْأَبْعَدِ</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُ</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">تَعَالَى</span>: <span class=\"quran-arabic-font text-success\">إِنِّي</span> <span class=\"quran-arabic-font text-success\">حَرَّمْتُ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْكَافِرِينَ،</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يُقَالُ</span>: <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">إِبْرَاهِيمُ</span> <span class=\"quran-arabic-font text-success\">انْظُرْ</span> <span class=\"quran-arabic-font text-success\">تَحْتَ</span> <span class=\"quran-arabic-font text-success\">رِجْلِكَ،</span> <span class=\"quran-arabic-font text-success\">فَيَنْظُرَ،فَإِذَا</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">بِذِيخٍ</span> <span class=\"quran-arabic-font text-success\">مُتَلَطِّخٍ،</span> <span class=\"quran-arabic-font text-success\">فَيُؤْخَذُ</span> <span class=\"quran-arabic-font text-success\">بِقَوَائِمِهِ</span> <span class=\"quran-arabic-font text-success\">فَيُلْقَى</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">النَّار</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மறுமை நாளில் இப்ராஹீம் (அலை) அவர்கள் தனது தந்தை ஆஸரைச் சந்திப்பார்கள். ஆஸரின் முகத்தில் புழுதியும் இருளும் படிந்திருக்கும். இப்ராஹீம் (அலை) அவர்கள் அவரிடம், \"உனக்கு நான் மாறுசெய்ய வேண்டாம் என்று கூறவில்லையா?\" என்று கேட்பார்கள். அதற்கு அவரது தந்தை, \"இன்று நான் உனக்கு மாறுசெய்ய மாட்டேன்\" என்று கூறுவார். இப்ராஹீம் (அலை) அவர்கள், \"என் இறைவனே! அவர்கள் எழுப்பப்படும் நாளில் என்னை இழிவுபடுத்த மாட்டாய் என்று எனக்கு நீ வாக்குறுதி அளித்தாயே! எனது தந்தை இந்த நிலையில் இருப்பதை விடப் பெரிய இழிவு வேறென்ன இருக்க முடியும்?\" என்று கேட்பார்கள். அல்லாஹ் அவரிடம், \"நிச்சயமாக நான் நிராகரிப்பவர்களுக்குச் சொர்க்கத்தைத் தடை செய்துவிட்டேன்\" என்று கூறுவான். பின்னர், \"இப்ராஹீமே! உனது கால்களுக்குக் கீழே பார்\" என்று கூறப்படும். அவர்கள் பார்ப்பார்கள், அங்கே தனது தந்தை சாணம் படிந்த ஒரு ஆண் கழுதைப்புலியாக (மாற்றப்பட்டிருப்பதைக்) காண்பார்கள். அது கால்களால் பிடிக்கப்பட்டு நரக நெருப்பில் எறியப்படும்.) இதை அபூ அப்துர்-ரஹ்மான் அன்-நஸாஈ அவர்களும் தனது 'ஸுனன் அல்-குப்ரா'வின் தஃப்ஸீரில் பதிவு செய்துள்ளார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾يَوْمَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَنفَعُ</span> <span class=\"quran-arabic-font text-success\">مَالٌ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">بَنُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அந்நாளில், செல்வமோ பிள்ளைகளோ எந்தப் பலனும் அளிக்காது.) இதன் பொருள், ஒரு மனிதனின் செல்வம் அவனை அல்லாஹ்வின் தண்டனையிலிருந்து பாதுகாக்காது; அவன் பூமி நிறையத் தங்கத்தை ஈடாக வழங்கினாலும் சரியே.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلاَ</span> <span class=\"quran-arabic-font text-success\">بَنُونَ﴿</span><br />\r\n<br />\r\n(பிள்ளைகளும் இல்லை) இதன் பொருள், 'பூமியில் உள்ள அனைத்து மக்களையும் ஈடாகக் கொடுத்தாலும் பயனில்லை' என்பதாகும். அந்நாளில் அல்லாஹ் மீதுள்ள நம்பிக்கை, அவனுக்காகத் தூய்மையான முறையில் செயல்படுவது மற்றும் ஷிர்க்கிலிருந்தும் (இணைவைப்பு) அதனைச் செய்வோரிடமிருந்தும் விலகி இருப்பது மட்டுமே பயனளிக்கும். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِلاَّ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">أَتَى</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">بِقَلْبٍ</span> <span class=\"quran-arabic-font text-success\">سَلِيمٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(தூய்மையான இதயத்துடன் அல்லாஹ்விடம் வருபவரைத் தவிர.) இதன் பொருள், எவ்வித அசுத்தமும் அல்லது ஷிர்க்கும் (இணைவைப்பு) இல்லாத இதயம் என்பதாகும். இப்னு ஸீரீன் கூறினார்கள், \"தூய்மையான இதயம் என்பது அல்லாஹ் உண்மையானவன் என்பதையும், இறுதித் தீர்ப்பு நாள் சந்தேகமின்றி வரும் என்பதையும், கல்லறைகளில் உள்ளவர்களை அல்லாஹ் உயிர்த்தெழுப்புவான் என்பதையும் அறியும்.\" ஸஈத் பின் அல்-முஸய்யிப் கூறினார்கள், \"தூய்மையான இதயம் என்பது ஆரோக்கியமான இதயமாகும்.\" இதுவே முஃமினின் (இறைநம்பிக்கையாளரின்) இதயமாகும்; ஏனெனில் காஃபிர் (நிராகரிப்பாளர்) மற்றும் முனாஃபிக்கின் (நயவஞ்சகர்) இதயம் நோயுற்றதாகும். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فِى</span> <span class=\"quran-arabic-font text-success\">قُلُوبِهِمْ</span> <span class=\"quran-arabic-font text-success\">مَّرَضٌ﴿</span><br />\r\n<br />\r\n(அவர்களுடைய இதயங்களில் ஒரு நோய் இருக்கிறது) (<a href=\"qurandisp.php?sura=2&ayah=10\" class=\"link\">2:10</a>). அபூ உஸ்மான் அந்-நிஸாபூரி கூறினார்கள், \"பித்அத் (மார்க்கத்தில் புதிதாகத் தோற்றுவிக்கப்பட்டவை) இல்லாத மற்றும் ஸுன்னாவைக் கொண்டு மனநிறைவு அடையும் இதயமே இதுவாகும்.\"<br />\r\n<br />","text":"இப்ராஹீம் (அலை) அவர்கள் தனக்காகவும் தனது தந்தைக்காகவும் செய்த பிரார்த்தனை\n\r\n\n\r\n﴾رَبِّ هَبْ لِى حُكْماً﴿\n\r\n(என் இறைவனே! எனக்கு ஞானத்தை வழங்குவாயாக!) இங்கே இப்ராஹீம் (அலை) அவர்கள் தனது இறைவனிடம் தனக்கு 'ஹுக்ம்' வழங்குமாறு வேண்டுகிறார்கள். \"இது அறிவைக் குறிக்கிறது\" என்று இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள். ﴾وَأَلْحِقْنِى بِالصَّـلِحِينَ﴿\n\r\n\n\r\n(மேலும் என்னை நல்லோர்களுடன் சேர்த்துவிடுவாயாக.) இதன் பொருள், 'இவ்வுலகிலும் மறுமையிலும் என்னை நல்லோர்களில் ஒருவனாக ஆக்குவாயாக' என்பதாகும். இது நபி (ஸல்) அவர்கள் மரணிக்கும் தருவாயில் மூன்று முறை கூறிய வார்த்தைகளைப் போன்றது: ﴾«اللَّهُمَّ فِي الرَّفِيقِ الْأَعْلَى»﴿\n\r\n\n\r\n(யா அல்லாஹ், மேலான தோழருடன் (சொர்க்கத்தில்) சேர்த்துவிடுவாயாக). ﴾وَاجْعَل لِّى لِسَانَ صِدْقٍ فِى الْآخِرِينَ ﴿\n\r\n\n\r\n(மேலும், பிற்காலத்தவர்களிடையே எனக்கு நற்பெயரை ஏற்படுத்துவாயாக.) இதன் பொருள், 'எனது மரணத்திற்குப் பிறகு நான் நல்ல முறையில் நினைவுகூரப்பட வேண்டும்; மக்கள் என்னைப் புகழவும், ஒரு முன்மாதிரியாக எடுத்துக்கொள்ளவும் வேண்டும்' என்பதாகும். இது பின்வரும் வசனத்தைப் போன்றது, ﴾وَتَرَكْنَا عَلَيْهِ فِى الْآخِرِينَ سَلَـمٌ عَلَى إِبْرَهِيمَ كَذَلِكَ نَجْزِى الْمُحْسِنِينَ ﴿\n\r\n\n\r\n(பிற்காலத்தவர்களிடையே அவருக்காக (ஒரு நற்பெயரை) நாம் விட்டுவைத்தோம்: \"இப்ராஹீம் மீது ஸலாம் (சாந்தி) உண்டாவதாக. இவ்வாறே நாம் நன்மை செய்பவர்களுக்குக் கூலி வழங்குகிறோம்.\") (37:108-110) ﴾وَاجْعَلْنِى مِن وَرَثَةِ جَنَّةِ النَّعِيمِ ﴿\n\r\n\n\r\n(இன்பமயமான சொர்க்கத்தின் வாரிசுதாரர்களில் ஒருவனாக என்னை ஆக்குவாயாக.) இதன் பொருள், 'இவ்வுலகில் நான் மறைந்த பிறகு எனக்கு நற்பெயரை வழங்கி, மறுமையிலும் இன்பமயமான சொர்க்கத்தின் வாரிசுதாரர்களில் ஒருவனாக என்னை ஆக்குவாயாக' என்பதாகும். ﴾وَاغْفِرْ لِأَبِي إِنَّهُ كَانَ مِنَ الضَّالِّينَ﴿\n\r\n\n\r\n(எனது தந்தையை மன்னிப்பாயாக; நிச்சயமாக அவர் வழிதவறியவர்களில் ஒருவராக இருக்கிறார்)\n\r\n\n\r\nஇது பின்வரும் வசனத்தைப் போன்றது, ﴾رَبَّنَا اغْفِرْ لِى وَلِوَالِدَىَّ﴿\n\r\n\n\r\n(எங்கள் இறைவனே! எனக்கும், எனது பெற்றோருக்கும் மன்னிப்பு அருள்வாயாக) (14:41). ஆனால், இப்ராஹீம் (அலை) அவர்கள் தனது தந்தைக்காக இவ்வாறு வேண்டுவதை பின்னர் நிறுத்திக்கொண்டார்கள். அல்லாஹ் கூறுவது போல: ﴾وَمَا كَانَ اسْتِغْفَارُ إِبْرَهِيمَ لِأَبِيهِ إِلاَّ عَن مَّوْعِدَةٍ وَعَدَهَآ إِيَّاهُ﴿\n\r\n\n\r\n(இப்ராஹீம் தனது தந்தைக்காக மன்னிப்புக் கோரியதெல்லாம், அவர் தனது தந்தைக்கு அளித்திருந்த ஒரு வாக்குறுதியின் காரணமாகவே தவிர வேறில்லை) (9:114), எதுவரை என்றால்: ﴾إِنَّ إِبْرَهِيمَ لأَوَّاهٌ حَلِيمٌ﴿\n\r\n\n\r\n(நிச்சயமாக இப்ராஹீம் மிகவும் இரக்கமுள்ளவராகவும், சகிப்புத்தன்மை கொண்டவராகவும் இருந்தார்) (9:114).\n\r\n\n\r\nஅல்லாஹ், இப்ராஹீம் (அலை) அவர்கள் தனது தந்தைக்காக மன்னிப்புக் கோருவதைத் தடுத்தான். அவன் கூறுவது போல: ﴾قَدْ كَانَتْ لَكُمْ أُسْوَةٌ حَسَنَةٌ فِى إِبْرَهِيمَ وَالَّذِينَ مَعَهُ﴿\n\r\n\n\r\n(நிச்சயமாக இப்ராஹீமிடமும் அவருடன் இருந்தவர்களிடமும் உங்களுக்கு ஓர் அழகிய முன்மாதிரி இருக்கிறது), அவன் பின்வருமாறு கூறும் வரை: ﴾وَمَآ أَمْلِكُ لَكَ مِنَ اللَّهِ مِن شَىْءٍ﴿\n\r\n\n\r\n(ஆனால் அல்லாஹ்விடமிருந்து உமக்காக எதையும் செய்யும் அதிகாரம் எனக்கில்லை.) (60:4), ﴾وَلاَ تُخْزِنِى يَوْمَ يُبْعَثُونَ ﴿\n\r\n\n\r\n(படைப்பினங்கள் எழுப்பப்படும் நாளில் என்னை இழிவுபடுத்தாதே.) இதன் பொருள், 'மறுமை நாளில், ஆதி முதல் அந்தம் வரையுள்ள அனைத்துப் படைப்புகளும் எழுப்பப்படும் நாளில் என்னை இழிவிலிருந்து பாதுகாப்பாயாக' என்பதாகும். அல்-புகாரி பதிவு செய்துள்ளார்கள்: அபூ ஹுரைரா (ரழி) அவர்கள் கூறினார்கள், நபி (ஸல்) அவர்கள் கூறினார்கள்: ﴾«إِنَّ إِبْرَاهِيمَ رَأَى أَبَاهُ يَوْمَ الْقِيَامَةِ عَلَيْهِ الْغَبَرَةُ وَالْقَتَرَة»﴿\n\r\n\n\r\n(மறுமை நாளில் இப்ராஹீம் (அலை) அவர்கள் தனது தந்தையைப் புழுதியும் இருளும் சூழ்ந்தவராகக் காண்பார்கள்.)\n\r\n\n\r\nஅபூ ஹுரைரா (ரழி) அவர்கள் அறிவிக்கும் மற்றொரு அறிவிப்பில், நபி (ஸல்) அவர்கள் கூறினார்கள்: ﴾«يَلْقَى إِبْرَاهِيمُ أَبَاهُ فَيَقُولُ: يَا رَبِّ إِنَّكَ وَعَدْتَنِي أَنَّكَ لَا تُخْزِينِي يَوْمَ يُبْعَثُونَ، فَيَقُولُ اللهُ تَعَالَى: إِنِّي حَرَّمْتُ الْجَنَّةَ عَلَى الْكَافِرين»﴿\n\r\n\n\r\n(இப்ராஹீம் (அலை) அவர்கள் தனது தந்தையைச் சந்திப்பார்கள். அப்போது அவர், \"என் இறைவனே! படைப்புகள் எழுப்பப்படும் நாளில் என்னை இழிவுபடுத்த மாட்டாய் என்று எனக்கு நீ வாக்குறுதி அளித்தாயே!\" என்று வேண்டுவார்கள். அதற்கு அல்லாஹ், \"நிச்சயமாக நான் நிராகரிப்பவர்களுக்குச் சொர்க்கத்தைத் தடை செய்துவிட்டேன்\" என்று கூறுவான்.)\n\r\n\n\r\nஅவர்கள் (புகாரி) நபிமார்களைப் (அலை) பற்றிய ஹதீஸ்களிலும் இதைப் பதிவு செய்துள்ளார்கள், அதன் வாசகம் பின்வருமாறு: ﴾«يَلْقَى إِبْرَاهِيمُ أَبَاهُ آزَرَ يَوْمَ الْقِيَامَةِ، وَعَلَى وَجْهِ آزَرَ قَتَرَةٌ وَغَبَرَةٌ، فَيَقُولُ لَهُ إِبْرَاهِيمُ: أَلَمْ أَقُلْ لَكَ لَا تَعْصِينِي، فَيَقُولُ أَبُوهُ: فَالْيَوْمَ لَا أَعْصِيكَ، فَيَقُولُ إِبْرَاهِيمُ: يَا رَبِّ إِنَّكَ وَعَدْتَنِي أَنْ لَا تُخْزِيَنِي يَوْمَ يُبْعَثُونَ، فَأَيُّ خِزْيٍ أَخْزَى مِنْ أَبِي الْأَبْعَدِ فَيَقُولُ اللهُ تَعَالَى: إِنِّي حَرَّمْتُ الْجَنَّةَ عَلَى الْكَافِرِينَ، ثُمَّ يُقَالُ: يَا إِبْرَاهِيمُ انْظُرْ تَحْتَ رِجْلِكَ، فَيَنْظُرَ،فَإِذَا هُوَ بِذِيخٍ مُتَلَطِّخٍ، فَيُؤْخَذُ بِقَوَائِمِهِ فَيُلْقَى فِي النَّار»﴿\n\r\n\n\r\n(மறுமை நாளில் இப்ராஹீம் (அலை) அவர்கள் தனது தந்தை ஆஸரைச் சந்திப்பார்கள். ஆஸரின் முகத்தில் புழுதியும் இருளும் படிந்திருக்கும். இப்ராஹீம் (அலை) அவர்கள் அவரிடம், \"உனக்கு நான் மாறுசெய்ய வேண்டாம் என்று கூறவில்லையா?\" என்று கேட்பார்கள். அதற்கு அவரது தந்தை, \"இன்று நான் உனக்கு மாறுசெய்ய மாட்டேன்\" என்று கூறுவார். இப்ராஹீம் (அலை) அவர்கள், \"என் இறைவனே! அவர்கள் எழுப்பப்படும் நாளில் என்னை இழிவுபடுத்த மாட்டாய் என்று எனக்கு நீ வாக்குறுதி அளித்தாயே! எனது தந்தை இந்த நிலையில் இருப்பதை விடப் பெரிய இழிவு வேறென்ன இருக்க முடியும்?\" என்று கேட்பார்கள். அல்லாஹ் அவரிடம், \"நிச்சயமாக நான் நிராகரிப்பவர்களுக்குச் சொர்க்கத்தைத் தடை செய்துவிட்டேன்\" என்று கூறுவான். பின்னர், \"இப்ராஹீமே! உனது கால்களுக்குக் கீழே பார்\" என்று கூறப்படும். அவர்கள் பார்ப்பார்கள், அங்கே தனது தந்தை சாணம் படிந்த ஒரு ஆண் கழுதைப்புலியாக (மாற்றப்பட்டிருப்பதைக்) காண்பார்கள். அது கால்களால் பிடிக்கப்பட்டு நரக நெருப்பில் எறியப்படும்.) இதை அபூ அப்துர்-ரஹ்மான் அன்-நஸாஈ அவர்களும் தனது 'ஸுனன் அல்-குப்ரா'வின் தஃப்ஸீரில் பதிவு செய்துள்ளார்கள்.\n\r\n\n\r\n﴾يَوْمَ لاَ يَنفَعُ مَالٌ وَلاَ بَنُونَ ﴿\n\r\n\n\r\n(அந்நாளில், செல்வமோ பிள்ளைகளோ எந்தப் பலனும் அளிக்காது.) இதன் பொருள், ஒரு மனிதனின் செல்வம் அவனை அல்லாஹ்வின் தண்டனையிலிருந்து பாதுகாக்காது; அவன் பூமி நிறையத் தங்கத்தை ஈடாக வழங்கினாலும் சரியே.\n\r\n\n\r\n﴾وَلاَ بَنُونَ﴿\n\r\n\n\r\n(பிள்ளைகளும் இல்லை) இதன் பொருள், 'பூமியில் உள்ள அனைத்து மக்களையும் ஈடாகக் கொடுத்தாலும் பயனில்லை' என்பதாகும். அந்நாளில் அல்லாஹ் மீதுள்ள நம்பிக்கை, அவனுக்காகத் தூய்மையான முறையில் செயல்படுவது மற்றும் ஷிர்க்கிலிருந்தும் (இணைவைப்பு) அதனைச் செய்வோரிடமிருந்தும் விலகி இருப்பது மட்டுமே பயனளிக்கும். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾إِلاَّ مَنْ أَتَى اللَّهَ بِقَلْبٍ سَلِيمٍ ﴿\n\r\n\n\r\n(தூய்மையான இதயத்துடன் அல்லாஹ்விடம் வருபவரைத் தவிர.) இதன் பொருள், எவ்வித அசுத்தமும் அல்லது ஷிர்க்கும் (இணைவைப்பு) இல்லாத இதயம் என்பதாகும். இப்னு ஸீரீன் கூறினார்கள், \"தூய்மையான இதயம் என்பது அல்லாஹ் உண்மையானவன் என்பதையும், இறுதித் தீர்ப்பு நாள் சந்தேகமின்றி வரும் என்பதையும், கல்லறைகளில் உள்ளவர்களை அல்லாஹ் உயிர்த்தெழுப்புவான் என்பதையும் அறியும்.\" ஸஈத் பின் அல்-முஸய்யிப் கூறினார்கள், \"தூய்மையான இதயம் என்பது ஆரோக்கியமான இதயமாகும்.\" இதுவே முஃமினின் (இறைநம்பிக்கையாளரின்) இதயமாகும்; ஏனெனில் காஃபிர் (நிராகரிப்பாளர்) மற்றும் முனாஃபிக்கின் (நயவஞ்சகர்) இதயம் நோயுற்றதாகும். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾فِى قُلُوبِهِمْ مَّرَضٌ﴿\n\r\n\n\r\n(அவர்களுடைய இதயங்களில் ஒரு நோய் இருக்கிறது) (2:10). அபூ உஸ்மான் அந்-நிஸாபூரி கூறினார்கள், \"பித்அத் (மார்க்கத்தில் புதிதாகத் தோற்றுவிக்கப்பட்டவை) இல்லாத மற்றும் ஸுன்னாவைக் கொண்டு மனநிறைவு அடையும் இதயமே இதுவாகும்.\""},"90":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=104\" class=\"link\">26:104</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:104 ஐ பார்க்கவும்"},"91":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=104\" class=\"link\">26:104</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:104 ஐ பார்க்கவும்"},"92":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=104\" class=\"link\">26:104</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:104 ஐ பார்க்கவும்"},"93":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=104\" class=\"link\">26:104</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:104 ஐ பார்க்கவும்"},"94":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=104\" class=\"link\">26:104</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:104 ஐ பார்க்கவும்"},"95":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=104\" class=\"link\">26:104</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:104 ஐ பார்க்கவும்"},"96":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=104\" class=\"link\">26:104</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:104 ஐ பார்க்கவும்"},"97":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=104\" class=\"link\">26:104</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:104 ஐ பார்க்கவும்"},"98":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=104\" class=\"link\">26:104</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:104 ஐ பார்க்கவும்"},"99":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=104\" class=\"link\">26:104</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:104 ஐ பார்க்கவும்"},"100":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=104\" class=\"link\">26:104</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:104 ஐ பார்க்கவும்"},"101":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=104\" class=\"link\">26:104</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:104 ஐ பார்க்கவும்"},"102":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=104\" class=\"link\">26:104</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:104 ஐ பார்க்கவும்"},"103":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=104\" class=\"link\">26:104</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:104 ஐ பார்க்கவும்"},"104":{"html":"<strong>மறுமை நாளில் இறையச்சமுடையவர்களும் வழிதவறியவர்களும்; மேலும் பாவம் செய்தவர்களின் வாதங்களும் துக்கமும்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَأُزْلِفَتِ</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةُ</span> <span class=\"quran-arabic-font text-success\">لِلْمُتَّقِينَ﴿</span><br />\r\n<br />\r\n(மேலும் சொர்க்கம் இறையச்சமுடையவர்களுக்கு நெருக்கமாக்கப்படும்) அதாவது, சொர்க்கவாசிகளுக்காக அது அலங்கரிக்கப்பட்டு, அவர்கள் பார்க்கும் விதமாக அவர்களுக்கு மிக அருகில் கொண்டு வரப்படும். இவ்வுலகின் இன்பங்களை விட சொர்க்கத்தையே மேலானதாகக் கருதி, அதற்காகவே இவ்வுலகில் பாடுபட்ட இறையச்சமுடையவர்களே அதன் மக்கள் ஆவர்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَبُرِّزَتِ</span> <span class=\"quran-arabic-font text-success\">الْجَحِيمُ</span> <span class=\"quran-arabic-font text-success\">لِلْغَاوِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும், வழிதவறியவர்களுக்கு நரக நெருப்பு வெளிப்படையாகக் காட்டப்படும்.) அதாவது, நரகம் அவர்களுக்குக் காட்டப்படும் போது, அதிலிருந்து ஒரு நீண்ட கழுத்துப் பகுதி வெளிப்பட்டு, முனகிக் கொண்டும் பெருமூச்சு விட்டுக்கொண்டும் இருக்கும்; அச்சத்தால் அவர்களின் இதயங்கள் தொண்டைக் குழிகளுக்கு வந்துவிடும். நரகவாசிகளை இழிவுபடுத்தும் விதமாகவும் கண்டிக்கும் விதமாகவும் அவர்களிடம் இவ்வாறு கூறப்படும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَقِيلَ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">أَيْنَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">كُنتُمْ</span> <span class=\"quran-arabic-font text-success\">تَعْبُدُونَ</span> - <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">دُونِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">هَلْ</span> <span class=\"quran-arabic-font text-success\">يَنصُرُونَكُمْ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">يَنتَصِرُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அல்லாஹ்வையன்றி நீங்கள் வணங்கிக் கொண்டிருந்தவை எங்கே? அவர்கள் உங்களுக்கு உதவி செய்ய முடியுமா அல்லது தங்களுக்குத் தாங்களே உதவி செய்து கொள்ள முடியுமா?) அதாவது, \"அல்லாஹ்வைத் தவிர்த்து நீங்கள் வணங்கிக் கொண்டிருந்த அந்தத் தெய்வங்களாலும் சிலைகளாலும் இன்று உங்களுக்கு எந்த உதவியும் செய்ய முடியாது; தங்களுக்குத் தாங்களே கூட அவர்களால் பாதுகாத்துக் கொள்ள முடியாது. இன்று நீங்களும் உங்களின் அந்தத் தெய்வங்களும் நரகத்தின் எரிபொருட்களாவீர்கள்; நிச்சயமாக நீங்கள் அதில் நுழைவீர்கள்\" (என்று கூறப்படும்).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَكُبْكِبُواْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">هُمْ</span> <span class=\"quran-arabic-font text-success\">وَالْغَاوُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(பின்னர் அவர்களும், வழிதவறியவர்களும் அதில் (நரக நெருப்பில்) முகம் குப்புறத் தள்ளப்படுவார்கள்.) முஜாஹித் (ரழி) அவர்கள் கூறுகிறார்கள்: \"அவர்கள் நரகத்தில் தூக்கி எறியப்படுவார்கள் என்பதே இதன் பொருள்.\" மற்றவர்கள் கூறுகிறார்கள்: \"நிராகரிப்பாளர்களும், அவர்களை ஷிர்க் (இணைவைப்பு) செய்ய அழைத்த அவர்களின் தலைவர்களும் ஒருவருக்கொருவர் மேல் அடுக்குகளாக வீசப்படுவார்கள்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَجُنُودُ</span> <span class=\"quran-arabic-font text-success\">إِبْلِيسَ</span> <span class=\"quran-arabic-font text-success\">أَجْمَعُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும் இப்லீஸின் படைகள் அனைத்தும் ஒன்றாகவும் தள்ளப்படுவார்கள்.) அவர்கள் அனைவரும் நரகத்தில் வீசப்படுவார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالُواْ</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">يَخْتَصِمُونَ</span> - <span class=\"quran-arabic-font text-success\">تَاللَّهِ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كُنَّا</span> <span class=\"quran-arabic-font text-success\">لَفِى</span> <span class=\"quran-arabic-font text-success\">ضَلَالٍ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٍ</span> - <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">نُسَوِّيكُمْ</span> <span class=\"quran-arabic-font text-success\">بِرَبِّ</span> <span class=\"quran-arabic-font text-success\">الْعَالَمِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அங்கு அவர்கள் ஒருவருக்கொருவர் வாக்குவாதம் செய்து கொண்டு கூறுவார்கள்: \"அல்லாஹ்வின் மீது சத்தியமாக! அகிலங்களின் இறைவனுக்கு உங்களை நாங்கள் சமமாக்கிய போது, நிச்சயமாக நாங்கள் தெளிவான வழிகேட்டிலேயே இருந்தோம்.\") அவர்களில் பலவீனமானவர்கள், தங்களின் கர்வமிக்க தலைவர்களிடம், \"நிச்சயமாக நாங்கள் உங்களையே பின்பற்றினோம்; எனவே நரக நெருப்பிலிருந்து எங்களைச் சிறிதளவாவது உங்களால் காப்பாற்ற முடியுமா?\" என்று கேட்பார்கள். பின்னர், தாங்களே குற்றவாளிகள் என்பதை உணர்ந்து இவ்வாறு கூறுவார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾تَاللَّهِ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كُنَّا</span> <span class=\"quran-arabic-font text-success\">لَفِى</span> <span class=\"quran-arabic-font text-success\">ضَلَالٍ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٍ</span> - <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">نُسَوِّيكُمْ</span> <span class=\"quran-arabic-font text-success\">بِرَبِّ</span> <span class=\"quran-arabic-font text-success\">الْعَالَمِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அல்லாஹ்வின் மீது சத்தியமாக! அகிலங்களின் இறைவனுக்கு உங்களை நாங்கள் சமமாக்கிய போது, நிச்சயமாக நாங்கள் தெளிவான வழிகேட்டிலேயே இருந்தோம்.) அதாவது, \"அகிலங்களின் இறைவனுடைய கட்டளைகளுக்கு எப்படிக் கீழ்ப்படிய வேண்டுமோ, அவ்வாறு உங்கள் கட்டளைகளுக்கு நாங்கள் கீழ்ப்படிந்தோம்; மேலும் அகிலங்களின் இறைவனுடன் சேர்த்து உங்களையும் நாங்கள் வணங்கினோம்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَضَلَّنَآ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">الْمُجْرِمُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும், அந்தப் பாவிகளைத் தவிர வேறு எவரும் எங்களை வழிகெடுக்கவில்லை.) அதாவது, \"அந்தத் தீயவர்களைத் தவிர வேறு யாரும் எங்களை இத்தகைய செயல்களுக்கு அழைக்கவில்லை.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَمَا</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">شَافِعِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(இப்போது எங்களுக்குப் பரிந்துரைப்பவர்கள் யாரும் இல்லை.) அவர்கள் இவ்வாறு கூறுவார்கள் என்று குறிப்பிடும் மற்றொரு வசனத்தைப் போன்றது இது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَهَل</span> <span class=\"quran-arabic-font text-success\">لَّنَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">شُفَعَآءَ</span> <span class=\"quran-arabic-font text-success\">فَيَشْفَعُواْ</span> <span class=\"quran-arabic-font text-success\">لَنَآ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">نُرَدُّ</span> <span class=\"quran-arabic-font text-success\">فَنَعْمَلَ</span> <span class=\"quran-arabic-font text-success\">غَيْرَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">كُنَّا</span> <span class=\"quran-arabic-font text-success\">نَعْمَلُ﴿</span><br />\r\n<br />\r\n(...எங்களுக்காகப் பரிந்து பேசக்கூடிய பரிந்துரையாளர்கள் எவரேனும் உண்டா? அல்லது நாங்கள் (உலகிற்குத்) திருப்பி அனுப்பப்பட மாட்டோமா? அவ்வாறானால் நாங்கள் செய்து கொண்டிருந்தவற்றிற்கு மாற்றமான நற்செயல்களைச் செய்வோம்) (<a href=\"qurandisp.php?sura=7&ayah=53\" class=\"link\">7:53</a>). அதுபோலவே இந்த சூராவிலும் அவர்கள் இவ்வாறு கூறுவார்கள் என்று அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَمَا</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">شَافِعِينَ</span> - <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">صَدِيقٍ</span> <span class=\"quran-arabic-font text-success\">حَمِيمٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(இப்போது எங்களுக்குப் பரிந்துரைப்பவர்களும் இல்லை, நெருங்கிய நண்பரும் இல்லை.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَلَوْ</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">كَرَّةً</span> <span class=\"quran-arabic-font text-success\">فَنَكُونَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n((அந்தோ!) நாங்கள் மீண்டும் செல்ல ஒரு வாய்ப்பு கிடைத்தால், நிச்சயமாக நாங்கள் நம்பிக்கையாளர்களில் ஒருவராக ஆகிவிடுவோம்!) அவர்கள் தங்கள் இறைவனுக்குக் கீழ்ப்படிந்து நற்செயல்கள் புரிவதற்காக மீண்டும் இவ்வுலகிற்குத் திரும்ப விரும்புவார்கள் - இது அவர்களின் கூற்று - ஆனால், அவர்கள் மீண்டும் இவ்வுலகிற்கு அனுப்பப்பட்டாலும், தடுக்கப்பட்ட செயல்களையே மீண்டும் செய்வார்கள் என்பதை அல்லாஹ் நன்கு அறிவான்; மேலும் அவர்கள் பொய்யர்கள் என்பதையும் அவன் அறிவான். நரகவாசிகள் ஒருவருக்கொருவர் எவ்வாறு விவாதிப்பார்கள் என்பதைப் பற்றி ஸூரா ஸாதில் அல்லாஹ் இவ்வாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">لَحَقٌّ</span> <span class=\"quran-arabic-font text-success\">تَخَاصُمُ</span> <span class=\"quran-arabic-font text-success\">أَهْلِ</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிச்சயமாக இதுவே உண்மையானது - நரகவாசிகள் ஒருவருக்கொருவர் செய்து கொள்ளும் விவாதம்!) (<a href=\"qurandisp.php?sura=38&ayah=64\" class=\"link\">38:64</a>). பின்னர் அவன் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">لَآيَةً</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">أَكْثَرُهُمْ</span> <span class=\"quran-arabic-font text-success\">مُّؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிச்சயமாக இதில் ஓர் அத்தாட்சி இருக்கிறது; இருப்பினும் அவர்களில் பெரும்பாலோர் நம்பிக்கையாளர்களாக இல்லை.) அதாவது, இப்ராஹீம் (அலை) அவர்கள் தம் மக்களுடன் செய்த விவாதத்திலும், தவ்ஹீதிற்கு (ஏகத்துவத்திற்கு) அவர் முன்வைத்த ஆதாரத்திலும் ஓர் அத்தாட்சி இருக்கிறது. அதாவது அல்லாஹ்வைத் தவிர வேறு இறைவன் இல்லை என்பதற்கு இது ஒரு தெளிவான சான்றாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">لَآيَةً</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">أَكْثَرُهُمْ</span> <span class=\"quran-arabic-font text-success\">مُّؤْمِنِينَ</span> - <span class=\"quran-arabic-font text-success\">وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">رَبَّكَ</span> <span class=\"quran-arabic-font text-success\">لَهُوَ</span> <span class=\"quran-arabic-font text-success\">الْعَزِيزُ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمُ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிச்சயமாக இதில் ஓர் அத்தாட்சி இருக்கிறது; இருப்பினும் அவர்களில் பெரும்பாலோர் நம்பிக்கையாளர்களாக இல்லை. மேலும் நிச்சயமாக, உம்முடைய இறைவன், அவன் யாவற்றையும் மிகைத்தவன், மகா கருணையாளன்.)<br />\r\n<br />","text":"மறுமை நாளில் இறையச்சமுடையவர்களும் வழிதவறியவர்களும்; மேலும் பாவம் செய்தவர்களின் வாதங்களும் துக்கமும்\n\r\n\n\r\n﴾وَأُزْلِفَتِ الْجَنَّةُ لِلْمُتَّقِينَ﴿\n\r\n\n\r\n(மேலும் சொர்க்கம் இறையச்சமுடையவர்களுக்கு நெருக்கமாக்கப்படும்) அதாவது, சொர்க்கவாசிகளுக்காக அது அலங்கரிக்கப்பட்டு, அவர்கள் பார்க்கும் விதமாக அவர்களுக்கு மிக அருகில் கொண்டு வரப்படும். இவ்வுலகின் இன்பங்களை விட சொர்க்கத்தையே மேலானதாகக் கருதி, அதற்காகவே இவ்வுலகில் பாடுபட்ட இறையச்சமுடையவர்களே அதன் மக்கள் ஆவர்.\n\r\n\n\r\n﴾وَبُرِّزَتِ الْجَحِيمُ لِلْغَاوِينَ ﴿\n\r\n\n\r\n(மேலும், வழிதவறியவர்களுக்கு நரக நெருப்பு வெளிப்படையாகக் காட்டப்படும்.) அதாவது, நரகம் அவர்களுக்குக் காட்டப்படும் போது, அதிலிருந்து ஒரு நீண்ட கழுத்துப் பகுதி வெளிப்பட்டு, முனகிக் கொண்டும் பெருமூச்சு விட்டுக்கொண்டும் இருக்கும்; அச்சத்தால் அவர்களின் இதயங்கள் தொண்டைக் குழிகளுக்கு வந்துவிடும். நரகவாசிகளை இழிவுபடுத்தும் விதமாகவும் கண்டிக்கும் விதமாகவும் அவர்களிடம் இவ்வாறு கூறப்படும்:\n\r\n\n\r\n﴾وَقِيلَ لَهُمْ أَيْنَ مَا كُنتُمْ تَعْبُدُونَ - مِن دُونِ اللَّهِ هَلْ يَنصُرُونَكُمْ أَوْ يَنتَصِرُونَ ﴿\n\r\n\n\r\n(அல்லாஹ்வையன்றி நீங்கள் வணங்கிக் கொண்டிருந்தவை எங்கே? அவர்கள் உங்களுக்கு உதவி செய்ய முடியுமா அல்லது தங்களுக்குத் தாங்களே உதவி செய்து கொள்ள முடியுமா?) அதாவது, \"அல்லாஹ்வைத் தவிர்த்து நீங்கள் வணங்கிக் கொண்டிருந்த அந்தத் தெய்வங்களாலும் சிலைகளாலும் இன்று உங்களுக்கு எந்த உதவியும் செய்ய முடியாது; தங்களுக்குத் தாங்களே கூட அவர்களால் பாதுகாத்துக் கொள்ள முடியாது. இன்று நீங்களும் உங்களின் அந்தத் தெய்வங்களும் நரகத்தின் எரிபொருட்களாவீர்கள்; நிச்சயமாக நீங்கள் அதில் நுழைவீர்கள்\" (என்று கூறப்படும்).\n\r\n\n\r\n﴾فَكُبْكِبُواْ فِيهَا هُمْ وَالْغَاوُونَ ﴿\n\r\n\n\r\n(பின்னர் அவர்களும், வழிதவறியவர்களும் அதில் (நரக நெருப்பில்) முகம் குப்புறத் தள்ளப்படுவார்கள்.) முஜாஹித் (ரழி) அவர்கள் கூறுகிறார்கள்: \"அவர்கள் நரகத்தில் தூக்கி எறியப்படுவார்கள் என்பதே இதன் பொருள்.\" மற்றவர்கள் கூறுகிறார்கள்: \"நிராகரிப்பாளர்களும், அவர்களை ஷிர்க் (இணைவைப்பு) செய்ய அழைத்த அவர்களின் தலைவர்களும் ஒருவருக்கொருவர் மேல் அடுக்குகளாக வீசப்படுவார்கள்.\"\n\r\n\n\r\n﴾وَجُنُودُ إِبْلِيسَ أَجْمَعُونَ ﴿\n\r\n\n\r\n(மேலும் இப்லீஸின் படைகள் அனைத்தும் ஒன்றாகவும் தள்ளப்படுவார்கள்.) அவர்கள் அனைவரும் நரகத்தில் வீசப்படுவார்கள்.\n\r\n\n\r\n﴾قَالُواْ وَهُمْ فِيهَا يَخْتَصِمُونَ - تَاللَّهِ إِن كُنَّا لَفِى ضَلَالٍ مُّبِينٍ - إِذْ نُسَوِّيكُمْ بِرَبِّ الْعَالَمِينَ ﴿\n\r\n\n\r\n(அங்கு அவர்கள் ஒருவருக்கொருவர் வாக்குவாதம் செய்து கொண்டு கூறுவார்கள்: \"அல்லாஹ்வின் மீது சத்தியமாக! அகிலங்களின் இறைவனுக்கு உங்களை நாங்கள் சமமாக்கிய போது, நிச்சயமாக நாங்கள் தெளிவான வழிகேட்டிலேயே இருந்தோம்.\") அவர்களில் பலவீனமானவர்கள், தங்களின் கர்வமிக்க தலைவர்களிடம், \"நிச்சயமாக நாங்கள் உங்களையே பின்பற்றினோம்; எனவே நரக நெருப்பிலிருந்து எங்களைச் சிறிதளவாவது உங்களால் காப்பாற்ற முடியுமா?\" என்று கேட்பார்கள். பின்னர், தாங்களே குற்றவாளிகள் என்பதை உணர்ந்து இவ்வாறு கூறுவார்கள்:\n\r\n\n\r\n﴾تَاللَّهِ إِن كُنَّا لَفِى ضَلَالٍ مُّبِينٍ - إِذْ نُسَوِّيكُمْ بِرَبِّ الْعَالَمِينَ ﴿\n\r\n\n\r\n(அல்லாஹ்வின் மீது சத்தியமாக! அகிலங்களின் இறைவனுக்கு உங்களை நாங்கள் சமமாக்கிய போது, நிச்சயமாக நாங்கள் தெளிவான வழிகேட்டிலேயே இருந்தோம்.) அதாவது, \"அகிலங்களின் இறைவனுடைய கட்டளைகளுக்கு எப்படிக் கீழ்ப்படிய வேண்டுமோ, அவ்வாறு உங்கள் கட்டளைகளுக்கு நாங்கள் கீழ்ப்படிந்தோம்; மேலும் அகிலங்களின் இறைவனுடன் சேர்த்து உங்களையும் நாங்கள் வணங்கினோம்.\"\n\r\n\n\r\n﴾وَمَآ أَضَلَّنَآ إِلاَّ الْمُجْرِمُونَ ﴿\n\r\n\n\r\n(மேலும், அந்தப் பாவிகளைத் தவிர வேறு எவரும் எங்களை வழிகெடுக்கவில்லை.) அதாவது, \"அந்தத் தீயவர்களைத் தவிர வேறு யாரும் எங்களை இத்தகைய செயல்களுக்கு அழைக்கவில்லை.\"\n\r\n\n\r\n﴾فَمَا لَنَا مِن شَافِعِينَ ﴿\n\r\n\n\r\n(இப்போது எங்களுக்குப் பரிந்துரைப்பவர்கள் யாரும் இல்லை.) அவர்கள் இவ்வாறு கூறுவார்கள் என்று குறிப்பிடும் மற்றொரு வசனத்தைப் போன்றது இது:\n\r\n\n\r\n﴾فَهَل لَّنَا مِن شُفَعَآءَ فَيَشْفَعُواْ لَنَآ أَوْ نُرَدُّ فَنَعْمَلَ غَيْرَ الَّذِى كُنَّا نَعْمَلُ﴿\n\r\n\n\r\n(...எங்களுக்காகப் பரிந்து பேசக்கூடிய பரிந்துரையாளர்கள் எவரேனும் உண்டா? அல்லது நாங்கள் (உலகிற்குத்) திருப்பி அனுப்பப்பட மாட்டோமா? அவ்வாறானால் நாங்கள் செய்து கொண்டிருந்தவற்றிற்கு மாற்றமான நற்செயல்களைச் செய்வோம்) (7:53). அதுபோலவே இந்த சூராவிலும் அவர்கள் இவ்வாறு கூறுவார்கள் என்று அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾فَمَا لَنَا مِن شَافِعِينَ - وَلاَ صَدِيقٍ حَمِيمٍ ﴿\n\r\n\n\r\n(இப்போது எங்களுக்குப் பரிந்துரைப்பவர்களும் இல்லை, நெருங்கிய நண்பரும் இல்லை.)\n\r\n\n\r\n﴾فَلَوْ أَنَّ لَنَا كَرَّةً فَنَكُونَ مِنَ الْمُؤْمِنِينَ ﴿\n\r\n\n\r\n((அந்தோ!) நாங்கள் மீண்டும் செல்ல ஒரு வாய்ப்பு கிடைத்தால், நிச்சயமாக நாங்கள் நம்பிக்கையாளர்களில் ஒருவராக ஆகிவிடுவோம்!) அவர்கள் தங்கள் இறைவனுக்குக் கீழ்ப்படிந்து நற்செயல்கள் புரிவதற்காக மீண்டும் இவ்வுலகிற்குத் திரும்ப விரும்புவார்கள் - இது அவர்களின் கூற்று - ஆனால், அவர்கள் மீண்டும் இவ்வுலகிற்கு அனுப்பப்பட்டாலும், தடுக்கப்பட்ட செயல்களையே மீண்டும் செய்வார்கள் என்பதை அல்லாஹ் நன்கு அறிவான்; மேலும் அவர்கள் பொய்யர்கள் என்பதையும் அவன் அறிவான். நரகவாசிகள் ஒருவருக்கொருவர் எவ்வாறு விவாதிப்பார்கள் என்பதைப் பற்றி ஸூரா ஸாதில் அல்லாஹ் இவ்வாறு கூறுகிறான்:\n\r\n\n\r\n﴾إِنَّ ذَلِكَ لَحَقٌّ تَخَاصُمُ أَهْلِ النَّارِ ﴿\n\r\n\n\r\n(நிச்சயமாக இதுவே உண்மையானது - நரகவாசிகள் ஒருவருக்கொருவர் செய்து கொள்ளும் விவாதம்!) (38:64). பின்னர் அவன் கூறுகிறான்:\n\r\n\n\r\n﴾إِنَّ فِي ذَلِكَ لَآيَةً وَمَا كَانَ أَكْثَرُهُمْ مُّؤْمِنِينَ ﴿\n\r\n\n\r\n(நிச்சயமாக இதில் ஓர் அத்தாட்சி இருக்கிறது; இருப்பினும் அவர்களில் பெரும்பாலோர் நம்பிக்கையாளர்களாக இல்லை.) அதாவது, இப்ராஹீம் (அலை) அவர்கள் தம் மக்களுடன் செய்த விவாதத்திலும், தவ்ஹீதிற்கு (ஏகத்துவத்திற்கு) அவர் முன்வைத்த ஆதாரத்திலும் ஓர் அத்தாட்சி இருக்கிறது. அதாவது அல்லாஹ்வைத் தவிர வேறு இறைவன் இல்லை என்பதற்கு இது ஒரு தெளிவான சான்றாகும்.\n\r\n\n\r\n﴾إِنَّ فِي ذَلِكَ لَآيَةً وَمَا كَانَ أَكْثَرُهُمْ مُّؤْمِنِينَ - وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ ﴿\n\r\n\n\r\n(நிச்சயமாக இதில் ஓர் அத்தாட்சி இருக்கிறது; இருப்பினும் அவர்களில் பெரும்பாலோர் நம்பிக்கையாளர்களாக இல்லை. மேலும் நிச்சயமாக, உம்முடைய இறைவன், அவன் யாவற்றையும் மிகைத்தவன், மகா கருணையாளன்.)"},"105":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=110\" class=\"link\">26:110</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:110 ஐ பார்க்கவும்"},"106":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=110\" class=\"link\">26:110</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:110 ஐ பார்க்கவும்"},"107":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=110\" class=\"link\">26:110</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:110 ஐ பார்க்கவும்"},"108":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=110\" class=\"link\">26:110</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:110 ஐ பார்க்கவும்"},"109":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=110\" class=\"link\">26:110</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:110 ஐ பார்க்கவும்"},"110":{"html":"<strong>நூஹ் (அலை) அவர்கள் தம் மக்களுக்குப் போதித்ததும், அவர்களின் எதிர்வினையும்</strong><br />\r\n<br />\r\nபூமிவாழ் மக்கள் சிலைகளை வணங்கத் தொடங்கிய பிறகு, அவர்களுக்கு அல்லாஹ் அனுப்பிய முதல் தூதரான தனது அடியாரும் தூதருமான நூஹ் (அலை) அவர்களைப் பற்றி இங்கு அல்லாஹ் கூறுகிறான். சிலை வழிபாட்டைத் தடுப்பதற்காகவும், அதன் விளைவுகளைக் குறித்து மக்களை எச்சரிப்பதற்காகவும் அல்லாஹ் அவர்களை அனுப்பினான். ஆனால், அவரது சமூகத்தினர் அவர்களைப் பொய்யாக்கி, அல்லாஹ்வைத் தவிர்த்து சிலைகளை வணங்கும் தங்களின் தீய வழக்கத்தைத் தொடர்ந்தனர். அவர்களை நிராகரிப்பது என்பது அனைத்துத் தூதர்களையும் நிராகரிப்பதற்குச் சமம் என்று அல்லாஹ் வஹீ (இறைச்செய்தி) அறிவித்தான். எனவே அல்லாஹ் கூறினான்:<span class=\"quran-arabic-font text-success\">﴾كَذَّبَتْ</span> <span class=\"quran-arabic-font text-success\">قَوْمُ</span> <span class=\"quran-arabic-font text-success\">نُوحٍ</span> <span class=\"quran-arabic-font text-success\">الْمُرْسَلِينَ</span> - <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">أَخُوهُمْ</span> <span class=\"quran-arabic-font text-success\">نُوحٌ</span> <span class=\"quran-arabic-font text-success\">أَلاَ</span> <span class=\"quran-arabic-font text-success\">تَتَّقُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நூஹுடைய சமூகத்தினர் தூதர்களைப் பொய்யாக்கினார்கள். அவர்களின் சகோதரர் நூஹ் அவர்களிடம், \"நீங்கள் (அல்லாஹ்வுக்கு) அஞ்சமாட்டீர்களா?\" என்று கேட்டபோது) அதாவது, 'அல்லாஹ்வைத் தவிர மற்றவர்களை நீங்கள் வணங்கும் நிலையில், நீங்கள் அல்லாஹ்வுக்கு அஞ்சமாட்டீர்களா?' என்று பொருள்.<span class=\"quran-arabic-font text-success\">﴾إِنِّي</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">رَسُولٌ</span> <span class=\"quran-arabic-font text-success\">أَمِينٌ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிச்சயமாக நான் உங்களுக்கு நம்பிக்கைக்குரிய தூதராவேன்.) அதாவது, 'நான் உங்களுக்காக அல்லாஹ்வினால் அனுப்பப்பட்ட தூதராவேன்; அல்லாஹ் என்னிடம் ஒப்படைத்த பணியை நான் நம்பிக்கையுடன் நிறைவேற்றுகிறேன். எனது இறைவனின் செய்திகளை நான் உங்களுக்கு எடுத்துரைக்கிறேன். அவற்றில் நான் எதையும் கூட்டவோ அல்லது குறைக்கவோ மாட்டேன்.'<span class=\"quran-arabic-font text-success\">﴾فَاتَّقُواْ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">وَأَطِيعُونِ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">أَسْأَلُكُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَجْرٍ</span> <span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">أَجْرِيَ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">الْعَالَمِينَ﴿</span><br />\r\n<br />\r\n(எனவே அல்லாஹ்வுக்கு அஞ்சுங்கள், எனக்கும் கீழ்ப்படியுங்கள். இதற்காக நான் உங்களிடம் எந்தக் கூலியையும் கோரவில்லை; என்னுடைய கூலி அகிலங்களின் இறைவனிடமேயன்றி (வேறு யாரிடமும்) இல்லை.) அதாவது, 'நான் உங்களுக்கு வழங்கும் இந்த அறிவுரைக்காக எந்தவொரு பிரதிபலனையும் நான் விரும்பவில்லை; இதற்கான கூலியை நான் அல்லாஹ்விடமே பெற்றுக்கொள்வேன்.'<span class=\"quran-arabic-font text-success\">﴾فَاتَّقُواْ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">وَأَطِيعُونِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(எனவே அல்லாஹ்வுக்கு அஞ்சுங்கள், எனக்கும் கீழ்ப்படியுங்கள்.) 'நான் உண்மையையே கூறுகிறேன் என்பதும், அல்லாஹ் என்னிடம் ஒப்படைத்த தூதுத்துவப் பணியை நான் நம்பிக்கையுடன் நிறைவேற்றுகிறேன் என்பதும் உங்களுக்குத் தெளிவாகத் தெரிகிறது.'<br />\r\n<br />\r\n<br />\r\n<br />","text":"நூஹ் (அலை) அவர்கள் தம் மக்களுக்குப் போதித்ததும், அவர்களின் எதிர்வினையும்\n\r\n\n\r\nபூமிவாழ் மக்கள் சிலைகளை வணங்கத் தொடங்கிய பிறகு, அவர்களுக்கு அல்லாஹ் அனுப்பிய முதல் தூதரான தனது அடியாரும் தூதருமான நூஹ் (அலை) அவர்களைப் பற்றி இங்கு அல்லாஹ் கூறுகிறான். சிலை வழிபாட்டைத் தடுப்பதற்காகவும், அதன் விளைவுகளைக் குறித்து மக்களை எச்சரிப்பதற்காகவும் அல்லாஹ் அவர்களை அனுப்பினான். ஆனால், அவரது சமூகத்தினர் அவர்களைப் பொய்யாக்கி, அல்லாஹ்வைத் தவிர்த்து சிலைகளை வணங்கும் தங்களின் தீய வழக்கத்தைத் தொடர்ந்தனர். அவர்களை நிராகரிப்பது என்பது அனைத்துத் தூதர்களையும் நிராகரிப்பதற்குச் சமம் என்று அல்லாஹ் வஹீ (இறைச்செய்தி) அறிவித்தான். எனவே அல்லாஹ் கூறினான்:﴾كَذَّبَتْ قَوْمُ نُوحٍ الْمُرْسَلِينَ - إِذْ قَالَ لَهُمْ أَخُوهُمْ نُوحٌ أَلاَ تَتَّقُونَ ﴿\n\r\n\n\r\n(நூஹுடைய சமூகத்தினர் தூதர்களைப் பொய்யாக்கினார்கள். அவர்களின் சகோதரர் நூஹ் அவர்களிடம், \"நீங்கள் (அல்லாஹ்வுக்கு) அஞ்சமாட்டீர்களா?\" என்று கேட்டபோது) அதாவது, 'அல்லாஹ்வைத் தவிர மற்றவர்களை நீங்கள் வணங்கும் நிலையில், நீங்கள் அல்லாஹ்வுக்கு அஞ்சமாட்டீர்களா?' என்று பொருள்.﴾إِنِّي لَكُمْ رَسُولٌ أَمِينٌ ﴿\n\r\n\n\r\n(நிச்சயமாக நான் உங்களுக்கு நம்பிக்கைக்குரிய தூதராவேன்.) அதாவது, 'நான் உங்களுக்காக அல்லாஹ்வினால் அனுப்பப்பட்ட தூதராவேன்; அல்லாஹ் என்னிடம் ஒப்படைத்த பணியை நான் நம்பிக்கையுடன் நிறைவேற்றுகிறேன். எனது இறைவனின் செய்திகளை நான் உங்களுக்கு எடுத்துரைக்கிறேன். அவற்றில் நான் எதையும் கூட்டவோ அல்லது குறைக்கவோ மாட்டேன்.'﴾فَاتَّقُواْ اللَّهَ وَأَطِيعُونِ وَمَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِنْ أَجْرِيَ إِلَّا عَلَى رَبِّ الْعَالَمِينَ﴿\n\r\n\n\r\n(எனவே அல்லாஹ்வுக்கு அஞ்சுங்கள், எனக்கும் கீழ்ப்படியுங்கள். இதற்காக நான் உங்களிடம் எந்தக் கூலியையும் கோரவில்லை; என்னுடைய கூலி அகிலங்களின் இறைவனிடமேயன்றி (வேறு யாரிடமும்) இல்லை.) அதாவது, 'நான் உங்களுக்கு வழங்கும் இந்த அறிவுரைக்காக எந்தவொரு பிரதிபலனையும் நான் விரும்பவில்லை; இதற்கான கூலியை நான் அல்லாஹ்விடமே பெற்றுக்கொள்வேன்.'﴾فَاتَّقُواْ اللَّهَ وَأَطِيعُونِ ﴿\n\r\n\n\r\n(எனவே அல்லாஹ்வுக்கு அஞ்சுங்கள், எனக்கும் கீழ்ப்படியுங்கள்.) 'நான் உண்மையையே கூறுகிறேன் என்பதும், அல்லாஹ் என்னிடம் ஒப்படைத்த தூதுத்துவப் பணியை நான் நம்பிக்கையுடன் நிறைவேற்றுகிறேன் என்பதும் உங்களுக்குத் தெளிவாகத் தெரிகிறது.'"},"111":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=115\" class=\"link\">26:115</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:115 ஐ பார்க்கவும்"},"112":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=115\" class=\"link\">26:115</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:115 ஐ பார்க்கவும்"},"113":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=115\" class=\"link\">26:115</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:115 ஐ பார்க்கவும்"},"114":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=115\" class=\"link\">26:115</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:115 ஐ பார்க்கவும்"},"115":{"html":"<strong>நூஹ் (அலை) அவர்களின் சமூகத்தினரின் கோரிக்கையும் அதற்கு அன்னாரது பதிலும்</strong><br />\r\n<br />\r\nஅல்லாஹ், நூஹ் (அலை) அவர்களுக்கும் அவர்களுடைய சமூகத்தாருக்குமிடையே நடைபெற்ற விவாதத்தையும், வாக்குவாதத்தையும் பற்றி இங்கு விவரிக்கின்றான்.<br />\r\n<br />\r\nஅவர்கள் கூறினார்கள்: \"நாங்கள் உங்களை நம்ப மாட்டோம்; உங்களைப் பின்பற்றி உங்களை விசுவாசிக்கும் மிகவும் தாழ்ந்த நிலையில் உள்ளவர்களுக்குச் சமமாக நாங்களும் உங்களைப் பின்பற்ற மாட்டோம். அவர்கள் எங்களில் மிகத் தாழ்ந்தவர்களாய் இருக்கின்றனர்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالُواْ</span> <span class=\"quran-arabic-font text-success\">أَنُؤْمِنُ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">وَاتَّبَعَكَ</span> <span class=\"quran-arabic-font text-success\">الْأَرْذَلُونَ</span> - <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">عِلْمِي</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يَعْمَلُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அவர்கள் கூறினார்கள்: \"தாழ்ந்த நிலையில் உள்ளவர்கள் உங்களைப் பின்பற்றியிருக்க, நாங்களா உங்களை நம்புவோம்?\" அதற்கு அவர் (நூஹ் (அலை)) கூறினார்கள்: \"அவர்கள் (இதற்கு முன்பு) என்ன செய்து கொண்டிருந்தார்கள் என்பதைப் பற்றி எனக்கு என்ன அறிவு இருக்கிறது?\") அதாவது, 'அவர்கள் என்னைப் பின்பற்றினால் அதில் எனக்கு என்ன கவலை? அவர்கள் இதற்கு முன்பு என்ன செய்து கொண்டிருந்தாலும், நான் அவர்களைப் பற்றி ஆராயவோ அல்லது அவர்களின் பின்னணியைச் சோதிக்கவோ வேண்டிய அவசியமில்லை. அவர்கள் என்னை விசுவாசித்தால் (ஈமான் கொண்டால்) அதை ஏற்றுக்கொள்வதே எனது பணி. அவர்களின் உள்ளங்களில் உள்ளவற்றை அல்லாஹ்வே அறிவான்.'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنْ</span> <span class=\"quran-arabic-font text-success\">حِسَابُهُمْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">رَبِّي</span> <span class=\"quran-arabic-font text-success\">لَوْ</span> <span class=\"quran-arabic-font text-success\">تَشْعُرُونَ</span> - <span class=\"quran-arabic-font text-success\">وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَنَاْ</span> <span class=\"quran-arabic-font text-success\">بِطَارِدِ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அவர்களின் விசாரணை எனது இறைவனிடமே இருக்கிறது - நீங்கள் உணர்வார்களாயின் (இதைப் புரிந்து கொள்வீர்கள்). மேலும், விசுவாசிகளை நான் விரட்டிவிடுபவன் அல்ல.) அவர்கள் ஈமான் கொள்வதற்கு, பலஹீனமான அந்த எளிய மக்களை அவர் விரட்டிவிட்டால், தாங்கள் அவரைப் பின்பற்றுவதாக அவர்கள் கூறியதாகத் தெரிகிறது. ஆனால், அவர் (நூஹ் (அலை)) அதைச் செய்ய மறுத்து இவ்வாறு கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَنَاْ</span> <span class=\"quran-arabic-font text-success\">بِطَارِدِ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span> - <span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">أَنَا</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">نَذِيرٌ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٌ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும், நான் விசுவாசிகளை விரட்டிவிடுபவன் அல்ல. நான் பகிரங்கமாக எச்சரிப்பவனேயன்றி வேறில்லை.) அதாவது, 'நான் ஓர் எச்சரிக்கையாளராகவே அனுப்பப்பட்டுள்ளேன். எனவே, எவர் எனக்குக் கீழ்ப்படிந்து, என்னைப் பின்பற்றி, என்னை விசுவாசிக்கின்றாரோ அவர் என்னைச் சேர்ந்தவர், நானும் அவரைச் சேர்ந்தவன்; அவர் கண்ணியமான குலத்தைச் சேர்ந்தவராக இருந்தாலும் அல்லது அற்பமானவராக இருந்தாலும், உயர் வர்க்கத்தினராக இருந்தாலும் அல்லது தாழ்ந்த வர்க்கத்தினராக இருந்தாலும் சரியே.'<br />\r\n<br />","text":"நூஹ் (அலை) அவர்களின் சமூகத்தினரின் கோரிக்கையும் அதற்கு அன்னாரது பதிலும்\n\r\n\n\r\nஅல்லாஹ், நூஹ் (அலை) அவர்களுக்கும் அவர்களுடைய சமூகத்தாருக்குமிடையே நடைபெற்ற விவாதத்தையும், வாக்குவாதத்தையும் பற்றி இங்கு விவரிக்கின்றான்.\n\r\n\n\r\nஅவர்கள் கூறினார்கள்: \"நாங்கள் உங்களை நம்ப மாட்டோம்; உங்களைப் பின்பற்றி உங்களை விசுவாசிக்கும் மிகவும் தாழ்ந்த நிலையில் உள்ளவர்களுக்குச் சமமாக நாங்களும் உங்களைப் பின்பற்ற மாட்டோம். அவர்கள் எங்களில் மிகத் தாழ்ந்தவர்களாய் இருக்கின்றனர்.\"\n\r\n\n\r\n﴾قَالُواْ أَنُؤْمِنُ لَكَ وَاتَّبَعَكَ الْأَرْذَلُونَ - قَالَ وَمَا عِلْمِي بِمَا كَانُواْ يَعْمَلُونَ ﴿\n\r\n\n\r\n(அவர்கள் கூறினார்கள்: \"தாழ்ந்த நிலையில் உள்ளவர்கள் உங்களைப் பின்பற்றியிருக்க, நாங்களா உங்களை நம்புவோம்?\" அதற்கு அவர் (நூஹ் (அலை)) கூறினார்கள்: \"அவர்கள் (இதற்கு முன்பு) என்ன செய்து கொண்டிருந்தார்கள் என்பதைப் பற்றி எனக்கு என்ன அறிவு இருக்கிறது?\") அதாவது, 'அவர்கள் என்னைப் பின்பற்றினால் அதில் எனக்கு என்ன கவலை? அவர்கள் இதற்கு முன்பு என்ன செய்து கொண்டிருந்தாலும், நான் அவர்களைப் பற்றி ஆராயவோ அல்லது அவர்களின் பின்னணியைச் சோதிக்கவோ வேண்டிய அவசியமில்லை. அவர்கள் என்னை விசுவாசித்தால் (ஈமான் கொண்டால்) அதை ஏற்றுக்கொள்வதே எனது பணி. அவர்களின் உள்ளங்களில் உள்ளவற்றை அல்லாஹ்வே அறிவான்.'\n\r\n\n\r\n﴾إِنْ حِسَابُهُمْ إِلاَّ عَلَى رَبِّي لَوْ تَشْعُرُونَ - وَمَآ أَنَاْ بِطَارِدِ الْمُؤْمِنِينَ ﴿\n\r\n\n\r\n(அவர்களின் விசாரணை எனது இறைவனிடமே இருக்கிறது - நீங்கள் உணர்வார்களாயின் (இதைப் புரிந்து கொள்வீர்கள்). மேலும், விசுவாசிகளை நான் விரட்டிவிடுபவன் அல்ல.) அவர்கள் ஈமான் கொள்வதற்கு, பலஹீனமான அந்த எளிய மக்களை அவர் விரட்டிவிட்டால், தாங்கள் அவரைப் பின்பற்றுவதாக அவர்கள் கூறியதாகத் தெரிகிறது. ஆனால், அவர் (நூஹ் (அலை)) அதைச் செய்ய மறுத்து இவ்வாறு கூறினார்கள்:\n\r\n\n\r\n﴾وَمَآ أَنَاْ بِطَارِدِ الْمُؤْمِنِينَ - إِنْ أَنَا إِلاَّ نَذِيرٌ مُّبِينٌ ﴿\n\r\n\n\r\n(மேலும், நான் விசுவாசிகளை விரட்டிவிடுபவன் அல்ல. நான் பகிரங்கமாக எச்சரிப்பவனேயன்றி வேறில்லை.) அதாவது, 'நான் ஓர் எச்சரிக்கையாளராகவே அனுப்பப்பட்டுள்ளேன். எனவே, எவர் எனக்குக் கீழ்ப்படிந்து, என்னைப் பின்பற்றி, என்னை விசுவாசிக்கின்றாரோ அவர் என்னைச் சேர்ந்தவர், நானும் அவரைச் சேர்ந்தவன்; அவர் கண்ணியமான குலத்தைச் சேர்ந்தவராக இருந்தாலும் அல்லது அற்பமானவராக இருந்தாலும், உயர் வர்க்கத்தினராக இருந்தாலும் அல்லது தாழ்ந்த வர்க்கத்தினராக இருந்தாலும் சரியே.'"},"116":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=122\" class=\"link\">26:122</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:122 ஐ பார்க்கவும்"},"117":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=122\" class=\"link\">26:122</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:122 ஐ பார்க்கவும்"},"118":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=122\" class=\"link\">26:122</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:122 ஐ பார்க்கவும்"},"119":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=122\" class=\"link\">26:122</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:122 ஐ பார்க்கவும்"},"120":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=122\" class=\"link\">26:122</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:122 ஐ பார்க்கவும்"},"121":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=122\" class=\"link\">26:122</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:122 ஐ பார்க்கவும்"},"122":{"html":"<strong>அவரது சமூகத்தாரின் அச்சுறுத்தல், அவர்களுக்கு எதிராக நூஹ் (அலை) அவர்கள் செய்த பிரார்த்தனை மற்றும் அவர்களின் அழிவு</strong><br />\r\n<br />\r\nநூஹ் (அலை) அவர்கள் நீண்ட காலம் தம் சமூகத்தாருக்கு மத்தியில் தங்கியிருந்து, இரவும் பகலும், இரகசியமாகவும் வெளிப்படையாகவும் அவர்களை அல்லாஹ்வின் பக்கம் அழைத்தார்கள். அவர்கள் தம் அழைப்பை மீண்டும் மீண்டும் வலியுறுத்திய போதெல்லாம், அச்சமூகத்தார் தங்களது தீவிர நிராகரிப்பில் நிலைத்திருப்பதிலும், அவரது அழைப்பை எதிர்ப்பதிலும் இன்னும் உறுதியாகவே இருந்தனர். இறுதியில், அவர்கள் கூறினார்கள்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾لَئِنْ</span> <span class=\"quran-arabic-font text-success\">لَّمْ</span> <span class=\"quran-arabic-font text-success\">تَنْتَهِ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">نُوحُ</span> <span class=\"quran-arabic-font text-success\">لَتَكُونَنَّ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُرْجُومِينَ﴿</span><br />\r\n<br />\r\n(“நூஹே! நீர் (இதை) நிறுத்திக் கொள்ளவில்லை என்றால், நிச்சயமாக நீர் கல்லெறிந்து கொல்லப்படுவோரில் ஒருவராகி விடுவீர்.”) அதாவது, ‘எம்மை உம்முடைய மார்க்கத்தின் பக்கம் அழைப்பதை நீர் நிறுத்தவில்லை என்றால்,’<br />\r\n<span class=\"quran-arabic-font text-success\">﴾لَتَكُونَنَّ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُرْجُومِينَ﴿</span><br />\r\n<br />\r\n(“நிச்சயமாக நீர் கல்லெறிந்து கொல்லப்படுவோரில் ஒருவராகி விடுவீர்.”) இதன் பொருள், ‘நாங்கள் உம்மைக் கல்லெறிந்து கொல்வோம்’ என்பதாகும். அந்தத் தருணத்தில், அவர்கள் தம்மக்களுக்கு எதிராகப் பிரார்த்தித்தார்கள்; அல்லாஹ் அவரது பிரார்த்தனைக்கு பதிலளித்தான். நூஹ் (அலை) அவர்கள் கூறினார்கள்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾رَبِّ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">قَوْمِى</span> <span class=\"quran-arabic-font text-success\">كَذَّبُونِ</span> - <span class=\"quran-arabic-font text-success\">فَافْتَحْ</span> <span class=\"quran-arabic-font text-success\">بَيْنِى</span> <span class=\"quran-arabic-font text-success\">وَبَيْنَهُمْ</span> <span class=\"quran-arabic-font text-success\">فَتْحاً</span> <span class=\"quran-arabic-font text-success\">وَنَجِّنِى</span> <span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">مَّعِىَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ﴿</span><br />\r\n<br />\r\n(“என் இறைவா! நிச்சயமாக எனது சமூகத்தார் என்னை நிராகரித்து விட்டனர். ஆகவே, எனக்கும் அவர்களுக்கும் இடையில் நீ ஒரு தீர்ப்பை வழங்குவாயாக; மேலும் என்னையும், என்னுடன் இருக்கும் இறைநம்பிக்கையாளர்களையும் காப்பாற்றுவாயாக.”) இது பின்வரும் வசனத்தைப் போன்றதாகும்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَدَعَا</span> <span class=\"quran-arabic-font text-success\">رَبَّهُ</span> <span class=\"quran-arabic-font text-success\">أَنِّي</span> <span class=\"quran-arabic-font text-success\">مَغْلُوبٌ</span> <span class=\"quran-arabic-font text-success\">فَانتَصِرْ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அப்போது அவர் தனது இறைவனை அழைத்து, “நிச்சயமாக நான் தோற்கடிக்கப்பட்டுவிட்டேன்; ஆகவே, (எனக்கு) உதவி செய்வாயாக!” என்று பிரார்த்தித்தார்.) (<a href=\"qurandisp.php?sura=54&ayah=10\" class=\"link\">54:10</a>). மேலும் அல்லாஹ் இங்கு கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَأَنجَيْنَـهُ</span> <span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">مَّعَهُ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْفُلْكِ</span> <span class=\"quran-arabic-font text-success\">الْمَشْحُونِ</span> - <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">أَغْرَقْنَا</span> <span class=\"quran-arabic-font text-success\">بَعْدُ</span> <span class=\"quran-arabic-font text-success\">الْبَـقِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(“ஆகவே, நாம் அவரையும் அவருடன் இருந்தவர்களையும் பாரம் ஏற்றப்பட்ட கப்பலில் காப்பாற்றினோம். பின்னர், எஞ்சியிருந்தோரை நாம் மூழ்கடித்தோம்.”) “பாரம் ஏற்றப்பட்ட கப்பல்” என்பது, சரக்குகளாலும் அதில் ஏற்றப்பட்ட ஒவ்வொரு உயிரினத்தின் ஜோடிகளாலும் நிரப்பப்பட்ட கப்பலைக் குறிக்கும். இந்த வசனத்தின் பொருள்: ‘நாம் நூஹ் (அலை) அவர்களையும் அவர்களைப் பின்பற்றிய அனைவரையும் காப்பாற்றினோம்; அவர்களை நிராகரித்து, அவரது கட்டளைகளுக்கு மாறு செய்த அனைவரையும் நாம் மூழ்கடித்தோம்’ என்பதாகும்.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">لأَيَةً</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">أَكْثَرُهُم</span> <span class=\"quran-arabic-font text-success\">مُّؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">رَبَّكَ</span> <span class=\"quran-arabic-font text-success\">لَهُوَ</span> <span class=\"quran-arabic-font text-success\">الْعَزِيزُ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمُ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(“நிச்சயமாக இதில் ஓர் அத்தாட்சி இருக்கிறது; ஆனால் அவர்களில் பெரும்பாலோர் நம்பிக்கை கொள்வதில்லை. மேலும், நிச்சயமாக உம்முடைய இறைவன், அவன்தான் மிகைத்தவனாகவும் மகா கருணையுடையவனாகவும் இருக்கிறான்.”)<br />\r\n<span class=\"quran-arabic-font text-success\">﴾كَذَّبَتْ</span> <span class=\"quran-arabic-font text-success\">عَادٌ</span> <span class=\"quran-arabic-font text-success\">الْمُرْسَلِينَ</span> - <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">أَخُوهُمْ</span> <span class=\"quran-arabic-font text-success\">هُودٌ</span> <span class=\"quran-arabic-font text-success\">أَلاَ</span> <span class=\"quran-arabic-font text-success\">تَتَّقُونَ</span> - <span class=\"quran-arabic-font text-success\">إِنِّى</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">رَسُولٌ</span> <span class=\"quran-arabic-font text-success\">أَمِينٌ﴿﴾</span>-<span class=\"quran-arabic-font text-success\">﴿﴾</span> <span class=\"quran-arabic-font text-success\">فَاتَّقُواْ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">وَأَطِيعُونِ</span> <span class=\"quran-arabic-font text-success\">﴿﴾</span>- <span class=\"quran-arabic-font text-success\">﴿﴾وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَسْأَلُكُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَجْرٍ</span> <span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">أَجْرِىَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">الْعَـلَمِينَ﴿﴾</span>-<span class=\"quran-arabic-font text-success\">﴿﴾</span> <span class=\"quran-arabic-font text-success\">أَتَبْنُونَ</span> <span class=\"quran-arabic-font text-success\">بِكُلِّ</span> <span class=\"quran-arabic-font text-success\">رِيعٍ</span> <span class=\"quran-arabic-font text-success\">ءَايَةً</span> <span class=\"quran-arabic-font text-success\">تَعْبَثُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n (“ஆது” சமூகத்தாரும் தூதர்களைப் பொய்யாக்கினர்.) (அவர்களுடைய சகோதரர் ஹூத் அவர்களிடம்: “(அல்லாஹ்வை) நீங்கள் அஞ்சமாட்டீர்களா?” என்று கேட்டபோது,) (“நிச்சயமாக நான் உங்களுக்கு நம்பிக்கைக்குரிய ஒரு தூதன் ஆவேன்.”) (“ஆகவே, நீங்கள் அல்லாஹ்வை அஞ்சுங்கள்; எனக்குக் கீழ்ப்படியுங்கள்.”) (“இதற்காக நான் உங்களிடம் யாதொரு கூலியும் கேட்கவில்லை; என்னுடைய கூலி அகிலங்களுக்கெல்லாம் இறைவனாகியவனிடமேயன்றி (வேறெவரிடமும்) இல்லை.”) (“நீங்கள் ஒவ்வொரு மேட்டுப் பகுதியிலும் வீணாக ஒரு சின்னத்தை எழுப்புகிறீர்களா?”) <br />\r\n<br />","text":"அவரது சமூகத்தாரின் அச்சுறுத்தல், அவர்களுக்கு எதிராக நூஹ் (அலை) அவர்கள் செய்த பிரார்த்தனை மற்றும் அவர்களின் அழிவு\n\r\n\n\r\nநூஹ் (அலை) அவர்கள் நீண்ட காலம் தம் சமூகத்தாருக்கு மத்தியில் தங்கியிருந்து, இரவும் பகலும், இரகசியமாகவும் வெளிப்படையாகவும் அவர்களை அல்லாஹ்வின் பக்கம் அழைத்தார்கள். அவர்கள் தம் அழைப்பை மீண்டும் மீண்டும் வலியுறுத்திய போதெல்லாம், அச்சமூகத்தார் தங்களது தீவிர நிராகரிப்பில் நிலைத்திருப்பதிலும், அவரது அழைப்பை எதிர்ப்பதிலும் இன்னும் உறுதியாகவே இருந்தனர். இறுதியில், அவர்கள் கூறினார்கள்:\n\r\n﴾لَئِنْ لَّمْ تَنْتَهِ يَا نُوحُ لَتَكُونَنَّ مِنَ الْمُرْجُومِينَ﴿\n\r\n\n\r\n(“நூஹே! நீர் (இதை) நிறுத்திக் கொள்ளவில்லை என்றால், நிச்சயமாக நீர் கல்லெறிந்து கொல்லப்படுவோரில் ஒருவராகி விடுவீர்.”) அதாவது, ‘எம்மை உம்முடைய மார்க்கத்தின் பக்கம் அழைப்பதை நீர் நிறுத்தவில்லை என்றால்,’\n\r\n﴾لَتَكُونَنَّ مِنَ الْمُرْجُومِينَ﴿\n\r\n\n\r\n(“நிச்சயமாக நீர் கல்லெறிந்து கொல்லப்படுவோரில் ஒருவராகி விடுவீர்.”) இதன் பொருள், ‘நாங்கள் உம்மைக் கல்லெறிந்து கொல்வோம்’ என்பதாகும். அந்தத் தருணத்தில், அவர்கள் தம்மக்களுக்கு எதிராகப் பிரார்த்தித்தார்கள்; அல்லாஹ் அவரது பிரார்த்தனைக்கு பதிலளித்தான். நூஹ் (அலை) அவர்கள் கூறினார்கள்:\n\r\n﴾رَبِّ إِنَّ قَوْمِى كَذَّبُونِ - فَافْتَحْ بَيْنِى وَبَيْنَهُمْ فَتْحاً وَنَجِّنِى وَمَن مَّعِىَ مِنَ الْمُؤْمِنِينَ﴿\n\r\n\n\r\n(“என் இறைவா! நிச்சயமாக எனது சமூகத்தார் என்னை நிராகரித்து விட்டனர். ஆகவே, எனக்கும் அவர்களுக்கும் இடையில் நீ ஒரு தீர்ப்பை வழங்குவாயாக; மேலும் என்னையும், என்னுடன் இருக்கும் இறைநம்பிக்கையாளர்களையும் காப்பாற்றுவாயாக.”) இது பின்வரும் வசனத்தைப் போன்றதாகும்:\n\r\n﴾فَدَعَا رَبَّهُ أَنِّي مَغْلُوبٌ فَانتَصِرْ ﴿\n\r\n\n\r\n(அப்போது அவர் தனது இறைவனை அழைத்து, “நிச்சயமாக நான் தோற்கடிக்கப்பட்டுவிட்டேன்; ஆகவே, (எனக்கு) உதவி செய்வாயாக!” என்று பிரார்த்தித்தார்.) (54:10). மேலும் அல்லாஹ் இங்கு கூறுகிறான்:\n\r\n﴾فَأَنجَيْنَـهُ وَمَن مَّعَهُ فِى الْفُلْكِ الْمَشْحُونِ - ثُمَّ أَغْرَقْنَا بَعْدُ الْبَـقِينَ ﴿\n\r\n\n\r\n(“ஆகவே, நாம் அவரையும் அவருடன் இருந்தவர்களையும் பாரம் ஏற்றப்பட்ட கப்பலில் காப்பாற்றினோம். பின்னர், எஞ்சியிருந்தோரை நாம் மூழ்கடித்தோம்.”) “பாரம் ஏற்றப்பட்ட கப்பல்” என்பது, சரக்குகளாலும் அதில் ஏற்றப்பட்ட ஒவ்வொரு உயிரினத்தின் ஜோடிகளாலும் நிரப்பப்பட்ட கப்பலைக் குறிக்கும். இந்த வசனத்தின் பொருள்: ‘நாம் நூஹ் (அலை) அவர்களையும் அவர்களைப் பின்பற்றிய அனைவரையும் காப்பாற்றினோம்; அவர்களை நிராகரித்து, அவரது கட்டளைகளுக்கு மாறு செய்த அனைவரையும் நாம் மூழ்கடித்தோம்’ என்பதாகும்.\n\r\n﴾إِنَّ فِى ذَلِكَ لأَيَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ ﴿\n\r\n\n\r\n(“நிச்சயமாக இதில் ஓர் அத்தாட்சி இருக்கிறது; ஆனால் அவர்களில் பெரும்பாலோர் நம்பிக்கை கொள்வதில்லை. மேலும், நிச்சயமாக உம்முடைய இறைவன், அவன்தான் மிகைத்தவனாகவும் மகா கருணையுடையவனாகவும் இருக்கிறான்.”)\n\r\n﴾كَذَّبَتْ عَادٌ الْمُرْسَلِينَ - إِذْ قَالَ لَهُمْ أَخُوهُمْ هُودٌ أَلاَ تَتَّقُونَ - إِنِّى لَكُمْ رَسُولٌ أَمِينٌ﴿﴾-﴿﴾ فَاتَّقُواْ اللَّهَ وَأَطِيعُونِ ﴿﴾- ﴿﴾وَمَآ أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ إِنْ أَجْرِىَ إِلاَّ عَلَى رَبِّ الْعَـلَمِينَ﴿﴾-﴿﴾ أَتَبْنُونَ بِكُلِّ رِيعٍ ءَايَةً تَعْبَثُونَ ﴿\n\r\n\n\r\n (“ஆது” சமூகத்தாரும் தூதர்களைப் பொய்யாக்கினர்.) (அவர்களுடைய சகோதரர் ஹூத் அவர்களிடம்: “(அல்லாஹ்வை) நீங்கள் அஞ்சமாட்டீர்களா?” என்று கேட்டபோது,) (“நிச்சயமாக நான் உங்களுக்கு நம்பிக்கைக்குரிய ஒரு தூதன் ஆவேன்.”) (“ஆகவே, நீங்கள் அல்லாஹ்வை அஞ்சுங்கள்; எனக்குக் கீழ்ப்படியுங்கள்.”) (“இதற்காக நான் உங்களிடம் யாதொரு கூலியும் கேட்கவில்லை; என்னுடைய கூலி அகிலங்களுக்கெல்லாம் இறைவனாகியவனிடமேயன்றி (வேறெவரிடமும்) இல்லை.”) (“நீங்கள் ஒவ்வொரு மேட்டுப் பகுதியிலும் வீணாக ஒரு சின்னத்தை எழுப்புகிறீர்களா?”)"},"123":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=135\" class=\"link\">26:135</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:135 ஐ பார்க்கவும்"},"124":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=135\" class=\"link\">26:135</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:135 ஐ பார்க்கவும்"},"125":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=135\" class=\"link\">26:135</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:135 ஐ பார்க்கவும்"},"126":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=135\" class=\"link\">26:135</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:135 ஐ பார்க்கவும்"},"127":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=135\" class=\"link\">26:135</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:135 ஐ பார்க்கவும்"},"128":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=135\" class=\"link\">26:135</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:135 ஐ பார்க்கவும்"},"129":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=135\" class=\"link\">26:135</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:135 ஐ பார்க்கவும்"},"130":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=135\" class=\"link\">26:135</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:135 ஐ பார்க்கவும்"},"131":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=135\" class=\"link\">26:135</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:135 ஐ பார்க்கவும்"},"132":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=135\" class=\"link\">26:135</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:135 ஐ பார்க்கவும்"},"133":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=135\" class=\"link\">26:135</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:135 ஐ பார்க்கவும்"},"134":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=135\" class=\"link\">26:135</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:135 ஐ பார்க்கவும்"},"135":{"html":"<strong>ஹூத் (அலை) அவர்கள் தம் சமூகமான ஆத் கூட்டத்தினருக்கு விடுத்த அழைப்பு</strong><br />\r\n<br />\r\nஇங்கே அல்லாஹ் தனது அடியாரும் தூதருமான ஹூத் (அலை) அவர்களைப் பற்றி, அவர்கள் தம் சமூகமான ஆத் கூட்டத்தினரை (நேர்வழியின் பக்கம்) அழைத்தபோது நடந்ததைக் கூறுகிறான். அவர்களுடைய சமூகம் யமனிலுள்ள ஹள்ரமவ்த் (Hadramawt) எல்லைப்பகுதியிலுள்ள வளைந்த மணற்குன்றுகளைக் கொண்ட 'அஹ்காஃப்' (Ahqaf) எனும் பகுதியில் வசித்து வந்தது. அவர்கள் நூஹ் (அலை) அவர்களின் காலத்திற்குப் பிறகு வாழ்ந்தார்கள். ஸூரத்துல் அஃராஃபில் அல்லாஹ் கூறுகிறான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَاذكُرُواْ</span> <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">جَعَلَكُمْ</span> <span class=\"quran-arabic-font text-success\">خُلَفَآءَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِ</span> <span class=\"quran-arabic-font text-success\">قَوْمِ</span> <span class=\"quran-arabic-font text-success\">نُوحٍ</span> <span class=\"quran-arabic-font text-success\">وَزَادَكُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْخَلْقِ</span> <span class=\"quran-arabic-font text-success\">بَسْطَةً﴿</span><br />\r\n<br />\r\n(நூஹ் (அலை) அவர்களின் சமூகத்திற்குப் பிறகு உங்களை அவன் வழித்தோன்றல்களாக ஆக்கினான் என்பதையும், உடல் அமைப்பில் உங்களை அவன் மேம்படுத்தினான் என்பதையும் நினைவுகூருங்கள்) (<a href=\"qurandisp.php?sura=7&ayah=69\" class=\"link\">7:69</a>). இது, அவர்கள் உடல் ரீதியாக வலிமையாகவும், நல்ல உடற்கட்டுடனும், மிகவும் உயரமானவர்களாகவும், மூர்க்கமானவர்களாகவும் இருந்தார்கள் என்பதைக் குறிக்கிறது. மேலும் அவர்களுக்கு ஏராளமான வாழ்வாதாரங்கள், செல்வம், தோட்டங்கள், ஆறுகள், புதல்வர்கள், பயிர்கள் மற்றும் கனிகள் வழங்கப்பட்டிருந்தன. இவ்வளவு இருந்தும், அவர்கள் அல்லாஹ்வையல்லாது பிறரை வணங்கினார்கள். ஆகவே, அல்லாஹ் அவர்களிலிருந்தே ஒருவரான ஹூத் (அலை) அவர்களை நற்செய்தி கூறுபவராகவும், எச்சரிக்கை செய்பவராகவும் ஒரு தூதராக அனுப்பினான். அவர்கள் அல்லாஹ்வை மட்டும் வணங்குமாறு அழைப்பு விடுத்தார்கள். மேலும், அவர்கள் தமக்கு மாறு செய்து, தம்மைத் துன்புறுத்தினால் ஏற்படக்கூடிய அல்லாஹ்வின் கோபம் மற்றும் தண்டனையைக் குறித்து எச்சரித்தார்கள். நூஹ் (அலை) அவர்கள் தம் சமூகத்தினரிடம் கூறியது போலவே, இவர்களும் அவர்களிடம் கூறினார்கள்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَتَبْنُونَ</span> <span class=\"quran-arabic-font text-success\">بِكُلِّ</span> <span class=\"quran-arabic-font text-success\">رِيعٍ</span> <span class=\"quran-arabic-font text-success\">ءَايَةً</span> <span class=\"quran-arabic-font text-success\">تَعْبَثُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(ஒவ்வொரு உயர்ந்த இடத்திலும் (Ri') வேடிக்கைக்காக ஒரு அடையாளத்தை நீங்கள் எழுப்புகிறீர்களா?) ‘ரிஃ’ (Ri') என்ற சொல்லின் பொருள் குறித்து தஃப்ஸீர் அறிஞர்கள் பல கருத்துக்களைக் கொண்டுள்ளனர். சுருக்கமாகக் கூறினால், அது பிரதான சாலைகள் சந்திக்கும் இடத்திலுள்ள உயர்ந்த பகுதியைக் குறிக்கிறது. அங்கு அவர்கள் பிரம்மாண்டமான, உறுதியான மற்றும் வியக்கத்தக்க கட்டிடங்களைக் கட்டுவார்கள். இதனால்தான் அவர்கள் கூறினார்கள்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَتَبْنُونَ</span> <span class=\"quran-arabic-font text-success\">بِكُلِّ</span> <span class=\"quran-arabic-font text-success\">رِيعٍ</span> <span class=\"quran-arabic-font text-success\">ءَايَةً﴿</span><br />\r\n<br />\r\n(ஒவ்வொரு உயர்ந்த இடத்திலும் ஒரு அடையாளத்தை நீங்கள் எழுப்புகிறீர்களா?) அதாவது, ஒரு பிரசித்தி பெற்ற அடையாளச் சின்னம்,<br />\r\n<span class=\"quran-arabic-font text-success\">﴾تَعْبَثُونَ﴿</span><br />\r\n<br />\r\n(வேடிக்கைக்காக) என்பதன் பொருள், ‘அதை நீங்கள் தேவைக்காகச் செய்யவில்லை, மாறாக வீணான நோக்கத்திற்காகவும், விளையாட்டிற்காகவும், உங்கள் வலிமையைப் பறைசாற்றுவதற்காகவுமே செய்கிறீர்கள்’ என்பதாகும். ஆகவே, அவர்களின் நபியான ஹூத் (அலை) அவர்கள் இச்செயலைக் கண்டித்தார்கள். ஏனெனில், இது நேரத்தை வீணடிப்பதாகவும், எந்தப் பயனுமின்றி மக்களின் உடலை வருத்துவதாகவும், இவ்வுலகிலோ மறுமையிலோ பலன் தராத காரியத்தில் அவர்களை மூழ்கச் செய்வதாகவும் இருந்தது. அவர்கள் கூறினார்கள்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَتَتَّخِذُونَ</span> <span class=\"quran-arabic-font text-success\">مَصَانِعَ</span> <span class=\"quran-arabic-font text-success\">لَعَلَّكُمْ</span> <span class=\"quran-arabic-font text-success\">تَخْلُدُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும் நீங்கள் என்றென்றும் நிலைத்திருப்பீர்கள் என்பது போல், உங்களுக்காக மஸானிஃகளை (மாளிகைகளை) அமைத்துக் கொள்கிறீர்களா?) முஜாஹித் அவர்கள் கூறினார்கள்: “இதன் பொருள் உறுதியாகவும், உயரமாகவும் கட்டப்பட்ட கோட்டைகளும், நீண்ட காலம் நிலைத்திருக்கக் கூடிய கட்டிடங்களும் ஆகும்.”<br />\r\n<span class=\"quran-arabic-font text-success\">﴾لَعَلَّكُمْ</span> <span class=\"quran-arabic-font text-success\">تَخْلُدُونَ﴿</span><br />\r\n<br />\r\n(நீங்கள் அங்கே என்றென்றும் நிலைத்திருக்கப் போகிறீர்கள் என்பது போல்) என்பதன் பொருள்: ‘நீங்கள் அங்கே நிரந்தரமாகத் தங்கிவிடலாம் என எண்ணுகிறீர்கள். ஆனால் அது நடக்கப் போவதில்லை. ஏனெனில் உங்களுக்கு முன் இருந்தவர்களுக்கு என்ன நேர்ந்ததோ, அதுபோலவே இவையும் ஒருநாள் அழிந்துவிடும்.’<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَإِذَا</span> <span class=\"quran-arabic-font text-success\">بَطَشْتُمْ</span> <span class=\"quran-arabic-font text-success\">بَطَشْتُمْ</span> <span class=\"quran-arabic-font text-success\">جَبَّارِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும் நீங்கள் (எவரையும்) பிடிக்கும்போது, கொடுங்கோலர்களாகப் பிடிக்கிறீர்கள்) அவர்கள் வலிமையானவர்களாகவும், மூர்க்கமானவர்களாகவும், கொடுங்கோன்மை மிக்கவர்களாகவும் இங்கே வர்ணிக்கப்படுகிறார்கள்.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَاتَّقُواْ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">وَأَطِيعُونِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(எனவே, அல்லாஹ்விடம் தக்வா (இறையச்சம்) கொள்ளுங்கள்; எனக்குக் கீழ்ப்படியுங்கள்.) ‘உங்கள் இறைவனை வணங்குங்கள், உங்கள் தூதருக்குக் கீழ்ப்படியுங்கள்’ (என்பது இதன் பொருள்). பின்னர் ஹூத் (அலை) அவர்கள், அல்லாஹ் அவர்களுக்கு வழங்கிய அருட்கொடைகளைப் பற்றி நினைவூட்டத் தொடங்கினார்கள். அவர்கள் கூறினார்கள்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَاتَّقُواْ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">أَمَدَّكُمْ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">تَعْلَمُونَ</span> - <span class=\"quran-arabic-font text-success\">أَمَدَّكُمْ</span> <span class=\"quran-arabic-font text-success\">بِأَنْعَامٍ</span> <span class=\"quran-arabic-font text-success\">وَبَنِينَ</span> - <span class=\"quran-arabic-font text-success\">وَجَنَّاتٍ</span> <span class=\"quran-arabic-font text-success\">وَعُيُونٍ</span> - <span class=\"quran-arabic-font text-success\">إِنِّى</span> <span class=\"quran-arabic-font text-success\">أَخَافُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">عَذَابَ</span> <span class=\"quran-arabic-font text-success\">يَوْمٍ</span> <span class=\"quran-arabic-font text-success\">عَظِيمٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நீங்கள் அறிந்திருப்பதைக் கொண்டு உங்களுக்கு உதவி செய்தவனுக்கு அஞ்சுங்கள். அவன் உங்களுக்கு கால்நடைகள், புதல்வர்கள், தோட்டங்கள் மற்றும் நீரூற்றுகளைக் கொண்டு உதவி செய்துள்ளான். நிச்சயமாக, ஒரு மகத்தான நாளின் வேதனை உங்கள் மீது வருவதை நான் அஞ்சுகிறேன்.) அதாவது, ‘நீங்கள் உங்கள் நபியை நிராகரித்து அவருக்கு மாறு செய்தால் (அந்த வேதனை வரும்)’. இவ்வாறு அவர்கள் ஆசை வார்த்தைகளைக் கூறியும், எச்சரித்தும் அல்லாஹ்வின் பக்கம் அவர்களை அழைத்தார்கள். ஆனால் அதனால் எந்தப் பயனும் ஏற்படவில்லை.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالُواْ</span> <span class=\"quran-arabic-font text-success\">سَوَآءٌ</span> <span class=\"quran-arabic-font text-success\">عَلَيْنَآ</span> <span class=\"quran-arabic-font text-success\">أَوَعَظْتَ</span> <span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">تَكُنْ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْوَعِظِينَ</span> - <span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">هَذَا</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">خُلُقُ</span> <span class=\"quran-arabic-font text-success\">الْأَوَّلِينَ</span> - <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">نَحْنُ</span> <span class=\"quran-arabic-font text-success\">بِمُعَذَّبِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அதற்கு) அவர்கள் கூறினார்கள்: \"நீர் உபதேசம் செய்வதும், அல்லது உபதேசம் செய்பவராக நீர் இல்லாமலிருப்பதும் எங்களுக்குச் சமமே. இது முன்னோர்களின் வழக்கமேயன்றி வேறில்லை. நாங்கள் வேதனை செய்யப்படுபவர்கள் அல்லர்.\"<br />\r\n<br />","text":"ஹூத் (அலை) அவர்கள் தம் சமூகமான ஆத் கூட்டத்தினருக்கு விடுத்த அழைப்பு\n\r\n\n\r\nஇங்கே அல்லாஹ் தனது அடியாரும் தூதருமான ஹூத் (அலை) அவர்களைப் பற்றி, அவர்கள் தம் சமூகமான ஆத் கூட்டத்தினரை (நேர்வழியின் பக்கம்) அழைத்தபோது நடந்ததைக் கூறுகிறான். அவர்களுடைய சமூகம் யமனிலுள்ள ஹள்ரமவ்த் (Hadramawt) எல்லைப்பகுதியிலுள்ள வளைந்த மணற்குன்றுகளைக் கொண்ட 'அஹ்காஃப்' (Ahqaf) எனும் பகுதியில் வசித்து வந்தது. அவர்கள் நூஹ் (அலை) அவர்களின் காலத்திற்குப் பிறகு வாழ்ந்தார்கள். ஸூரத்துல் அஃராஃபில் அல்லாஹ் கூறுகிறான்:\n\r\n﴾وَاذكُرُواْ إِذْ جَعَلَكُمْ خُلَفَآءَ مِن بَعْدِ قَوْمِ نُوحٍ وَزَادَكُمْ فِى الْخَلْقِ بَسْطَةً﴿\n\r\n\n\r\n(நூஹ் (அலை) அவர்களின் சமூகத்திற்குப் பிறகு உங்களை அவன் வழித்தோன்றல்களாக ஆக்கினான் என்பதையும், உடல் அமைப்பில் உங்களை அவன் மேம்படுத்தினான் என்பதையும் நினைவுகூருங்கள்) (7:69). இது, அவர்கள் உடல் ரீதியாக வலிமையாகவும், நல்ல உடற்கட்டுடனும், மிகவும் உயரமானவர்களாகவும், மூர்க்கமானவர்களாகவும் இருந்தார்கள் என்பதைக் குறிக்கிறது. மேலும் அவர்களுக்கு ஏராளமான வாழ்வாதாரங்கள், செல்வம், தோட்டங்கள், ஆறுகள், புதல்வர்கள், பயிர்கள் மற்றும் கனிகள் வழங்கப்பட்டிருந்தன. இவ்வளவு இருந்தும், அவர்கள் அல்லாஹ்வையல்லாது பிறரை வணங்கினார்கள். ஆகவே, அல்லாஹ் அவர்களிலிருந்தே ஒருவரான ஹூத் (அலை) அவர்களை நற்செய்தி கூறுபவராகவும், எச்சரிக்கை செய்பவராகவும் ஒரு தூதராக அனுப்பினான். அவர்கள் அல்லாஹ்வை மட்டும் வணங்குமாறு அழைப்பு விடுத்தார்கள். மேலும், அவர்கள் தமக்கு மாறு செய்து, தம்மைத் துன்புறுத்தினால் ஏற்படக்கூடிய அல்லாஹ்வின் கோபம் மற்றும் தண்டனையைக் குறித்து எச்சரித்தார்கள். நூஹ் (அலை) அவர்கள் தம் சமூகத்தினரிடம் கூறியது போலவே, இவர்களும் அவர்களிடம் கூறினார்கள்:\n\r\n﴾أَتَبْنُونَ بِكُلِّ رِيعٍ ءَايَةً تَعْبَثُونَ ﴿\n\r\n\n\r\n(ஒவ்வொரு உயர்ந்த இடத்திலும் (Ri') வேடிக்கைக்காக ஒரு அடையாளத்தை நீங்கள் எழுப்புகிறீர்களா?) ‘ரிஃ’ (Ri') என்ற சொல்லின் பொருள் குறித்து தஃப்ஸீர் அறிஞர்கள் பல கருத்துக்களைக் கொண்டுள்ளனர். சுருக்கமாகக் கூறினால், அது பிரதான சாலைகள் சந்திக்கும் இடத்திலுள்ள உயர்ந்த பகுதியைக் குறிக்கிறது. அங்கு அவர்கள் பிரம்மாண்டமான, உறுதியான மற்றும் வியக்கத்தக்க கட்டிடங்களைக் கட்டுவார்கள். இதனால்தான் அவர்கள் கூறினார்கள்:\n\r\n﴾أَتَبْنُونَ بِكُلِّ رِيعٍ ءَايَةً﴿\n\r\n\n\r\n(ஒவ்வொரு உயர்ந்த இடத்திலும் ஒரு அடையாளத்தை நீங்கள் எழுப்புகிறீர்களா?) அதாவது, ஒரு பிரசித்தி பெற்ற அடையாளச் சின்னம்,\n\r\n﴾تَعْبَثُونَ﴿\n\r\n\n\r\n(வேடிக்கைக்காக) என்பதன் பொருள், ‘அதை நீங்கள் தேவைக்காகச் செய்யவில்லை, மாறாக வீணான நோக்கத்திற்காகவும், விளையாட்டிற்காகவும், உங்கள் வலிமையைப் பறைசாற்றுவதற்காகவுமே செய்கிறீர்கள்’ என்பதாகும். ஆகவே, அவர்களின் நபியான ஹூத் (அலை) அவர்கள் இச்செயலைக் கண்டித்தார்கள். ஏனெனில், இது நேரத்தை வீணடிப்பதாகவும், எந்தப் பயனுமின்றி மக்களின் உடலை வருத்துவதாகவும், இவ்வுலகிலோ மறுமையிலோ பலன் தராத காரியத்தில் அவர்களை மூழ்கச் செய்வதாகவும் இருந்தது. அவர்கள் கூறினார்கள்:\n\r\n﴾وَتَتَّخِذُونَ مَصَانِعَ لَعَلَّكُمْ تَخْلُدُونَ ﴿\n\r\n\n\r\n(மேலும் நீங்கள் என்றென்றும் நிலைத்திருப்பீர்கள் என்பது போல், உங்களுக்காக மஸானிஃகளை (மாளிகைகளை) அமைத்துக் கொள்கிறீர்களா?) முஜாஹித் அவர்கள் கூறினார்கள்: “இதன் பொருள் உறுதியாகவும், உயரமாகவும் கட்டப்பட்ட கோட்டைகளும், நீண்ட காலம் நிலைத்திருக்கக் கூடிய கட்டிடங்களும் ஆகும்.”\n\r\n﴾لَعَلَّكُمْ تَخْلُدُونَ﴿\n\r\n\n\r\n(நீங்கள் அங்கே என்றென்றும் நிலைத்திருக்கப் போகிறீர்கள் என்பது போல்) என்பதன் பொருள்: ‘நீங்கள் அங்கே நிரந்தரமாகத் தங்கிவிடலாம் என எண்ணுகிறீர்கள். ஆனால் அது நடக்கப் போவதில்லை. ஏனெனில் உங்களுக்கு முன் இருந்தவர்களுக்கு என்ன நேர்ந்ததோ, அதுபோலவே இவையும் ஒருநாள் அழிந்துவிடும்.’\n\r\n﴾وَإِذَا بَطَشْتُمْ بَطَشْتُمْ جَبَّارِينَ ﴿\n\r\n\n\r\n(மேலும் நீங்கள் (எவரையும்) பிடிக்கும்போது, கொடுங்கோலர்களாகப் பிடிக்கிறீர்கள்) அவர்கள் வலிமையானவர்களாகவும், மூர்க்கமானவர்களாகவும், கொடுங்கோன்மை மிக்கவர்களாகவும் இங்கே வர்ணிக்கப்படுகிறார்கள்.\n\r\n﴾فَاتَّقُواْ اللَّهَ وَأَطِيعُونِ ﴿\n\r\n\n\r\n(எனவே, அல்லாஹ்விடம் தக்வா (இறையச்சம்) கொள்ளுங்கள்; எனக்குக் கீழ்ப்படியுங்கள்.) ‘உங்கள் இறைவனை வணங்குங்கள், உங்கள் தூதருக்குக் கீழ்ப்படியுங்கள்’ (என்பது இதன் பொருள்). பின்னர் ஹூத் (அலை) அவர்கள், அல்லாஹ் அவர்களுக்கு வழங்கிய அருட்கொடைகளைப் பற்றி நினைவூட்டத் தொடங்கினார்கள். அவர்கள் கூறினார்கள்:\n\r\n﴾وَاتَّقُواْ الَّذِى أَمَدَّكُمْ بِمَا تَعْلَمُونَ - أَمَدَّكُمْ بِأَنْعَامٍ وَبَنِينَ - وَجَنَّاتٍ وَعُيُونٍ - إِنِّى أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمٍ ﴿\n\r\n\n\r\n(நீங்கள் அறிந்திருப்பதைக் கொண்டு உங்களுக்கு உதவி செய்தவனுக்கு அஞ்சுங்கள். அவன் உங்களுக்கு கால்நடைகள், புதல்வர்கள், தோட்டங்கள் மற்றும் நீரூற்றுகளைக் கொண்டு உதவி செய்துள்ளான். நிச்சயமாக, ஒரு மகத்தான நாளின் வேதனை உங்கள் மீது வருவதை நான் அஞ்சுகிறேன்.) அதாவது, ‘நீங்கள் உங்கள் நபியை நிராகரித்து அவருக்கு மாறு செய்தால் (அந்த வேதனை வரும்)’. இவ்வாறு அவர்கள் ஆசை வார்த்தைகளைக் கூறியும், எச்சரித்தும் அல்லாஹ்வின் பக்கம் அவர்களை அழைத்தார்கள். ஆனால் அதனால் எந்தப் பயனும் ஏற்படவில்லை.\n\r\n﴾قَالُواْ سَوَآءٌ عَلَيْنَآ أَوَعَظْتَ أَمْ لَمْ تَكُنْ مِّنَ الْوَعِظِينَ - إِنْ هَذَا إِلاَّ خُلُقُ الْأَوَّلِينَ - وَمَا نَحْنُ بِمُعَذَّبِينَ ﴿\n\r\n\n\r\n(அதற்கு) அவர்கள் கூறினார்கள்: \"நீர் உபதேசம் செய்வதும், அல்லது உபதேசம் செய்பவராக நீர் இல்லாமலிருப்பதும் எங்களுக்குச் சமமே. இது முன்னோர்களின் வழக்கமேயன்றி வேறில்லை. நாங்கள் வேதனை செய்யப்படுபவர்கள் அல்லர்.\""},"136":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=140\" class=\"link\">26:140</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:140 ஐ பார்க்கவும்"},"137":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=140\" class=\"link\">26:140</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:140 ஐ பார்க்கவும்"},"138":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=140\" class=\"link\">26:140</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:140 ஐ பார்க்கவும்"},"139":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=140\" class=\"link\">26:140</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:140 ஐ பார்க்கவும்"},"140":{"html":"<strong>ஹூத் (அலை) அவர்களின் சமூகத்தினர் அளித்த பதிலும், அவர்களுக்கான தண்டனையும்</strong><br />\r\n<br />\r\nஹூத் (அலை) அவர்கள் தம் சமூகத்தாருக்கு எச்சரிக்கை விடுத்தும், நன்மைகளை நோக்கி அவர்களை ஆர்வமூட்டியும், சத்தியத்தைத் தெளிவாக விளக்கியும் கூறிய பிறகு, அவர்கள் அவருக்கு எத்தகைய பதிலளித்தார்கள் என்பதை அல்லாஹ் கூறுகிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالُواْ</span> <span class=\"quran-arabic-font text-success\">سَوَآءٌ</span> <span class=\"quran-arabic-font text-success\">عَلَيْنَآ</span> <span class=\"quran-arabic-font text-success\">أَوَعَظْتَ</span> <span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">تَكُنْ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْوَعِظِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அவர்கள் கூறினார்கள்: \"நீர் எமக்கு அறிவுரை கூறினாலும் அல்லது அறிவுரை கூறுபவராக இல்லாவிட்டாலும் எமக்குச் சமமே.\") அதாவது, \"நாங்கள் எங்கள் வழிகளைக் கைவிடப்போவதில்லை.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمَا</span> <span class=\"quran-arabic-font text-success\">نَحْنُ</span> <span class=\"quran-arabic-font text-success\">بِتَارِكِى</span> <span class=\"quran-arabic-font text-success\">ءالِهَتِنَا</span> <span class=\"quran-arabic-font text-success\">عَن</span> <span class=\"quran-arabic-font text-success\">قَوْلِكَ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">نَحْنُ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">بِمُؤْمِنِينَ﴿</span><br />\r\n<br />\r\n(உமது வெறும் சொல்லுக்காக நாங்கள் எங்கள் தெய்வங்களை விட்டுவிடுபவர்கள் அல்லர்; நாங்கள் உம்மை நம்புபவர்களும் அல்லர்) (<a href=\"qurandisp.php?sura=11&ayah=53\" class=\"link\">11:53</a>). நிலைமை இவ்வாறுதான் இருந்தது, அல்லாஹ் கூறுவது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">سَوَآءٌ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">ءَأَنذَرْتَهُمْ</span> <span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">تُنذِرْهُمْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, நிராகரிப்பவர்களை நீர் எச்சரித்தாலும் சரி, அல்லது எச்சரிக்காவிட்டாலும் சரி அவர்களுக்குச் சமமே; அவர்கள் நம்பிக்கை கொள்ள மாட்டார்கள்) (<a href=\"qurandisp.php?sura=2&ayah=6\" class=\"link\">2:6</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">حَقَّتْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">كَلِمَةُ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(உண்மையில், எவர்கள் மீது உமது இறைவனின் வாக்கு உறுதியாகிவிட்டதோ, அவர்கள் நம்பிக்கை கொள்ள மாட்டார்கள்) (<a href=\"qurandisp.php?sura=10&ayah=96\" class=\"link\">10:96</a>-97). மேலும் அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنْ</span> <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">خُلُقُ</span> <span class=\"quran-arabic-font text-success\">الاٌّوَّلِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(இது முன்னோர்களின் 'குலுக்' (பழக்கவழக்கம்) அன்றி வேறில்லை.) சில அறிஞர்கள் இதனை \"கல்க்\" (Khalq) என்று ஓதுகிறார்கள். இப்னு மஸ்ஊத் (ரழி), அப்துல்லாஹ் பின் அப்பாஸ் (ரழி) — அல்-அவ்ஃபியிடமிருந்து அறிவிக்கப்பட்டபடி — அல்கமா (ரழி) மற்றும் முஜாஹித் (ரழி) ஆகியோரின் கூற்றுப்படி, \"நீர் எங்களிடம் கொண்டு வந்திருப்பவை முன்னோர்களின் கட்டுக்கதைகளே (இக்திலாக்)\" என்பது இதன் பொருளாகும். இது குறைஷி இணைவைப்பாளர்கள் கூறியதைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">أَسَـطِيرُ</span> <span class=\"quran-arabic-font text-success\">الاٌّوَّلِينَ</span> <span class=\"quran-arabic-font text-success\">اكْتَتَبَهَا</span> <span class=\"quran-arabic-font text-success\">فَهِىَ</span> <span class=\"quran-arabic-font text-success\">تُمْلَى</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">بُكْرَةً</span> <span class=\"quran-arabic-font text-success\">وَأَصِيلاً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும் அவர்கள் கூறுகிறார்கள்: \"இவை முன்னோர்களின் கட்டுக்கதைகள்; அவற்றை அவர் எழுதி வைத்துள்ளார்; அவை காலையிலும் மாலையிலும் அவருக்கு ஓதிக் காட்டப்படுகின்றன.\") (<a href=\"qurandisp.php?sura=25&ayah=5\" class=\"link\">25:5</a>) மேலும் அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَقَالَ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">كَفَرُواْ</span> <span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">إِفْكٌ</span> <span class=\"quran-arabic-font text-success\">افْتَرَاهُ</span> <span class=\"quran-arabic-font text-success\">وَأَعَانَهُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">قَوْمٌ</span> <span class=\"quran-arabic-font text-success\">ءَاخَرُونَ</span> <span class=\"quran-arabic-font text-success\">فَقَدْ</span> <span class=\"quran-arabic-font text-success\">جَآءُوا</span> <span class=\"quran-arabic-font text-success\">ظُلْماً</span> <span class=\"quran-arabic-font text-success\">وَزُوراً</span> <span class=\"quran-arabic-font text-success\">وَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">أَسَـطِيرُ</span> <span class=\"quran-arabic-font text-success\">الاٌّوَّلِينَ﴿</span><br />\r\n<br />\r\n(நிராகரிப்பவர்கள் கூறுகிறார்கள்: \"இது அவர் இட்டுக்கட்டிய ஒரு பொய்யே அன்றி வேறில்லை; இதற்கு மற்ற மக்கள் அவருக்கு உதவி செய்திருக்கிறார்கள். உண்மையில், அவர்கள் ஓர் அநீதியையும் ஒரு பொய்யையுமே கொண்டு வந்திருக்கிறார்கள்.\" மேலும் அவர்கள், \"முன்னோர்களின் கட்டுக்கதைகள்...\" என்றும் கூறுகிறார்கள்.) (<a href=\"qurandisp.php?sura=25&ayah=4\" class=\"link\">25:4</a>-5)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَإِذَا</span> <span class=\"quran-arabic-font text-success\">قِيلَ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">مَّاذَآ</span> <span class=\"quran-arabic-font text-success\">أَنزَلَ</span> <span class=\"quran-arabic-font text-success\">رَبُّكُمْ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">أَسَـطِيرُ</span> <span class=\"quran-arabic-font text-success\">الاٌّوَّلِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும் அவர்களிடம்: \"உங்கள் இறைவன் எதை இறக்கி வைத்தான்?\" என்று கேட்கப்பட்டால், \"முன்னோர்களின் கட்டுக்கதைகள்!\" என்று அவர்கள் கூறுகிறார்கள்.) (<a href=\"qurandisp.php?sura=16&ayah=24\" class=\"link\">16:24</a>).<br />\r\n<br />\r\nவேறு சில அறிஞர்கள் இதை இவ்வாறு ஓதினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنْ</span> <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">خُلُقُ</span> <span class=\"quran-arabic-font text-success\">الاٌّوَّلِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(இது முன்னோர்களின் 'குலுக்' (பழக்கவழக்கம்) அன்றி வேறில்லை.) \"குலுக்\" என்பது அவர்களின் மார்க்கத்தைக் குறிக்கும். அவர்கள் பின்பற்றி வந்தது முன்னோர்கள் மற்றும் அவர்களின் தந்தை, பாட்டனார்களின் மார்க்கத்தையே. அதாவது, \"நாங்கள் அவர்களைப் பின்பற்றுகிறோம்; அவர்கள் வாழ்ந்ததைப் போல வாழ்ந்து, அவர்கள் மரித்ததைப் போல மரிப்போம்; மீண்டும் உயிர்த்தெழுதலோ, தீர்ப்பு நாளோ கிடையாது\" என்பது அவர்கள் கூற்றின் சாரமாகும். எனவேதான் அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَمَا</span> <span class=\"quran-arabic-font text-success\">نَحْنُ</span> <span class=\"quran-arabic-font text-success\">بِمُعَذَّبِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும் நாங்கள் தண்டிக்கப்படப்போவதில்லை.) அல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَكَذَّبُوهُ</span> <span class=\"quran-arabic-font text-success\">فَأَهْلَكْنَـهُمْ﴿</span><br />\r\n<br />\r\n(ஆகவே, அவர்கள் அவரைப் பொய்யாக்கினார்கள்; எனவே நாம் அவர்களை அழித்தோம்.) அதாவது, அவர்கள் அல்லாஹ்வின் தூதர் ஹூத் (அலை) அவர்களைத் தொடர்ந்து நிராகரித்து, பிடிவாதமாக எதிர்த்ததால் அல்லாஹ் அவர்களை அழித்தான். அவர்கள் அழிக்கப்பட்ட விதம் குர்ஆனில் பல இடங்களில் விவரிக்கப்பட்டுள்ளது: அல்லாஹ் அவர்களுக்கு எதிராக வலிமையான, சீற்றமிக்க மற்றும் மிகக் குளிர்ந்த புயல் காற்றை அனுப்பினான். அவர்கள் மிகவும் வலிமையானவர்களாகவும், மூர்க்கமானவர்களாகவும் இருந்ததால், அவர்கள் அழிக்கப்பட்ட விதமும் அவர்களின் இயல்புக்கு ஏற்றவாறு அமைந்திருந்தது. அவர்களை விடவும் வலிமையான மற்றும் மூர்க்கமான ஒன்றைக் கொண்டு அல்லாஹ் அவர்களை அடக்கினான். அல்லாஹ் கூறுவது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَلَمْ</span> <span class=\"quran-arabic-font text-success\">تَرَ</span> <span class=\"quran-arabic-font text-success\">كَيْفَ</span> <span class=\"quran-arabic-font text-success\">فَعَلَ</span> <span class=\"quran-arabic-font text-success\">رَبُّكَ</span> <span class=\"quran-arabic-font text-success\">بِعَادٍ</span> - <span class=\"quran-arabic-font text-success\">إِرَمَ</span> <span class=\"quran-arabic-font text-success\">ذَاتِ</span> <span class=\"quran-arabic-font text-success\">الْعِمَادِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(தூண்களைக் கொண்ட 'இரம்' நகரைச் சேர்ந்த 'ஆத்' சமூகத்தினரை உமது இறைவன் எப்படி (தண்டித்தான்) என்பதை நீர் பார்க்கவில்லையா?) (<a href=\"qurandisp.php?sura=89&ayah=6\" class=\"link\">89:6</a>-7). இது முந்தைய 'ஆத்' சமூகத்தைக் குறிக்கிறது. அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَأَنَّهُ</span> <span class=\"quran-arabic-font text-success\">أَهْلَكَ</span> <span class=\"quran-arabic-font text-success\">عَاداً</span> <span class=\"quran-arabic-font text-success\">الاٍّولَى</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(மேலும் நிச்சயமாக அவனே முந்தைய 'ஆத்' கூட்டத்தினரை அழித்தான்) (<a href=\"qurandisp.php?sura=53&ayah=50\" class=\"link\">53:50</a>). அவர்கள் நூஹ் (அலை) அவர்களின் மகனான சாம் என்பவரின் வழித்தோன்றலான இரம் என்பவரின் வம்சாவளியைச் சேர்ந்தவர்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾ذَاتِ</span> <span class=\"quran-arabic-font text-success\">الْعِمَادِ﴿</span><br />\r\n<br />\r\n(தூண்களைக் கொண்டவர்கள்) அவர்கள் தூண்களுக்கு மத்தியில் வாழ்ந்து வந்தார்கள். 'இரம்' என்பது ஒரு நகரம் என்று சொல்பவர்கள், இந்தத் தகவலை கஅப் (ரழி) மற்றும் வஹ்ப் (ரழி) ஆகியோரின் கூற்றுகளான இஸ்ராயீலிய்யத் (Isra'iliyyat) அறிவிப்புகளிலிருந்து பெறுகிறார்கள். ஆனால், அதற்கு முறையான ஆதாரம் எதுவுமில்லை. அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾الَّتِى</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يُخْلَقْ</span> <span class=\"quran-arabic-font text-success\">مِثْلُهَا</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْبِلَـدِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நாடுகளில் அது போன்றொன்று படைக்கப்படவில்லை) (<a href=\"qurandisp.php?sura=89&ayah=8\" class=\"link\">89:8</a>). அதாவது, வலிமை, ஆற்றல் மற்றும் கொடுங்கோன்மை ஆகியவற்றில் இந்த கோத்திரத்தைப் போன்று வேறெதுவும் படைக்கப்படவில்லை. ஒருவேளை அது ஒரு நகரத்தைக் குறித்திருந்தால், \"நாடுகளில் அது போன்றொன்று கட்டப்படவில்லை\" என்று கூறப்பட்டிருக்கும். மேலும் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَأَمَّا</span> <span class=\"quran-arabic-font text-success\">عَادٌ</span> <span class=\"quran-arabic-font text-success\">فَاسْتَكْبَرُواْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الاٌّرْضِ</span> <span class=\"quran-arabic-font text-success\">بِغَيْرِ</span> <span class=\"quran-arabic-font text-success\">الْحَقِّ</span> <span class=\"quran-arabic-font text-success\">وَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">أَشَدُّ</span> <span class=\"quran-arabic-font text-success\">مِنَّا</span> <span class=\"quran-arabic-font text-success\">قُوَّةً</span> <span class=\"quran-arabic-font text-success\">أَوَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَرَوْاْ</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">خَلَقَهُمْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">أَشَدُّ</span> <span class=\"quran-arabic-font text-success\">مِنْهُمْ</span> <span class=\"quran-arabic-font text-success\">قُوَّةً</span> <span class=\"quran-arabic-font text-success\">وَكَانُواْ</span> <span class=\"quran-arabic-font text-success\">بِـَايَـتِنَا</span> <span class=\"quran-arabic-font text-success\">يَجْحَدُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n('ஆத்' கூட்டத்தினரோ, பூமியில் அநியாயமாகப் பெருமை அடித்துக் கொண்டு, \"வலிமையில் எங்களை விடச் சிறந்தவர் யார்?\" என்று கூறினார்கள். அவர்களைப் படைத்த அல்லாஹ், அவர்களை விட வலிமையில் மிக்கவன் என்பதை அவர்கள் பார்க்கவில்லையா? அவர்கள் நமது அத்தாட்சிகளை மறுத்துக் கொண்டிருந்தார்கள்.) (<a href=\"qurandisp.php?sura=41&ayah=15\" class=\"link\">41:15</a>) மேலும் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَأَمَّا</span> <span class=\"quran-arabic-font text-success\">عَادٌ</span> <span class=\"quran-arabic-font text-success\">فَأُهْلِكُواْ</span> <span class=\"quran-arabic-font text-success\">بِرِيحٍ</span> <span class=\"quran-arabic-font text-success\">صَرْصَرٍ</span> <span class=\"quran-arabic-font text-success\">عَاتِيَةٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n('ஆத்' கூட்டத்தாரோ, அவர்கள் சீற்றமிக்க கடும் புயல் காற்றினால் அழிக்கப்பட்டார்கள்!)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾سَخَّرَهَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">سَبْعَ</span> <span class=\"quran-arabic-font text-success\">لَيَالٍ</span> <span class=\"quran-arabic-font text-success\">وَثَمَانِيَةَ</span> <span class=\"quran-arabic-font text-success\">أَيَّامٍ</span> <span class=\"quran-arabic-font text-success\">حُسُوماً﴿</span><br />\r\n<br />\r\n(தொடர்ச்சியாக) என்று அல்லாஹ் கூறும் வரை (<a href=\"qurandisp.php?sura=69&ayah=6\" class=\"link\">69:6</a>-7). அதாவது, தொடர்ந்து (ஏழு இரவுகளும் எட்டுப் பகல்களும்).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَتَرَى</span> <span class=\"quran-arabic-font text-success\">الْقَوْمَ</span> <span class=\"quran-arabic-font text-success\">فِيهَا</span> <span class=\"quran-arabic-font text-success\">صَرْعَى</span> <span class=\"quran-arabic-font text-success\">كَأَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">أَعْجَازُ</span> <span class=\"quran-arabic-font text-success\">نَخْلٍ</span> <span class=\"quran-arabic-font text-success\">خَاوِيَةٍ﴿</span><br />\r\n<br />\r\n(அதில் அந்த மக்கள் வீழ்ந்து கிடப்பதை நீர் காண்பீர்; அவர்கள் உள்ளீடற்ற பேரீச்சை மரத்தின் அடிமரங்களைப் போல் இருந்தார்கள்!) (<a href=\"qurandisp.php?sura=69&ayah=7\" class=\"link\">69:7</a>). இதன் பொருள், அவர்கள் தலையற்ற உடல்களாகக் கிடந்தார்கள். ஏனெனில், அந்தக் காற்று ஒருவரைத் தூக்கிச் சென்று தலைகீழாகக் கீழே வீசும்; அப்போது அவரது மூளை சிதறி, தலை உடைந்து அவர் தூக்கி எறியப்படுவார். அவர்கள் வேரோடு பிடுங்கப்பட்ட பேரீச்சை மரங்களைப் போல் காட்சியளித்தனர். அவர்கள் மலைகளிலும் குகைகளிலும் கோட்டைகளை அமைத்துக் கொண்டனர்; மேலும் ஒரு மனிதனின் உயரத்தில் பாதி அளவு ஆழத்திற்கு அகழிகளையும் தோண்டியிருந்தனர். ஆனால், அல்லாஹ்வின் கட்டளை வரும்போது அவை எவையும் அவர்களுக்குச் சிறிதும் உதவவில்லை.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">أَجَلَ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">جَآءَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُؤَخَّرُ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக, அல்லாஹ்வினால் குறிக்கப்பட்ட தவணை வந்துவிட்டால், அது பிற்படுத்தப்பட மாட்டாது) (<a href=\"qurandisp.php?sura=71&ayah=4\" class=\"link\">71:4</a>). அல்லாஹ் இங்கே கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَكَذَّبُوهُ</span> <span class=\"quran-arabic-font text-success\">فَأَهْلَكْنَـهُمْ﴿</span><br />\r\n<br />\r\n(ஆகவே, அவர்கள் அவரைப் பொய்யாக்கினார்கள்; எனவே நாம் அவர்களை அழித்தோம்.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">لأَيَةً</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">أَكْثَرُهُم</span> <span class=\"quran-arabic-font text-success\">مُّؤْمِنِينَ</span> - <span class=\"quran-arabic-font text-success\">وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">رَبَّكَ</span> <span class=\"quran-arabic-font text-success\">لَهُوَ</span> <span class=\"quran-arabic-font text-success\">الْعَزِيزُ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمُ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக இதில் ஓர் அத்தாட்சி இருக்கிறது; எனினும் அவர்களில் பெரும்பாலோர் நம்பிக்கை கொள்பவர்களாக இல்லை. மேலும் நிச்சயமாக உமது இறைவன் - அவன்தான் யாவற்றையும் மிகைத்தவன்; மிக்க கருணையாளன்.) (<a href=\"qurandisp.php?sura=26&ayah=139\" class=\"link\">26:139</a>-140).<br />\r\n<br />","text":"ஹூத் (அலை) அவர்களின் சமூகத்தினர் அளித்த பதிலும், அவர்களுக்கான தண்டனையும்\n\r\n\n\r\nஹூத் (அலை) அவர்கள் தம் சமூகத்தாருக்கு எச்சரிக்கை விடுத்தும், நன்மைகளை நோக்கி அவர்களை ஆர்வமூட்டியும், சத்தியத்தைத் தெளிவாக விளக்கியும் கூறிய பிறகு, அவர்கள் அவருக்கு எத்தகைய பதிலளித்தார்கள் என்பதை அல்லாஹ் கூறுகிறான்.\n\r\n\n\r\n﴾قَالُواْ سَوَآءٌ عَلَيْنَآ أَوَعَظْتَ أَمْ لَمْ تَكُنْ مِّنَ الْوَعِظِينَ ﴿\n\r\n\n\r\n(அவர்கள் கூறினார்கள்: \"நீர் எமக்கு அறிவுரை கூறினாலும் அல்லது அறிவுரை கூறுபவராக இல்லாவிட்டாலும் எமக்குச் சமமே.\") அதாவது, \"நாங்கள் எங்கள் வழிகளைக் கைவிடப்போவதில்லை.\"\n\r\n\n\r\n﴾وَمَا نَحْنُ بِتَارِكِى ءالِهَتِنَا عَن قَوْلِكَ وَمَا نَحْنُ لَكَ بِمُؤْمِنِينَ﴿\n\r\n\n\r\n(உமது வெறும் சொல்லுக்காக நாங்கள் எங்கள் தெய்வங்களை விட்டுவிடுபவர்கள் அல்லர்; நாங்கள் உம்மை நம்புபவர்களும் அல்லர்) (11:53). நிலைமை இவ்வாறுதான் இருந்தது, அல்லாஹ் கூறுவது போல:\n\r\n\n\r\n﴾إِنَّ الَّذِينَ كَفَرُواْ سَوَآءٌ عَلَيْهِمْ ءَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لاَ يُؤْمِنُونَ ﴿\n\r\n\n\r\n(நிச்சயமாக, நிராகரிப்பவர்களை நீர் எச்சரித்தாலும் சரி, அல்லது எச்சரிக்காவிட்டாலும் சரி அவர்களுக்குச் சமமே; அவர்கள் நம்பிக்கை கொள்ள மாட்டார்கள்) (2:6).\n\r\n\n\r\n﴾إِنَّ الَّذِينَ حَقَّتْ عَلَيْهِمْ كَلِمَةُ رَبِّكَ لاَ يُؤْمِنُونَ ﴿\n\r\n\n\r\n(உண்மையில், எவர்கள் மீது உமது இறைவனின் வாக்கு உறுதியாகிவிட்டதோ, அவர்கள் நம்பிக்கை கொள்ள மாட்டார்கள்) (10:96-97). மேலும் அவர்கள் கூறினார்கள்:\n\r\n\n\r\n﴾إِنْ هَـذَا إِلاَّ خُلُقُ الاٌّوَّلِينَ ﴿\n\r\n\n\r\n(இது முன்னோர்களின் 'குலுக்' (பழக்கவழக்கம்) அன்றி வேறில்லை.) சில அறிஞர்கள் இதனை \"கல்க்\" (Khalq) என்று ஓதுகிறார்கள். இப்னு மஸ்ஊத் (ரழி), அப்துல்லாஹ் பின் அப்பாஸ் (ரழி) — அல்-அவ்ஃபியிடமிருந்து அறிவிக்கப்பட்டபடி — அல்கமா (ரழி) மற்றும் முஜாஹித் (ரழி) ஆகியோரின் கூற்றுப்படி, \"நீர் எங்களிடம் கொண்டு வந்திருப்பவை முன்னோர்களின் கட்டுக்கதைகளே (இக்திலாக்)\" என்பது இதன் பொருளாகும். இது குறைஷி இணைவைப்பாளர்கள் கூறியதைப் போன்றது:\n\r\n\n\r\n﴾وَقَالُواْ أَسَـطِيرُ الاٌّوَّلِينَ اكْتَتَبَهَا فَهِىَ تُمْلَى عَلَيْهِ بُكْرَةً وَأَصِيلاً ﴿\n\r\n\n\r\n(மேலும் அவர்கள் கூறுகிறார்கள்: \"இவை முன்னோர்களின் கட்டுக்கதைகள்; அவற்றை அவர் எழுதி வைத்துள்ளார்; அவை காலையிலும் மாலையிலும் அவருக்கு ஓதிக் காட்டப்படுகின்றன.\") (25:5) மேலும் அல்லாஹ் கூறினான்:\n\r\n\n\r\n﴾وَقَالَ الَّذِينَ كَفَرُواْ إِنْ هَـذَا إِلاَّ إِفْكٌ افْتَرَاهُ وَأَعَانَهُ عَلَيْهِ قَوْمٌ ءَاخَرُونَ فَقَدْ جَآءُوا ظُلْماً وَزُوراً وَقَالُواْ أَسَـطِيرُ الاٌّوَّلِينَ﴿\n\r\n\n\r\n(நிராகரிப்பவர்கள் கூறுகிறார்கள்: \"இது அவர் இட்டுக்கட்டிய ஒரு பொய்யே அன்றி வேறில்லை; இதற்கு மற்ற மக்கள் அவருக்கு உதவி செய்திருக்கிறார்கள். உண்மையில், அவர்கள் ஓர் அநீதியையும் ஒரு பொய்யையுமே கொண்டு வந்திருக்கிறார்கள்.\" மேலும் அவர்கள், \"முன்னோர்களின் கட்டுக்கதைகள்...\" என்றும் கூறுகிறார்கள்.) (25:4-5)\n\r\n\n\r\n﴾وَإِذَا قِيلَ لَهُمْ مَّاذَآ أَنزَلَ رَبُّكُمْ قَالُواْ أَسَـطِيرُ الاٌّوَّلِينَ ﴿\n\r\n\n\r\n(மேலும் அவர்களிடம்: \"உங்கள் இறைவன் எதை இறக்கி வைத்தான்?\" என்று கேட்கப்பட்டால், \"முன்னோர்களின் கட்டுக்கதைகள்!\" என்று அவர்கள் கூறுகிறார்கள்.) (16:24).\n\r\n\n\r\nவேறு சில அறிஞர்கள் இதை இவ்வாறு ஓதினார்கள்:\n\r\n\n\r\n﴾إِنْ هَـذَا إِلاَّ خُلُقُ الاٌّوَّلِينَ ﴿\n\r\n\n\r\n(இது முன்னோர்களின் 'குலுக்' (பழக்கவழக்கம்) அன்றி வேறில்லை.) \"குலுக்\" என்பது அவர்களின் மார்க்கத்தைக் குறிக்கும். அவர்கள் பின்பற்றி வந்தது முன்னோர்கள் மற்றும் அவர்களின் தந்தை, பாட்டனார்களின் மார்க்கத்தையே. அதாவது, \"நாங்கள் அவர்களைப் பின்பற்றுகிறோம்; அவர்கள் வாழ்ந்ததைப் போல வாழ்ந்து, அவர்கள் மரித்ததைப் போல மரிப்போம்; மீண்டும் உயிர்த்தெழுதலோ, தீர்ப்பு நாளோ கிடையாது\" என்பது அவர்கள் கூற்றின் சாரமாகும். எனவேதான் அவர்கள் கூறினார்கள்:\n\r\n\n\r\n﴾وَمَا نَحْنُ بِمُعَذَّبِينَ ﴿\n\r\n\n\r\n(மேலும் நாங்கள் தண்டிக்கப்படப்போவதில்லை.) அல்லாஹ்வின் கூற்று:\n\r\n\n\r\n﴾فَكَذَّبُوهُ فَأَهْلَكْنَـهُمْ﴿\n\r\n\n\r\n(ஆகவே, அவர்கள் அவரைப் பொய்யாக்கினார்கள்; எனவே நாம் அவர்களை அழித்தோம்.) அதாவது, அவர்கள் அல்லாஹ்வின் தூதர் ஹூத் (அலை) அவர்களைத் தொடர்ந்து நிராகரித்து, பிடிவாதமாக எதிர்த்ததால் அல்லாஹ் அவர்களை அழித்தான். அவர்கள் அழிக்கப்பட்ட விதம் குர்ஆனில் பல இடங்களில் விவரிக்கப்பட்டுள்ளது: அல்லாஹ் அவர்களுக்கு எதிராக வலிமையான, சீற்றமிக்க மற்றும் மிகக் குளிர்ந்த புயல் காற்றை அனுப்பினான். அவர்கள் மிகவும் வலிமையானவர்களாகவும், மூர்க்கமானவர்களாகவும் இருந்ததால், அவர்கள் அழிக்கப்பட்ட விதமும் அவர்களின் இயல்புக்கு ஏற்றவாறு அமைந்திருந்தது. அவர்களை விடவும் வலிமையான மற்றும் மூர்க்கமான ஒன்றைக் கொண்டு அல்லாஹ் அவர்களை அடக்கினான். அல்லாஹ் கூறுவது போல:\n\r\n\n\r\n﴾أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِعَادٍ - إِرَمَ ذَاتِ الْعِمَادِ ﴿\n\r\n\n\r\n(தூண்களைக் கொண்ட 'இரம்' நகரைச் சேர்ந்த 'ஆத்' சமூகத்தினரை உமது இறைவன் எப்படி (தண்டித்தான்) என்பதை நீர் பார்க்கவில்லையா?) (89:6-7). இது முந்தைய 'ஆத்' சமூகத்தைக் குறிக்கிறது. அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾وَأَنَّهُ أَهْلَكَ عَاداً الاٍّولَى ﴿\n\r\n\n\r\n(மேலும் நிச்சயமாக அவனே முந்தைய 'ஆத்' கூட்டத்தினரை அழித்தான்) (53:50). அவர்கள் நூஹ் (அலை) அவர்களின் மகனான சாம் என்பவரின் வழித்தோன்றலான இரம் என்பவரின் வம்சாவளியைச் சேர்ந்தவர்கள்.\n\r\n\n\r\n﴾ذَاتِ الْعِمَادِ﴿\n\r\n\n\r\n(தூண்களைக் கொண்டவர்கள்) அவர்கள் தூண்களுக்கு மத்தியில் வாழ்ந்து வந்தார்கள். 'இரம்' என்பது ஒரு நகரம் என்று சொல்பவர்கள், இந்தத் தகவலை கஅப் (ரழி) மற்றும் வஹ்ப் (ரழி) ஆகியோரின் கூற்றுகளான இஸ்ராயீலிய்யத் (Isra'iliyyat) அறிவிப்புகளிலிருந்து பெறுகிறார்கள். ஆனால், அதற்கு முறையான ஆதாரம் எதுவுமில்லை. அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾الَّتِى لَمْ يُخْلَقْ مِثْلُهَا فِى الْبِلَـدِ ﴿\n\r\n\n\r\n(நாடுகளில் அது போன்றொன்று படைக்கப்படவில்லை) (89:8). அதாவது, வலிமை, ஆற்றல் மற்றும் கொடுங்கோன்மை ஆகியவற்றில் இந்த கோத்திரத்தைப் போன்று வேறெதுவும் படைக்கப்படவில்லை. ஒருவேளை அது ஒரு நகரத்தைக் குறித்திருந்தால், \"நாடுகளில் அது போன்றொன்று கட்டப்படவில்லை\" என்று கூறப்பட்டிருக்கும். மேலும் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾فَأَمَّا عَادٌ فَاسْتَكْبَرُواْ فِى الاٌّرْضِ بِغَيْرِ الْحَقِّ وَقَالُواْ مَنْ أَشَدُّ مِنَّا قُوَّةً أَوَلَمْ يَرَوْاْ أَنَّ اللَّهَ الَّذِى خَلَقَهُمْ هُوَ أَشَدُّ مِنْهُمْ قُوَّةً وَكَانُواْ بِـَايَـتِنَا يَجْحَدُونَ ﴿\n\r\n\n\r\n('ஆத்' கூட்டத்தினரோ, பூமியில் அநியாயமாகப் பெருமை அடித்துக் கொண்டு, \"வலிமையில் எங்களை விடச் சிறந்தவர் யார்?\" என்று கூறினார்கள். அவர்களைப் படைத்த அல்லாஹ், அவர்களை விட வலிமையில் மிக்கவன் என்பதை அவர்கள் பார்க்கவில்லையா? அவர்கள் நமது அத்தாட்சிகளை மறுத்துக் கொண்டிருந்தார்கள்.) (41:15) மேலும் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\n﴾وَأَمَّا عَادٌ فَأُهْلِكُواْ بِرِيحٍ صَرْصَرٍ عَاتِيَةٍ ﴿\n\r\n\n\r\n('ஆத்' கூட்டத்தாரோ, அவர்கள் சீற்றமிக்க கடும் புயல் காற்றினால் அழிக்கப்பட்டார்கள்!)\n\r\n\n\r\n﴾سَخَّرَهَا عَلَيْهِمْ سَبْعَ لَيَالٍ وَثَمَانِيَةَ أَيَّامٍ حُسُوماً﴿\n\r\n\n\r\n(தொடர்ச்சியாக) என்று அல்லாஹ் கூறும் வரை (69:6-7). அதாவது, தொடர்ந்து (ஏழு இரவுகளும் எட்டுப் பகல்களும்).\n\r\n\n\r\n﴾فَتَرَى الْقَوْمَ فِيهَا صَرْعَى كَأَنَّهُمْ أَعْجَازُ نَخْلٍ خَاوِيَةٍ﴿\n\r\n\n\r\n(அதில் அந்த மக்கள் வீழ்ந்து கிடப்பதை நீர் காண்பீர்; அவர்கள் உள்ளீடற்ற பேரீச்சை மரத்தின் அடிமரங்களைப் போல் இருந்தார்கள்!) (69:7). இதன் பொருள், அவர்கள் தலையற்ற உடல்களாகக் கிடந்தார்கள். ஏனெனில், அந்தக் காற்று ஒருவரைத் தூக்கிச் சென்று தலைகீழாகக் கீழே வீசும்; அப்போது அவரது மூளை சிதறி, தலை உடைந்து அவர் தூக்கி எறியப்படுவார். அவர்கள் வேரோடு பிடுங்கப்பட்ட பேரீச்சை மரங்களைப் போல் காட்சியளித்தனர். அவர்கள் மலைகளிலும் குகைகளிலும் கோட்டைகளை அமைத்துக் கொண்டனர்; மேலும் ஒரு மனிதனின் உயரத்தில் பாதி அளவு ஆழத்திற்கு அகழிகளையும் தோண்டியிருந்தனர். ஆனால், அல்லாஹ்வின் கட்டளை வரும்போது அவை எவையும் அவர்களுக்குச் சிறிதும் உதவவில்லை.\n\r\n\n\r\n﴾إِنَّ أَجَلَ اللَّهِ إِذَا جَآءَ لاَ يُؤَخَّرُ﴿\n\r\n\n\r\n(நிச்சயமாக, அல்லாஹ்வினால் குறிக்கப்பட்ட தவணை வந்துவிட்டால், அது பிற்படுத்தப்பட மாட்டாது) (71:4). அல்லாஹ் இங்கே கூறுகிறான்:\n\r\n\n\r\n﴾فَكَذَّبُوهُ فَأَهْلَكْنَـهُمْ﴿\n\r\n\n\r\n(ஆகவே, அவர்கள் அவரைப் பொய்யாக்கினார்கள்; எனவே நாம் அவர்களை அழித்தோம்.)\n\r\n\n\r\n﴾إِنَّ فِى ذَلِكَ لأَيَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ - وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ﴿\n\r\n\n\r\n(நிச்சயமாக இதில் ஓர் அத்தாட்சி இருக்கிறது; எனினும் அவர்களில் பெரும்பாலோர் நம்பிக்கை கொள்பவர்களாக இல்லை. மேலும் நிச்சயமாக உமது இறைவன் - அவன்தான் யாவற்றையும் மிகைத்தவன்; மிக்க கருணையாளன்.) (26:139-140)."},"141":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=145\" class=\"link\">26:145</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:145 ஐ பார்க்கவும்"},"142":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=145\" class=\"link\">26:145</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:145 ஐ பார்க்கவும்"},"143":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=145\" class=\"link\">26:145</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:145 ஐ பார்க்கவும்"},"144":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=145\" class=\"link\">26:145</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:145 ஐ பார்க்கவும்"},"145":{"html":"<strong>ஸாலிஹ் (அலை) மற்றும் தமூத் சமூகத்தினர்</strong><br />\r\n<br />\r\nஅல்லாஹ் தனது அடியாரும் தூதருமான ஸாலிஹ் (அலை) அவர்களைப் பற்றி இங்கு கூறுகிறான். அவர்களை அவன் தமூத் சமூகத்தினரிடம் அனுப்பினான். அவர்கள் 'அல்-ஹிஜ்ர்' எனும் நகரத்தில் வாழ்ந்த அரேபியர்கள் ஆவர். இது வாதி அல்-குராவுக்கும் பெரும் சிரியாவிற்கும் இடையில் அமைந்துள்ளது. அவர்கள் வாழ்ந்த இடம் நன்கு அறியப்பட்டதாகும். ஸூரா அல்-அஃராஃபின் விளக்கவுரையில், அல்லாஹ்வின் தூதர் (ஸல்) (ஸல்) அவர்கள் சிரியாவின் மீது போர் தொடுக்க விரும்பியபோது, அவர்களின் இருப்பிடங்களைக் கடந்து சென்றது குறித்த ஹதீஸ்களை நாம் குறிப்பிட்டுள்ளோம். அவர் தபூக் போருக்காகச் சென்ற போது இது நிகழ்ந்தது. தமூத் சமூகத்தினர் ஆத் சமூகத்திற்குப் பின்னரும், இப்ராஹீம் (அலை) அவர்களுக்கு முன்னரும் வாழ்ந்தனர்.<br />\r\n<br />\r\nஅவர்களது தூதர் ஸாலிஹ் (அலை), அல்லாஹ்வை மட்டுமே வணங்குமாறும், அவனுக்கு எதனையும் இணையாக்கக் கூடாது என்றும், தமக்கு வழங்கப்பட்டக் கட்டளைகளுக்குக் கீழ்ப்படியுமாறும் அவர்களை அழைத்தார்கள். ஆனால் அவர்களோ அவரை நிராகரித்து, அவருக்கு எதிர்ப்பைத் தெரிவித்தார்கள். தனது இந்த அழைப்புப் பணிக்காக அவர்களிடம் எவ்விதக் கூலியையும் தான் எதிர்பார்க்கவில்லை என்றும், அதற்கான கூலியை அல்லாஹ்விடமே எதிர்பார்ப்பதாகவும் அவர் அவர்களிடம் கூறினார்கள். பின்னர் அவர்களுக்கு அல்லாஹ்வின் அருட்கொடைகளைப் பற்றி அவர் நினைவூட்டினார்கள்.<br />\r\n<br />","text":"ஸாலிஹ் (அலை) மற்றும் தமூத் சமூகத்தினர்\n\r\n\n\r\nஅல்லாஹ் தனது அடியாரும் தூதருமான ஸாலிஹ் (அலை) அவர்களைப் பற்றி இங்கு கூறுகிறான். அவர்களை அவன் தமூத் சமூகத்தினரிடம் அனுப்பினான். அவர்கள் 'அல்-ஹிஜ்ர்' எனும் நகரத்தில் வாழ்ந்த அரேபியர்கள் ஆவர். இது வாதி அல்-குராவுக்கும் பெரும் சிரியாவிற்கும் இடையில் அமைந்துள்ளது. அவர்கள் வாழ்ந்த இடம் நன்கு அறியப்பட்டதாகும். ஸூரா அல்-அஃராஃபின் விளக்கவுரையில், அல்லாஹ்வின் தூதர் (ஸல்) (ஸல்) அவர்கள் சிரியாவின் மீது போர் தொடுக்க விரும்பியபோது, அவர்களின் இருப்பிடங்களைக் கடந்து சென்றது குறித்த ஹதீஸ்களை நாம் குறிப்பிட்டுள்ளோம். அவர் தபூக் போருக்காகச் சென்ற போது இது நிகழ்ந்தது. தமூத் சமூகத்தினர் ஆத் சமூகத்திற்குப் பின்னரும், இப்ராஹீம் (அலை) அவர்களுக்கு முன்னரும் வாழ்ந்தனர்.\n\r\n\n\r\nஅவர்களது தூதர் ஸாலிஹ் (அலை), அல்லாஹ்வை மட்டுமே வணங்குமாறும், அவனுக்கு எதனையும் இணையாக்கக் கூடாது என்றும், தமக்கு வழங்கப்பட்டக் கட்டளைகளுக்குக் கீழ்ப்படியுமாறும் அவர்களை அழைத்தார்கள். ஆனால் அவர்களோ அவரை நிராகரித்து, அவருக்கு எதிர்ப்பைத் தெரிவித்தார்கள். தனது இந்த அழைப்புப் பணிக்காக அவர்களிடம் எவ்விதக் கூலியையும் தான் எதிர்பார்க்கவில்லை என்றும், அதற்கான கூலியை அல்லாஹ்விடமே எதிர்பார்ப்பதாகவும் அவர் அவர்களிடம் கூறினார்கள். பின்னர் அவர்களுக்கு அல்லாஹ்வின் அருட்கொடைகளைப் பற்றி அவர் நினைவூட்டினார்கள்."},"146":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=152\" class=\"link\">26:152</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:152 ஐ பார்க்கவும்"},"147":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=152\" class=\"link\">26:152</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:152 ஐ பார்க்கவும்"},"148":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=152\" class=\"link\">26:152</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:152 ஐ பார்க்கவும்"},"149":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=152\" class=\"link\">26:152</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:152 ஐ பார்க்கவும்"},"150":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=152\" class=\"link\">26:152</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:152 ஐ பார்க்கவும்"},"151":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=152\" class=\"link\">26:152</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:152 ஐ பார்க்கவும்"},"152":{"html":"<strong>அவர்களுடைய நிலைமைகள் மற்றும் அருட்கொடைகள் குறித்து அவர்களுக்கு ஒரு நினைவூட்டல்</strong><br />\r\n<br />\r\nசாலிஹ் (அலை) அவர்கள் அம்மக்களுக்கு அறிவுரை வழங்கினார்கள். அல்லாஹ்வின் வேதனை அவர்களை வந்தடையக்கூடும் என்று அவர்களை எச்சரித்தார்கள். மேலும், அல்லாஹ் அவர்களுக்கு வழங்கியிருந்த அருட்கொடைகளை அவர்களுக்கு நினைவூட்டினார்கள். அவன் அவர்களுக்குத் தாராளமான வாழ்வாதாரத்தை வழங்கி, அனைத்து வகையான ஆபத்துகளிலிருந்தும் அவர்களைப் பாதுகாத்தான்; அவர்களுக்குத் தோட்டங்களையும், ஓடும் நீரூற்றுகளையும் அளித்து, அவர்களுக்காகப் பயிர்களையும் கனிகளையும் வெளிப்படுத்தினான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَنَخْلٍ</span> <span class=\"quran-arabic-font text-success\">طَلْعُهَا</span> <span class=\"quran-arabic-font text-success\">هَضِيمٌ﴿</span><br />\r\n<br />\r\n(மேலும் மென்மையான பாளைகளைக் கொண்ட பேரீச்சை மரங்கள்.) அல்-அவ்ஃபி அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து, \"(நன்கு) பழுத்த மற்றும் செழுமையானது\" என்று அறிவித்துள்ளார்கள். அலி இப்னு அபீ தல்ஹா அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து, இதன் பொருள் \"செழிப்பாக வளர்வது\" என்று அறிவித்துள்ளார்கள். இஸ்மாயீல் இப்னு அபீ காலித் அவர்கள், ஸஹாபாக்களைச் சந்தித்த அம்ரு இப்னு அபீ அம்ரு அவர்களிடமிருந்து - அவர் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து - இதன் பொருள், \"அது பழுத்து மென்மையாகும் போது\" என்று அறிவித்துள்ளார்கள். இதை இப்னு அபீ ஹாதிம் அவர்கள் பதிவு செய்துள்ளார். மேலும் அவர், \"இதைப் போன்ற ஒரு கருத்து அபூ சாலிஹ் அவர்களிடமிருந்தும் அறிவிக்கப்பட்டுள்ளது\" என்று கூறியுள்ளார்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَتَنْحِتُونَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْجِبَالِ</span> <span class=\"quran-arabic-font text-success\">بُيُوتاً</span> <span class=\"quran-arabic-font text-success\">فَارِهِينَ﴿</span><br />\r\n<br />\r\n(மேலும் நீங்கள் மலைகளைக் குடைந்து பெரும் திறமையுடன் வீடுகளை அமைக்கிறீர்கள்.) இப்னு அப்பாஸ் (ரழி) அவர்களும் மற்றவர்களும், \"பெரும் திறமையுடன்\" என்று கூறினார்கள். அவரிடமிருந்து வரும் மற்றொரு அறிவிப்பின்படி: \"அவர்கள் பேராசைக்காரர்களாகவும், வீண்விரயம் செய்பவர்களாகவும் இருந்தார்கள்.\" இது முஜாஹித் மற்றும் மற்றொரு குழுவினரின் கருத்தாகும். இந்த இரண்டு கருத்துகளுக்கும் இடையில் எந்த முரண்பாடும் இல்லை. ஏனெனில், அவர்கள் வசிப்பிடங்களாகத் தேவையில்லாத போதிலும், ஒருவித ஆடம்பரக் களியாட்டமாகவே மலைகளில் வீடுகளைக் குடைந்து கட்டினார்கள். அவர்களின் கட்டுமானங்களைப் பார்த்த எவருக்கும் நன்கு தெரிந்திருப்பதைப் போல, அவர்கள் கொத்து வேலைகளிலும் கல் செதுக்கும் கலையிலும் மிகுந்த திறமை பெற்றிருந்தனர். எனவே, சாலிஹ் (அலை) அவர்கள் அவர்களிடம் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾فَاتَّقُواْ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">وَأَطِيعُونِ﴿</span><br />\r\n<br />\r\n(எனவே, அல்லாஹ்விடம் தக்வா (பயபக்தி) கொள்ளுங்கள், மேலும் எனக்குக் கீழ்ப்படியுங்கள்.) இம்மையும் மறுமையும் உங்களுக்குப் பயனளிக்கக்கூடியவற்றில் கவனம் செலுத்துங்கள்; உங்களைப் படைத்த உங்கள் இறைவனை வணங்குங்கள். நீங்கள் அவனை மட்டுமே வணங்கவும், காலையிலும் மாலையிலும் அவனைத் துதிக்கவும் அவன் உங்களுக்கு வாழ்வாதாரங்களை வழங்கினான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلاَ</span> <span class=\"quran-arabic-font text-success\">تُطِيعُواْ</span> <span class=\"quran-arabic-font text-success\">أَمْرَ</span> <span class=\"quran-arabic-font text-success\">الْمُسْرِفِينَ</span> - <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يُفْسِدُونَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">يُصْلِحُونَ﴿</span><br />\r\n<br />\r\n(மேலும், வரம்பு மீறுபவர்களின் கட்டளைக்குக் கீழ்ப்படியாதீர்கள். அவர்கள் பூமியில் குழப்பம் விளைவிக்கிறார்கள், சீர்திருத்தம் செய்வதில்லை.) அதாவது, அம்மக்களை ஷிர்க் (இணைவைப்பு), குஃப்ர் (நிராகரிப்பு) மற்றும் சத்தியத்திற்கு எதிராகச் செயல்படத் தூண்டிய அவர்களுடைய தலைவர்களையும் வழிகாட்டிகளையும் இது குறிக்கிறது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالُواْ</span> <span class=\"quran-arabic-font text-success\">إِنَّمَآ</span> <span class=\"quran-arabic-font text-success\">أَنتَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُسَحَّرِينَ</span> - <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَنتَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">بَشَرٌ</span> <span class=\"quran-arabic-font text-success\">مِّثْلُنَا</span> <span class=\"quran-arabic-font text-success\">فَأْتِ</span> <span class=\"quran-arabic-font text-success\">بِآيَةٍ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كُنتَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الصَّادِقِينَ</span> - <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">هَذِهِ</span> <span class=\"quran-arabic-font text-success\">نَاقَةٌ</span> <span class=\"quran-arabic-font text-success\">لَّهَا</span> <span class=\"quran-arabic-font text-success\">شِرْبٌ</span> <span class=\"quran-arabic-font text-success\">وَلَكُمْ</span> <span class=\"quran-arabic-font text-success\">شِرْبُ</span> <span class=\"quran-arabic-font text-success\">يَوْمٍ</span> <span class=\"quran-arabic-font text-success\">مَّعْلُومٍ</span> - <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَمَسُّوهَا</span> <span class=\"quran-arabic-font text-success\">بِسُوءٍ</span> <span class=\"quran-arabic-font text-success\">فَيَأْخُذَكُمْ</span> <span class=\"quran-arabic-font text-success\">عَذَابُ</span> <span class=\"quran-arabic-font text-success\">يَوْمٍ</span> <span class=\"quran-arabic-font text-success\">عَظِيمٍ</span> - <span class=\"quran-arabic-font text-success\">فَعَقَرُوهَا</span> <span class=\"quran-arabic-font text-success\">فَأَصْبَحُواْ</span> <span class=\"quran-arabic-font text-success\">نَادِمِينَ</span> - <span class=\"quran-arabic-font text-success\">فَأَخَذَهُمُ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابُ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">لَآيَةً</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">أَكْثَرُهُم</span> <span class=\"quran-arabic-font text-success\">مُّؤْمِنِينَ</span> - <span class=\"quran-arabic-font text-success\">وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">رَبَّكَ</span> <span class=\"quran-arabic-font text-success\">لَهُوَ</span> <span class=\"quran-arabic-font text-success\">الْعَزِيزُ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمُ﴿</span><br />\r\n<br />\r\n(153) \"நீர் சூனியம் செய்யப்பட்டவர்களில் ஒருவர் என்று அவர்கள் கூறினார்கள்.\" (154) \"நீரும் எங்களைப் போன்ற ஒரு மனிதரே; நீர் உண்மையாளராக இருந்தால் ஓர் அத்தாட்சியைக் கொண்டு வாரும் (என்றும் கூறினார்கள்).\" (155) அதற்கு அவர், \"இதோ! இது (அல்லாஹ்வின்) ஒட்டகம்; இது நீர் அருந்த ஒரு முறை (ஒரு நாள்) உண்டு; நீங்கள் நீர் அருந்தக் குறிப்பிட்ட ஒரு நாள் உண்டு\" என்று கூறினார். (156) \"மேலும், இதற்கு நீங்கள் யாதொரு தீங்கும் செய்யாதீர்கள்; (அப்படிச் செய்தால்) மகத்தான நாளின் வேதனை உங்களைப் பிடித்துக் கொள்ளும்\" (என்றும் எச்சரித்தார்). (157) ஆனால், அவர்கள் (அந்த ஒட்டகத்தின் கால் நரம்பைத் தறித்து) அதனை அறுத்துவிட்டார்கள்; பின்னர் (தம் செயலுக்காகக்) கவலைப்படுபவர்களாகி விட்டார்கள். (158) ஆகவே, வேதனை அவர்களைப் பிடித்துக் கொண்டது; நிச்சயமாக இதில் ஓர் அத்தாட்சி இருக்கிறது; எனினும் அவர்களில் பெரும்பாலோர் நம்பிக்கை கொள்பவர்களாக இல்லை. (159) மேலும், நிச்சயமாக உமது இறைவன் - அவன்தான் யாவற்றையும் மிகைத்தவன்; மிக்க கருணையுடையவன்.<br />\r\n<br />","text":"அவர்களுடைய நிலைமைகள் மற்றும் அருட்கொடைகள் குறித்து அவர்களுக்கு ஒரு நினைவூட்டல்\n\r\n\n\r\nசாலிஹ் (அலை) அவர்கள் அம்மக்களுக்கு அறிவுரை வழங்கினார்கள். அல்லாஹ்வின் வேதனை அவர்களை வந்தடையக்கூடும் என்று அவர்களை எச்சரித்தார்கள். மேலும், அல்லாஹ் அவர்களுக்கு வழங்கியிருந்த அருட்கொடைகளை அவர்களுக்கு நினைவூட்டினார்கள். அவன் அவர்களுக்குத் தாராளமான வாழ்வாதாரத்தை வழங்கி, அனைத்து வகையான ஆபத்துகளிலிருந்தும் அவர்களைப் பாதுகாத்தான்; அவர்களுக்குத் தோட்டங்களையும், ஓடும் நீரூற்றுகளையும் அளித்து, அவர்களுக்காகப் பயிர்களையும் கனிகளையும் வெளிப்படுத்தினான்.\n\r\n\n\r\n﴾وَنَخْلٍ طَلْعُهَا هَضِيمٌ﴿\n\r\n\n\r\n(மேலும் மென்மையான பாளைகளைக் கொண்ட பேரீச்சை மரங்கள்.) அல்-அவ்ஃபி அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து, \"(நன்கு) பழுத்த மற்றும் செழுமையானது\" என்று அறிவித்துள்ளார்கள். அலி இப்னு அபீ தல்ஹா அவர்கள் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து, இதன் பொருள் \"செழிப்பாக வளர்வது\" என்று அறிவித்துள்ளார்கள். இஸ்மாயீல் இப்னு அபீ காலித் அவர்கள், ஸஹாபாக்களைச் சந்தித்த அம்ரு இப்னு அபீ அம்ரு அவர்களிடமிருந்து - அவர் இப்னு அப்பாஸ் (ரழி) அவர்களிடமிருந்து - இதன் பொருள், \"அது பழுத்து மென்மையாகும் போது\" என்று அறிவித்துள்ளார்கள். இதை இப்னு அபீ ஹாதிம் அவர்கள் பதிவு செய்துள்ளார். மேலும் அவர், \"இதைப் போன்ற ஒரு கருத்து அபூ சாலிஹ் அவர்களிடமிருந்தும் அறிவிக்கப்பட்டுள்ளது\" என்று கூறியுள்ளார்.\n\r\n\n\r\n﴾وَتَنْحِتُونَ مِنَ الْجِبَالِ بُيُوتاً فَارِهِينَ﴿\n\r\n\n\r\n(மேலும் நீங்கள் மலைகளைக் குடைந்து பெரும் திறமையுடன் வீடுகளை அமைக்கிறீர்கள்.) இப்னு அப்பாஸ் (ரழி) அவர்களும் மற்றவர்களும், \"பெரும் திறமையுடன்\" என்று கூறினார்கள். அவரிடமிருந்து வரும் மற்றொரு அறிவிப்பின்படி: \"அவர்கள் பேராசைக்காரர்களாகவும், வீண்விரயம் செய்பவர்களாகவும் இருந்தார்கள்.\" இது முஜாஹித் மற்றும் மற்றொரு குழுவினரின் கருத்தாகும். இந்த இரண்டு கருத்துகளுக்கும் இடையில் எந்த முரண்பாடும் இல்லை. ஏனெனில், அவர்கள் வசிப்பிடங்களாகத் தேவையில்லாத போதிலும், ஒருவித ஆடம்பரக் களியாட்டமாகவே மலைகளில் வீடுகளைக் குடைந்து கட்டினார்கள். அவர்களின் கட்டுமானங்களைப் பார்த்த எவருக்கும் நன்கு தெரிந்திருப்பதைப் போல, அவர்கள் கொத்து வேலைகளிலும் கல் செதுக்கும் கலையிலும் மிகுந்த திறமை பெற்றிருந்தனர். எனவே, சாலிஹ் (அலை) அவர்கள் அவர்களிடம் கூறினார்கள்:\n\r\n\n\r\n﴾فَاتَّقُواْ اللَّهَ وَأَطِيعُونِ﴿\n\r\n\n\r\n(எனவே, அல்லாஹ்விடம் தக்வா (பயபக்தி) கொள்ளுங்கள், மேலும் எனக்குக் கீழ்ப்படியுங்கள்.) இம்மையும் மறுமையும் உங்களுக்குப் பயனளிக்கக்கூடியவற்றில் கவனம் செலுத்துங்கள்; உங்களைப் படைத்த உங்கள் இறைவனை வணங்குங்கள். நீங்கள் அவனை மட்டுமே வணங்கவும், காலையிலும் மாலையிலும் அவனைத் துதிக்கவும் அவன் உங்களுக்கு வாழ்வாதாரங்களை வழங்கினான்.\n\r\n\n\r\n﴾وَلاَ تُطِيعُواْ أَمْرَ الْمُسْرِفِينَ - الَّذِينَ يُفْسِدُونَ فِى الْأَرْضِ وَلاَ يُصْلِحُونَ﴿\n\r\n\n\r\n(மேலும், வரம்பு மீறுபவர்களின் கட்டளைக்குக் கீழ்ப்படியாதீர்கள். அவர்கள் பூமியில் குழப்பம் விளைவிக்கிறார்கள், சீர்திருத்தம் செய்வதில்லை.) அதாவது, அம்மக்களை ஷிர்க் (இணைவைப்பு), குஃப்ர் (நிராகரிப்பு) மற்றும் சத்தியத்திற்கு எதிராகச் செயல்படத் தூண்டிய அவர்களுடைய தலைவர்களையும் வழிகாட்டிகளையும் இது குறிக்கிறது.\n\r\n\n\r\n﴾قَالُواْ إِنَّمَآ أَنتَ مِنَ الْمُسَحَّرِينَ - مَآ أَنتَ إِلاَّ بَشَرٌ مِّثْلُنَا فَأْتِ بِآيَةٍ إِن كُنتَ مِنَ الصَّادِقِينَ - قَالَ هَذِهِ نَاقَةٌ لَّهَا شِرْبٌ وَلَكُمْ شِرْبُ يَوْمٍ مَّعْلُومٍ - وَلاَ تَمَسُّوهَا بِسُوءٍ فَيَأْخُذَكُمْ عَذَابُ يَوْمٍ عَظِيمٍ - فَعَقَرُوهَا فَأَصْبَحُواْ نَادِمِينَ - فَأَخَذَهُمُ الْعَذَابُ إِنَّ فِى ذَلِكَ لَآيَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ - وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ﴿\n\r\n\n\r\n(153) \"நீர் சூனியம் செய்யப்பட்டவர்களில் ஒருவர் என்று அவர்கள் கூறினார்கள்.\" (154) \"நீரும் எங்களைப் போன்ற ஒரு மனிதரே; நீர் உண்மையாளராக இருந்தால் ஓர் அத்தாட்சியைக் கொண்டு வாரும் (என்றும் கூறினார்கள்).\" (155) அதற்கு அவர், \"இதோ! இது (அல்லாஹ்வின்) ஒட்டகம்; இது நீர் அருந்த ஒரு முறை (ஒரு நாள்) உண்டு; நீங்கள் நீர் அருந்தக் குறிப்பிட்ட ஒரு நாள் உண்டு\" என்று கூறினார். (156) \"மேலும், இதற்கு நீங்கள் யாதொரு தீங்கும் செய்யாதீர்கள்; (அப்படிச் செய்தால்) மகத்தான நாளின் வேதனை உங்களைப் பிடித்துக் கொள்ளும்\" (என்றும் எச்சரித்தார்). (157) ஆனால், அவர்கள் (அந்த ஒட்டகத்தின் கால் நரம்பைத் தறித்து) அதனை அறுத்துவிட்டார்கள்; பின்னர் (தம் செயலுக்காகக்) கவலைப்படுபவர்களாகி விட்டார்கள். (158) ஆகவே, வேதனை அவர்களைப் பிடித்துக் கொண்டது; நிச்சயமாக இதில் ஓர் அத்தாட்சி இருக்கிறது; எனினும் அவர்களில் பெரும்பாலோர் நம்பிக்கை கொள்பவர்களாக இல்லை. (159) மேலும், நிச்சயமாக உமது இறைவன் - அவன்தான் யாவற்றையும் மிகைத்தவன்; மிக்க கருணையுடையவன்."},"153":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=159\" class=\"link\">26:159</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:159 ஐ பார்க்கவும்"},"154":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=159\" class=\"link\">26:159</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:159 ஐ பார்க்கவும்"},"155":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=159\" class=\"link\">26:159</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:159 ஐ பார்க்கவும்"},"156":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=159\" class=\"link\">26:159</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:159 ஐ பார்க்கவும்"},"157":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=159\" class=\"link\">26:159</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:159 ஐ பார்க்கவும்"},"158":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=159\" class=\"link\">26:159</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:159 ஐ பார்க்கவும்"},"159":{"html":"<strong>ஸமூது கூட்டத்தினரின் பதில், அவர்கள் ஓர் அத்தாட்சியைக் கோரியது மற்றும் அவர்களின் தண்டனை</strong><br />\r\n<br />\r\nதன் இறைவனை வணங்குமாறு ஸாலிஹ் (அலை) அவர்கள் ஸமூது கூட்டத்தினரை அழைத்தபோது, அவர்கள் அவருக்கு அளித்த பதிலை அல்லாஹ் நமக்குக் கூறுகிறான்.<span class=\"quran-arabic-font text-success\">﴾قَالُواْ</span> <span class=\"quran-arabic-font text-success\">إِنَّمَآ</span> <span class=\"quran-arabic-font text-success\">أَنتَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُسَحَّرِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அவர்கள் கூறினார்கள்: \"நிச்சயமாக நீர் சூனியம் செய்யப்பட்டவர்களில் ஒருவரே!\") முஜாஹித் அவர்கள் கூறினார்கள், \"அவர் சூனியத்தால் பாதிக்கப்பட்டவர் என்று அவர்கள் கருதினார்கள்.\" பின்னர் அவர்கள் கூறினார்கள்:<span class=\"quran-arabic-font text-success\">﴾مَآ</span> <span class=\"quran-arabic-font text-success\">أَنتَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">بَشَرٌ</span> <span class=\"quran-arabic-font text-success\">مِّثْلُنَا</span> <span class=\"quran-arabic-font text-success\">فَأْتِ</span> <span class=\"quran-arabic-font text-success\">بِآيَةٍ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كُنتَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الصَّادِقِينَ﴿</span><br />\r\n<br />\r\n(\"நீர் எங்களைப் போன்ற ஒரு மனிதரே அன்றி வேறில்லை; நீர் உண்மையாளராக இருந்தால் ஓர் அத்தாட்சியைக் கொண்டு வாரும்!\") அதாவது, 'நாங்கள் வஹீ (இறைச்செய்தி)யைப் பெறாதபோது, நீர் மட்டும் அதை எவ்வாறு பெற முடியும்?' இது அவர்கள் கூறுவதாக விவரிக்கப்பட்டுள்ள பின்வரும் வசனத்தைப் போன்றது:<span class=\"quran-arabic-font text-success\">﴾أَءُلْقِىَ</span> <span class=\"quran-arabic-font text-success\">الذِّكْرُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَيْنِنَا</span> <span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">كَذَّابٌ</span> <span class=\"quran-arabic-font text-success\">أَشِرٌ</span> - <span class=\"quran-arabic-font text-success\">سَيَعْلَمُونَ</span> <span class=\"quran-arabic-font text-success\">غَداً</span> <span class=\"quran-arabic-font text-success\">مَّنِ</span> <span class=\"quran-arabic-font text-success\">الْكَذَّابُ</span> <span class=\"quran-arabic-font text-success\">الْأَشِرُ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(\"எங்களுக்கு மத்தியில் இவருக்கு மட்டும் அறிவுரை (வஹீ) வழங்கப்பட்டதா? இல்லை, அவர் கர்வமிக்க பொய்யர்!\" நாளை அவர்கள் யார் பொய்யன், கர்வமிக்கவன் என்பதை அறிந்து கொள்வார்கள்!) (<a href=\"qurandisp.php?sura=54&ayah=25\" class=\"link\">54:25</a>-26)<br />\r\n<br />\r\nபின்னர், அவர் தம் இறைவனிடமிருந்து கொண்டு வந்த தூது உண்மையானது என்பதை நிரூபிக்க, அவரிடம் ஓர் அத்தாட்சியைக் கோரினார்கள். அவர்களில் ஒரு பெரும் கூட்டத்தினர் ஒன்று கூடி, தங்களுக்கு மத்தியில் இருந்த ஒரு குறிப்பிட்ட பாறையைச் சுட்டிக்காட்டி, அதிலிருந்து உடனடியாகப் பத்து மாத கர்ப்பிணியான ஒரு பெண் ஒட்டகத்தை வெளிப்படுத்துமாறு வேண்டினர். அவர்களின் கோரிக்கைக்குப் பதிலளித்தால், அவர்கள் தன்னை நம்பிப் பின்பற்றுவதாக வாக்குறுதி அளித்தால் மட்டுமே அதைச் செய்வதாக அல்லாஹ்வின் நபி ஸாலிஹ் (அலை) அவர்கள் கூறினார்கள். அவர்களும் அதற்குச் சம்மதித்தனர். அல்லாஹ்வின் நபி ஸாலிஹ் (அலை) அவர்கள் எழுந்து நின்று தொழுதார்கள்; பின்னர் அவர்களின் கோரிக்கையை நிறைவேற்றுமாறு அல்லாஹ்விடம் பிரார்த்தித்தார்கள். அவர்கள் சுட்டிக்காட்டிய பாறை பிளந்து, அவர்கள் கேட்டபடியே சரியாகப் பத்து மாத கர்ப்பிணியான ஒரு பெண் ஒட்டகம் வெளிப்பட்டது. இதைக் கண்டதும் அவர்களில் சிலர் நம்பிக்கை கொண்டார்கள், ஆனால் அவர்களில் பெரும்பாலோர் நிராகரித்தனர்.<span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">هَـذِهِ</span> <span class=\"quran-arabic-font text-success\">نَاقَةٌ</span> <span class=\"quran-arabic-font text-success\">لَّهَا</span> <span class=\"quran-arabic-font text-success\">شِرْبٌ</span> <span class=\"quran-arabic-font text-success\">وَلَكُمْ</span> <span class=\"quran-arabic-font text-success\">شِرْبُ</span> <span class=\"quran-arabic-font text-success\">يَوْمٍ</span> <span class=\"quran-arabic-font text-success\">مَّعْلُومٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அவர் கூறினார்கள்: \"இதோ ஒரு பெண் ஒட்டகம்: இதற்கும் (தண்ணீர்) குடிக்கும் உரிமை உண்டு; உங்களுக்கும் ஒரு குறிப்பிட்ட நாளில் (தண்ணீர்) குடிக்கும் உரிமை உண்டு.\") அதாவது, 'ஒரு நாள் அந்த ஒட்டகம் உங்கள் தண்ணீரைக் குடிக்கும், மறுநாள் நீங்கள் அதிலிருந்து குடிப்பீர்கள்'.<span class=\"quran-arabic-font text-success\">﴾وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَمَسُّوهَا</span> <span class=\"quran-arabic-font text-success\">بِسُوءٍ</span> <span class=\"quran-arabic-font text-success\">فَيَأْخُذَكُمْ</span> <span class=\"quran-arabic-font text-success\">عَذَابُ</span> <span class=\"quran-arabic-font text-success\">يَوْمٍ</span> <span class=\"quran-arabic-font text-success\">عَظِيمٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(\"மேலும் அதற்கு எந்தத் தீங்கும் இழைக்காதீர்கள்; அவ்வாறு செய்தால் ஒரு மகத்தான நாளின் வேதனை உங்களைப் பிடித்துக்கொள்ளும்\".) அந்த ஒட்டகத்திற்கு ஏதேனும் தீங்கு விளைவித்தால் அல்லாஹ்வின் தண்டனை ஏற்படும் என்று அவர் அவர்களை எச்சரித்தார்கள்.<br />\r\n<br />\r\nஅந்தப் பெண் ஒட்டகம் சில காலம் அவர்களுக்கு மத்தியில் தங்கியிருந்தது. அது தண்ணீரைக் குடித்து, இலைகளைத் தின்று, மேய்ந்து வந்தது. அதன் பாலிலிருந்து அவர்கள் பயனடைந்தார்கள்; அனைவரும் வயிறு நிறையக் குடிக்கும் அளவுக்குப் போதுமான பாலை அவர்கள் அதிலிருந்து கறந்து கொண்டனர். இவ்வாறு நீண்ட காலம் சென்ற பிறகு, அவர்களின் அழிவுக்கான நேரம் நெருங்கியபோது, அவர்கள் அந்த ஒட்டகத்தைக் கொல்லச் சதி செய்தார்கள்:<span class=\"quran-arabic-font text-success\">﴾فَعَقَرُوهَا</span> <span class=\"quran-arabic-font text-success\">فَأَصْبَحُواْ</span> <span class=\"quran-arabic-font text-success\">نَـدِمِينَ</span> <span class=\"quran-arabic-font text-success\">فَأَخَذَهُمُ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابُ﴿</span><br />\r\n<br />\r\n(ஆனால் அவர்கள் அதைக் கொன்றார்கள்; பின்னர் (தண்டனையைக் கண்டு) அவர்கள் வருந்தினார்கள். எனவே, வேதனை அவர்களைப் பிடித்துக்கொண்டது.) அவர்களின் தேசத்தில் ஒரு பலமான நிலநடுக்கம் ஏற்பட்டது. மேலும் ஒரு பெரும் பேரொலி (ஸய்ஹா) ஏற்பட்டு, அவர்களின் இதயங்களைத் துடிக்கச் செய்தது. அவர்கள் எதிர்பாராத வகையில் அழிவு ஏற்பட்டு, அவர்கள் தங்கள் வீடுகளிலேயே குப்புற வீழ்ந்து கிடந்தார்கள்.<span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">لأَيَةً</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">أَكْثَرُهُم</span> <span class=\"quran-arabic-font text-success\">مُّؤْمِنِينَ</span> <span class=\"quran-arabic-font text-success\">﴿﴾وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">رَبَّكَ</span> <span class=\"quran-arabic-font text-success\">لَهُوَ</span> <span class=\"quran-arabic-font text-success\">الْعَزِيزُ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمُ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிச்சயமாக இதில் ஓர் அத்தாட்சி இருக்கிறது; ஆனால் அவர்களில் பெரும்பாலோர் நம்பிக்கை கொண்டவர்களாக இருக்கவில்லை. நிச்சயமாக உமது இறைவன், அவன் தான் யாவற்றையும் மிகைத்தவன், மகா கருணையாளன்.)<br />\r\n<br />\r\n<br />\r\n<br />","text":"ஸமூது கூட்டத்தினரின் பதில், அவர்கள் ஓர் அத்தாட்சியைக் கோரியது மற்றும் அவர்களின் தண்டனை\n\r\n\n\r\nதன் இறைவனை வணங்குமாறு ஸாலிஹ் (அலை) அவர்கள் ஸமூது கூட்டத்தினரை அழைத்தபோது, அவர்கள் அவருக்கு அளித்த பதிலை அல்லாஹ் நமக்குக் கூறுகிறான்.﴾قَالُواْ إِنَّمَآ أَنتَ مِنَ الْمُسَحَّرِينَ ﴿\n\r\n\n\r\n(அவர்கள் கூறினார்கள்: \"நிச்சயமாக நீர் சூனியம் செய்யப்பட்டவர்களில் ஒருவரே!\") முஜாஹித் அவர்கள் கூறினார்கள், \"அவர் சூனியத்தால் பாதிக்கப்பட்டவர் என்று அவர்கள் கருதினார்கள்.\" பின்னர் அவர்கள் கூறினார்கள்:﴾مَآ أَنتَ إِلاَّ بَشَرٌ مِّثْلُنَا فَأْتِ بِآيَةٍ إِن كُنتَ مِنَ الصَّادِقِينَ﴿\n\r\n\n\r\n(\"நீர் எங்களைப் போன்ற ஒரு மனிதரே அன்றி வேறில்லை; நீர் உண்மையாளராக இருந்தால் ஓர் அத்தாட்சியைக் கொண்டு வாரும்!\") அதாவது, 'நாங்கள் வஹீ (இறைச்செய்தி)யைப் பெறாதபோது, நீர் மட்டும் அதை எவ்வாறு பெற முடியும்?' இது அவர்கள் கூறுவதாக விவரிக்கப்பட்டுள்ள பின்வரும் வசனத்தைப் போன்றது:﴾أَءُلْقِىَ الذِّكْرُ عَلَيْهِ مِن بَيْنِنَا بَلْ هُوَ كَذَّابٌ أَشِرٌ - سَيَعْلَمُونَ غَداً مَّنِ الْكَذَّابُ الْأَشِرُ ﴿\n\r\n\n\r\n(\"எங்களுக்கு மத்தியில் இவருக்கு மட்டும் அறிவுரை (வஹீ) வழங்கப்பட்டதா? இல்லை, அவர் கர்வமிக்க பொய்யர்!\" நாளை அவர்கள் யார் பொய்யன், கர்வமிக்கவன் என்பதை அறிந்து கொள்வார்கள்!) (54:25-26)\n\r\n\n\r\nபின்னர், அவர் தம் இறைவனிடமிருந்து கொண்டு வந்த தூது உண்மையானது என்பதை நிரூபிக்க, அவரிடம் ஓர் அத்தாட்சியைக் கோரினார்கள். அவர்களில் ஒரு பெரும் கூட்டத்தினர் ஒன்று கூடி, தங்களுக்கு மத்தியில் இருந்த ஒரு குறிப்பிட்ட பாறையைச் சுட்டிக்காட்டி, அதிலிருந்து உடனடியாகப் பத்து மாத கர்ப்பிணியான ஒரு பெண் ஒட்டகத்தை வெளிப்படுத்துமாறு வேண்டினர். அவர்களின் கோரிக்கைக்குப் பதிலளித்தால், அவர்கள் தன்னை நம்பிப் பின்பற்றுவதாக வாக்குறுதி அளித்தால் மட்டுமே அதைச் செய்வதாக அல்லாஹ்வின் நபி ஸாலிஹ் (அலை) அவர்கள் கூறினார்கள். அவர்களும் அதற்குச் சம்மதித்தனர். அல்லாஹ்வின் நபி ஸாலிஹ் (அலை) அவர்கள் எழுந்து நின்று தொழுதார்கள்; பின்னர் அவர்களின் கோரிக்கையை நிறைவேற்றுமாறு அல்லாஹ்விடம் பிரார்த்தித்தார்கள். அவர்கள் சுட்டிக்காட்டிய பாறை பிளந்து, அவர்கள் கேட்டபடியே சரியாகப் பத்து மாத கர்ப்பிணியான ஒரு பெண் ஒட்டகம் வெளிப்பட்டது. இதைக் கண்டதும் அவர்களில் சிலர் நம்பிக்கை கொண்டார்கள், ஆனால் அவர்களில் பெரும்பாலோர் நிராகரித்தனர்.﴾قَالَ هَـذِهِ نَاقَةٌ لَّهَا شِرْبٌ وَلَكُمْ شِرْبُ يَوْمٍ مَّعْلُومٍ ﴿\n\r\n\n\r\n(அவர் கூறினார்கள்: \"இதோ ஒரு பெண் ஒட்டகம்: இதற்கும் (தண்ணீர்) குடிக்கும் உரிமை உண்டு; உங்களுக்கும் ஒரு குறிப்பிட்ட நாளில் (தண்ணீர்) குடிக்கும் உரிமை உண்டு.\") அதாவது, 'ஒரு நாள் அந்த ஒட்டகம் உங்கள் தண்ணீரைக் குடிக்கும், மறுநாள் நீங்கள் அதிலிருந்து குடிப்பீர்கள்'.﴾وَلاَ تَمَسُّوهَا بِسُوءٍ فَيَأْخُذَكُمْ عَذَابُ يَوْمٍ عَظِيمٍ ﴿\n\r\n\n\r\n(\"மேலும் அதற்கு எந்தத் தீங்கும் இழைக்காதீர்கள்; அவ்வாறு செய்தால் ஒரு மகத்தான நாளின் வேதனை உங்களைப் பிடித்துக்கொள்ளும்\".) அந்த ஒட்டகத்திற்கு ஏதேனும் தீங்கு விளைவித்தால் அல்லாஹ்வின் தண்டனை ஏற்படும் என்று அவர் அவர்களை எச்சரித்தார்கள்.\n\r\n\n\r\nஅந்தப் பெண் ஒட்டகம் சில காலம் அவர்களுக்கு மத்தியில் தங்கியிருந்தது. அது தண்ணீரைக் குடித்து, இலைகளைத் தின்று, மேய்ந்து வந்தது. அதன் பாலிலிருந்து அவர்கள் பயனடைந்தார்கள்; அனைவரும் வயிறு நிறையக் குடிக்கும் அளவுக்குப் போதுமான பாலை அவர்கள் அதிலிருந்து கறந்து கொண்டனர். இவ்வாறு நீண்ட காலம் சென்ற பிறகு, அவர்களின் அழிவுக்கான நேரம் நெருங்கியபோது, அவர்கள் அந்த ஒட்டகத்தைக் கொல்லச் சதி செய்தார்கள்:﴾فَعَقَرُوهَا فَأَصْبَحُواْ نَـدِمِينَ فَأَخَذَهُمُ الْعَذَابُ﴿\n\r\n\n\r\n(ஆனால் அவர்கள் அதைக் கொன்றார்கள்; பின்னர் (தண்டனையைக் கண்டு) அவர்கள் வருந்தினார்கள். எனவே, வேதனை அவர்களைப் பிடித்துக்கொண்டது.) அவர்களின் தேசத்தில் ஒரு பலமான நிலநடுக்கம் ஏற்பட்டது. மேலும் ஒரு பெரும் பேரொலி (ஸய்ஹா) ஏற்பட்டு, அவர்களின் இதயங்களைத் துடிக்கச் செய்தது. அவர்கள் எதிர்பாராத வகையில் அழிவு ஏற்பட்டு, அவர்கள் தங்கள் வீடுகளிலேயே குப்புற வீழ்ந்து கிடந்தார்கள்.﴾إِنَّ فِى ذَلِكَ لأَيَةً وَمَا كَانَ أَكْثَرُهُم مُّؤْمِنِينَ ﴿﴾وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ ﴿\n\r\n\n\r\n(நிச்சயமாக இதில் ஓர் அத்தாட்சி இருக்கிறது; ஆனால் அவர்களில் பெரும்பாலோர் நம்பிக்கை கொண்டவர்களாக இருக்கவில்லை. நிச்சயமாக உமது இறைவன், அவன் தான் யாவற்றையும் மிகைத்தவன், மகா கருணையாளன்.)"},"160":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=164\" class=\"link\">26:164</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:164 ஐ பார்க்கவும்"},"161":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=164\" class=\"link\">26:164</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:164 ஐ பார்க்கவும்"},"162":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=164\" class=\"link\">26:164</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:164 ஐ பார்க்கவும்"},"163":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=164\" class=\"link\">26:164</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:164 ஐ பார்க்கவும்"},"164":{"html":"<strong>லூத் (அலை) அவர்களும் அவர்களின் அழைப்பும்</strong><br />\r\n<br />\r\nஇங்கே அல்லாஹ் தன் அடியாரும் தூதருமான லூத் (அலை) அவர்களைப் பற்றி கூறுகிறான். அவர் இப்ராஹீம் கலீலுல்லாஹ் (அலை) அவர்களின் சகோதரர் மகனான லூத் பின் ஹாரான் பின் ஆஸார் ஆவார். இப்ராஹீம் (அலை) அவர்களின் வாழ்நாளிலேயே, அல்லாஹ் அவரை ஒரு வலிமைமிக்க சமூகத்தாரிடம் அனுப்பினான். அவர்கள் சதூம் (Sodom) மற்றும் அதன் சுற்றுவட்டாரப் பகுதிகளில் வாழ்ந்து வந்தார்கள். அல்லாஹ் அவர்களை அழித்து, அப்பகுதியை துர்நாற்றம் வீசும் ஓர் அழுகிய ஏரியாக மாற்றினான். இது ஜோர்டான் பள்ளத்தாக்கிலுள்ள அல்-கவ்ர் (Al-Ghawr) பகுதியில், பைத்துல் முகத்தஸ் மலைகளின் எல்லையில், மலைகளுக்கும் அல்-கரக் மற்றும் அஷ்-ஷவ்பக் நிலப்பகுதிகளுக்கும் இடையில் அமைந்துள்ள ஒரு புகழ்பெற்ற இடமாகும்.<br />\r\n<br />\r\nஅவர் அவர்களை அல்லாஹ்வின் பக்கம் அழைத்தார்கள். அவனுக்கு எவ்வித இணையுமின்றி அவனை மட்டுமே வணங்கும்படியும், அல்லாஹ் அவர்களுக்காக அனுப்பிய தூதருக்குக் கீழ்ப்படியும்படியும் கூறினார்கள். அல்லாஹ்வுக்கு மாறு செய்வதிலிருந்தும், அவர்கள் புதிதாக உருவாக்கிய பாவத்தைச் செய்வதிலிருந்தும் அவர்களை அவர் தடுத்தார்கள். அவர்களுக்கு முன் உலகில் எவரும் இத்தகைய பாவத்தைச் செய்ததில்லை; அதாவது, பெண்களை விட்டுவிட்டு ஆண்களுடன் தாம்பத்திய உறவு கொள்வதாகும்.<br />\r\n<br />\r\nஅல்லாஹ் கூறினான்:<span class=\"quran-arabic-font text-success\">﴾أَتَأْتُونَ</span> <span class=\"quran-arabic-font text-success\">الذُّكْرَانَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْعَالَمِينَ</span> - <span class=\"quran-arabic-font text-success\">وَتَذَرُونَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">خَلَقَ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">رَبُّكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">أَزْوَاجِكُمْ</span> <span class=\"quran-arabic-font text-success\">بَلْ</span> <span class=\"quran-arabic-font text-success\">أَنتُمْ</span> <span class=\"quran-arabic-font text-success\">قَوْمٌ</span> <span class=\"quran-arabic-font text-success\">عَادُونَ</span> - <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">لَئِن</span> <span class=\"quran-arabic-font text-success\">لَّمْ</span> <span class=\"quran-arabic-font text-success\">تَنتَهِ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">لُوطُ</span> <span class=\"quran-arabic-font text-success\">لَتَكُونَنَّ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُخْرَجِينَ</span> - <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">إِنِّى</span> <span class=\"quran-arabic-font text-success\">لِعَمَلِكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْقَالِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n<br />\r\n<br />","text":"லூத் (அலை) அவர்களும் அவர்களின் அழைப்பும்\n\r\n\n\r\nஇங்கே அல்லாஹ் தன் அடியாரும் தூதருமான லூத் (அலை) அவர்களைப் பற்றி கூறுகிறான். அவர் இப்ராஹீம் கலீலுல்லாஹ் (அலை) அவர்களின் சகோதரர் மகனான லூத் பின் ஹாரான் பின் ஆஸார் ஆவார். இப்ராஹீம் (அலை) அவர்களின் வாழ்நாளிலேயே, அல்லாஹ் அவரை ஒரு வலிமைமிக்க சமூகத்தாரிடம் அனுப்பினான். அவர்கள் சதூம் (Sodom) மற்றும் அதன் சுற்றுவட்டாரப் பகுதிகளில் வாழ்ந்து வந்தார்கள். அல்லாஹ் அவர்களை அழித்து, அப்பகுதியை துர்நாற்றம் வீசும் ஓர் அழுகிய ஏரியாக மாற்றினான். இது ஜோர்டான் பள்ளத்தாக்கிலுள்ள அல்-கவ்ர் (Al-Ghawr) பகுதியில், பைத்துல் முகத்தஸ் மலைகளின் எல்லையில், மலைகளுக்கும் அல்-கரக் மற்றும் அஷ்-ஷவ்பக் நிலப்பகுதிகளுக்கும் இடையில் அமைந்துள்ள ஒரு புகழ்பெற்ற இடமாகும்.\n\r\n\n\r\nஅவர் அவர்களை அல்லாஹ்வின் பக்கம் அழைத்தார்கள். அவனுக்கு எவ்வித இணையுமின்றி அவனை மட்டுமே வணங்கும்படியும், அல்லாஹ் அவர்களுக்காக அனுப்பிய தூதருக்குக் கீழ்ப்படியும்படியும் கூறினார்கள். அல்லாஹ்வுக்கு மாறு செய்வதிலிருந்தும், அவர்கள் புதிதாக உருவாக்கிய பாவத்தைச் செய்வதிலிருந்தும் அவர்களை அவர் தடுத்தார்கள். அவர்களுக்கு முன் உலகில் எவரும் இத்தகைய பாவத்தைச் செய்ததில்லை; அதாவது, பெண்களை விட்டுவிட்டு ஆண்களுடன் தாம்பத்திய உறவு கொள்வதாகும்.\n\r\n\n\r\nஅல்லாஹ் கூறினான்:﴾أَتَأْتُونَ الذُّكْرَانَ مِنَ الْعَالَمِينَ - وَتَذَرُونَ مَا خَلَقَ لَكُمْ رَبُّكُمْ مِّنْ أَزْوَاجِكُمْ بَلْ أَنتُمْ قَوْمٌ عَادُونَ - قَالُواْ لَئِن لَّمْ تَنتَهِ يَا لُوطُ لَتَكُونَنَّ مِنَ الْمُخْرَجِينَ - قَالَ إِنِّى لِعَمَلِكُمْ مِّنَ الْقَالِينَ ﴿"},"165":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=175\" class=\"link\">26:175</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:175 ஐ பார்க்கவும்"},"166":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=175\" class=\"link\">26:175</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:175 ஐ பார்க்கவும்"},"167":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=175\" class=\"link\">26:175</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:175 ஐ பார்க்கவும்"},"168":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=175\" class=\"link\">26:175</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:175 ஐ பார்க்கவும்"},"169":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=175\" class=\"link\">26:175</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:175 ஐ பார்க்கவும்"},"170":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=175\" class=\"link\">26:175</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:175 ஐ பார்க்கவும்"},"171":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=175\" class=\"link\">26:175</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:175 ஐ பார்க்கவும்"},"172":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=175\" class=\"link\">26:175</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:175 ஐ பார்க்கவும்"},"173":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=175\" class=\"link\">26:175</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:175 ஐ பார்க்கவும்"},"174":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=175\" class=\"link\">26:175</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:175 ஐ பார்க்கவும்"},"175":{"html":"<strong>லூத் (அலை) அவர்கள் தனது சமூகத்தாரின் செயல்களைக் கண்டித்ததும், அதற்கு அவர்கள் அளித்த பதிலும், அவர்கள் தண்டிக்கப்பட்டதும்</strong><br />\r\n<br />\r\nஅல்லாஹ்வின் தூதரான லூத் (அலை) அவர்கள், தீய செயல்கள் புரிவதிலிருந்தும், ஆண்களுடன் உடலுறவு கொள்வதிலிருந்தும் அந்த மக்களைத் தடுத்தார்கள். மேலும், அல்லாஹ் அவர்களுக்காகவே படைத்த அவர்களின் மனைவிகளுடன் தாம்பத்திய உறவு கொள்ளுமாறு அவர்களுக்கு அறிவுறுத்தினார்கள். அதற்கு அந்த மக்களின் பதில் இவ்வாறு கூறுவதாக மட்டுமே இருந்தது: <span class=\"quran-arabic-font text-success\">﴾لَئِن</span> <span class=\"quran-arabic-font text-success\">لَّمْ</span> <span class=\"quran-arabic-font text-success\">تَنتَهِ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">لُوطُ﴿</span><br />\r\n<br />\r\n(லூத்தே! நீர் நிறுத்திக்கொள்ளவில்லையானால்,) அதாவது, 'நீர் கொண்டு வந்திருக்கும் இந்தப் போதனைகளை நீர் கைவிடவில்லையானால்,' <span class=\"quran-arabic-font text-success\">﴾لَتَكُونَنَّ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُخْرَجِينَ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக நீர் வெளியேற்றப்படுபவர்களில் ஒருவராகிவிடுவீர்!) அதாவது, 'நாங்கள் உம்மை எங்கள் ஊரிலிருந்து வெளியேற்றிவிடுவோம்.' இது பின்வரும் வசனத்தைப் போன்றதாகும்: <span class=\"quran-arabic-font text-success\">﴾فَمَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">جَوَابَ</span> <span class=\"quran-arabic-font text-success\">قَوْمِهِ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">أَخْرِجُواْ</span> <span class=\"quran-arabic-font text-success\">ءَالَ</span> <span class=\"quran-arabic-font text-success\">لُوطٍ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">قَرْيَتِكُمْ</span> <span class=\"quran-arabic-font text-success\">إِنَّهمْ</span> <span class=\"quran-arabic-font text-success\">أُنَاسٌ</span> <span class=\"quran-arabic-font text-success\">يَتَطَهَّرُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(\"லூத்தின் குடும்பத்தாரை உங்கள் ஊரிலிருந்து வெளியேற்றுங்கள்; நிச்சயமாக இவர்கள் மிகவும் தூய்மையானவர்களாக இருக்க விரும்பும் மனிதர்களாவர்\" என்று அவர்கள் கூறியதைத் தவிர, அவருடைய சமூகத்தாரிடமிருந்து வேறு பதில் வரவில்லை.) (<a href=\"qurandisp.php?sura=27&ayah=56\" class=\"link\">27:56</a>). அவர்கள் தங்கள் தவறான வழிகளைக் கைவிடப்போவதில்லை என்பதையும், வழிகேட்டிலேயே பிடிவாதமாக இருப்பதையும் கண்ட லூத் (அலை) அவர்கள், அவர்களிடமிருந்து தான் விலகியிருப்பதை அறிவிக்கும் விதமாக இவ்வாறு கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾إِنِّى</span> <span class=\"quran-arabic-font text-success\">لِعَمَلِكُم</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الْقَالِينَ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக நான் உங்கள் செயலைக் கடுமையாக வெறுப்பவர்களில் ஒருவன்.) 'இதைக் கண்டு சீற்றமடைபவர்களில் நானும் ஒருவன்; எனக்கு இது பிடிக்கவில்லை, நான் இதனை ஏற்க மாட்டேன், உங்களுக்கும் எனக்கும் எந்தச் சம்பந்தமும் இல்லை' (என்பதே இதன் பொருளாகும்). பிறகு லூத் (அலை) அவர்கள் அந்த மக்களுக்கு எதிராக அல்லாஹ்விடம் இவ்வாறு பிரார்த்தனை செய்தார்கள்: <span class=\"quran-arabic-font text-success\">﴾رَبِّ</span> <span class=\"quran-arabic-font text-success\">نَّجِنِى</span> <span class=\"quran-arabic-font text-success\">وَأَهْلِى</span> <span class=\"quran-arabic-font text-success\">مِمَّا</span> <span class=\"quran-arabic-font text-success\">يَعْمَلُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(என் இறைவனே! இவர்கள் செய்து கொண்டிருக்கும் தீய செயல்களிலிருந்து என்னையும் என் குடும்பத்தாரையும் காப்பாற்றுவாயாக!)<br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾فَنَجَّيْنَاهُ</span> <span class=\"quran-arabic-font text-success\">وَأَهْلَهُ</span> <span class=\"quran-arabic-font text-success\">أَجْمَعِينَ</span> - <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">عَجُوزاً</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْغَابِرِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(எனவே, நாம் அவரையும் அவருடைய குடும்பத்தினர் அனைவரையும் காப்பாற்றினோம்; பின்தங்கியவர்களில் இருந்த ஒரு மூதாட்டியைத் தவிர.)<br />\r\n<br />\r\nஅவள் அவருடைய மனைவியாவாள்; அவள் ஒரு தீய குணமுடைய மூதாட்டி. அவள் அங்கேயே தங்கிவிட்டதால், எஞ்சியிருந்த மற்றவர்களுடன் அவளும் அழிக்கப்பட்டாள். சூரா அல்-அஃராஃப், சூரா ஹூத் மற்றும் சூரா அல்-ஹிஜ்ர் ஆகியவற்றில் இவர்களைப் பற்றி அல்லாஹ் குறிப்பிடுவதைப் போலவே இதுவும் அமைந்துள்ளது. லூத் (அலை) அவர்களின் மனைவியைத் தவிர, மற்ற குடும்ப உறுப்பினர்களை இரவோடு இரவாக அழைத்துச் செல்லுமாறும், அவர்களின் சமூகத்தாருக்குத் தண்டனையாக ஸய்ஹா (பேரொலி) இறங்கும் சப்தத்தைக் கேட்டாலும் யாரும் திரும்பிப் பார்க்க வேண்டாம் என்றும் அல்லாஹ் அவருக்குக் கட்டளையிட்டான்.<br />\r\n<br />\r\nஎனவே, அவர்கள் பொறுமையுடன் அல்லாஹ்வின் கட்டளைக்குக் கீழ்ப்படிந்து உறுதியாக இருந்தனர். அல்லாஹ் அந்த மக்கள் அனைவரையும் அழிக்கும்படியான ஒரு தண்டனையை இறக்கினான். சுடப்பட்ட களிமண்ணாலான கற்களை ஒன்றன் மேல் ஒன்றாக அவர்கள் மீது மழையாகப் பொழியச் செய்தான்.<br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾ثُمَّ</span> <span class=\"quran-arabic-font text-success\">دَمَّرْنَا</span> <span class=\"quran-arabic-font text-success\">الْآخَرِينَ</span> <span class=\"quran-arabic-font text-success\">وَأَمْطَرْنَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">مَّطَرًا</span> <span class=\"quran-arabic-font text-success\">فَسَاءَ</span> <span class=\"quran-arabic-font text-success\">مَطَرُ</span> <span class=\"quran-arabic-font text-success\">الْمُنذَرِينَ﴿</span><br />\r\n<br />\r\n(பின்னர் மற்றவர்களை நாம் அழித்தோம். மேலும் அவர்கள் மீது ஒரு மழையைப் பொழியச் செய்தோம்; அச்சமூட்டி எச்சரிக்கப்பட்ட அவர்களின் மழை மிகக் கெட்டதாக இருந்தது.)<br />\r\n<br />\r\nஅல்லாஹ்வின் இந்த வசனம் வரை; <span class=\"quran-arabic-font text-success\">﴾وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">رَبَّكَ</span> <span class=\"quran-arabic-font text-success\">لَهُوَ</span> <span class=\"quran-arabic-font text-success\">الْعَزِيزُ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمُ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிச்சயமாக உம்முடைய இறைவன், அவனே யாவரையும் மிகைத்தவன், மகா கருணையாளன்.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾كَذَّبَ</span> <span class=\"quran-arabic-font text-success\">أَصْحَابُ</span> <span class=\"quran-arabic-font text-success\">الْأَيْكَةِ</span> <span class=\"quran-arabic-font text-success\">الْمُرْسَلِينَ</span> - <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">شُعَيْبٌ</span> <span class=\"quran-arabic-font text-success\">أَلاَ</span> <span class=\"quran-arabic-font text-success\">تَتَّقُونَ</span> <span class=\"quran-arabic-font text-success\">إِنِّى</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">رَسُولٌ</span> <span class=\"quran-arabic-font text-success\">أَمِينٌ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />","text":"லூத் (அலை) அவர்கள் தனது சமூகத்தாரின் செயல்களைக் கண்டித்ததும், அதற்கு அவர்கள் அளித்த பதிலும், அவர்கள் தண்டிக்கப்பட்டதும்\n\r\n\n\r\nஅல்லாஹ்வின் தூதரான லூத் (அலை) அவர்கள், தீய செயல்கள் புரிவதிலிருந்தும், ஆண்களுடன் உடலுறவு கொள்வதிலிருந்தும் அந்த மக்களைத் தடுத்தார்கள். மேலும், அல்லாஹ் அவர்களுக்காகவே படைத்த அவர்களின் மனைவிகளுடன் தாம்பத்திய உறவு கொள்ளுமாறு அவர்களுக்கு அறிவுறுத்தினார்கள். அதற்கு அந்த மக்களின் பதில் இவ்வாறு கூறுவதாக மட்டுமே இருந்தது: ﴾لَئِن لَّمْ تَنتَهِ يَا لُوطُ﴿\n\r\n\n\r\n(லூத்தே! நீர் நிறுத்திக்கொள்ளவில்லையானால்,) அதாவது, 'நீர் கொண்டு வந்திருக்கும் இந்தப் போதனைகளை நீர் கைவிடவில்லையானால்,' ﴾لَتَكُونَنَّ مِنَ الْمُخْرَجِينَ﴿\n\r\n\n\r\n(நிச்சயமாக நீர் வெளியேற்றப்படுபவர்களில் ஒருவராகிவிடுவீர்!) அதாவது, 'நாங்கள் உம்மை எங்கள் ஊரிலிருந்து வெளியேற்றிவிடுவோம்.' இது பின்வரும் வசனத்தைப் போன்றதாகும்: ﴾فَمَا كَانَ جَوَابَ قَوْمِهِ إِلاَّ أَن قَالُواْ أَخْرِجُواْ ءَالَ لُوطٍ مِّن قَرْيَتِكُمْ إِنَّهمْ أُنَاسٌ يَتَطَهَّرُونَ ﴿\n\r\n\n\r\n(\"லூத்தின் குடும்பத்தாரை உங்கள் ஊரிலிருந்து வெளியேற்றுங்கள்; நிச்சயமாக இவர்கள் மிகவும் தூய்மையானவர்களாக இருக்க விரும்பும் மனிதர்களாவர்\" என்று அவர்கள் கூறியதைத் தவிர, அவருடைய சமூகத்தாரிடமிருந்து வேறு பதில் வரவில்லை.) (27:56). அவர்கள் தங்கள் தவறான வழிகளைக் கைவிடப்போவதில்லை என்பதையும், வழிகேட்டிலேயே பிடிவாதமாக இருப்பதையும் கண்ட லூத் (அலை) அவர்கள், அவர்களிடமிருந்து தான் விலகியிருப்பதை அறிவிக்கும் விதமாக இவ்வாறு கூறினார்கள்: ﴾إِنِّى لِعَمَلِكُم مِّنَ الْقَالِينَ﴿\n\r\n\n\r\n(நிச்சயமாக நான் உங்கள் செயலைக் கடுமையாக வெறுப்பவர்களில் ஒருவன்.) 'இதைக் கண்டு சீற்றமடைபவர்களில் நானும் ஒருவன்; எனக்கு இது பிடிக்கவில்லை, நான் இதனை ஏற்க மாட்டேன், உங்களுக்கும் எனக்கும் எந்தச் சம்பந்தமும் இல்லை' (என்பதே இதன் பொருளாகும்). பிறகு லூத் (அலை) அவர்கள் அந்த மக்களுக்கு எதிராக அல்லாஹ்விடம் இவ்வாறு பிரார்த்தனை செய்தார்கள்: ﴾رَبِّ نَّجِنِى وَأَهْلِى مِمَّا يَعْمَلُونَ ﴿\n\r\n\n\r\n(என் இறைவனே! இவர்கள் செய்து கொண்டிருக்கும் தீய செயல்களிலிருந்து என்னையும் என் குடும்பத்தாரையும் காப்பாற்றுவாயாக!)\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்: ﴾فَنَجَّيْنَاهُ وَأَهْلَهُ أَجْمَعِينَ - إِلاَّ عَجُوزاً فِى الْغَابِرِينَ ﴿\n\r\n\n\r\n(எனவே, நாம் அவரையும் அவருடைய குடும்பத்தினர் அனைவரையும் காப்பாற்றினோம்; பின்தங்கியவர்களில் இருந்த ஒரு மூதாட்டியைத் தவிர.)\n\r\n\n\r\nஅவள் அவருடைய மனைவியாவாள்; அவள் ஒரு தீய குணமுடைய மூதாட்டி. அவள் அங்கேயே தங்கிவிட்டதால், எஞ்சியிருந்த மற்றவர்களுடன் அவளும் அழிக்கப்பட்டாள். சூரா அல்-அஃராஃப், சூரா ஹூத் மற்றும் சூரா அல்-ஹிஜ்ர் ஆகியவற்றில் இவர்களைப் பற்றி அல்லாஹ் குறிப்பிடுவதைப் போலவே இதுவும் அமைந்துள்ளது. லூத் (அலை) அவர்களின் மனைவியைத் தவிர, மற்ற குடும்ப உறுப்பினர்களை இரவோடு இரவாக அழைத்துச் செல்லுமாறும், அவர்களின் சமூகத்தாருக்குத் தண்டனையாக ஸய்ஹா (பேரொலி) இறங்கும் சப்தத்தைக் கேட்டாலும் யாரும் திரும்பிப் பார்க்க வேண்டாம் என்றும் அல்லாஹ் அவருக்குக் கட்டளையிட்டான்.\n\r\n\n\r\nஎனவே, அவர்கள் பொறுமையுடன் அல்லாஹ்வின் கட்டளைக்குக் கீழ்ப்படிந்து உறுதியாக இருந்தனர். அல்லாஹ் அந்த மக்கள் அனைவரையும் அழிக்கும்படியான ஒரு தண்டனையை இறக்கினான். சுடப்பட்ட களிமண்ணாலான கற்களை ஒன்றன் மேல் ஒன்றாக அவர்கள் மீது மழையாகப் பொழியச் செய்தான்.\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்: ﴾ثُمَّ دَمَّرْنَا الْآخَرِينَ وَأَمْطَرْنَا عَلَيْهِمْ مَّطَرًا فَسَاءَ مَطَرُ الْمُنذَرِينَ﴿\n\r\n\n\r\n(பின்னர் மற்றவர்களை நாம் அழித்தோம். மேலும் அவர்கள் மீது ஒரு மழையைப் பொழியச் செய்தோம்; அச்சமூட்டி எச்சரிக்கப்பட்ட அவர்களின் மழை மிகக் கெட்டதாக இருந்தது.)\n\r\n\n\r\nஅல்லாஹ்வின் இந்த வசனம் வரை; ﴾وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ ﴿\n\r\n\n\r\n(நிச்சயமாக உம்முடைய இறைவன், அவனே யாவரையும் மிகைத்தவன், மகா கருணையாளன்.)\n\r\n\n\r\n﴾كَذَّبَ أَصْحَابُ الْأَيْكَةِ الْمُرْسَلِينَ - إِذْ قَالَ لَهُمْ شُعَيْبٌ أَلاَ تَتَّقُونَ إِنِّى لَكُمْ رَسُولٌ أَمِينٌ ﴿"},"176":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=180\" class=\"link\">26:180</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:180 ஐ பார்க்கவும்"},"177":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=180\" class=\"link\">26:180</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:180 ஐ பார்க்கவும்"},"178":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=180\" class=\"link\">26:180</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:180 ஐ பார்க்கவும்"},"179":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=180\" class=\"link\">26:180</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:180 ஐ பார்க்கவும்"},"180":{"html":"<strong>ஷுஐப் (அலை) அவர்களும் அல்-ஐக்கா வாசிகளுக்கு அவர்கள் செய்த போதனைகளும்</strong><br />\r\n<br />\r\nமிகவும் சரியான கருத்தின்படி, அல்-ஐக்கா வாசிகள் என்பவர்கள் மத்யன் மக்களே ஆவர். அல்லாஹ்வின் தூதர் ஷுஐப் (அலை) அவர்கள் அந்த மக்களில் ஒருவராக இருந்தார்கள். எனினும், இவ்வசனத்தில் \"அவர்களது சகோதரர் ஷுஐப்\" என்று அல்லாஹ் குறிப்பிடவில்லை. ஏனெனில், அவர்கள் வணங்கி வந்த 'அல்-ஐக்கா' எனும் மரத்தையே தெய்வமாக கருதி, அந்தப் பெயராலேயே தங்களை அழைத்துக்கொண்டனர். 'அல்-ஐக்கா' என்பது அடர்ந்த காட்டில் பின்னிப் பிணைந்துள்ள மரக்கூட்டங்களைப் போன்ற ஒரு வகை மரமாகும் என்று கூறப்படுகிறது. இதனால்தான், அல்-ஐக்கா வாசிகள் தூதர்களைப் பொய்யாக்கினார்கள் என்று அல்லாஹ் குறிப்பிடும்போது, \"அவர்களது சகோதரர் ஷுஐப் அவர்களிடம் கூறியபோது\" என்று கூறாமல், பின்வருமாறு கூறினான்: <span class=\"quran-arabic-font text-success\">﴾إِذْ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span> <span class=\"quran-arabic-font text-success\">شُعَيْبٌ﴿</span><br />\r\n<br />\r\n(ஷுஐப் அவர்கள் அவர்களிடம் கூறியபோது) இரத்த உறவு ரீதியாக அவர் அவர்களுக்குச் சகோதரராக இருந்தபோதிலும், அவர்கள் சூட்டிக்கொண்ட அந்தப் பெயரில் பொதிந்துள்ள கருத்தின் காரணமாக, அவர் அவர்களைச் சார்ந்தவராக இங்கு விவரிக்கப்படவில்லை. சிலர் இந்த நுணுக்கத்தைக் கவனிக்கத் தவறியதால், அல்-ஐக்கா வாசிகள் என்பவர்கள் மத்யன் மக்களிடமிருந்து வேறுபட்டவர்கள் என்று எண்ணினர். மேலும், ஷுஐப் (அலை) அவர்கள் இரண்டு சமூகங்களுக்கு அனுப்பப்பட்டார்கள் என்றும், சிலர் மூன்று சமூகங்களுக்கு அனுப்பப்பட்டார்கள் என்றும் வாதிட்டனர். <span class=\"quran-arabic-font text-success\">﴾أَصْحَابُ</span> <span class=\"quran-arabic-font text-success\">الْأَيْكَةِ﴿</span><br />\r\n<br />\r\n(அல்-ஐக்கா வாசிகள்) ஷுஐப் (அலை) அவர்களின் சமூகத்தினரே ஆவர். இதுவே இஸ்ஹாக் பின் பிஷ்ர் அவர்களின் கருத்தாகும். ஜுவைபிர் அல்லாத மற்றுமொருவர், \"அல்-ஐக்கா வாசிகளும் மத்யன் மக்களும் ஒருவரே\" என்று கூறினார். அல்லாஹ்வே மிக அறிந்தவன். அவர்கள் இரு வேறு அடையாளங்களைக் கொண்ட வெவ்வேறு சமூகங்கள் என்ற மற்றொரு கருத்து இருந்தபோதிலும், அவர்கள் ஒரே சமூகம் என்பதே சரியான கருத்தாகும்; ஆனால் வெவ்வேறு இடங்களில் அவர்கள் வெவ்வேறு விதமாக விவரிக்கப்படுகின்றனர். மத்யன் கதையில் குறிப்பிடப்பட்டுள்ளதைப் போலவே, ஷுஐப் (அலை) அவர்கள் இந்த மக்களுக்கும் போதனை செய்தார்கள்; மேலும் அளவையிலும் நிறுவையிலும் நேர்மையாக இருக்குமாறு அவர்களுக்குக் கட்டளையிட்டார்கள். இதுவும் அவர்கள் ஒரே சமூகத்தினர் என்பதையே உணர்த்துகிறது. <span class=\"quran-arabic-font text-success\">﴾أَوْفُواْ</span> <span class=\"quran-arabic-font text-success\">الْكَيْلَ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَكُونُواْ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُخْسِرِينَ</span> - <span class=\"quran-arabic-font text-success\">وَزِنُواْ</span> <span class=\"quran-arabic-font text-success\">بِالْقِسْطَاسِ</span> <span class=\"quran-arabic-font text-success\">الْمُسْتَقِيمِ</span> - <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَبْخَسُواْ</span> <span class=\"quran-arabic-font text-success\">النَّاسَ</span> <span class=\"quran-arabic-font text-success\">أَشْيَآءهُمْ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَعْثَوْاْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ</span> <span class=\"quran-arabic-font text-success\">مُفْسِدِينَ﴿</span><br />\r\n<br />","text":"ஷுஐப் (அலை) அவர்களும் அல்-ஐக்கா வாசிகளுக்கு அவர்கள் செய்த போதனைகளும்\n\r\n\n\r\nமிகவும் சரியான கருத்தின்படி, அல்-ஐக்கா வாசிகள் என்பவர்கள் மத்யன் மக்களே ஆவர். அல்லாஹ்வின் தூதர் ஷுஐப் (அலை) அவர்கள் அந்த மக்களில் ஒருவராக இருந்தார்கள். எனினும், இவ்வசனத்தில் \"அவர்களது சகோதரர் ஷுஐப்\" என்று அல்லாஹ் குறிப்பிடவில்லை. ஏனெனில், அவர்கள் வணங்கி வந்த 'அல்-ஐக்கா' எனும் மரத்தையே தெய்வமாக கருதி, அந்தப் பெயராலேயே தங்களை அழைத்துக்கொண்டனர். 'அல்-ஐக்கா' என்பது அடர்ந்த காட்டில் பின்னிப் பிணைந்துள்ள மரக்கூட்டங்களைப் போன்ற ஒரு வகை மரமாகும் என்று கூறப்படுகிறது. இதனால்தான், அல்-ஐக்கா வாசிகள் தூதர்களைப் பொய்யாக்கினார்கள் என்று அல்லாஹ் குறிப்பிடும்போது, \"அவர்களது சகோதரர் ஷுஐப் அவர்களிடம் கூறியபோது\" என்று கூறாமல், பின்வருமாறு கூறினான்: ﴾إِذْ قَالَ لَهُمْ شُعَيْبٌ﴿\n\r\n\n\r\n(ஷுஐப் அவர்கள் அவர்களிடம் கூறியபோது) இரத்த உறவு ரீதியாக அவர் அவர்களுக்குச் சகோதரராக இருந்தபோதிலும், அவர்கள் சூட்டிக்கொண்ட அந்தப் பெயரில் பொதிந்துள்ள கருத்தின் காரணமாக, அவர் அவர்களைச் சார்ந்தவராக இங்கு விவரிக்கப்படவில்லை. சிலர் இந்த நுணுக்கத்தைக் கவனிக்கத் தவறியதால், அல்-ஐக்கா வாசிகள் என்பவர்கள் மத்யன் மக்களிடமிருந்து வேறுபட்டவர்கள் என்று எண்ணினர். மேலும், ஷுஐப் (அலை) அவர்கள் இரண்டு சமூகங்களுக்கு அனுப்பப்பட்டார்கள் என்றும், சிலர் மூன்று சமூகங்களுக்கு அனுப்பப்பட்டார்கள் என்றும் வாதிட்டனர். ﴾أَصْحَابُ الْأَيْكَةِ﴿\n\r\n\n\r\n(அல்-ஐக்கா வாசிகள்) ஷுஐப் (அலை) அவர்களின் சமூகத்தினரே ஆவர். இதுவே இஸ்ஹாக் பின் பிஷ்ர் அவர்களின் கருத்தாகும். ஜுவைபிர் அல்லாத மற்றுமொருவர், \"அல்-ஐக்கா வாசிகளும் மத்யன் மக்களும் ஒருவரே\" என்று கூறினார். அல்லாஹ்வே மிக அறிந்தவன். அவர்கள் இரு வேறு அடையாளங்களைக் கொண்ட வெவ்வேறு சமூகங்கள் என்ற மற்றொரு கருத்து இருந்தபோதிலும், அவர்கள் ஒரே சமூகம் என்பதே சரியான கருத்தாகும்; ஆனால் வெவ்வேறு இடங்களில் அவர்கள் வெவ்வேறு விதமாக விவரிக்கப்படுகின்றனர். மத்யன் கதையில் குறிப்பிடப்பட்டுள்ளதைப் போலவே, ஷுஐப் (அலை) அவர்கள் இந்த மக்களுக்கும் போதனை செய்தார்கள்; மேலும் அளவையிலும் நிறுவையிலும் நேர்மையாக இருக்குமாறு அவர்களுக்குக் கட்டளையிட்டார்கள். இதுவும் அவர்கள் ஒரே சமூகத்தினர் என்பதையே உணர்த்துகிறது. ﴾أَوْفُواْ الْكَيْلَ وَلاَ تَكُونُواْ مِنَ الْمُخْسِرِينَ - وَزِنُواْ بِالْقِسْطَاسِ الْمُسْتَقِيمِ - وَلاَ تَبْخَسُواْ النَّاسَ أَشْيَآءهُمْ وَلاَ تَعْثَوْاْ فِى الْأَرْضِ مُفْسِدِينَ﴿"},"181":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=184\" class=\"link\">26:184</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:184 ஐ பார்க்கவும்"},"182":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=184\" class=\"link\">26:184</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:184 ஐ பார்க்கவும்"},"183":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=184\" class=\"link\">26:184</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:184 ஐ பார்க்கவும்"},"184":{"html":"<strong>அளவையை முழுமையாக்க வேண்டுமென்ற கட்டளை</strong><br />\r\n<br />\r\nஅல்லாஹ் அவர்களுக்கு அளவையை முழுமையாக்குமாறு கட்டளையிட்டான், மேலும் அளவையில் குறைவு செய்வதைத் தடுத்தான். அவன் கூறினான்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾أَوْفُواْ</span> <span class=\"quran-arabic-font text-success\">الْكَيْلَ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَكُونُواْ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُخْسِرِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அளவை முழுமையாக்குங்கள்; (அவர்களுக்கு) நஷ்டம் இழைப்போரில் (நீங்களும்) ஆகிவிடாதீர்கள்.) இதன் பொருள்: 'நீங்கள் மக்களுக்குக் கொடுக்கும்போது முழுமையாக அளந்து கொடுங்கள்; நீங்கள் வாங்கும்போது மட்டும் முழுமையாகப் பெற்றுக்கொண்டு, கொடுக்கும் போது அளவைக் குறைத்து அவர்களுக்கு நஷ்டத்தை ஏற்படுத்தாதீர்கள். நீங்கள் எதைப் பெறுகிறீர்களோ அதையே கொடுங்கள், எதைக் கொடுக்கிறீர்களோ அதையே பெறுங்கள்.'<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَزِنُواْ</span> <span class=\"quran-arabic-font text-success\">بِالْقِسْطَاسِ</span> <span class=\"quran-arabic-font text-success\">الْمُسْتَقِيمِ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(சரியான தராசைக் கொண்டு எடை நிறுத்துங்கள்.) அல்-கிஸ்தாஸ் என்பது தராசைக் குறிக்கும்.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَبْخَسُواْ</span> <span class=\"quran-arabic-font text-success\">النَّاسَ</span> <span class=\"quran-arabic-font text-success\">أَشْيَاءَهُمْ﴿</span><br />\r\n<br />\r\n(மக்களுக்கு(க் கொடுக்க வேண்டிய) அவர்களது பொருட்களைக் குறைத்து விடாதீர்கள்.) அதாவது, அவர்களுக்குக் குறைவாகக் கொடுத்து ஏமாற்றாதீர்கள்.<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَعْثَوْاْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الاٌّرْضِ</span> <span class=\"quran-arabic-font text-success\">مُفْسِدِينَ﴿</span><br />\r\n<br />\r\n(பூமியில் விஷமம் செய்துகொண்டு அலையாதீர்கள்.) அதாவது, வழிப்பறியில் ஈடுபடுவதன் மூலம் குழப்பம் விளைவிக்காதீர்கள். இது பின்வரும் வசனத்தைப் போன்றதாகும்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَقْعُدُواْ</span> <span class=\"quran-arabic-font text-success\">بِكُلِّ</span> <span class=\"quran-arabic-font text-success\">صِرَطٍ</span> <span class=\"quran-arabic-font text-success\">تُوعِدُونَ﴿</span><br />\r\n<br />\r\n(ஒவ்வொரு பாதையிலும் (மக்களை) அச்சுறுத்துவதற்காக அமராதீர்கள்) (<a href=\"qurandisp.php?sura=7&ayah=86\" class=\"link\">7:86</a>).<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَاتَّقُواْ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">خَلَقَكُمْ</span> <span class=\"quran-arabic-font text-success\">وَالْجِبِلَّةَ</span> <span class=\"quran-arabic-font text-success\">الاٌّوَّلِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(உங்களையும், முந்தைய சமுதாயத்தினரையும் படைத்தவனை அஞ்சிக் கொள்ளுங்கள்.) இங்கு அவர் (ஷுஐப் (அலை)) அவர்களைப் படைத்தவனும், அவர்களுடைய முன்னோர்களைப் படைத்தவனுமாகிய அல்லாஹ்வின் தண்டனையைக் குறித்து அவர்களை அச்சமூட்டி எச்சரிக்கிறார்கள். இது மூஸா (அலை) அவர்கள் கூறியதைப் போன்றதாகும்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾رَبُّكُمْ</span> <span class=\"quran-arabic-font text-success\">وَرَبُّ</span> <span class=\"quran-arabic-font text-success\">ءَابَآئِكُمُ</span> <span class=\"quran-arabic-font text-success\">الاٌّوَّلِينَ﴿</span><br />\r\n<br />\r\n(அவனே உங்கள் இறைவனும், உங்கள் முந்தைய மூதாதையர்களின் இறைவனும் ஆவான்!) (<a href=\"qurandisp.php?sura=26&ayah=26\" class=\"link\">26:26</a>).<br />\r\n<br />\r\nஇப்னு அப்பாஸ் (ரழி), முஜாஹித், அஸ்-ஸுத்தீ, ஸுஃப்யான் பின் உயைனா மற்றும் அப்துர் ரஹ்மான் பின் ஜைத் பின் அஸ்லம் ஆகியோர் கூறினார்கள்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَالْجِبِلَّةَ</span> <span class=\"quran-arabic-font text-success\">الاٌّوَّلِينَ﴿</span><br />\r\n<br />\r\n(முந்தைய தலைமுறையினர்.) அதாவது, அவன் முற்காலத் தலைமுறைகளைப் படைத்தான் என்று பொருள்படும். மேலும் இப்னு ஜைத் (ரழி) பின்வரும் வசனத்தை ஓதிக்காட்டினார்கள்:<br />\r\n<span class=\"quran-arabic-font text-success\">﴾وَلَقَدْ</span> <span class=\"quran-arabic-font text-success\">أَضَلَّ</span> <span class=\"quran-arabic-font text-success\">مِنْكُمْ</span> <span class=\"quran-arabic-font text-success\">جِبِلاًّ</span> <span class=\"quran-arabic-font text-success\">كَثِيراً﴿</span><br />\r\n<br />\r\n(நிச்சயமாக அவன் (ஷைத்தான்) உங்களில் பெரும் கூட்டத்தினரை வழிதவறச் செய்தான்) (<a href=\"qurandisp.php?sura=36&ayah=62\" class=\"link\">36:62</a>).<br />\r\n<br />\r\n<strong>ஷுஐப் (அலை) அவர்களுக்கு அவர்கள் அளித்த மறுமொழியும் அவர்களுக்கு வந்த அழிவும்</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">﴾قَالُواْ</span> <span class=\"quran-arabic-font text-success\">إِنَّمَآ</span> <span class=\"quran-arabic-font text-success\">أَنتَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُسَحَّرِينَ</span> <span class=\"quran-arabic-font text-success\">﴿﴾وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَنتَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">بَشَرٌ</span> <span class=\"quran-arabic-font text-success\">مّثْلُنَا</span> <span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">نَّظُنُّكَ</span> <span class=\"quran-arabic-font text-success\">لَمِنَ</span> <span class=\"quran-arabic-font text-success\">الْكَـذِبِينَ</span>-<span class=\"quran-arabic-font text-success\">﴿﴾فَأَسْقِطْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْنَا</span> <span class=\"quran-arabic-font text-success\">كِسَفاً</span> <span class=\"quran-arabic-font text-success\">مّنَ</span> <span class=\"quran-arabic-font text-success\">السَّمَآء</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كُنتَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الصَّـدِقِينَ</span>-<span class=\"quran-arabic-font text-success\">﴿﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">رَبّى</span> <span class=\"quran-arabic-font text-success\">أَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">تَعْمَلُونَ</span>-<span class=\"quran-arabic-font text-success\">﴿﴾فَكَذَّبُوهُ</span> <span class=\"quran-arabic-font text-success\">فَأَخَذَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَذَابُ</span> <span class=\"quran-arabic-font text-success\">يَوْمِ</span> <span class=\"quran-arabic-font text-success\">الظُّلَّةِ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">عَذَابَ</span> <span class=\"quran-arabic-font text-success\">يَوْمٍ</span> <span class=\"quran-arabic-font text-success\">عَظِيمٍ</span>-<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அதற்கு) அவர்கள், \"நீ சூனியம் செய்யப்பட்டவர்களில் ஒருவரே!\" என்று கூறினார்கள். \"மேலும், நீ எங்களைப் போன்ற ஒரு மனிதரேயன்றி வேறில்லை; நிச்சயமாக நாங்கள் உன்னைப் பொய்யர்களில் ஒருவராகவே எண்ணுகிறோம்.\" \"(ஆகவே) நீ உண்மையாளர்களில் ஒருவராக இருந்தால், வானத்திலிருந்து ஒரு துண்டை எங்கள் மீது விழச் செய்!\" (என்றும் கூறினர்). (அதற்கு) அவர், \"நீங்கள் செய்வதை என் இறைவன் நன்கறிபவன்\" என்று கூறினார். ஆயினும், அவர்கள் அவரைப் பொய்யாக்கினார்கள்; எனவே, 'மேக நிழல் நாளின்' வேதனை அவர்களைப் பிடித்துக் கொண்டது; நிச்சயமாக அது மகத்தான ஒரு நாளின் வேதனையாக இருந்தது.<br />\r\n<br />","text":"அளவையை முழுமையாக்க வேண்டுமென்ற கட்டளை\n\r\n\n\r\nஅல்லாஹ் அவர்களுக்கு அளவையை முழுமையாக்குமாறு கட்டளையிட்டான், மேலும் அளவையில் குறைவு செய்வதைத் தடுத்தான். அவன் கூறினான்:\n\r\n﴾أَوْفُواْ الْكَيْلَ وَلاَ تَكُونُواْ مِنَ الْمُخْسِرِينَ ﴿\n\r\n\n\r\n(அளவை முழுமையாக்குங்கள்; (அவர்களுக்கு) நஷ்டம் இழைப்போரில் (நீங்களும்) ஆகிவிடாதீர்கள்.) இதன் பொருள்: 'நீங்கள் மக்களுக்குக் கொடுக்கும்போது முழுமையாக அளந்து கொடுங்கள்; நீங்கள் வாங்கும்போது மட்டும் முழுமையாகப் பெற்றுக்கொண்டு, கொடுக்கும் போது அளவைக் குறைத்து அவர்களுக்கு நஷ்டத்தை ஏற்படுத்தாதீர்கள். நீங்கள் எதைப் பெறுகிறீர்களோ அதையே கொடுங்கள், எதைக் கொடுக்கிறீர்களோ அதையே பெறுங்கள்.'\n\r\n﴾وَزِنُواْ بِالْقِسْطَاسِ الْمُسْتَقِيمِ ﴿\n\r\n\n\r\n(சரியான தராசைக் கொண்டு எடை நிறுத்துங்கள்.) அல்-கிஸ்தாஸ் என்பது தராசைக் குறிக்கும்.\n\r\n﴾وَلاَ تَبْخَسُواْ النَّاسَ أَشْيَاءَهُمْ﴿\n\r\n\n\r\n(மக்களுக்கு(க் கொடுக்க வேண்டிய) அவர்களது பொருட்களைக் குறைத்து விடாதீர்கள்.) அதாவது, அவர்களுக்குக் குறைவாகக் கொடுத்து ஏமாற்றாதீர்கள்.\n\r\n﴾وَلاَ تَعْثَوْاْ فِى الاٌّرْضِ مُفْسِدِينَ﴿\n\r\n\n\r\n(பூமியில் விஷமம் செய்துகொண்டு அலையாதீர்கள்.) அதாவது, வழிப்பறியில் ஈடுபடுவதன் மூலம் குழப்பம் விளைவிக்காதீர்கள். இது பின்வரும் வசனத்தைப் போன்றதாகும்:\n\r\n﴾وَلاَ تَقْعُدُواْ بِكُلِّ صِرَطٍ تُوعِدُونَ﴿\n\r\n\n\r\n(ஒவ்வொரு பாதையிலும் (மக்களை) அச்சுறுத்துவதற்காக அமராதீர்கள்) (7:86).\n\r\n﴾وَاتَّقُواْ الَّذِى خَلَقَكُمْ وَالْجِبِلَّةَ الاٌّوَّلِينَ ﴿\n\r\n\n\r\n(உங்களையும், முந்தைய சமுதாயத்தினரையும் படைத்தவனை அஞ்சிக் கொள்ளுங்கள்.) இங்கு அவர் (ஷுஐப் (அலை)) அவர்களைப் படைத்தவனும், அவர்களுடைய முன்னோர்களைப் படைத்தவனுமாகிய அல்லாஹ்வின் தண்டனையைக் குறித்து அவர்களை அச்சமூட்டி எச்சரிக்கிறார்கள். இது மூஸா (அலை) அவர்கள் கூறியதைப் போன்றதாகும்:\n\r\n﴾رَبُّكُمْ وَرَبُّ ءَابَآئِكُمُ الاٌّوَّلِينَ﴿\n\r\n\n\r\n(அவனே உங்கள் இறைவனும், உங்கள் முந்தைய மூதாதையர்களின் இறைவனும் ஆவான்!) (26:26).\n\r\n\n\r\nஇப்னு அப்பாஸ் (ரழி), முஜாஹித், அஸ்-ஸுத்தீ, ஸுஃப்யான் பின் உயைனா மற்றும் அப்துர் ரஹ்மான் பின் ஜைத் பின் அஸ்லம் ஆகியோர் கூறினார்கள்:\n\r\n﴾وَالْجِبِلَّةَ الاٌّوَّلِينَ﴿\n\r\n\n\r\n(முந்தைய தலைமுறையினர்.) அதாவது, அவன் முற்காலத் தலைமுறைகளைப் படைத்தான் என்று பொருள்படும். மேலும் இப்னு ஜைத் (ரழி) பின்வரும் வசனத்தை ஓதிக்காட்டினார்கள்:\n\r\n﴾وَلَقَدْ أَضَلَّ مِنْكُمْ جِبِلاًّ كَثِيراً﴿\n\r\n\n\r\n(நிச்சயமாக அவன் (ஷைத்தான்) உங்களில் பெரும் கூட்டத்தினரை வழிதவறச் செய்தான்) (36:62).\n\r\n\n\r\nஷுஐப் (அலை) அவர்களுக்கு அவர்கள் அளித்த மறுமொழியும் அவர்களுக்கு வந்த அழிவும்\n\r\n\n\r\n﴾قَالُواْ إِنَّمَآ أَنتَ مِنَ الْمُسَحَّرِينَ ﴿﴾وَمَآ أَنتَ إِلاَّ بَشَرٌ مّثْلُنَا وَإِن نَّظُنُّكَ لَمِنَ الْكَـذِبِينَ-﴿﴾فَأَسْقِطْ عَلَيْنَا كِسَفاً مّنَ السَّمَآء إِن كُنتَ مِنَ الصَّـدِقِينَ-﴿﴾قَالَ رَبّى أَعْلَمُ بِمَا تَعْمَلُونَ-﴿﴾فَكَذَّبُوهُ فَأَخَذَهُمْ عَذَابُ يَوْمِ الظُّلَّةِ إِنَّهُ كَانَ عَذَابَ يَوْمٍ عَظِيمٍ-﴿\n\r\n\n\r\n(அதற்கு) அவர்கள், \"நீ சூனியம் செய்யப்பட்டவர்களில் ஒருவரே!\" என்று கூறினார்கள். \"மேலும், நீ எங்களைப் போன்ற ஒரு மனிதரேயன்றி வேறில்லை; நிச்சயமாக நாங்கள் உன்னைப் பொய்யர்களில் ஒருவராகவே எண்ணுகிறோம்.\" \"(ஆகவே) நீ உண்மையாளர்களில் ஒருவராக இருந்தால், வானத்திலிருந்து ஒரு துண்டை எங்கள் மீது விழச் செய்!\" (என்றும் கூறினர்). (அதற்கு) அவர், \"நீங்கள் செய்வதை என் இறைவன் நன்கறிபவன்\" என்று கூறினார். ஆயினும், அவர்கள் அவரைப் பொய்யாக்கினார்கள்; எனவே, 'மேக நிழல் நாளின்' வேதனை அவர்களைப் பிடித்துக் கொண்டது; நிச்சயமாக அது மகத்தான ஒரு நாளின் வேதனையாக இருந்தது."},"185":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=191\" class=\"link\">26:191</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:191 ஐ பார்க்கவும்"},"186":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=191\" class=\"link\">26:191</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:191 ஐ பார்க்கவும்"},"187":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=191\" class=\"link\">26:191</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:191 ஐ பார்க்கவும்"},"188":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=191\" class=\"link\">26:191</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:191 ஐ பார்க்கவும்"},"189":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=191\" class=\"link\">26:191</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:191 ஐ பார்க்கவும்"},"190":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=191\" class=\"link\">26:191</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:191 ஐ பார்க்கவும்"},"191":{"html":"<strong>ஷுஐப் (அலை) அவர்களின் சமூகத்தாரின் பதில், அவர்களின் நிராகரிப்பு மற்றும் அவர்கள் மீது வேதனை இறங்கியது</strong><br />\r\n<br />\r\nதன் தூதருக்கு ஸமூத் சமூகத்தினர் அளித்த பதிலைப் போலவே ஷுஐப் (அலை) அவர்களின் சமூகத்தாரும் பதிலளித்தார்கள் என அல்லாஹ் கூறுகிறான் - ஏனெனில் அவர்கள் ஒரே மாதிரியான சிந்தனை கொண்டவர்களாக இருந்தனர். அவர்கள் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾إِنَّمَآ</span> <span class=\"quran-arabic-font text-success\">أَنتَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُسَحَّرِينَ﴿</span><br />\r\n<br />\r\n\"நீர் சூனியம் செய்யப்பட்டவர்களில் ஒருவரே அன்றி வேறில்லை!\" அதாவது, \"நீர் சூனியத்தால் பாதிக்கப்பட்டவர்களில் ஒருவர்\" (என்று அவர்கள் கருதினர்). <span class=\"quran-arabic-font text-success\">﴾وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَنتَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">بَشَرٌ</span> <span class=\"quran-arabic-font text-success\">مِّثْلُنَا</span> <span class=\"quran-arabic-font text-success\">وَإِن</span> <span class=\"quran-arabic-font text-success\">نَّظُنُّكَ</span> <span class=\"quran-arabic-font text-success\">لَمِنَ</span> <span class=\"quran-arabic-font text-success\">الْكَـذِبِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நீர் எங்களைப் போன்ற ஒரு மனிதரே அன்றி வேறில்லை. நிச்சயமாக, நீர் பொய்யர்களில் ஒருவரென்றே நாங்கள் கருதுகிறோம்!) அதாவது, \"நீர் எங்களிடம் வேண்டுமென்றே பொய் சொல்கிறீர் என்றும், அல்லாஹ் உம்மைத் தூதராக அனுப்பவில்லை என்றும் நாங்கள் கருதுகிறோம்\" (என்று அவர்கள் கூறினார்கள்). <span class=\"quran-arabic-font text-success\">﴾فَأَسْقِطْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْنَا</span> <span class=\"quran-arabic-font text-success\">كِسَفاً</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">السَّمَآءِ﴿</span><br />\r\n<br />\r\n(ஆகவே, வானத்தின் ஒரு துண்டை எங்கள் மீது விழச்செய்யும்!) \"வானத்தின் ஒரு பகுதி\" என்று அத்-தஹ்ஹாக் (ரழி) அவர்களும், \"வானத்திலிருந்து ஒரு துண்டு\" என்று கதாதா (ரழி) அவர்களும், \"வானத்திலிருந்து ஒரு தண்டனை\" என்று அஸ்-ஸுத்தீ (ரழி) அவர்களும் விளக்கம் அளித்துள்ளனர். இது குறைஷிகள் கூறியதைப் போன்றதே ஆகும்; அதனை அல்லாஹ் இவ்வாறு குறிப்பிடுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَقَالُواْ</span> <span class=\"quran-arabic-font text-success\">لَن</span> <span class=\"quran-arabic-font text-success\">نُّؤْمِنَ</span> <span class=\"quran-arabic-font text-success\">لَكَ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">تَفْجُرَ</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الاٌّرْضِ</span> <span class=\"quran-arabic-font text-success\">يَنْبُوعًا</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அவர்கள் கூறுகிறார்கள்: \"நீர் எங்களுக்காகப் பூமியிலிருந்து ஒரு நீரூற்றை ஓடச் செய்யும் வரை நாங்கள் உம்மை நம்ப மாட்டோம்\") என்பது முதல்: <span class=\"quran-arabic-font text-success\">﴾أَوْ</span> <span class=\"quran-arabic-font text-success\">تُسْقِطَ</span> <span class=\"quran-arabic-font text-success\">السَّمَآءَ</span> <span class=\"quran-arabic-font text-success\">كَمَا</span> <span class=\"quran-arabic-font text-success\">زَعَمْتَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْنَا</span> <span class=\"quran-arabic-font text-success\">كِسَفًا</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">تَأْتِىَ</span> <span class=\"quran-arabic-font text-success\">بِاللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَالْمَلَـئِكَةِ</span> <span class=\"quran-arabic-font text-success\">قَبِيلاً</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(\"அல்லது நீர் வாதிடுவது போல் வானத்தைத் துண்டு துண்டாக எங்கள் மீது விழச் செய்ய வேண்டும், அல்லது அல்லாஹ்வையும் வானவர்களையும் எங்கள் முன்னே நேருக்கு நேராகக் கொண்டு வர வேண்டும்.\") (<a href=\"qurandisp.php?sura=17&ayah=90\" class=\"link\">17:90</a>-92) <span class=\"quran-arabic-font text-success\">﴾وَإِذْ</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">اللَّهُمَّ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">هَـذَا</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">الْحَقَّ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عِندِكَ</span> <span class=\"quran-arabic-font text-success\">فَأَمْطِرْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْنَا</span> <span class=\"quran-arabic-font text-success\">حِجَارَةً</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">السَّمَآءِ﴿</span><br />\r\n<br />\r\n(\"மேலும், அவர்கள்: 'யா அல்லாஹ்! இது உன்னிடமிருந்து வந்த உண்மையாக இருந்தால், எங்கள் மீது வானத்திலிருந்து கல் மழையைப் பொழியச் செய்...' என்று கூறியதை நினைவுகூருங்கள்\") (<a href=\"qurandisp.php?sura=8&ayah=32\" class=\"link\">8:32</a>). இதேபோல், இந்த அறிவற்ற நிராகரிப்பாளர்களும் கூறினார்கள்: <span class=\"quran-arabic-font text-success\">﴾فَأَسْقِطْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْنَا</span> <span class=\"quran-arabic-font text-success\">كِسَفاً</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">السَّمَآءِ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">كُنتَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الصَّـدِقِينَ﴿</span><br />\r\n<br />\r\n(நீர் உண்மையாளராக இருந்தால், வானத்திலிருந்து ஒரு துண்டை எங்கள் மீது விழச்செய்யும்!) <span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">رَبِّى</span> <span class=\"quran-arabic-font text-success\">أَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">بِمَا</span> <span class=\"quran-arabic-font text-success\">تَعْمَلُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அதற்கு அவர்: \"நீங்கள் செய்பவற்றை என் இறைவன் நன்கு அறிந்தவன்\" என்று கூறினார்கள்.) அதாவது, \"அல்லாஹ் உங்களைப் பற்றி நன்கு அறிந்தவன்; நீங்கள் தண்டனைக்குத் தகுதியானவர்களாக இருந்தால், அவன் அதைக் கொண்டு உங்களைத் தண்டிப்பான்; அவன் உங்களுக்கு அநீதி இழைக்க மாட்டான்\" என்பதாகும். அவர்கள் வேண்டியபடியே, அவர்களுக்குச் சரியான பிரதிபலனாக அந்தத் தண்டனை நிகழ்ந்தது. அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾فَكَذَّبُوهُ</span> <span class=\"quran-arabic-font text-success\">فَأَخَذَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَذَابُ</span> <span class=\"quran-arabic-font text-success\">يَوْمِ</span> <span class=\"quran-arabic-font text-success\">الظُّلَّةِ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">عَذَابَ</span> <span class=\"quran-arabic-font text-success\">يَوْمٍ</span> <span class=\"quran-arabic-font text-success\">عَظِيمٍ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(ஆனால் அவர்கள் அவரைப் பொய்யாக்கினார்கள், அதனால் 'நிழல் தரும் மேக' நாளின் வேதனை அவர்களைப் பிடித்துக்கொண்டது. நிச்சயமாக அது ஒரு மகத்தான நாளின் வேதனையாக இருந்தது.) வானத்திலிருந்து ஒரு துண்டு விழ வேண்டும் என்று அவர்கள் கேட்டதற்கு இணங்கவே இது அமைந்தது. அல்லாஹ் அவர்களுக்கு ஏழு நாட்கள் நீடித்த கடுமையான வெப்பத்தைத் தண்டனையாக அளித்தான்; அதிலிருந்து எதனாலும் அவர்களைப் பாதுகாக்க முடியவில்லை. பிறகு, அவர்களுக்கு நிழல் தருவதற்காக ஒரு மேகத்தை அல்லாஹ் அனுப்பினான்; வெப்பத்தைத் தணிக்க அந்த நிழலை நோக்கி அவர்கள் ஓடினார்கள். அவர்கள் அனைவரும் அதன் கீழ் திரண்டபோது, அல்லாஹ் அவர்கள் மீது நெருப்புப் பொறிகளையும், தீப்பிழம்புகளையும், கடுமையான வெப்பத்தையும் இறக்கினான். பூமி அவர்களைக் கீழ்நோக்கி உலுக்கியது; மேலும் அவர்களை அழிக்கும் வகையில் ஒரு பெரும் 'ஸைஹா' (பேரொலி) அவர்கள் மீது ஏவப்பட்டது. அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">عَذَابَ</span> <span class=\"quran-arabic-font text-success\">يَوْمٍ</span> <span class=\"quran-arabic-font text-success\">عَظِيمٍ﴿</span><br />\r\n<br />\r\n(நிச்சயமாக அது ஒரு மகத்தான நாளின் வேதனையாக இருந்தது.) அவர்கள் எவ்வாறு அழிக்கப்பட்டார்கள் என்பதை அல்லாஹ் குர்ஆனின் மூன்று இடங்களில் விவரித்துள்ளான். ஒவ்வொன்றும் அந்தந்தச் சூழலுக்குப் பொருத்தமான முறையில் விவரிக்கப்பட்டுள்ளது. சூரா அல்-அஃராஃபில், நிலநடுக்கம் அவர்களைப் பிடித்துக்கொண்டது என்றும், அவர்கள் தங்கள் வீடுகளில் (இறந்து) கவிழ்ந்து கிடந்தார்கள் என்றும் கூறுகிறான். இதற்குக் காரணம் அவர்கள் இவ்வாறு கூறியதே ஆகும்: <span class=\"quran-arabic-font text-success\">﴾لَنُخْرِجَنَّكَ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">شُعَيْبُ</span> <span class=\"quran-arabic-font text-success\">وَالَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنُواْ</span> <span class=\"quran-arabic-font text-success\">مَعَكَ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَرْيَتِنَآ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">لَتَعُودُنَّ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">مِلَّتِنَا﴿</span><br />\r\n<br />\r\n(\"ஷுஐபே! உம்மையும் உம்முடன் ஈமான் கொண்டவர்களையும் எங்கள் ஊரிலிருந்து நிச்சயமாக நாங்கள் வெளியேற்றுவோம்; அல்லது நீங்கள் அனைவரும் எங்கள் மார்க்கத்திற்குத் திரும்பிவிட வேண்டும்.\") (<a href=\"qurandisp.php?sura=7&ayah=88\" class=\"link\">7:88</a>). அவர்கள் அல்லாஹ்வின் தூதரையும் விசுவாசிகளையும் பயமுறுத்த முயன்றதால், அவர்கள் நிலநடுக்கத்தால் பிடிக்கப்பட்டனர். சூரா ஹூதில், அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَأَخَذَتِ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ظَلَمُواْ</span> <span class=\"quran-arabic-font text-success\">الصَّيْحَةُ﴿</span><br />\r\n<br />\r\n(அநீதி இழைத்தவர்களைப் பேரொலி பிடித்துக்கொண்டது) (<a href=\"qurandisp.php?sura=11&ayah=94\" class=\"link\">11:94</a>). அவர்கள் அல்லாஹ்வின் தூதரை இவ்வாறு ஏளனம் செய்ததே இதற்குக் காரணமாகும்: <span class=\"quran-arabic-font text-success\">﴾أَصَلَوَتُكَ</span> <span class=\"quran-arabic-font text-success\">تَأْمُرُكَ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">نَّتْرُكَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">يَعْبُدُ</span> <span class=\"quran-arabic-font text-success\">ءابَاؤُنَآ</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">نَّفْعَلَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">أَمْوَالِنَا</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">نَشَاءُ</span> <span class=\"quran-arabic-font text-success\">إِنَّكَ</span> <span class=\"quran-arabic-font text-success\">لَأَنتَ</span> <span class=\"quran-arabic-font text-success\">الْحَلِيمُ</span> <span class=\"quran-arabic-font text-success\">الرَّشِيدُ﴿</span><br />\r\n<br />\r\n(\"எங்கள் முன்னோர்கள் வணங்கியவற்றை நாங்கள் விட்டுவிட வேண்டும் என்றோ, அல்லது எங்கள் சொத்துக்களை நாங்கள் விரும்பியபடி செலவிடுவதைத் தடுத்துவிட வேண்டும் என்றோ உமது தொழுகையா உமக்குக் கட்டளையிடுகிறது? நிச்சயமாக நீர் மிகுந்த சகிப்புத்தன்மை உடையவர், நேர்வழி நடப்பவர்!\") (<a href=\"qurandisp.php?sura=11&ayah=87\" class=\"link\">11:87</a>). அவர்கள் இதனை ஏளனமாகவும் கிண்டலாகவும் கூறியதால், 'ஸைஹா' (பேரொலி) வந்து அவர்களை மௌனமாக்கியது பொருத்தமானதாக இருந்தது. அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾فَأَخَذَتْهُمُ</span> <span class=\"quran-arabic-font text-success\">الصَّيْحَةُ﴿</span><br />\r\n<br />\r\n(ஆகவே, அந்தப் பேரொலி அவர்களைப் பிடித்துக்கொண்டது) (<a href=\"qurandisp.php?sura=15&ayah=73\" class=\"link\">15:73</a>). <span class=\"quran-arabic-font text-success\">﴾وَأَخَذَتِ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ظَلَمُواْ</span> <span class=\"quran-arabic-font text-success\">الصَّيْحَةُ﴿</span><br />\r\n<br />\r\n(அநீதி இழைத்தவர்களைப் பேரொலி பிடித்துக்கொண்டது) (<a href=\"qurandisp.php?sura=11&ayah=94\" class=\"link\">11:94</a>). இங்கு அவர்கள் பிடிவாதமாகவும் முரட்டுத்தனமாகவும்: <span class=\"quran-arabic-font text-success\">﴾فَأَسْقِطْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْنَا</span> <span class=\"quran-arabic-font text-success\">كِسَفاً</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">السَّمَآءِ﴿</span><br />\r\n<br />\r\n(வானத்திலிருந்து ஒரு துண்டை எங்கள் மீது விழச்செய்யும்!) என்று கூறினார்கள். எனவே, அவர்கள் ஒருபோதும் நிகழாது என்று கருதிய ஒன்று அவர்களுக்குச் சம்பவித்தது பொருத்தமாக அமைந்தது: <span class=\"quran-arabic-font text-success\">﴾فَأَخَذَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَذَابُ</span> <span class=\"quran-arabic-font text-success\">يَوْمِ</span> <span class=\"quran-arabic-font text-success\">الظُّلَّةِ</span> <span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">عَذَابَ</span> <span class=\"quran-arabic-font text-success\">يَوْمٍ</span> <span class=\"quran-arabic-font text-success\">عَظِيمٍ﴿</span><br />\r\n<br />\r\n(அதனால் நிழல் தரும் மேக நாளின் வேதனை அவர்களைப் பிடித்துக்கொண்டது. நிச்சயமாக அது ஒரு மகத்தான நாளின் வேதனையாக இருந்தது.) முஹம்மத் பின் ஜரீர் அவர்கள், யஸீத் அல்-பாஹிலீ அவர்களிடமிருந்து அறிவிக்கிறார்கள்: \"நான் இப்னு அப்பாஸ் (ரழி) அவர்களிடம் இந்த வசனத்தைப் பற்றிக் கேட்டேன்: <span class=\"quran-arabic-font text-success\">﴾فَأَخَذَهُمْ</span> <span class=\"quran-arabic-font text-success\">عَذَابُ</span> <span class=\"quran-arabic-font text-success\">يَوْمِ</span> <span class=\"quran-arabic-font text-success\">الظُّلَّةِ﴿</span><br />\r\n<br />\r\n(அதனால் நிழல் தரும் மேக நாளின் வேதனை அவர்களைப் பிடித்துக்கொண்டது.) அதற்கு அவர்கள் கூறினார்கள்: 'அல்லாஹ் அவர்கள் மீது இடியையும் கடுமையான வெப்பத்தையும் அனுப்பினான். அது அவர்களைப் பெரிதும் அச்சமூட்டியதால் அவர்கள் தங்கள் வீடுகளுக்குள் புகுந்தனர். ஆனால் அந்த வெப்பம் வீடுகளின் உட்பகுதி வரை அவர்களைத் துரத்திச் சென்று அச்சுறுத்தியது. உடனே அவர்கள் வீடுகளிலிருந்து திறந்தவெளிகளுக்குத் தப்பி ஓடினர். அப்போது அல்லாஹ் ஒரு மேகத்தை அனுப்பி அவர்களுக்கு நிழல் தந்தான். அவர்கள் அதைக் குளிர்ச்சியாகவும் இதமாகவும் உணர்ந்தனர். எனவே ஒருவரையொருவர் அழைத்து அனைவரும் அந்த மேகத்தின் கீழ் ஒன்றுதிரண்டனர். அப்போது அல்லாஹ் அவர்கள் மீது நெருப்பைப் பொழியச் செய்தான்.' 'அதுவே நிழல் தரும் மேக நாளின் வேதனை; நிச்சயமாக அது ஒரு மகத்தான நாளின் வேதனையாக இருந்தது' என்று இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்.\" <span class=\"quran-arabic-font text-success\">﴾إِنَّ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">ذَلِكَ</span> <span class=\"quran-arabic-font text-success\">لَآيَةً</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">أَكْثَرُهُمْ</span> <span class=\"quran-arabic-font text-success\">مُّؤْمِنِينَ</span> - <span class=\"quran-arabic-font text-success\">وَإِنَّ</span> <span class=\"quran-arabic-font text-success\">رَبَّكَ</span> <span class=\"quran-arabic-font text-success\">لَهُوَ</span> <span class=\"quran-arabic-font text-success\">الْعَزِيزُ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمُ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(நிச்சயமாக இதில் ஓர் அத்தாட்சி இருக்கிறது; எனினும் அவர்களில் பெரும்பாலோர் நம்பிக்கை கொள்வதில்லை. நிச்சயமாக உமது இறைவன், அவன்தான் மிகைத்தவன், மகா கருணையாளன்.) <a href=\"qurandisp.php?sura=26&ayah=190\" class=\"link\">26:190</a>-191. அதாவது, நிராகரிப்பாளர்களைத் தண்டிப்பதில் அவன் மிகைத்தவன்; நம்பிக்கை கொண்ட அடியார்களுக்கு அவன் மகா கருணையாளன்.<br />\r\n<br />","text":"ஷுஐப் (அலை) அவர்களின் சமூகத்தாரின் பதில், அவர்களின் நிராகரிப்பு மற்றும் அவர்கள் மீது வேதனை இறங்கியது\n\r\n\n\r\nதன் தூதருக்கு ஸமூத் சமூகத்தினர் அளித்த பதிலைப் போலவே ஷுஐப் (அலை) அவர்களின் சமூகத்தாரும் பதிலளித்தார்கள் என அல்லாஹ் கூறுகிறான் - ஏனெனில் அவர்கள் ஒரே மாதிரியான சிந்தனை கொண்டவர்களாக இருந்தனர். அவர்கள் கூறினார்கள்: ﴾إِنَّمَآ أَنتَ مِنَ الْمُسَحَّرِينَ﴿\n\r\n\n\r\n\"நீர் சூனியம் செய்யப்பட்டவர்களில் ஒருவரே அன்றி வேறில்லை!\" அதாவது, \"நீர் சூனியத்தால் பாதிக்கப்பட்டவர்களில் ஒருவர்\" (என்று அவர்கள் கருதினர்). ﴾وَمَآ أَنتَ إِلاَّ بَشَرٌ مِّثْلُنَا وَإِن نَّظُنُّكَ لَمِنَ الْكَـذِبِينَ ﴿\n\r\n\n\r\n(நீர் எங்களைப் போன்ற ஒரு மனிதரே அன்றி வேறில்லை. நிச்சயமாக, நீர் பொய்யர்களில் ஒருவரென்றே நாங்கள் கருதுகிறோம்!) அதாவது, \"நீர் எங்களிடம் வேண்டுமென்றே பொய் சொல்கிறீர் என்றும், அல்லாஹ் உம்மைத் தூதராக அனுப்பவில்லை என்றும் நாங்கள் கருதுகிறோம்\" (என்று அவர்கள் கூறினார்கள்). ﴾فَأَسْقِطْ عَلَيْنَا كِسَفاً مِّنَ السَّمَآءِ﴿\n\r\n\n\r\n(ஆகவே, வானத்தின் ஒரு துண்டை எங்கள் மீது விழச்செய்யும்!) \"வானத்தின் ஒரு பகுதி\" என்று அத்-தஹ்ஹாக் (ரழி) அவர்களும், \"வானத்திலிருந்து ஒரு துண்டு\" என்று கதாதா (ரழி) அவர்களும், \"வானத்திலிருந்து ஒரு தண்டனை\" என்று அஸ்-ஸுத்தீ (ரழி) அவர்களும் விளக்கம் அளித்துள்ளனர். இது குறைஷிகள் கூறியதைப் போன்றதே ஆகும்; அதனை அல்லாஹ் இவ்வாறு குறிப்பிடுகிறான்: ﴾وَقَالُواْ لَن نُّؤْمِنَ لَكَ حَتَّى تَفْجُرَ لَنَا مِنَ الاٌّرْضِ يَنْبُوعًا ﴿\n\r\n\n\r\n(அவர்கள் கூறுகிறார்கள்: \"நீர் எங்களுக்காகப் பூமியிலிருந்து ஒரு நீரூற்றை ஓடச் செய்யும் வரை நாங்கள் உம்மை நம்ப மாட்டோம்\") என்பது முதல்: ﴾أَوْ تُسْقِطَ السَّمَآءَ كَمَا زَعَمْتَ عَلَيْنَا كِسَفًا أَوْ تَأْتِىَ بِاللَّهِ وَالْمَلَـئِكَةِ قَبِيلاً ﴿\n\r\n\n\r\n(\"அல்லது நீர் வாதிடுவது போல் வானத்தைத் துண்டு துண்டாக எங்கள் மீது விழச் செய்ய வேண்டும், அல்லது அல்லாஹ்வையும் வானவர்களையும் எங்கள் முன்னே நேருக்கு நேராகக் கொண்டு வர வேண்டும்.\") (17:90-92) ﴾وَإِذْ قَالُواْ اللَّهُمَّ إِن كَانَ هَـذَا هُوَ الْحَقَّ مِنْ عِندِكَ فَأَمْطِرْ عَلَيْنَا حِجَارَةً مِّنَ السَّمَآءِ﴿\n\r\n\n\r\n(\"மேலும், அவர்கள்: 'யா அல்லாஹ்! இது உன்னிடமிருந்து வந்த உண்மையாக இருந்தால், எங்கள் மீது வானத்திலிருந்து கல் மழையைப் பொழியச் செய்...' என்று கூறியதை நினைவுகூருங்கள்\") (8:32). இதேபோல், இந்த அறிவற்ற நிராகரிப்பாளர்களும் கூறினார்கள்: ﴾فَأَسْقِطْ عَلَيْنَا كِسَفاً مِّنَ السَّمَآءِ إِن كُنتَ مِنَ الصَّـدِقِينَ﴿\n\r\n\n\r\n(நீர் உண்மையாளராக இருந்தால், வானத்திலிருந்து ஒரு துண்டை எங்கள் மீது விழச்செய்யும்!) ﴾قَالَ رَبِّى أَعْلَمُ بِمَا تَعْمَلُونَ ﴿\n\r\n\n\r\n(அதற்கு அவர்: \"நீங்கள் செய்பவற்றை என் இறைவன் நன்கு அறிந்தவன்\" என்று கூறினார்கள்.) அதாவது, \"அல்லாஹ் உங்களைப் பற்றி நன்கு அறிந்தவன்; நீங்கள் தண்டனைக்குத் தகுதியானவர்களாக இருந்தால், அவன் அதைக் கொண்டு உங்களைத் தண்டிப்பான்; அவன் உங்களுக்கு அநீதி இழைக்க மாட்டான்\" என்பதாகும். அவர்கள் வேண்டியபடியே, அவர்களுக்குச் சரியான பிரதிபலனாக அந்தத் தண்டனை நிகழ்ந்தது. அல்லாஹ் கூறுகிறான்: ﴾فَكَذَّبُوهُ فَأَخَذَهُمْ عَذَابُ يَوْمِ الظُّلَّةِ إِنَّهُ كَانَ عَذَابَ يَوْمٍ عَظِيمٍ ﴿\n\r\n\n\r\n(ஆனால் அவர்கள் அவரைப் பொய்யாக்கினார்கள், அதனால் 'நிழல் தரும் மேக' நாளின் வேதனை அவர்களைப் பிடித்துக்கொண்டது. நிச்சயமாக அது ஒரு மகத்தான நாளின் வேதனையாக இருந்தது.) வானத்திலிருந்து ஒரு துண்டு விழ வேண்டும் என்று அவர்கள் கேட்டதற்கு இணங்கவே இது அமைந்தது. அல்லாஹ் அவர்களுக்கு ஏழு நாட்கள் நீடித்த கடுமையான வெப்பத்தைத் தண்டனையாக அளித்தான்; அதிலிருந்து எதனாலும் அவர்களைப் பாதுகாக்க முடியவில்லை. பிறகு, அவர்களுக்கு நிழல் தருவதற்காக ஒரு மேகத்தை அல்லாஹ் அனுப்பினான்; வெப்பத்தைத் தணிக்க அந்த நிழலை நோக்கி அவர்கள் ஓடினார்கள். அவர்கள் அனைவரும் அதன் கீழ் திரண்டபோது, அல்லாஹ் அவர்கள் மீது நெருப்புப் பொறிகளையும், தீப்பிழம்புகளையும், கடுமையான வெப்பத்தையும் இறக்கினான். பூமி அவர்களைக் கீழ்நோக்கி உலுக்கியது; மேலும் அவர்களை அழிக்கும் வகையில் ஒரு பெரும் 'ஸைஹா' (பேரொலி) அவர்கள் மீது ஏவப்பட்டது. அல்லாஹ் கூறுகிறான்: ﴾إِنَّهُ كَانَ عَذَابَ يَوْمٍ عَظِيمٍ﴿\n\r\n\n\r\n(நிச்சயமாக அது ஒரு மகத்தான நாளின் வேதனையாக இருந்தது.) அவர்கள் எவ்வாறு அழிக்கப்பட்டார்கள் என்பதை அல்லாஹ் குர்ஆனின் மூன்று இடங்களில் விவரித்துள்ளான். ஒவ்வொன்றும் அந்தந்தச் சூழலுக்குப் பொருத்தமான முறையில் விவரிக்கப்பட்டுள்ளது. சூரா அல்-அஃராஃபில், நிலநடுக்கம் அவர்களைப் பிடித்துக்கொண்டது என்றும், அவர்கள் தங்கள் வீடுகளில் (இறந்து) கவிழ்ந்து கிடந்தார்கள் என்றும் கூறுகிறான். இதற்குக் காரணம் அவர்கள் இவ்வாறு கூறியதே ஆகும்: ﴾لَنُخْرِجَنَّكَ يَا شُعَيْبُ وَالَّذِينَ ءَامَنُواْ مَعَكَ مِن قَرْيَتِنَآ أَوْ لَتَعُودُنَّ فِي مِلَّتِنَا﴿\n\r\n\n\r\n(\"ஷுஐபே! உம்மையும் உம்முடன் ஈமான் கொண்டவர்களையும் எங்கள் ஊரிலிருந்து நிச்சயமாக நாங்கள் வெளியேற்றுவோம்; அல்லது நீங்கள் அனைவரும் எங்கள் மார்க்கத்திற்குத் திரும்பிவிட வேண்டும்.\") (7:88). அவர்கள் அல்லாஹ்வின் தூதரையும் விசுவாசிகளையும் பயமுறுத்த முயன்றதால், அவர்கள் நிலநடுக்கத்தால் பிடிக்கப்பட்டனர். சூரா ஹூதில், அல்லாஹ் கூறுகிறான்: ﴾وَأَخَذَتِ الَّذِينَ ظَلَمُواْ الصَّيْحَةُ﴿\n\r\n\n\r\n(அநீதி இழைத்தவர்களைப் பேரொலி பிடித்துக்கொண்டது) (11:94). அவர்கள் அல்லாஹ்வின் தூதரை இவ்வாறு ஏளனம் செய்ததே இதற்குக் காரணமாகும்: ﴾أَصَلَوَتُكَ تَأْمُرُكَ أَن نَّتْرُكَ مَا يَعْبُدُ ءابَاؤُنَآ أَوْ أَن نَّفْعَلَ فِى أَمْوَالِنَا مَا نَشَاءُ إِنَّكَ لَأَنتَ الْحَلِيمُ الرَّشِيدُ﴿\n\r\n\n\r\n(\"எங்கள் முன்னோர்கள் வணங்கியவற்றை நாங்கள் விட்டுவிட வேண்டும் என்றோ, அல்லது எங்கள் சொத்துக்களை நாங்கள் விரும்பியபடி செலவிடுவதைத் தடுத்துவிட வேண்டும் என்றோ உமது தொழுகையா உமக்குக் கட்டளையிடுகிறது? நிச்சயமாக நீர் மிகுந்த சகிப்புத்தன்மை உடையவர், நேர்வழி நடப்பவர்!\") (11:87). அவர்கள் இதனை ஏளனமாகவும் கிண்டலாகவும் கூறியதால், 'ஸைஹா' (பேரொலி) வந்து அவர்களை மௌனமாக்கியது பொருத்தமானதாக இருந்தது. அல்லாஹ் கூறுகிறான்: ﴾فَأَخَذَتْهُمُ الصَّيْحَةُ﴿\n\r\n\n\r\n(ஆகவே, அந்தப் பேரொலி அவர்களைப் பிடித்துக்கொண்டது) (15:73). ﴾وَأَخَذَتِ الَّذِينَ ظَلَمُواْ الصَّيْحَةُ﴿\n\r\n\n\r\n(அநீதி இழைத்தவர்களைப் பேரொலி பிடித்துக்கொண்டது) (11:94). இங்கு அவர்கள் பிடிவாதமாகவும் முரட்டுத்தனமாகவும்: ﴾فَأَسْقِطْ عَلَيْنَا كِسَفاً مِّنَ السَّمَآءِ﴿\n\r\n\n\r\n(வானத்திலிருந்து ஒரு துண்டை எங்கள் மீது விழச்செய்யும்!) என்று கூறினார்கள். எனவே, அவர்கள் ஒருபோதும் நிகழாது என்று கருதிய ஒன்று அவர்களுக்குச் சம்பவித்தது பொருத்தமாக அமைந்தது: ﴾فَأَخَذَهُمْ عَذَابُ يَوْمِ الظُّلَّةِ إِنَّهُ كَانَ عَذَابَ يَوْمٍ عَظِيمٍ﴿\n\r\n\n\r\n(அதனால் நிழல் தரும் மேக நாளின் வேதனை அவர்களைப் பிடித்துக்கொண்டது. நிச்சயமாக அது ஒரு மகத்தான நாளின் வேதனையாக இருந்தது.) முஹம்மத் பின் ஜரீர் அவர்கள், யஸீத் அல்-பாஹிலீ அவர்களிடமிருந்து அறிவிக்கிறார்கள்: \"நான் இப்னு அப்பாஸ் (ரழி) அவர்களிடம் இந்த வசனத்தைப் பற்றிக் கேட்டேன்: ﴾فَأَخَذَهُمْ عَذَابُ يَوْمِ الظُّلَّةِ﴿\n\r\n\n\r\n(அதனால் நிழல் தரும் மேக நாளின் வேதனை அவர்களைப் பிடித்துக்கொண்டது.) அதற்கு அவர்கள் கூறினார்கள்: 'அல்லாஹ் அவர்கள் மீது இடியையும் கடுமையான வெப்பத்தையும் அனுப்பினான். அது அவர்களைப் பெரிதும் அச்சமூட்டியதால் அவர்கள் தங்கள் வீடுகளுக்குள் புகுந்தனர். ஆனால் அந்த வெப்பம் வீடுகளின் உட்பகுதி வரை அவர்களைத் துரத்திச் சென்று அச்சுறுத்தியது. உடனே அவர்கள் வீடுகளிலிருந்து திறந்தவெளிகளுக்குத் தப்பி ஓடினர். அப்போது அல்லாஹ் ஒரு மேகத்தை அனுப்பி அவர்களுக்கு நிழல் தந்தான். அவர்கள் அதைக் குளிர்ச்சியாகவும் இதமாகவும் உணர்ந்தனர். எனவே ஒருவரையொருவர் அழைத்து அனைவரும் அந்த மேகத்தின் கீழ் ஒன்றுதிரண்டனர். அப்போது அல்லாஹ் அவர்கள் மீது நெருப்பைப் பொழியச் செய்தான்.' 'அதுவே நிழல் தரும் மேக நாளின் வேதனை; நிச்சயமாக அது ஒரு மகத்தான நாளின் வேதனையாக இருந்தது' என்று இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்.\" ﴾إِنَّ فِي ذَلِكَ لَآيَةً وَمَا كَانَ أَكْثَرُهُمْ مُّؤْمِنِينَ - وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ ﴿\n\r\n\n\r\n(நிச்சயமாக இதில் ஓர் அத்தாட்சி இருக்கிறது; எனினும் அவர்களில் பெரும்பாலோர் நம்பிக்கை கொள்வதில்லை. நிச்சயமாக உமது இறைவன், அவன்தான் மிகைத்தவன், மகா கருணையாளன்.) 26:190-191. அதாவது, நிராகரிப்பாளர்களைத் தண்டிப்பதில் அவன் மிகைத்தவன்; நம்பிக்கை கொண்ட அடியார்களுக்கு அவன் மகா கருணையாளன்."},"192":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=195\" class=\"link\">26:195</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:195 ஐ பார்க்கவும்"},"193":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=195\" class=\"link\">26:195</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:195 ஐ பார்க்கவும்"},"194":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=195\" class=\"link\">26:195</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:195 ஐ பார்க்கவும்"},"195":{"html":"<strong>குர்ஆன் அல்லாஹ்வால் அருளப்பட்டது</strong><br />\r\n<br />\r\nஇங்கே அல்லாஹ், தனது அடியாரும் தூதருமான முஹம்மது (ஸல்) அவர்களுக்கு அவன் அருளிய வேதத்தைப் பற்றி நமக்குக் கூறுகிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِنَّهُ</span><br />\r\n<br />\r\n(நிச்சயமாக இது) என்பது குர்ஆனைக் குறிக்கிறது. இந்தச் சூராவின் தொடக்கத்தில் அது இவ்வாறு விவரிக்கப்பட்டுள்ளது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يَأْتِيهِم</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">ذِكْرٍ</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">الرَّحْمَنِ</span> <span class=\"quran-arabic-font text-success\">مُحْدَثٍ</span><br />\r\n<br />\r\n(அளவற்ற அருளாளனிடமிருந்து ஒரு புதிய வஹீ (இறைச்செய்தி)யாக அவர்களிடம் ஒரு நினைவூட்டல் வரும்போதெல்லாம்...) (<a href=\"qurandisp.php?sura=26&ayah=5\" class=\"link\">26:5</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَتَنزِيلُ</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span> <span class=\"quran-arabic-font text-success\">الْعَالَمِينَ</span><br />\r\n<br />\r\n(இது அகிலங்களின் இறைவனிடமிருந்து அருளப்பட்ட வஹீ (இறைச்செய்தி) ஆகும்.) இதன் பொருள், அல்லாஹ் இதனை உங்களுக்கு இறக்கிவைத்து, இதனை உங்களுக்கு வஹீயாக அறிவித்தான் என்பதாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">نَزَلَ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">الرُّوحُ</span> <span class=\"quran-arabic-font text-success\">الْأَمِينُ</span><br />\r\n<br />\r\n(நம்பிக்கைக்குரிய ரூஹ் அதனைக் கொண்டு இறங்கினார்.) இது ஜிப்ரீல் (அலை) அவர்களைக் குறிக்கிறது. இப்னு அப்பாஸ் (ரழி), முஹம்மது பின் கஅப், கதாதா, அதிய்யா அல்-அவ்ஃபீ, அஸ்-ஸுத்தீ, அத்-தஹ்ஹாக், அஸ்-ஸுஹ்ரீ மற்றும் இப்னு ஜுரைஜ் போன்ற ஒன்றுக்கும் மேற்பட்ட ஸலஃபுகள் (முன்னோர்கள்) இவ்வாறு கருதுகின்றனர். இதில் எந்தக் கருத்து வேறுபாடும் இல்லை. அஸ்-ஸுஹ்ரீ அவர்கள் கூறினார்கள்: \"இது பின்வரும் வசனத்தைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">قُلْ</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">عَدُوًّا</span> <span class=\"quran-arabic-font text-success\">لِّجِبْرِيلَ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">نَزَّلَهُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">قَلْبِكَ</span> <span class=\"quran-arabic-font text-success\">بِإِذْنِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">مُصَدِّقًا</span> <span class=\"quran-arabic-font text-success\">لِّمَا</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">يَدَيْهِ</span><br />\r\n<br />\r\n(கூறுவீராக: \"யார் ஜிப்ரீலுக்கு விரோதியாக இருக்கிறாரோ — நிச்சயமாக அவர் அல்லாஹ்வின் அனுமதியுடன், அதற்கு முன் வந்ததை உறுதிப்படுத்தும் விதமாக, அதனை உமது உள்ளத்தில் இறக்கிவைத்தார்...\") (<a href=\"qurandisp.php?sura=2&ayah=97\" class=\"link\">2:97</a>).<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">قَلْبِكَ</span><br />\r\n<br />\r\n(உமது உள்ளத்தின் மீது) 'முஹம்மதே! எந்தவொரு கலப்படமுமின்றி, எதுவும் கூட்டப்படாமலும் குறைக்கப்படாமலும் (இது உமது உள்ளத்தில் இறக்கப்பட்டது).'<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِتَكُونَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُنْذِرِينَ</span><br />\r\n<br />\r\n(நீர் எச்சரிக்கை செய்பவர்களில் ஒருவராக இருப்பதற்காக) இதன் பொருள், ‘இதற்கு மாறுசெய்து இதனை நிராகரிப்பவர்களுக்கு அல்லாஹ்வின் தண்டனையைக் கொண்டு நீர் எச்சரிக்கை செய்வதற்காகவும், இதனைப் பின்பற்றும் நம்பிக்கையாளர்களுக்கு இதன் மூலம் நற்செய்தி கூறுவதற்காகவும் (இது அருளப்பட்டது).’<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">بِلِسَانٍ</span> <span class=\"quran-arabic-font text-success\">عَرَبِيٍّ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٍ</span><br />\r\n<br />\r\n(தெளிவான அரபு மொழியில்.) அதாவது, ‘நாம் உமக்கு வஹீயாக அருளிய இந்த குர்ஆனை, அது மிகத் தெளிவாக இருப்பதற்காகவும், சாக்குப்போக்குகளுக்கு இடமளிக்காமல் தெளிவான ஆதாரத்தை நிலைநாட்டி, நேர்வழியைக் காண்பிப்பதற்காகவும், மிகச் சரியான மற்றும் இலக்கிய நயமிக்க அரபு மொழியில் நாம் அருளினோம்.’<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَفِي</span> <span class=\"quran-arabic-font text-success\">زُبُرِ</span> <span class=\"quran-arabic-font text-success\">الْأَوَّلِينَ</span> - <span class=\"quran-arabic-font text-success\">أَوَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَكُن</span> <span class=\"quran-arabic-font text-success\">لَّهُمْ</span> <span class=\"quran-arabic-font text-success\">آيَةً</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَعْلَمَهُ</span> <span class=\"quran-arabic-font text-success\">عُلَمَاءُ</span> <span class=\"quran-arabic-font text-success\">بَنِي</span> <span class=\"quran-arabic-font text-success\">إِسْرَائِيلَ</span> - <span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">نَزَّلْنَاهُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">بَعْضِ</span> <span class=\"quran-arabic-font text-success\">الْأَعْجَمِينَ</span><br />\r\n<br />","text":"குர்ஆன் அல்லாஹ்வால் அருளப்பட்டது\n\r\n\n\r\nஇங்கே அல்லாஹ், தனது அடியாரும் தூதருமான முஹம்மது (ஸல்) அவர்களுக்கு அவன் அருளிய வேதத்தைப் பற்றி நமக்குக் கூறுகிறான்.\n\r\n\n\r\nوَإِنَّهُ\n\r\n\n\r\n(நிச்சயமாக இது) என்பது குர்ஆனைக் குறிக்கிறது. இந்தச் சூராவின் தொடக்கத்தில் அது இவ்வாறு விவரிக்கப்பட்டுள்ளது:\n\r\n\n\r\nوَمَا يَأْتِيهِم مِّن ذِكْرٍ مِّنَ الرَّحْمَنِ مُحْدَثٍ\n\r\n\n\r\n(அளவற்ற அருளாளனிடமிருந்து ஒரு புதிய வஹீ (இறைச்செய்தி)யாக அவர்களிடம் ஒரு நினைவூட்டல் வரும்போதெல்லாம்...) (26:5).\n\r\n\n\r\nلَتَنزِيلُ رَبِّ الْعَالَمِينَ\n\r\n\n\r\n(இது அகிலங்களின் இறைவனிடமிருந்து அருளப்பட்ட வஹீ (இறைச்செய்தி) ஆகும்.) இதன் பொருள், அல்லாஹ் இதனை உங்களுக்கு இறக்கிவைத்து, இதனை உங்களுக்கு வஹீயாக அறிவித்தான் என்பதாகும்.\n\r\n\n\r\nنَزَلَ بِهِ الرُّوحُ الْأَمِينُ\n\r\n\n\r\n(நம்பிக்கைக்குரிய ரூஹ் அதனைக் கொண்டு இறங்கினார்.) இது ஜிப்ரீல் (அலை) அவர்களைக் குறிக்கிறது. இப்னு அப்பாஸ் (ரழி), முஹம்மது பின் கஅப், கதாதா, அதிய்யா அல்-அவ்ஃபீ, அஸ்-ஸுத்தீ, அத்-தஹ்ஹாக், அஸ்-ஸுஹ்ரீ மற்றும் இப்னு ஜுரைஜ் போன்ற ஒன்றுக்கும் மேற்பட்ட ஸலஃபுகள் (முன்னோர்கள்) இவ்வாறு கருதுகின்றனர். இதில் எந்தக் கருத்து வேறுபாடும் இல்லை. அஸ்-ஸுஹ்ரீ அவர்கள் கூறினார்கள்: \"இது பின்வரும் வசனத்தைப் போன்றதாகும்:\n\r\n\n\r\nقُلْ مَن كَانَ عَدُوًّا لِّجِبْرِيلَ فَإِنَّهُ نَزَّلَهُ عَلَى قَلْبِكَ بِإِذْنِ اللَّهِ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ\n\r\n\n\r\n(கூறுவீராக: \"யார் ஜிப்ரீலுக்கு விரோதியாக இருக்கிறாரோ — நிச்சயமாக அவர் அல்லாஹ்வின் அனுமதியுடன், அதற்கு முன் வந்ததை உறுதிப்படுத்தும் விதமாக, அதனை உமது உள்ளத்தில் இறக்கிவைத்தார்...\") (2:97).\n\r\n\n\r\nعَلَى قَلْبِكَ\n\r\n\n\r\n(உமது உள்ளத்தின் மீது) 'முஹம்மதே! எந்தவொரு கலப்படமுமின்றி, எதுவும் கூட்டப்படாமலும் குறைக்கப்படாமலும் (இது உமது உள்ளத்தில் இறக்கப்பட்டது).'\n\r\n\n\r\nلِتَكُونَ مِنَ الْمُنْذِرِينَ\n\r\n\n\r\n(நீர் எச்சரிக்கை செய்பவர்களில் ஒருவராக இருப்பதற்காக) இதன் பொருள், ‘இதற்கு மாறுசெய்து இதனை நிராகரிப்பவர்களுக்கு அல்லாஹ்வின் தண்டனையைக் கொண்டு நீர் எச்சரிக்கை செய்வதற்காகவும், இதனைப் பின்பற்றும் நம்பிக்கையாளர்களுக்கு இதன் மூலம் நற்செய்தி கூறுவதற்காகவும் (இது அருளப்பட்டது).’\n\r\n\n\r\nبِلِسَانٍ عَرَبِيٍّ مُّبِينٍ\n\r\n\n\r\n(தெளிவான அரபு மொழியில்.) அதாவது, ‘நாம் உமக்கு வஹீயாக அருளிய இந்த குர்ஆனை, அது மிகத் தெளிவாக இருப்பதற்காகவும், சாக்குப்போக்குகளுக்கு இடமளிக்காமல் தெளிவான ஆதாரத்தை நிலைநாட்டி, நேர்வழியைக் காண்பிப்பதற்காகவும், மிகச் சரியான மற்றும் இலக்கிய நயமிக்க அரபு மொழியில் நாம் அருளினோம்.’\n\r\n\n\r\nوَإِنَّهُ لَفِي زُبُرِ الْأَوَّلِينَ - أَوَلَمْ يَكُن لَّهُمْ آيَةً أَن يَعْلَمَهُ عُلَمَاءُ بَنِي إِسْرَائِيلَ - وَلَوْ نَزَّلْنَاهُ عَلَى بَعْضِ الْأَعْجَمِينَ"},"196":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=199\" class=\"link\">26:199</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:199 ஐ பார்க்கவும்"},"197":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=199\" class=\"link\">26:199</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:199 ஐ பார்க்கவும்"},"198":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=199\" class=\"link\">26:199</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:199 ஐ பார்க்கவும்"},"199":{"html":"<strong>முந்தைய வேதங்களில் குர்ஆனைப் பற்றிய குறிப்புகள்</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்: இக்குர்ஆன், தங்களுக்கு முந்தைய காலத்திலும் அண்மைக் காலத்திலும் வாழ்ந்த நபிமார்கள் விட்டுச் சென்ற முந்தைய வேதங்களில் குறிப்பிடப்பட்டுள்ளது. அந்த நபிமார்கள் இதனைப் பற்றி முன்னறிவிப்புச் செய்திருந்தார்கள். அவர்கள் இதனைப் பின்பற்ற வேண்டும் என்று அல்லாஹ் அவர்களிடம் ஒரு உடன்படிக்கையை வாங்கினான். மேலும் அவர்களில் இறுதியானவர் (ஈஸா (அலை)) எழுந்து நின்று, அஹ்மது எனும் பெயருடைய தூதரைப் பற்றிய நற்செய்தியுடன் தனது சமூகத்தாரிடம் உரையாற்றினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَإِذْ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">عِيسَى</span> <span class=\"quran-arabic-font text-success\">ابْنُ</span> <span class=\"quran-arabic-font text-success\">مَرْيَمَ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">بَنِي</span> <span class=\"quran-arabic-font text-success\">إِسْرَائِيلَ</span> <span class=\"quran-arabic-font text-success\">إِنِّي</span> <span class=\"quran-arabic-font text-success\">رَسُولُ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span> <span class=\"quran-arabic-font text-success\">إِلَيْكُم</span> <span class=\"quran-arabic-font text-success\">مُّصَدِّقاً</span> <span class=\"quran-arabic-font text-success\">لِّمَا</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">يَدَيَّ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">التَّوْرَاةِ</span> <span class=\"quran-arabic-font text-success\">وَمُبَشِّراً</span> <span class=\"quran-arabic-font text-success\">بِرَسُولٍ</span> <span class=\"quran-arabic-font text-success\">يَأْتِي</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِي</span> <span class=\"quran-arabic-font text-success\">اسْمُهُ</span> <span class=\"quran-arabic-font text-success\">أَحْمَدُ</span><br />\r\n<br />\r\n(மர்யமின் மகன் ஈஸா (அலை) அவர்கள், “இஸ்ரவேல் மக்களே! எனக்கு முன்புள்ள தவ்ராத்தை மெய்ப்பிப்பவனாகவும், எனக்குப் பின் வரவிருக்கும் அஹ்மது என்ற பெயருடைய ஒரு தூதரைப் பற்றி நற்செய்தி கூறுபவனாகவும் உங்களிடம் வந்துள்ள அல்லாஹ்வின் தூதர் நான்” என்று கூறியதை (நினைவு கூருங்கள்).) (<a href=\"qurandisp.php?sura=61&ayah=6\" class=\"link\">61:6</a>) இங்கு 'ஸுபுர்' என்பது வேதங்களைக் குறிக்கிறது. 'அஸ்-ஸபூர்' என்பதன் பன்மையே 'ஸுபுர்' ஆகும். தாவூத் (அலை) அவர்களுக்கு வழங்கப்பட்ட வேதத்தைக் குறிக்கவும் இந்தப் பெயர் பயன்படுத்தப்படுகிறது. அதாவது, \"நாம் தாவூதுக்கு ஜபூரை வழங்கினோம்\" (<a href=\"qurandisp.php?sura=17&ayah=55\" class=\"link\">17:55</a>) என்று அல்லாஹ் கூறுவதைப் போல. அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَكُلُّ</span> <span class=\"quran-arabic-font text-success\">شَىْءٍ</span> <span class=\"quran-arabic-font text-success\">فَعَلُوهُ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الزُّبُرِ</span><br />\r\n<br />\r\n(அவர்கள் செய்த ஒவ்வொரு காரியமும் அஸ்-ஸுபுரில் (ஏடுகளில்) பதிவு செய்யப்பட்டுள்ளது.) (<a href=\"qurandisp.php?sura=54&ayah=52\" class=\"link\">54:52</a>), அதாவது, அது வானவர்களின் ஏடுகளில் அவர்களுக்கு எதிராகப் பதிவு செய்யப்பட்டுள்ளது. பின்னர் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَوَلَمْ</span> <span class=\"quran-arabic-font text-success\">يَكُن</span> <span class=\"quran-arabic-font text-success\">لَّهُمْ</span> <span class=\"quran-arabic-font text-success\">آيَةً</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يَعْلَمَهُ</span> <span class=\"quran-arabic-font text-success\">عُلَمَاءُ</span> <span class=\"quran-arabic-font text-success\">بَنِي</span> <span class=\"quran-arabic-font text-success\">إِسْرَائِيلَ</span><br />\r\n<br />\r\n(இஸ்ரவேல் மக்களின் அறிஞர்கள் இதை அறிந்திருப்பது அவர்களுக்கு ஓர் அத்தாட்சியாக இல்லையா?) அதாவது, இஸ்ரவேல் மக்களின் அறிஞர்கள் தாங்கள் பயிலும் வேதங்களில் இந்தக் குர்ஆனைப் பற்றிய குறிப்புகளைக் காண்பது, இது உண்மையானது என்பதற்கு அவர்களுக்குப் போதுமான சான்றாக இல்லையா? இதன் பொருள் என்னவெனில்: அவர்களில் நடுநிலையாளர்கள் முஹம்மது (ஸல்) அவர்களின் பண்புகள், அவர்களது தூதுத்துவம் மற்றும் அவர்களது உம்மத்தைப் பற்றிய செய்திகள் தங்கள் வேதங்களில் இடம்பெற்றுள்ளதை ஒப்புக்கொண்டனர். அப்துல்லாஹ் பின் ஸலாம் (ரழி), ஸல்மான் அல்-ஃபாரிஸி (ரழி) மற்றும் நபியவர்களைச் சந்தித்த ஏனைய ஈமான் கொண்டவர்கள் இதனை உறுதிப்படுத்தியுள்ளனர். அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَتَّبِعُونَ</span> <span class=\"quran-arabic-font text-success\">الرَّسُولَ</span> <span class=\"quran-arabic-font text-success\">النَّبِىَّ</span> <span class=\"quran-arabic-font text-success\">الأُمِّىَّ</span><br />\r\n<br />\r\n(எழுதவோ படிக்கவோ தெரியாத அந்தத் தூதரை, நபியைப் பின்பற்றுபவர்கள்...) (<a href=\"qurandisp.php?sura=7&ayah=157\" class=\"link\">7:157</a>)<br />\r\n<br />\r\n<strong>குறைஷிகளின் கடுமையான நிராகரிப்பு</strong><br />\r\n<br />\r\nபின்னர், குறைஷிகளின் நிராகரிப்பு எவ்வளவு தீவிரமானது என்பதையும், அவர்கள் இக்குர்ஆனை எவ்வளவு பிடிவாதமாக எதிர்த்தார்கள் என்பதையும் அல்லாஹ் கூறுகிறான். சொல்லாற்றல் மிக்க இந்த வேதம், அரபி மொழியில் ஒரு வார்த்தை கூடத் தெரியாத ஓர் அரபி அல்லாதவர் மீது அருளப்பட்டிருந்தாலும், அவர்கள் அவரை நம்பியிருக்க மாட்டார்கள். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">نَزَّلْنَاهُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">بَعْضِ</span> <span class=\"quran-arabic-font text-success\">الْأَعْجَمِينَ</span><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَقَرَأَهُ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِم</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">كَانُوا</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">مُؤْمِنِينَ</span><br />\r\n<br />\r\n(இதை நாம் அரபியர் அல்லாத எவர் மீதேனும் இறக்கியிருந்து, அவர் அதை அவர்களுக்கு ஓதிக்காட்டியிருந்தாலும், அவர்கள் அதை நம்பியிருக்க மாட்டார்கள்.) மேலும் அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">فَتَحْنَا</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِم</span> <span class=\"quran-arabic-font text-success\">بَاباً</span> <span class=\"quran-arabic-font text-success\">مِّنَ</span> <span class=\"quran-arabic-font text-success\">السَّمَاءِ</span> <span class=\"quran-arabic-font text-success\">فَظَلُّوا</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span> <span class=\"quran-arabic-font text-success\">يَعْرُجُونَ</span> <span class=\"quran-arabic-font text-success\">لَقَالُوا</span> <span class=\"quran-arabic-font text-success\">إِنَّمَا</span> <span class=\"quran-arabic-font text-success\">سُكِّرَتْ</span> <span class=\"quran-arabic-font text-success\">أَبْصَارُنَا</span><br />\r\n<br />\r\n(நாம் அவர்களுக்கு வானத்திலிருந்து ஒரு வாசலைத் திறந்து, அதன் வழியாக அவர்கள் மேலே ஏறிக்கொண்டிருந்தாலும், அவர்கள் நிச்சயமாக, \"எங்கள் பார்வைகள் மயக்கப்பட்டு விட்டன...\" என்றே கூறுவார்கள்.) (<a href=\"qurandisp.php?sura=15&ayah=14\" class=\"link\">15:14</a>-15)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَلَوْ</span> <span class=\"quran-arabic-font text-success\">أَنَّنَا</span> <span class=\"quran-arabic-font text-success\">نَزَّلْنَا</span> <span class=\"quran-arabic-font text-success\">إِلَيْهِمُ</span> <span class=\"quran-arabic-font text-success\">الْمَلَائِكَةَ</span> <span class=\"quran-arabic-font text-success\">وَكَلَّمَهُمُ</span> <span class=\"quran-arabic-font text-success\">الْمَوْتَى</span><br />\r\n<br />\r\n(நாம் அவர்களிடம் வானவர்களை இறக்கியிருந்தாலும், இறந்தவர்கள் அவர்களிடம் பேசியிருந்தாலும்...) (<a href=\"qurandisp.php?sura=6&ayah=111\" class=\"link\">6:111</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">حَقَّتْ</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">كَلِمَةُ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُونَ</span><br />\r\n<br />\r\n(நிச்சயமாக, எவர்கள் மீது உமது இறைவனின் வாக்கு உறுதியாகிவிட்டதோ, அவர்கள் நம்பிக்கை கொள்ள மாட்டார்கள்.) (<a href=\"qurandisp.php?sura=10&ayah=96\" class=\"link\">10:96</a>)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">كَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">سَلَكْنَاهُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">قُلُوبِ</span> <span class=\"quran-arabic-font text-success\">الْمُجْرِمِينَ</span> - <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُونَ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">يَرَوُا</span> <span class=\"quran-arabic-font text-success\">الْعَذَابَ</span> <span class=\"quran-arabic-font text-success\">الْأَلِيمَ</span> - <span class=\"quran-arabic-font text-success\">فَيَأْتِيَهُم</span> <span class=\"quran-arabic-font text-success\">بَغْتَةً</span> <span class=\"quran-arabic-font text-success\">وَهُمْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَشْعُرُونَ</span> - <span class=\"quran-arabic-font text-success\">فَيَقُولُوا</span> <span class=\"quran-arabic-font text-success\">هَلْ</span> <span class=\"quran-arabic-font text-success\">نَحْنُ</span> <span class=\"quran-arabic-font text-success\">مُنظَرُونَ</span> - <span class=\"quran-arabic-font text-success\">أَفَبِعَذَابِنَا</span> <span class=\"quran-arabic-font text-success\">يَسْتَعْجِلُونَ</span> - <span class=\"quran-arabic-font text-success\">أَفَرَأَيْتَ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">مَّتَّعْنَاهُمْ</span> <span class=\"quran-arabic-font text-success\">سِنِينَ</span> - <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">جَاءَهُم</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">كَانُوا</span> <span class=\"quran-arabic-font text-success\">يُوعَدُونَ</span> - <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">أَغْنَى</span> <span class=\"quran-arabic-font text-success\">عَنْهُمْ</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">كَانُوا</span> <span class=\"quran-arabic-font text-success\">يُمَتَّعُونَ</span> - <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">أَهْلَكْنَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَرْيَةٍ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">لَهَا</span> <span class=\"quran-arabic-font text-success\">مُنذِرُونَ</span><br />\r\n<br />\r\n(இவ்வாறே குற்றவாளிகளின் உள்ளங்களில் நாம் இதனை நுழையச் செய்தோம். துயருறுத்தும் வேதனையை அவர்கள் காணாத வரையில் அவர்கள் இதனை நம்பிக்கை கொள்ள மாட்டார்கள். அவர்கள் அறியாத விதத்தில் திடீரென அது அவர்களிடம் வரும். அப்போது அவர்கள், “எங்களுக்குச் சற்றே அவகாசம் அளிக்கப்படுமா?” என்று கேட்பார்கள். நமது வேதனையை (வரவழைக்க) அவர்கள் அவசரப்படுகிறார்களா? (நபியே!) நீர் கவனித்தீரா? நாம் அவர்களைப் பல ஆண்டுகள் சுகபோகங்களை அனுபவிக்கச் செய்து, பின்னர் அவர்களுக்கு வாக்களிக்கப்பட்ட (வேதனை) அவர்களிடம் வந்தால், அவர்கள் அனுபவித்துக் கொண்டிருந்த சுகபோகங்கள் அவர்களுக்குப் பயனளிக்காது. எச்சரிக்கை செய்பவர்கள் இல்லாமல் எந்த ஊரையும் நாம் அழித்ததில்லை.)<br />\r\n<br />","text":"முந்தைய வேதங்களில் குர்ஆனைப் பற்றிய குறிப்புகள்\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்: இக்குர்ஆன், தங்களுக்கு முந்தைய காலத்திலும் அண்மைக் காலத்திலும் வாழ்ந்த நபிமார்கள் விட்டுச் சென்ற முந்தைய வேதங்களில் குறிப்பிடப்பட்டுள்ளது. அந்த நபிமார்கள் இதனைப் பற்றி முன்னறிவிப்புச் செய்திருந்தார்கள். அவர்கள் இதனைப் பின்பற்ற வேண்டும் என்று அல்லாஹ் அவர்களிடம் ஒரு உடன்படிக்கையை வாங்கினான். மேலும் அவர்களில் இறுதியானவர் (ஈஸா (அலை)) எழுந்து நின்று, அஹ்மது எனும் பெயருடைய தூதரைப் பற்றிய நற்செய்தியுடன் தனது சமூகத்தாரிடம் உரையாற்றினார்கள்:\n\r\n\n\r\nوَإِذْ قَالَ عِيسَى ابْنُ مَرْيَمَ يَا بَنِي إِسْرَائِيلَ إِنِّي رَسُولُ اللَّهِ إِلَيْكُم مُّصَدِّقاً لِّمَا بَيْنَ يَدَيَّ مِنَ التَّوْرَاةِ وَمُبَشِّراً بِرَسُولٍ يَأْتِي مِن بَعْدِي اسْمُهُ أَحْمَدُ\n\r\n\n\r\n(மர்யமின் மகன் ஈஸா (அலை) அவர்கள், “இஸ்ரவேல் மக்களே! எனக்கு முன்புள்ள தவ்ராத்தை மெய்ப்பிப்பவனாகவும், எனக்குப் பின் வரவிருக்கும் அஹ்மது என்ற பெயருடைய ஒரு தூதரைப் பற்றி நற்செய்தி கூறுபவனாகவும் உங்களிடம் வந்துள்ள அல்லாஹ்வின் தூதர் நான்” என்று கூறியதை (நினைவு கூருங்கள்).) (61:6) இங்கு 'ஸுபுர்' என்பது வேதங்களைக் குறிக்கிறது. 'அஸ்-ஸபூர்' என்பதன் பன்மையே 'ஸுபுர்' ஆகும். தாவூத் (அலை) அவர்களுக்கு வழங்கப்பட்ட வேதத்தைக் குறிக்கவும் இந்தப் பெயர் பயன்படுத்தப்படுகிறது. அதாவது, \"நாம் தாவூதுக்கு ஜபூரை வழங்கினோம்\" (17:55) என்று அல்லாஹ் கூறுவதைப் போல. அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَكُلُّ شَىْءٍ فَعَلُوهُ فِى الزُّبُرِ\n\r\n\n\r\n(அவர்கள் செய்த ஒவ்வொரு காரியமும் அஸ்-ஸுபுரில் (ஏடுகளில்) பதிவு செய்யப்பட்டுள்ளது.) (54:52), அதாவது, அது வானவர்களின் ஏடுகளில் அவர்களுக்கு எதிராகப் பதிவு செய்யப்பட்டுள்ளது. பின்னர் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nأَوَلَمْ يَكُن لَّهُمْ آيَةً أَن يَعْلَمَهُ عُلَمَاءُ بَنِي إِسْرَائِيلَ\n\r\n\n\r\n(இஸ்ரவேல் மக்களின் அறிஞர்கள் இதை அறிந்திருப்பது அவர்களுக்கு ஓர் அத்தாட்சியாக இல்லையா?) அதாவது, இஸ்ரவேல் மக்களின் அறிஞர்கள் தாங்கள் பயிலும் வேதங்களில் இந்தக் குர்ஆனைப் பற்றிய குறிப்புகளைக் காண்பது, இது உண்மையானது என்பதற்கு அவர்களுக்குப் போதுமான சான்றாக இல்லையா? இதன் பொருள் என்னவெனில்: அவர்களில் நடுநிலையாளர்கள் முஹம்மது (ஸல்) அவர்களின் பண்புகள், அவர்களது தூதுத்துவம் மற்றும் அவர்களது உம்மத்தைப் பற்றிய செய்திகள் தங்கள் வேதங்களில் இடம்பெற்றுள்ளதை ஒப்புக்கொண்டனர். அப்துல்லாஹ் பின் ஸலாம் (ரழி), ஸல்மான் அல்-ஃபாரிஸி (ரழி) மற்றும் நபியவர்களைச் சந்தித்த ஏனைய ஈமான் கொண்டவர்கள் இதனை உறுதிப்படுத்தியுள்ளனர். அல்லாஹ் கூறினான்:\n\r\n\n\r\nالَّذِينَ يَتَّبِعُونَ الرَّسُولَ النَّبِىَّ الأُمِّىَّ\n\r\n\n\r\n(எழுதவோ படிக்கவோ தெரியாத அந்தத் தூதரை, நபியைப் பின்பற்றுபவர்கள்...) (7:157)\n\r\n\n\r\nகுறைஷிகளின் கடுமையான நிராகரிப்பு\n\r\n\n\r\nபின்னர், குறைஷிகளின் நிராகரிப்பு எவ்வளவு தீவிரமானது என்பதையும், அவர்கள் இக்குர்ஆனை எவ்வளவு பிடிவாதமாக எதிர்த்தார்கள் என்பதையும் அல்லாஹ் கூறுகிறான். சொல்லாற்றல் மிக்க இந்த வேதம், அரபி மொழியில் ஒரு வார்த்தை கூடத் தெரியாத ஓர் அரபி அல்லாதவர் மீது அருளப்பட்டிருந்தாலும், அவர்கள் அவரை நம்பியிருக்க மாட்டார்கள். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَلَوْ نَزَّلْنَاهُ عَلَى بَعْضِ الْأَعْجَمِينَ\n\r\n\n\r\nفَقَرَأَهُ عَلَيْهِم مَّا كَانُوا بِهِ مُؤْمِنِينَ\n\r\n\n\r\n(இதை நாம் அரபியர் அல்லாத எவர் மீதேனும் இறக்கியிருந்து, அவர் அதை அவர்களுக்கு ஓதிக்காட்டியிருந்தாலும், அவர்கள் அதை நம்பியிருக்க மாட்டார்கள்.) மேலும் அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَلَوْ فَتَحْنَا عَلَيْهِم بَاباً مِّنَ السَّمَاءِ فَظَلُّوا فِيهِ يَعْرُجُونَ لَقَالُوا إِنَّمَا سُكِّرَتْ أَبْصَارُنَا\n\r\n\n\r\n(நாம் அவர்களுக்கு வானத்திலிருந்து ஒரு வாசலைத் திறந்து, அதன் வழியாக அவர்கள் மேலே ஏறிக்கொண்டிருந்தாலும், அவர்கள் நிச்சயமாக, \"எங்கள் பார்வைகள் மயக்கப்பட்டு விட்டன...\" என்றே கூறுவார்கள்.) (15:14-15)\n\r\n\n\r\nوَلَوْ أَنَّنَا نَزَّلْنَا إِلَيْهِمُ الْمَلَائِكَةَ وَكَلَّمَهُمُ الْمَوْتَى\n\r\n\n\r\n(நாம் அவர்களிடம் வானவர்களை இறக்கியிருந்தாலும், இறந்தவர்கள் அவர்களிடம் பேசியிருந்தாலும்...) (6:111)\n\r\n\n\r\nإِنَّ الَّذِينَ حَقَّتْ عَلَيْهِمْ كَلِمَةُ رَبِّكَ لاَ يُؤْمِنُونَ\n\r\n\n\r\n(நிச்சயமாக, எவர்கள் மீது உமது இறைவனின் வாக்கு உறுதியாகிவிட்டதோ, அவர்கள் நம்பிக்கை கொள்ள மாட்டார்கள்.) (10:96)\n\r\n\n\r\nكَذَلِكَ سَلَكْنَاهُ فِي قُلُوبِ الْمُجْرِمِينَ - لاَ يُؤْمِنُونَ بِهِ حَتَّى يَرَوُا الْعَذَابَ الْأَلِيمَ - فَيَأْتِيَهُم بَغْتَةً وَهُمْ لاَ يَشْعُرُونَ - فَيَقُولُوا هَلْ نَحْنُ مُنظَرُونَ - أَفَبِعَذَابِنَا يَسْتَعْجِلُونَ - أَفَرَأَيْتَ إِن مَّتَّعْنَاهُمْ سِنِينَ - ثُمَّ جَاءَهُم مَّا كَانُوا يُوعَدُونَ - مَا أَغْنَى عَنْهُمْ مَّا كَانُوا يُمَتَّعُونَ - وَمَا أَهْلَكْنَا مِن قَرْيَةٍ إِلاَّ لَهَا مُنذِرُونَ\n\r\n\n\r\n(இவ்வாறே குற்றவாளிகளின் உள்ளங்களில் நாம் இதனை நுழையச் செய்தோம். துயருறுத்தும் வேதனையை அவர்கள் காணாத வரையில் அவர்கள் இதனை நம்பிக்கை கொள்ள மாட்டார்கள். அவர்கள் அறியாத விதத்தில் திடீரென அது அவர்களிடம் வரும். அப்போது அவர்கள், “எங்களுக்குச் சற்றே அவகாசம் அளிக்கப்படுமா?” என்று கேட்பார்கள். நமது வேதனையை (வரவழைக்க) அவர்கள் அவசரப்படுகிறார்களா? (நபியே!) நீர் கவனித்தீரா? நாம் அவர்களைப் பல ஆண்டுகள் சுகபோகங்களை அனுபவிக்கச் செய்து, பின்னர் அவர்களுக்கு வாக்களிக்கப்பட்ட (வேதனை) அவர்களிடம் வந்தால், அவர்கள் அனுபவித்துக் கொண்டிருந்த சுகபோகங்கள் அவர்களுக்குப் பயனளிக்காது. எச்சரிக்கை செய்பவர்கள் இல்லாமல் எந்த ஊரையும் நாம் அழித்ததில்லை.)"},"200":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=209\" class=\"link\">26:209</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:209 ஐ பார்க்கவும்"},"201":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=209\" class=\"link\">26:209</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:209 ஐ பார்க்கவும்"},"202":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=209\" class=\"link\">26:209</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:209 ஐ பார்க்கவும்"},"203":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=209\" class=\"link\">26:209</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:209 ஐ பார்க்கவும்"},"204":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=209\" class=\"link\">26:209</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:209 ஐ பார்க்கவும்"},"205":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=209\" class=\"link\">26:209</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:209 ஐ பார்க்கவும்"},"206":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=209\" class=\"link\">26:209</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:209 ஐ பார்க்கவும்"},"207":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=209\" class=\"link\">26:209</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:209 ஐ பார்க்கவும்"},"208":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=209\" class=\"link\">26:209</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:209 ஐ பார்க்கவும்"},"209":{"html":"<strong>மறுப்பவர்கள் வேதனையைக் காணும் வரை நம்பிக்கை கொள்ள மாட்டார்கள்</strong><br />\r\n<br />\r\nஅல்லாஹ் கூறுகிறான்: 'இவ்வாறே பாவிகளின் இதயங்களில் (சத்தியத்தை) மறுப்பதையும், இறை நிராகரிப்பையும், பிடிவாதத்தையும் நாம் நுழையச் செய்கிறோம்.' <span class=\"quran-arabic-font text-success\">﴾كَذَلِكَ</span> <span class=\"quran-arabic-font text-success\">سَلَكْنَاهُ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">قُلُوبِ</span> <span class=\"quran-arabic-font text-success\">الْمُجْرِمِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span> <span class=\"quran-arabic-font text-success\">﴾لاَ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنُونَ</span> <span class=\"quran-arabic-font text-success\">بِهِ﴿</span><br />\r\n<br />\r\n(அவர்கள் இதில் நம்பிக்கை கொள்ள மாட்டார்கள்), அதாவது அந்தச் சத்தியத்தை, <span class=\"quran-arabic-font text-success\">﴾حَتَّى</span> <span class=\"quran-arabic-font text-success\">يَرَوُاْ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابَ</span> <span class=\"quran-arabic-font text-success\">الْأَلِيمَ﴿</span><br />\r\n<br />\r\n(நோவினை செய்யும் வேதனையை அவர்கள் காணும் வரை.) அதாவது, அவர்களின் சாக்குப்போக்குகள் பயனற்றுப் போய், அவர்கள் மீது சாபம் உண்டாகி, அவர்களுக்கு மிக மோசமான தங்குமிடம் அமையும் போது (அவர்கள் உணர்வார்கள்). <span class=\"quran-arabic-font text-success\">﴾فَيَأْتِيَهُم</span> <span class=\"quran-arabic-font text-success\">بَغْتَةً﴿</span><br />\r\n<br />\r\n(அவர்களுக்கு அது திடீரென்று வரும்,) அதாவது, அல்லாஹ்வின் வேதனை அவர்கள் மீது எதிர்பாராத விதமாக வரும், <span class=\"quran-arabic-font text-success\">﴾وَهُمْ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَشْعُرُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span> <span class=\"quran-arabic-font text-success\">﴾</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُواْ</span> <span class=\"quran-arabic-font text-success\">هَلْ</span> <span class=\"quran-arabic-font text-success\">نَحْنُ</span> <span class=\"quran-arabic-font text-success\">مُنظَرُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அவர்கள் அதனை உணராத நிலையில். பின்னர் அவர்கள் கூறுவார்கள்: \"எங்களுக்குச் சற்று அவகாசம் அளிக்கப்படுமா?\") அதாவது, வேதனையைக் காணும்போது, அவர்கள் அல்லாஹ்வுக்குக் கீழ்ப்படிவதற்காகத் தங்களுக்கு இன்னும் சிறிது காலம் அவகாசம் கிடைக்காதா என விரும்புவார்கள் - அல்லது அவ்வாறு அவர்கள் கூறுவார்கள். இது இந்த வசனத்தைப் போன்றது: <span class=\"quran-arabic-font text-success\">﴾وَأَنذِرِ</span> <span class=\"quran-arabic-font text-success\">النَّاسَ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَأْتِيهِمُ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابُ﴿</span><br />\r\n<br />\r\n(வேதனை அவர்களிடம் வரும் அந்த நாளைக் குறித்து மனிதர்களை எச்சரிப்பீராக!) என்பது முதல்: <span class=\"quran-arabic-font text-success\">﴾مَا</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">زَوَالٍ﴿</span><br />\r\n<br />\r\n(உங்களுக்கு அழிவே இல்லை என்று நீங்கள் சத்தியம் செய்து கொண்டிருந்தீர்களே!) (14: 44). ஒவ்வொரு பாவியும் தீமை செய்பவனும் தனக்குரிய வேதனையைக் காணும்போது, அவன் மிகுந்த வருத்தத்தை அடைவான். மூஸா (அலை) அவர்கள் ஃபிர்அவ்னுக்கு எதிராகப் பிரார்த்தித்தபோது, அவனது நிலையும் அவ்வாறே இருந்தது: <span class=\"quran-arabic-font text-success\">﴾رَبَّنَآ</span> <span class=\"quran-arabic-font text-success\">إِنَّكَ</span> <span class=\"quran-arabic-font text-success\">ءاتَيْتَ</span> <span class=\"quran-arabic-font text-success\">فِرْعَوْنَ</span> <span class=\"quran-arabic-font text-success\">وَمَلَأَهُ</span> <span class=\"quran-arabic-font text-success\">زِينَةً</span> <span class=\"quran-arabic-font text-success\">وَأَمْوَالاً</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الْحَيَوةِ</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا﴿</span><br />\r\n<br />\r\n(எங்கள் இறைவனே! நிச்சயமாக நீ ஃபிர்அவ்னுக்கும் அவனது தலைவர்களுக்கும் இவ்வுலக வாழ்வில் அலங்காரத்தையும் செல்வங்களையும் வழங்கியுள்ளாய்) என்பது முதல்: <span class=\"quran-arabic-font text-success\">﴾قَالَ</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">أُجِيبَتْ</span> <span class=\"quran-arabic-font text-success\">دَّعْوَتُكُمَا﴿</span><br />\r\n<br />\r\n((அல்லாஹ்) கூறினான்: \"நிச்சயமாக உங்கள் இருவரின் பிரார்த்தனையும் ஏற்றுக்கொள்ளப்பட்டது.\") (<a href=\"qurandisp.php?sura=10&ayah=88\" class=\"link\">10:88</a>-89). இந்தப் பிரார்த்தனை ஃபிர்அவ்ன் மீது தாக்கத்தை ஏற்படுத்தியது; அவன் நோவினை செய்யும் வேதனையைக் காணும் வரை நம்பிக்கை கொள்ளவில்லை: <span class=\"quran-arabic-font text-success\">﴾حَتَّى</span> <span class=\"quran-arabic-font text-success\">إِذَآ</span> <span class=\"quran-arabic-font text-success\">أَدْرَكَهُ</span> <span class=\"quran-arabic-font text-success\">الْغَرَقُ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">ءَامَنتُ</span> <span class=\"quran-arabic-font text-success\">أَنَّهُ</span> <span class=\"quran-arabic-font text-success\">لا</span> <span class=\"quran-arabic-font text-success\">إِلِـهَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">ءَامَنَتْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">بَنُو</span> <span class=\"quran-arabic-font text-success\">إِسْرَءِيلَ﴿</span><br />\r\n<br />\r\n(இறுதியில் மூழ்கும் நிலை அவனை நெருங்கியபோது: \"இஸ்ரவேலர்கள் எவனை நம்புகிறார்களோ, அவனைத் தவிர வேறு இறைவனில்லை என்று நானும் நம்பிக்கை கொள்கிறேன்\" என்று கூறினான்) என்பது முதல்: <span class=\"quran-arabic-font text-success\">﴾وَكُنتَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُفْسِدِينَ﴿</span><br />\r\n<br />\r\n(மேலும் நீ குழப்பம் விளைவிப்பவர்களில் ஒருவனாக இருந்தாய்) (<a href=\"qurandisp.php?sura=10&ayah=90\" class=\"link\">10:90</a>-91). மேலும் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾فَلَمَّا</span> <span class=\"quran-arabic-font text-success\">رَأَوْاْ</span> <span class=\"quran-arabic-font text-success\">بَأْسَنَا</span> <span class=\"quran-arabic-font text-success\">قَالُواْ</span> <span class=\"quran-arabic-font text-success\">ءَامَنَّا</span> <span class=\"quran-arabic-font text-success\">بِاللَّهِ</span> <span class=\"quran-arabic-font text-success\">وَحْدَهُ﴿</span><br />\r\n<br />\r\n(ஆகவே, அவர்கள் நமது வேதனையைக் கண்டபோது: \"நாங்கள் அல்லாஹ் ஒருவனை மட்டுமே நம்புகிறோம்...\" என்று கூறினார்கள்) (<a href=\"qurandisp.php?sura=40&ayah=84\" class=\"link\">40:84</a>-85). <span class=\"quran-arabic-font text-success\">﴾أَفَبِعَذَابِنَا</span> <span class=\"quran-arabic-font text-success\">يَسْتَعْجِلُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அப்படியிருக்க, அவர்கள் நமது வேதனையை அவசரமாகக் கோருகிறார்களா?) இது ஒரு கண்டனமும் அச்சுறுத்தலும் ஆகும். ஏனெனில் அவர்கள் அல்லாஹ்வைப் புறக்கணிக்கும் விதமாகவும், வேதனை ஒருபோதும் வராது என்ற எண்ணத்திலும் அல்லாஹ்வின் தூதரிடம் (ஸல்) இவ்வாறு கூறி வந்தனர்: <span class=\"quran-arabic-font text-success\">﴾ائْتِنَا</span> <span class=\"quran-arabic-font text-success\">بِعَذَابِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ﴿</span><br />\r\n<br />\r\n('அல்லாஹ்வின் வேதனையை எங்களிடம் கொண்டு வாரும்') (<a href=\"qurandisp.php?sura=29&ayah=29\" class=\"link\">29:29</a>). அல்லாஹ் கூறுவதைப் போல: <span class=\"quran-arabic-font text-success\">﴾وَيَسْتَعْجِلُونَكَ</span> <span class=\"quran-arabic-font text-success\">بِالْعَذَابِ﴿</span><br />\r\n<br />\r\n(மேலும் அவர்கள் உம்மிடம் வேதனையை விரைவுபடுத்தக் கோருகின்றனர்...) (<a href=\"qurandisp.php?sura=29&ayah=53\" class=\"link\">29:53</a>-55). பின்னர் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾أَفَرَأَيْتَ</span> <span class=\"quran-arabic-font text-success\">إِن</span> <span class=\"quran-arabic-font text-success\">مَّتَّعْنَاهُمْ</span> <span class=\"quran-arabic-font text-success\">سِنِينَ</span> - <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">جَآءَهُم</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يُوعَدُونَ</span> - <span class=\"quran-arabic-font text-success\">مَآ</span> <span class=\"quran-arabic-font text-success\">أَغْنَى</span> <span class=\"quran-arabic-font text-success\">عَنْهُمْ</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يُمَتَّعُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(உம் கவனத்திற்கு: நாம் அவர்களைப் பல ஆண்டுகள் (இவ்வுலகில்) சுகங்களை அனுபவிக்கச் செய்து, பின்னர் அவர்களுக்கு எச்சரிக்கப்பட்ட (வேதனை) அவர்களிடம் வந்தால், அவர்கள் அனுபவித்த சுகங்கள் அவர்களுக்கு எவ்விதப் பயனும் அளிக்காது என்பதைச் சிந்தித்தீரா?) அதாவது, 'நாம் அவர்களைத் தாமதப்படுத்தி, அவர்களுக்குக் குறுகிய காலமோ அல்லது நீண்ட காலமோ அவகாசம் அளித்தாலும், இறுதியில் அல்லாஹ்வின் வேதனை அவர்கள் மீது இறங்கும்போது, அவர்கள் அனுபவித்த ஆடம்பர வாழ்க்கை அவர்களுக்கு என்ன பயனைத் தரும்?' <span class=\"quran-arabic-font text-success\">﴾كَأَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">يَرَوْنَهَا</span> <span class=\"quran-arabic-font text-success\">لَمْ</span> <span class=\"quran-arabic-font text-success\">يَلْبَثُواْ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">عَشِيَّةً</span> <span class=\"quran-arabic-font text-success\">أَوْ</span> <span class=\"quran-arabic-font text-success\">ضُحَـهَا</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அவர்கள் அதைக் காணும் நாளில், அவர்கள் ஒரு மாலையையோ அல்லது ஒரு முற்பகலையோ தவிர (இவ்வுலகில்) தங்கியிருக்கவில்லை என்பதாகவே அவர்களுக்குத் தோன்றும்) (<a href=\"qurandisp.php?sura=79&ayah=46\" class=\"link\">79:46</a>). மேலும் அல்லாஹ் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾يَوَدُّ</span> <span class=\"quran-arabic-font text-success\">أَحَدُهُمْ</span> <span class=\"quran-arabic-font text-success\">لَوْ</span> <span class=\"quran-arabic-font text-success\">يُعَمَّرُ</span> <span class=\"quran-arabic-font text-success\">أَلْفَ</span> <span class=\"quran-arabic-font text-success\">سَنَةٍ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">بِمُزَحْزِحِهِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْعَذَابِ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يُعَمَّرَ﴿</span><br />\r\n<br />\r\n(அவர்களில் ஒவ்வொருவனும் ஆயிரம் ஆண்டுகள் உயிர் வாழ வேண்டும் என்று ஆசைப்படுகிறான். ஆனால் அத்தகைய நீண்ட ஆயுள் அவனுக்கு வழங்கப்பட்டாலும், அது அவனைத் தண்டனையிலிருந்து தப்புவிக்காது) (<a href=\"qurandisp.php?sura=2&ayah=96\" class=\"link\">2:96</a>). <span class=\"quran-arabic-font text-success\">﴾وَمَا</span> <span class=\"quran-arabic-font text-success\">يُغْنِى</span> <span class=\"quran-arabic-font text-success\">عَنْهُ</span> <span class=\"quran-arabic-font text-success\">مَالُهُ</span> <span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">تَرَدَّى</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அவன் (குழியில்) வீழ்ந்து அழியும் போது, அவனது செல்வம் அவனுக்கு எவ்விதப் பயனும் அளிக்காது) (<a href=\"qurandisp.php?sura=92&ayah=11\" class=\"link\">92:11</a>). அல்லாஹ் இங்கு கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾مَآ</span> <span class=\"quran-arabic-font text-success\">أَغْنَى</span> <span class=\"quran-arabic-font text-success\">عَنْهُمْ</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">كَانُواْ</span> <span class=\"quran-arabic-font text-success\">يُمَتَّعُونَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(அவர்கள் அனுபவித்து வந்த சுகங்கள் அவர்களுக்கு எவ்விதப் பயனும் அளிக்காது.) ஓர் ஆதாரப்பூர்வமான ஹதீஸின்படி: <span class=\"quran-arabic-font text-success\">﴾</span>«<span class=\"quran-arabic-font text-success\">يُؤْتَى</span> <span class=\"quran-arabic-font text-success\">بِالْكَافِرِ</span> <span class=\"quran-arabic-font text-success\">فَيُغْمَسُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span> <span class=\"quran-arabic-font text-success\">غَمْسَةً</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يُقَالُ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span>: <span class=\"quran-arabic-font text-success\">هَلْ</span> <span class=\"quran-arabic-font text-success\">رَأَيْتَ</span> <span class=\"quran-arabic-font text-success\">خَيْرًا</span> <span class=\"quran-arabic-font text-success\">قَطُّ؟</span> <span class=\"quran-arabic-font text-success\">هَلْ</span> <span class=\"quran-arabic-font text-success\">رَأَيْتَ</span> <span class=\"quran-arabic-font text-success\">نَعِيمًا</span> <span class=\"quran-arabic-font text-success\">قَطُّ؟</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُ</span>: <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">وَاللهِ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">رَبِّ،</span> <span class=\"quran-arabic-font text-success\">وَيُؤتَى</span> <span class=\"quran-arabic-font text-success\">بِأَشَدِّ</span> <span class=\"quran-arabic-font text-success\">النَّاسِ</span> <span class=\"quran-arabic-font text-success\">بُؤْسًا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الدُّنْيَا،</span> <span class=\"quran-arabic-font text-success\">فَيُصْبَغُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْجَنَّةِ</span> <span class=\"quran-arabic-font text-success\">صَبْغَةً،</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يُقَالُ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span>: <span class=\"quran-arabic-font text-success\">هَلْ</span> <span class=\"quran-arabic-font text-success\">رَأَيْتَ</span> <span class=\"quran-arabic-font text-success\">بُؤْسًا</span> <span class=\"quran-arabic-font text-success\">قَطُّ؟</span> <span class=\"quran-arabic-font text-success\">فَيَقُولُ</span>: <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">وَاللهِ</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">رَبِّ</span>»<span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(இறை மறுப்பாளன் (மறுமை நாளில்) கொண்டு வரப்பட்டு நரக நெருப்பில் ஒருமுறை முக்கி எடுக்கப்படுவான். பின்னர் அவனிடம், 'நீ எப்போதாவது ஏதேனும் நன்மையைக் கண்டிருக்கிறாயா? நீ எப்போதாவது ஏதேனும் சுகத்தை அனுபவித்திருக்கிறாயா?' என்று கேட்கப்படும். அதற்கு அவன், 'இல்லை, என் இறைவா!' என்பான். பிறகு, இவ்வுலகில் வாழ்ந்தவர்களில் மிகக் கடுமையான துன்பங்களை அனுபவித்த ஒருவன் கொண்டு வரப்பட்டு, சொர்க்கத்தில் ஒருமுறை நுழைத்து எடுக்கப்படுவான். பின்னர் அவனிடம், 'நீ எப்போதாவது ஏதேனும் தீமையைக் கண்டதுண்டா?' என்று கேட்கப்படும். அதற்கு அவன், 'இல்லை, என் இறைவா!' என்பான்.) அதாவது: ஏதோ எதுவுமே நடக்காதது போல.<br />\r\n<br />\r\nபின்னர் அல்லாஹ் தனது படைப்புகளிடம் காட்டும் நீதியைப் பற்றி கூறுகிறான். எந்தவொரு சமூகத்தையும், அவர்களுக்கு எச்சரிக்கை செய்து, தூதர்களை அனுப்பி, அவர்களுக்கு எதிராக ஆதாரங்களை நிலைநாட்டி, அவர்களுக்கு எந்தச் சாக்குப்போக்கும் இல்லாத நிலையை ஏற்படுத்திய பின்னரேயன்றி அவன் அழிப்பதில்லை. அவன் கூறுகிறான்: <span class=\"quran-arabic-font text-success\">﴾وَمَآ</span> <span class=\"quran-arabic-font text-success\">أَهْلَكْنَا</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قَرْيَةٍ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">لَهَا</span> <span class=\"quran-arabic-font text-success\">مُنذِرُونَ</span> <span class=\"quran-arabic-font text-success\">﴿﴾ذِكْرَى</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">كُنَّا</span> <span class=\"quran-arabic-font text-success\">ظَالِمِينَ</span> <span class=\"quran-arabic-font text-success\">﴿</span><br />\r\n<br />\r\n(எந்த ஊரையும் - அதற்கு எச்சரிக்கை செய்பவர்கள் இருந்தாலன்றி நாம் அழித்ததில்லை. (அது) நினைவூட்டுவதற்காகவே; நாம் அநீதி இழைப்பவர்களாக இல்லை.) இது பின்வரும் வசனங்களைப் போன்றது: <span class=\"quran-arabic-font text-success\">﴾وَمَا</span> <span class=\"quran-arabic-font text-success\">كُنَّا</span> <span class=\"quran-arabic-font text-success\">مُعَذِّبِينَ</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">نَبْعَثَ</span> <span class=\"quran-arabic-font text-success\">رَسُولاً﴿</span><br />\r\n<br />\r\n(நாம் ஒரு தூதரை அனுப்பும் வரை யாரையும் தண்டிப்பதில்லை) (<a href=\"qurandisp.php?sura=17&ayah=15\" class=\"link\">17:15</a>). <span class=\"quran-arabic-font text-success\">﴾وَمَا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">رَبُّكَ</span> <span class=\"quran-arabic-font text-success\">مُهْلِكَ</span> <span class=\"quran-arabic-font text-success\">الْقُرَى</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">يَبْعَثَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">أُمِّهَا</span> <span class=\"quran-arabic-font text-success\">رَسُولاً</span> <span class=\"quran-arabic-font text-success\">يَتْلُو</span> <span class=\"quran-arabic-font text-success\">عَلَيْهِمْ</span> <span class=\"quran-arabic-font text-success\">ءَايَـتِنَا﴿</span><br />\r\n<br />\r\n(உமது இறைவன், ஊர்களின் தலைநகருக்கு ஒரு தூதரை அனுப்பி, அவர் நமது வசனங்களை அவர்களுக்கு ஓதிக்காட்டும் வரை எந்த ஊர்களையும் அழிப்பவனாக இல்லை) என்பது முதல்; <span class=\"quran-arabic-font text-success\">﴾وَأَهْلُهَا</span> <span class=\"quran-arabic-font text-success\">ظَالِمُونَ﴿</span><br />\r\n<br />\r\n(அவ்வூர் மக்கள் அநீதியாளர்களாக இருந்தாலன்றி நாம் ஊர்களை அழிப்பதில்லை) (<a href=\"qurandisp.php?sura=28&ayah=59\" class=\"link\">28:59</a>) என்பது வரை.<br />\r\n<br />","text":"மறுப்பவர்கள் வேதனையைக் காணும் வரை நம்பிக்கை கொள்ள மாட்டார்கள்\n\r\n\n\r\nஅல்லாஹ் கூறுகிறான்: 'இவ்வாறே பாவிகளின் இதயங்களில் (சத்தியத்தை) மறுப்பதையும், இறை நிராகரிப்பையும், பிடிவாதத்தையும் நாம் நுழையச் செய்கிறோம்.' ﴾كَذَلِكَ سَلَكْنَاهُ فِى قُلُوبِ الْمُجْرِمِينَ ﴿ ﴾لاَ يُؤْمِنُونَ بِهِ﴿\n\r\n\n\r\n(அவர்கள் இதில் நம்பிக்கை கொள்ள மாட்டார்கள்), அதாவது அந்தச் சத்தியத்தை, ﴾حَتَّى يَرَوُاْ الْعَذَابَ الْأَلِيمَ﴿\n\r\n\n\r\n(நோவினை செய்யும் வேதனையை அவர்கள் காணும் வரை.) அதாவது, அவர்களின் சாக்குப்போக்குகள் பயனற்றுப் போய், அவர்கள் மீது சாபம் உண்டாகி, அவர்களுக்கு மிக மோசமான தங்குமிடம் அமையும் போது (அவர்கள் உணர்வார்கள்). ﴾فَيَأْتِيَهُم بَغْتَةً﴿\n\r\n\n\r\n(அவர்களுக்கு அது திடீரென்று வரும்,) அதாவது, அல்லாஹ்வின் வேதனை அவர்கள் மீது எதிர்பாராத விதமாக வரும், ﴾وَهُمْ لاَ يَشْعُرُونَ ﴿ ﴾ فَيَقُولُواْ هَلْ نَحْنُ مُنظَرُونَ ﴿\n\r\n\n\r\n(அவர்கள் அதனை உணராத நிலையில். பின்னர் அவர்கள் கூறுவார்கள்: \"எங்களுக்குச் சற்று அவகாசம் அளிக்கப்படுமா?\") அதாவது, வேதனையைக் காணும்போது, அவர்கள் அல்லாஹ்வுக்குக் கீழ்ப்படிவதற்காகத் தங்களுக்கு இன்னும் சிறிது காலம் அவகாசம் கிடைக்காதா என விரும்புவார்கள் - அல்லது அவ்வாறு அவர்கள் கூறுவார்கள். இது இந்த வசனத்தைப் போன்றது: ﴾وَأَنذِرِ النَّاسَ يَوْمَ يَأْتِيهِمُ الْعَذَابُ﴿\n\r\n\n\r\n(வேதனை அவர்களிடம் வரும் அந்த நாளைக் குறித்து மனிதர்களை எச்சரிப்பீராக!) என்பது முதல்: ﴾مَا لَكُمْ مِّن زَوَالٍ﴿\n\r\n\n\r\n(உங்களுக்கு அழிவே இல்லை என்று நீங்கள் சத்தியம் செய்து கொண்டிருந்தீர்களே!) (14: 44). ஒவ்வொரு பாவியும் தீமை செய்பவனும் தனக்குரிய வேதனையைக் காணும்போது, அவன் மிகுந்த வருத்தத்தை அடைவான். மூஸா (அலை) அவர்கள் ஃபிர்அவ்னுக்கு எதிராகப் பிரார்த்தித்தபோது, அவனது நிலையும் அவ்வாறே இருந்தது: ﴾رَبَّنَآ إِنَّكَ ءاتَيْتَ فِرْعَوْنَ وَمَلَأَهُ زِينَةً وَأَمْوَالاً فِى الْحَيَوةِ الدُّنْيَا﴿\n\r\n\n\r\n(எங்கள் இறைவனே! நிச்சயமாக நீ ஃபிர்அவ்னுக்கும் அவனது தலைவர்களுக்கும் இவ்வுலக வாழ்வில் அலங்காரத்தையும் செல்வங்களையும் வழங்கியுள்ளாய்) என்பது முதல்: ﴾قَالَ قَدْ أُجِيبَتْ دَّعْوَتُكُمَا﴿\n\r\n\n\r\n((அல்லாஹ்) கூறினான்: \"நிச்சயமாக உங்கள் இருவரின் பிரார்த்தனையும் ஏற்றுக்கொள்ளப்பட்டது.\") (10:88-89). இந்தப் பிரார்த்தனை ஃபிர்அவ்ன் மீது தாக்கத்தை ஏற்படுத்தியது; அவன் நோவினை செய்யும் வேதனையைக் காணும் வரை நம்பிக்கை கொள்ளவில்லை: ﴾حَتَّى إِذَآ أَدْرَكَهُ الْغَرَقُ قَالَ ءَامَنتُ أَنَّهُ لا إِلِـهَ إِلاَّ الَّذِى ءَامَنَتْ بِهِ بَنُو إِسْرَءِيلَ﴿\n\r\n\n\r\n(இறுதியில் மூழ்கும் நிலை அவனை நெருங்கியபோது: \"இஸ்ரவேலர்கள் எவனை நம்புகிறார்களோ, அவனைத் தவிர வேறு இறைவனில்லை என்று நானும் நம்பிக்கை கொள்கிறேன்\" என்று கூறினான்) என்பது முதல்: ﴾وَكُنتَ مِنَ الْمُفْسِدِينَ﴿\n\r\n\n\r\n(மேலும் நீ குழப்பம் விளைவிப்பவர்களில் ஒருவனாக இருந்தாய்) (10:90-91). மேலும் அல்லாஹ் கூறுகிறான்: ﴾فَلَمَّا رَأَوْاْ بَأْسَنَا قَالُواْ ءَامَنَّا بِاللَّهِ وَحْدَهُ﴿\n\r\n\n\r\n(ஆகவே, அவர்கள் நமது வேதனையைக் கண்டபோது: \"நாங்கள் அல்லாஹ் ஒருவனை மட்டுமே நம்புகிறோம்...\" என்று கூறினார்கள்) (40:84-85). ﴾أَفَبِعَذَابِنَا يَسْتَعْجِلُونَ ﴿\n\r\n\n\r\n(அப்படியிருக்க, அவர்கள் நமது வேதனையை அவசரமாகக் கோருகிறார்களா?) இது ஒரு கண்டனமும் அச்சுறுத்தலும் ஆகும். ஏனெனில் அவர்கள் அல்லாஹ்வைப் புறக்கணிக்கும் விதமாகவும், வேதனை ஒருபோதும் வராது என்ற எண்ணத்திலும் அல்லாஹ்வின் தூதரிடம் (ஸல்) இவ்வாறு கூறி வந்தனர்: ﴾ائْتِنَا بِعَذَابِ اللَّهِ﴿\n\r\n\n\r\n('அல்லாஹ்வின் வேதனையை எங்களிடம் கொண்டு வாரும்') (29:29). அல்லாஹ் கூறுவதைப் போல: ﴾وَيَسْتَعْجِلُونَكَ بِالْعَذَابِ﴿\n\r\n\n\r\n(மேலும் அவர்கள் உம்மிடம் வேதனையை விரைவுபடுத்தக் கோருகின்றனர்...) (29:53-55). பின்னர் அல்லாஹ் கூறுகிறான்: ﴾أَفَرَأَيْتَ إِن مَّتَّعْنَاهُمْ سِنِينَ - ثُمَّ جَآءَهُم مَّا كَانُواْ يُوعَدُونَ - مَآ أَغْنَى عَنْهُمْ مَّا كَانُواْ يُمَتَّعُونَ ﴿\n\r\n\n\r\n(உம் கவனத்திற்கு: நாம் அவர்களைப் பல ஆண்டுகள் (இவ்வுலகில்) சுகங்களை அனுபவிக்கச் செய்து, பின்னர் அவர்களுக்கு எச்சரிக்கப்பட்ட (வேதனை) அவர்களிடம் வந்தால், அவர்கள் அனுபவித்த சுகங்கள் அவர்களுக்கு எவ்விதப் பயனும் அளிக்காது என்பதைச் சிந்தித்தீரா?) அதாவது, 'நாம் அவர்களைத் தாமதப்படுத்தி, அவர்களுக்குக் குறுகிய காலமோ அல்லது நீண்ட காலமோ அவகாசம் அளித்தாலும், இறுதியில் அல்லாஹ்வின் வேதனை அவர்கள் மீது இறங்கும்போது, அவர்கள் அனுபவித்த ஆடம்பர வாழ்க்கை அவர்களுக்கு என்ன பயனைத் தரும்?' ﴾كَأَنَّهُمْ يَوْمَ يَرَوْنَهَا لَمْ يَلْبَثُواْ إِلاَّ عَشِيَّةً أَوْ ضُحَـهَا ﴿\n\r\n\n\r\n(அவர்கள் அதைக் காணும் நாளில், அவர்கள் ஒரு மாலையையோ அல்லது ஒரு முற்பகலையோ தவிர (இவ்வுலகில்) தங்கியிருக்கவில்லை என்பதாகவே அவர்களுக்குத் தோன்றும்) (79:46). மேலும் அல்லாஹ் கூறுகிறான்: ﴾يَوَدُّ أَحَدُهُمْ لَوْ يُعَمَّرُ أَلْفَ سَنَةٍ وَمَا هُوَ بِمُزَحْزِحِهِ مِنَ الْعَذَابِ أَن يُعَمَّرَ﴿\n\r\n\n\r\n(அவர்களில் ஒவ்வொருவனும் ஆயிரம் ஆண்டுகள் உயிர் வாழ வேண்டும் என்று ஆசைப்படுகிறான். ஆனால் அத்தகைய நீண்ட ஆயுள் அவனுக்கு வழங்கப்பட்டாலும், அது அவனைத் தண்டனையிலிருந்து தப்புவிக்காது) (2:96). ﴾وَمَا يُغْنِى عَنْهُ مَالُهُ إِذَا تَرَدَّى ﴿\n\r\n\n\r\n(அவன் (குழியில்) வீழ்ந்து அழியும் போது, அவனது செல்வம் அவனுக்கு எவ்விதப் பயனும் அளிக்காது) (92:11). அல்லாஹ் இங்கு கூறுகிறான்: ﴾مَآ أَغْنَى عَنْهُمْ مَّا كَانُواْ يُمَتَّعُونَ ﴿\n\r\n\n\r\n(அவர்கள் அனுபவித்து வந்த சுகங்கள் அவர்களுக்கு எவ்விதப் பயனும் அளிக்காது.) ஓர் ஆதாரப்பூர்வமான ஹதீஸின்படி: ﴾«يُؤْتَى بِالْكَافِرِ فَيُغْمَسُ فِي النَّارِ غَمْسَةً ثُمَّ يُقَالُ لَهُ: هَلْ رَأَيْتَ خَيْرًا قَطُّ؟ هَلْ رَأَيْتَ نَعِيمًا قَطُّ؟ فَيَقُولُ: لَا وَاللهِ يَا رَبِّ، وَيُؤتَى بِأَشَدِّ النَّاسِ بُؤْسًا كَانَ فِي الدُّنْيَا، فَيُصْبَغُ فِي الْجَنَّةِ صَبْغَةً، ثُمَّ يُقَالُ لَهُ: هَلْ رَأَيْتَ بُؤْسًا قَطُّ؟ فَيَقُولُ: لَا وَاللهِ يَا رَبِّ»﴿\n\r\n\n\r\n(இறை மறுப்பாளன் (மறுமை நாளில்) கொண்டு வரப்பட்டு நரக நெருப்பில் ஒருமுறை முக்கி எடுக்கப்படுவான். பின்னர் அவனிடம், 'நீ எப்போதாவது ஏதேனும் நன்மையைக் கண்டிருக்கிறாயா? நீ எப்போதாவது ஏதேனும் சுகத்தை அனுபவித்திருக்கிறாயா?' என்று கேட்கப்படும். அதற்கு அவன், 'இல்லை, என் இறைவா!' என்பான். பிறகு, இவ்வுலகில் வாழ்ந்தவர்களில் மிகக் கடுமையான துன்பங்களை அனுபவித்த ஒருவன் கொண்டு வரப்பட்டு, சொர்க்கத்தில் ஒருமுறை நுழைத்து எடுக்கப்படுவான். பின்னர் அவனிடம், 'நீ எப்போதாவது ஏதேனும் தீமையைக் கண்டதுண்டா?' என்று கேட்கப்படும். அதற்கு அவன், 'இல்லை, என் இறைவா!' என்பான்.) அதாவது: ஏதோ எதுவுமே நடக்காதது போல.\n\r\n\n\r\nபின்னர் அல்லாஹ் தனது படைப்புகளிடம் காட்டும் நீதியைப் பற்றி கூறுகிறான். எந்தவொரு சமூகத்தையும், அவர்களுக்கு எச்சரிக்கை செய்து, தூதர்களை அனுப்பி, அவர்களுக்கு எதிராக ஆதாரங்களை நிலைநாட்டி, அவர்களுக்கு எந்தச் சாக்குப்போக்கும் இல்லாத நிலையை ஏற்படுத்திய பின்னரேயன்றி அவன் அழிப்பதில்லை. அவன் கூறுகிறான்: ﴾وَمَآ أَهْلَكْنَا مِن قَرْيَةٍ إِلاَّ لَهَا مُنذِرُونَ ﴿﴾ذِكْرَى وَمَا كُنَّا ظَالِمِينَ ﴿\n\r\n\n\r\n(எந்த ஊரையும் - அதற்கு எச்சரிக்கை செய்பவர்கள் இருந்தாலன்றி நாம் அழித்ததில்லை. (அது) நினைவூட்டுவதற்காகவே; நாம் அநீதி இழைப்பவர்களாக இல்லை.) இது பின்வரும் வசனங்களைப் போன்றது: ﴾وَمَا كُنَّا مُعَذِّبِينَ حَتَّى نَبْعَثَ رَسُولاً﴿\n\r\n\n\r\n(நாம் ஒரு தூதரை அனுப்பும் வரை யாரையும் தண்டிப்பதில்லை) (17:15). ﴾وَمَا كَانَ رَبُّكَ مُهْلِكَ الْقُرَى حَتَّى يَبْعَثَ فِى أُمِّهَا رَسُولاً يَتْلُو عَلَيْهِمْ ءَايَـتِنَا﴿\n\r\n\n\r\n(உமது இறைவன், ஊர்களின் தலைநகருக்கு ஒரு தூதரை அனுப்பி, அவர் நமது வசனங்களை அவர்களுக்கு ஓதிக்காட்டும் வரை எந்த ஊர்களையும் அழிப்பவனாக இல்லை) என்பது முதல்; ﴾وَأَهْلُهَا ظَالِمُونَ﴿\n\r\n\n\r\n(அவ்வூர் மக்கள் அநீதியாளர்களாக இருந்தாலன்றி நாம் ஊர்களை அழிப்பதில்லை) (28:59) என்பது வரை."},"210":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=212\" class=\"link\">26:212</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:212 ஐ பார்க்கவும்"},"211":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=212\" class=\"link\">26:212</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:212 ஐ பார்க்கவும்"},"212":{"html":"<strong>குர்ஆன் ஜிப்ரீல் (அலை) அவர்களால்தான் கொண்டு வரப்பட்டது, ஷைத்தான்களால் அல்ல</strong><br />\r\n<br />\r\nஅல்லாஹ் தன் வேதத்தைப் பற்றி நமக்குக் கூறுகிறான். அதற்கு முன்னாலோ பின்னாலோ எந்த அசத்தியமும் அதை நெருங்க முடியாது. அது மகா ஞானவானும் புகழுக்குரியவனுமான (அல்லாஹ்வால்) அருளப்பட்டது. மேலும், அது அல்லாஹ்வினால் உதவி வழங்கப்பட்ட, நம்பிக்கைக்குரிய ரூஹ் (அதாவது ஜிப்ரீல் (அலை)) அவர்களால் கொண்டு வரப்பட்டது என்று அவன் கூறுகிறான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">تَنَزَّلَتْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">الشَّيَاطِينُ</span><br />\r\n<br />\r\n(மேலும், இதனை ஷைத்தான்கள் கொண்டு வரவில்லை.)<br />\r\n<br />\r\nபின்னர், ஷைத்தான்கள் இதைக் கொண்டு வரவில்லை என்பதற்கு மூன்று காரணங்கள் இருப்பதாக அவன் கூறுகிறான். முதலாவது, அது அவர்களுக்குப் பொருத்தமானது அல்ல; அதாவது, அவர்களுக்கு அப்படிச் செய்வதற்கு விருப்பமும் இல்லை, தேவையும் இல்லை. ஏனெனில், மக்களின் குணத்தைக் கெடுப்பதும் அவர்களை வழிதவறச் செய்வதுமே ஷைத்தான்களின் இயல்பாகும். ஆனால், இந்த வேதமோ நன்மையை ஏவி, தீமையைத் தடுத்து, ஒளி, நேர்வழி மற்றும் வலிமையான சான்றுகளைக் கொண்டுள்ளது. இதற்கும் ஷைத்தான்களுக்கும் இடையே மிகப்பெரிய வேறுபாடு உள்ளது. அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يَنبَغِى</span> <span class=\"quran-arabic-font text-success\">لَهُمْ</span><br />\r\n<br />\r\n(அது அவர்களுக்குப் பொருத்தமானதும் அல்ல)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يَسْتَطِيعُونَ</span><br />\r\n<br />\r\n(அவர்களுக்கு அதற்குச் சக்தியும் இல்லை.)<br />\r\n<br />\r\nஅதாவது, அவர்கள் விரும்பினாலும் அவர்களால் அதைச் செய்ய முடியாது. அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لَوْ</span> <span class=\"quran-arabic-font text-success\">أَنزَلْنَا</span> <span class=\"quran-arabic-font text-success\">هَذَا</span> <span class=\"quran-arabic-font text-success\">الْقُرْآنَ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">جَبَلٍ</span> <span class=\"quran-arabic-font text-success\">لَّرَأَيْتَهُ</span> <span class=\"quran-arabic-font text-success\">خَاشِعاً</span> <span class=\"quran-arabic-font text-success\">مُّتَصَدِّعاً</span> <span class=\"quran-arabic-font text-success\">مِّنْ</span> <span class=\"quran-arabic-font text-success\">خَشْيَةِ</span> <span class=\"quran-arabic-font text-success\">اللَّهِ</span><br />\r\n<br />\r\n(இந்தக் குர்ஆனை ஒரு மலையின் மீது நாம் இறக்கியிருந்தால், அல்லாஹ்வின் அச்சத்தால் அது பணிந்து பிளந்து போவதை நீர் நிச்சயம் கண்டிருப்பீர்) (<a href=\"qurandisp.php?sura=59&ayah=21\" class=\"link\">59:21</a>).<br />\r\n<br />\r\nபின்னர், அவர்கள் இதை விரும்பி, இதைத் தாங்கி, பிறருக்குக் கொண்டு செல்லும் ஆற்றல் பெற்றிருந்தாலும், அவர்களால் அதைச் சாதிக்க முடியாது என்று அல்லாஹ் விளக்குகிறான். ஏனெனில், அல்லாஹ்வுடைய தூதர் (ஸல்) அவர்களுக்கு குர்ஆன் வஹீ (இறைச்செய்தி)யாக அருளப்பட்டுக் கொண்டிருந்த காலத்தில், வானங்கள் முழுமையாகப் பாதுகாப்பாளர்களாலும் எரிநட்சத்திரங்களாலும் நிரப்பப்பட்டிருந்தன. எனவே, எவ்விதக் குழப்பமும் ஏற்பட்டுவிடக் கூடாது என்பதற்காக, ஷைத்தான்களில் ஒருவரால் கூட அதன் ஓர் எழுத்தைக் கூடச் செவியேற்க முடியவில்லை. இது தனது அடியார்களுக்கு அல்லாஹ் காட்டிய பேரருளாகவும், தனது சட்டங்களைப் பாதுகாப்பதாகவும், தனது வேதத்திற்கும் தனது தூதர் (ஸல்) அவர்களுக்கு வழங்கிய ஆதரவாகவும் உள்ளது. அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">عَنِ</span> <span class=\"quran-arabic-font text-success\">السَّمْعِ</span> <span class=\"quran-arabic-font text-success\">لَمَعْزُولُونَ</span><br />\r\n<br />\r\n(நிச்சயமாக, அவர்கள் அதைச் செவியேற்பதிலிருந்து அப்புறப்படுத்தப்பட்டுள்ளனர்.)<br />\r\n<br />\r\nஇது, ஜின்களைப் பற்றி அல்லாஹ் நமக்குக் கூறுவதைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَنَّا</span> <span class=\"quran-arabic-font text-success\">لَمَسْنَا</span> <span class=\"quran-arabic-font text-success\">السَّمَآءَ</span> <span class=\"quran-arabic-font text-success\">فَوَجَدْنَاهَا</span> <span class=\"quran-arabic-font text-success\">مُلِئَتْ</span> <span class=\"quran-arabic-font text-success\">حَرَساً</span> <span class=\"quran-arabic-font text-success\">شَدِيداً</span> <span class=\"quran-arabic-font text-success\">وَشُهُباً</span> - <span class=\"quran-arabic-font text-success\">وَأَنَّا</span> <span class=\"quran-arabic-font text-success\">كُنَّا</span> <span class=\"quran-arabic-font text-success\">نَقْعُدُ</span> <span class=\"quran-arabic-font text-success\">مِنْهَا</span> <span class=\"quran-arabic-font text-success\">مَقَاعِدَ</span> <span class=\"quran-arabic-font text-success\">لِلسَّمْعِ</span> <span class=\"quran-arabic-font text-success\">فَمَن</span> <span class=\"quran-arabic-font text-success\">يَسْتَمِعِ</span> <span class=\"quran-arabic-font text-success\">الآنَ</span> <span class=\"quran-arabic-font text-success\">يَجِدْ</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">شِهَاباً</span> <span class=\"quran-arabic-font text-success\">رَّصَداً</span> - <span class=\"quran-arabic-font text-success\">وَأَنَّا</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">نَدْرِى</span> <span class=\"quran-arabic-font text-success\">أَشَرٌّ</span> <span class=\"quran-arabic-font text-success\">أُرِيدَ</span> <span class=\"quran-arabic-font text-success\">بِمَن</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">الأَرْضِ</span> <span class=\"quran-arabic-font text-success\">أَمْ</span> <span class=\"quran-arabic-font text-success\">أَرَادَ</span> <span class=\"quran-arabic-font text-success\">بِهِمْ</span> <span class=\"quran-arabic-font text-success\">رَبُّهُمْ</span> <span class=\"quran-arabic-font text-success\">رَشَداً</span><br />\r\n<br />\r\n“நிச்சயமாக நாங்கள் வானத்தைத் தொட்டுப் பார்த்தோம்; ஆனால் அது கடுமையான காவலாளிகளாலும் எரிநட்சத்திரங்களாலும் நிரப்பப்பட்டிருப்பதை நாங்கள் கண்டோம். மேலும், (செய்திகளைச்) செவியேற்பதற்காக அங்குள்ள சில இடங்களில் நாங்கள் அமர்ந்திருப்போம். ஆனால், இப்போது யாராவது செவியேற்க முயன்றால், அவர் தமக்காகக் காத்திருக்கும் ஓர் எரிநட்சத்திரத்தையே காண்பார். பூமியிலுள்ளவர்களுக்குத் தீங்கு நாடப்பட்டுள்ளதா? அல்லது அவர்களுடைய இறைவன் அவர்களுக்கு நேர்வழியை நாடினானா? (என்பதை நாங்கள் அறியமாட்டோம்)” <a href=\"qurandisp.php?sura=72&ayah=8\" class=\"link\">72:8</a>-10 வரை.<br />\r\n<br />\r\n<br />\r\n<br />","text":"குர்ஆன் ஜிப்ரீல் (அலை) அவர்களால்தான் கொண்டு வரப்பட்டது, ஷைத்தான்களால் அல்ல\n\r\n\n\r\nஅல்லாஹ் தன் வேதத்தைப் பற்றி நமக்குக் கூறுகிறான். அதற்கு முன்னாலோ பின்னாலோ எந்த அசத்தியமும் அதை நெருங்க முடியாது. அது மகா ஞானவானும் புகழுக்குரியவனுமான (அல்லாஹ்வால்) அருளப்பட்டது. மேலும், அது அல்லாஹ்வினால் உதவி வழங்கப்பட்ட, நம்பிக்கைக்குரிய ரூஹ் (அதாவது ஜிப்ரீல் (அலை)) அவர்களால் கொண்டு வரப்பட்டது என்று அவன் கூறுகிறான்.\n\r\n\n\r\nوَمَا تَنَزَّلَتْ بِهِ الشَّيَاطِينُ\n\r\n\n\r\n(மேலும், இதனை ஷைத்தான்கள் கொண்டு வரவில்லை.)\n\r\n\n\r\nபின்னர், ஷைத்தான்கள் இதைக் கொண்டு வரவில்லை என்பதற்கு மூன்று காரணங்கள் இருப்பதாக அவன் கூறுகிறான். முதலாவது, அது அவர்களுக்குப் பொருத்தமானது அல்ல; அதாவது, அவர்களுக்கு அப்படிச் செய்வதற்கு விருப்பமும் இல்லை, தேவையும் இல்லை. ஏனெனில், மக்களின் குணத்தைக் கெடுப்பதும் அவர்களை வழிதவறச் செய்வதுமே ஷைத்தான்களின் இயல்பாகும். ஆனால், இந்த வேதமோ நன்மையை ஏவி, தீமையைத் தடுத்து, ஒளி, நேர்வழி மற்றும் வலிமையான சான்றுகளைக் கொண்டுள்ளது. இதற்கும் ஷைத்தான்களுக்கும் இடையே மிகப்பெரிய வேறுபாடு உள்ளது. அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nوَمَا يَنبَغِى لَهُمْ\n\r\n\n\r\n(அது அவர்களுக்குப் பொருத்தமானதும் அல்ல)\n\r\n\n\r\nوَمَا يَسْتَطِيعُونَ\n\r\n\n\r\n(அவர்களுக்கு அதற்குச் சக்தியும் இல்லை.)\n\r\n\n\r\nஅதாவது, அவர்கள் விரும்பினாலும் அவர்களால் அதைச் செய்ய முடியாது. அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nلَوْ أَنزَلْنَا هَذَا الْقُرْآنَ عَلَى جَبَلٍ لَّرَأَيْتَهُ خَاشِعاً مُّتَصَدِّعاً مِّنْ خَشْيَةِ اللَّهِ\n\r\n\n\r\n(இந்தக் குர்ஆனை ஒரு மலையின் மீது நாம் இறக்கியிருந்தால், அல்லாஹ்வின் அச்சத்தால் அது பணிந்து பிளந்து போவதை நீர் நிச்சயம் கண்டிருப்பீர்) (59:21).\n\r\n\n\r\nபின்னர், அவர்கள் இதை விரும்பி, இதைத் தாங்கி, பிறருக்குக் கொண்டு செல்லும் ஆற்றல் பெற்றிருந்தாலும், அவர்களால் அதைச் சாதிக்க முடியாது என்று அல்லாஹ் விளக்குகிறான். ஏனெனில், அல்லாஹ்வுடைய தூதர் (ஸல்) அவர்களுக்கு குர்ஆன் வஹீ (இறைச்செய்தி)யாக அருளப்பட்டுக் கொண்டிருந்த காலத்தில், வானங்கள் முழுமையாகப் பாதுகாப்பாளர்களாலும் எரிநட்சத்திரங்களாலும் நிரப்பப்பட்டிருந்தன. எனவே, எவ்விதக் குழப்பமும் ஏற்பட்டுவிடக் கூடாது என்பதற்காக, ஷைத்தான்களில் ஒருவரால் கூட அதன் ஓர் எழுத்தைக் கூடச் செவியேற்க முடியவில்லை. இது தனது அடியார்களுக்கு அல்லாஹ் காட்டிய பேரருளாகவும், தனது சட்டங்களைப் பாதுகாப்பதாகவும், தனது வேதத்திற்கும் தனது தூதர் (ஸல்) அவர்களுக்கு வழங்கிய ஆதரவாகவும் உள்ளது. அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nإِنَّهُمْ عَنِ السَّمْعِ لَمَعْزُولُونَ\n\r\n\n\r\n(நிச்சயமாக, அவர்கள் அதைச் செவியேற்பதிலிருந்து அப்புறப்படுத்தப்பட்டுள்ளனர்.)\n\r\n\n\r\nஇது, ஜின்களைப் பற்றி அல்லாஹ் நமக்குக் கூறுவதைப் போன்றதாகும்:\n\r\n\n\r\nوَأَنَّا لَمَسْنَا السَّمَآءَ فَوَجَدْنَاهَا مُلِئَتْ حَرَساً شَدِيداً وَشُهُباً - وَأَنَّا كُنَّا نَقْعُدُ مِنْهَا مَقَاعِدَ لِلسَّمْعِ فَمَن يَسْتَمِعِ الآنَ يَجِدْ لَهُ شِهَاباً رَّصَداً - وَأَنَّا لاَ نَدْرِى أَشَرٌّ أُرِيدَ بِمَن فِى الأَرْضِ أَمْ أَرَادَ بِهِمْ رَبُّهُمْ رَشَداً\n\r\n\n\r\n“நிச்சயமாக நாங்கள் வானத்தைத் தொட்டுப் பார்த்தோம்; ஆனால் அது கடுமையான காவலாளிகளாலும் எரிநட்சத்திரங்களாலும் நிரப்பப்பட்டிருப்பதை நாங்கள் கண்டோம். மேலும், (செய்திகளைச்) செவியேற்பதற்காக அங்குள்ள சில இடங்களில் நாங்கள் அமர்ந்திருப்போம். ஆனால், இப்போது யாராவது செவியேற்க முயன்றால், அவர் தமக்காகக் காத்திருக்கும் ஓர் எரிநட்சத்திரத்தையே காண்பார். பூமியிலுள்ளவர்களுக்குத் தீங்கு நாடப்பட்டுள்ளதா? அல்லது அவர்களுடைய இறைவன் அவர்களுக்கு நேர்வழியை நாடினானா? (என்பதை நாங்கள் அறியமாட்டோம்)” 72:8-10 வரை."},"213":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=220\" class=\"link\">26:220</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:220 ஐ பார்க்கவும்"},"214":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=220\" class=\"link\">26:220</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:220 ஐ பார்க்கவும்"},"215":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=220\" class=\"link\">26:220</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:220 ஐ பார்க்கவும்"},"216":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=220\" class=\"link\">26:220</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:220 ஐ பார்க்கவும்"},"217":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=220\" class=\"link\">26:220</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:220 ஐ பார்க்கவும்"},"218":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=220\" class=\"link\">26:220</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:220 ஐ பார்க்கவும்"},"219":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=220\" class=\"link\">26:220</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:220 ஐ பார்க்கவும்"},"220":{"html":"<strong>தனது நெருங்கிய உறவினர்களை எச்சரிக்கும் கட்டளை</strong><br />\r\n<br />\r\nஇங்கே அல்லாஹ் (தன்னுடைய தூதரை) எவ்வித இணை துணையுமின்றி தன்னை மட்டுமே வணங்குமாறு கட்டளையிடுகிறான். மேலும், எவரேனும் அவனுக்கு இணையாக மற்றவர்களை வணங்கினால், அவர்களை அவன் தண்டிப்பான் என்றும் கூறுகிறான். பின்னர் அல்லாஹ், தனது தூதரை (ஸல்) அவரது நெருங்கிய உறவினர்களை எச்சரிக்குமாறும், அதாவது அவருக்கு மிக நெருக்கமானவர்களுக்கு அல்லாஹ்வின் மீதான ஈமானைத் (நம்பிக்கை) தவிர வேறு எதுவும் அவர்களைக் காப்பாற்றாது என்று கூறுமாறும் கட்டளையிட்டான். மேலும், தன்னைத் தற்கொண்ட (பின்பற்றிய) இறைநம்பிக்கையாளர்களிடம் அன்பாகவும் மென்மையாகவும் நடந்து கொள்ளுமாறும் <span class=\"quran-arabic-font text-success\">وَاخْفِضْ</span> <span class=\"quran-arabic-font text-success\">جَنَاحَكَ</span> <span class=\"quran-arabic-font text-success\">لِمَنِ</span> <span class=\"quran-arabic-font text-success\">اتَّبَعَكَ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنِينَ</span>, தனக்கு மாறுசெய்பவர்கள் யாராக இருந்தாலும் அவர்களைத் துண்டித்துக் கொள்ளுமாறும் அல்லாஹ் அவருக்குக் கட்டளையிட்டான். அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">فَإِنْ</span> <span class=\"quran-arabic-font text-success\">عَصَوْكَ</span> <span class=\"quran-arabic-font text-success\">فَقُلْ</span> <span class=\"quran-arabic-font text-success\">إِنِّى</span> <span class=\"quran-arabic-font text-success\">بَرِىءٌ</span> <span class=\"quran-arabic-font text-success\">مِّمَّا</span> <span class=\"quran-arabic-font text-success\">تَعْمَلُونَ</span><br />\r\n<br />\r\n(அவர்கள் உங்களுக்கு மாறுசெய்தால், \"நிச்சயமாக நீங்கள் செய்பவற்றிலிருந்து நான் விலகியவன்\" என்று கூறிவிடுவீராக.) இந்தக் குறிப்பிட்ட எச்சரிக்கை பொதுவான எச்சரிக்கைக்கு முரணானது அல்ல; உண்மையில் அது அதன் ஒரு பகுதியாகும். அல்லாஹ் பிறிதொரு இடத்தில் இவ்வாறு கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِتُنذِرَ</span> <span class=\"quran-arabic-font text-success\">قَوْماً</span> <span class=\"quran-arabic-font text-success\">مَّآ</span> <span class=\"quran-arabic-font text-success\">أُنذِرَ</span> <span class=\"quran-arabic-font text-success\">ءَابَآؤُهُمْ</span> <span class=\"quran-arabic-font text-success\">فَهُمْ</span> <span class=\"quran-arabic-font text-success\">غَـفِلُونَ</span><br />\r\n<br />\r\n(எச்சரிக்கப்படாத மூதாதையர்களைக் கொண்ட ஒரு சமூகத்தை நீர் எச்சரிப்பதற்காக, எனவே அவர்கள் கவனமற்றவர்களாக இருக்கிறார்கள்.) (<a href=\"qurandisp.php?sura=36&ayah=6\" class=\"link\">36:6</a>),<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِّتُنذِرَ</span> <span class=\"quran-arabic-font text-success\">أُمَّ</span> <span class=\"quran-arabic-font text-success\">الْقُرَى</span> <span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">حَوْلَهَا</span><br />\r\n<br />\r\n(நகரங்களின் தாய் (மக்கா) மற்றும் அதன் சுற்றுப்புறங்களில் உள்ளவர்களை நீர் எச்சரிப்பதற்காக) (<a href=\"qurandisp.php?sura=42&ayah=7\" class=\"link\">42:7</a>),<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَنذِرْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">يَخَافُونَ</span> <span class=\"quran-arabic-font text-success\">أَن</span> <span class=\"quran-arabic-font text-success\">يُحْشَرُواْ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">رَبِّهِمْ</span><br />\r\n<br />\r\n(தங்கள் இறைவனிடம் ஒன்றுதிரட்டப்படுவோம் என்று அஞ்சுபவர்களை இதன் மூலம் எச்சரிப்பீராக) (<a href=\"qurandisp.php?sura=6&ayah=51\" class=\"link\">6:51</a>),<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِتُبَشِّرَ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">الْمُتَّقِينَ</span> <span class=\"quran-arabic-font text-success\">وَتُنْذِرَ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">قَوْماً</span> <span class=\"quran-arabic-font text-success\">لُّدّاً</span><br />\r\n<br />\r\n(இறையச்சம் உடையவர்களுக்கு இதன் மூலம் நற்செய்தி கூறவும், பிடிவாதமாகத் தர்க்கம் புரியும் மக்களை எச்சரிக்கவும்.) (<a href=\"qurandisp.php?sura=19&ayah=97\" class=\"link\">19:97</a>),<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">لِأُنذِرَكُم</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">بَلَغَ</span><br />\r\n<br />\r\n(உங்களையும், இது யாரைச் சென்றடைகிறதோ அவர்களையும் இதன் மூலம் நான் எச்சரிப்பதற்காக) (<a href=\"qurandisp.php?sura=6&ayah=19\" class=\"link\">6:19</a>), மற்றும்<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَن</span> <span class=\"quran-arabic-font text-success\">يَكْفُرْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْأَحْزَابِ</span> <span class=\"quran-arabic-font text-success\">فَالنَّارُ</span> <span class=\"quran-arabic-font text-success\">مَوْعِدُهُ</span><br />\r\n<br />\r\n(ஆனால், பல்வேறு பிரிவினர்களில் எவர் இதை நிராகரிக்கிறார்களோ, அவர்களுக்கு வாக்களிக்கப்பட்ட இடம் நரக நெருப்பாகும்) (<a href=\"qurandisp.php?sura=11&ayah=17\" class=\"link\">11:17</a>). ஸஹீஹ் முஸ்லிமில் பதிவாகியுள்ளபடி, நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">وَالَّذِي</span> <span class=\"quran-arabic-font text-success\">نَفْسِي</span> <span class=\"quran-arabic-font text-success\">بِيَدِهِ،</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">يَسْمَعُ</span> <span class=\"quran-arabic-font text-success\">بِي</span> <span class=\"quran-arabic-font text-success\">أَحَدٌ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">هَذِهِ</span> <span class=\"quran-arabic-font text-success\">الْأُمَّةِ</span> <span class=\"quran-arabic-font text-success\">يَهُودِيٌّ</span> <span class=\"quran-arabic-font text-success\">وَلَا</span> <span class=\"quran-arabic-font text-success\">نَصْرَانِيٌّ،</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يَمُوتُ</span> <span class=\"quran-arabic-font text-success\">وَلَمْ</span> <span class=\"quran-arabic-font text-success\">يُؤْمِنْ</span> <span class=\"quran-arabic-font text-success\">بِالَّذِي</span> <span class=\"quran-arabic-font text-success\">أُرْسِلْتُ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">كَانَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">أَصْحَابِ</span> <span class=\"quran-arabic-font text-success\">النَّارِ</span>»<br />\r\n<br />\r\n(என் உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது சத்தியமாக, இந்தச் சமூகத்தைச் சேர்ந்த யூதரோ அல்லது கிறிஸ்தவரோ என்னைப் பற்றிக் கேள்விப்பட்டு, பிறகு நான் கொண்டு வந்தவற்றின் மீது நம்பிக்கை கொள்ளாமல் மரணித்தால், அவர் நரக நெருப்பில் நுழைந்தே தீருவார்.)<br />\r\n<br />\r\nஇந்த வசனம் வஹீ (இறைச்செய்தி)யாக அருளப்பட்டது தொடர்பாக பல ஹதீஸ்கள் அறிவிக்கப்பட்டுள்ளன, அவற்றில் சிலவற்றை கீழே காண்போம்: இமாம் அஹ்மத் (அல்லாஹ் அவர் மீது ரஹ்மத் செய்வானாக) அவர்கள் பதிவு செய்துள்ளார்கள், இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"அல்லாஹ்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَنذِرْ</span> <span class=\"quran-arabic-font text-success\">عَشِيرَتَكَ</span> <span class=\"quran-arabic-font text-success\">الْأَقْرَبِينَ</span><br />\r\n<br />\r\n(உமது நெருங்கிய உறவினர்களை எச்சரிப்பீராக) என்ற வசனத்தை அருளியபோது, நபி (ஸல்) அவர்கள் ஸஃபா மலைக்குச் சென்று, அதன் மீது ஏறி,<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">صَبَاحَاه</span>»<br />\r\n<br />\r\n(ஓ மக்களே!) என்று சத்தமிட்டு அழைத்தார்கள். மக்கள் அவர்களைச் சூழ்ந்து கொண்டனர். சிலர் தாங்களாகவே வந்தனர், சிலர் என்ன நடக்கிறது என்பதை அறிய தங்கள் பிரதிநிதிகளை அனுப்பினார்கள். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">بَنِي</span> <span class=\"quran-arabic-font text-success\">عَبْدِالْمُطَّلِبِ،</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">بَنِي</span> <span class=\"quran-arabic-font text-success\">فِهْرٍ،</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">بَنِي</span> <span class=\"quran-arabic-font text-success\">لُؤَيَ،</span> <span class=\"quran-arabic-font text-success\">أَرَأَيْتُمْ</span> <span class=\"quran-arabic-font text-success\">لَوْ</span> <span class=\"quran-arabic-font text-success\">أَخْبَرْتُكُمْ</span> <span class=\"quran-arabic-font text-success\">أَنَّ</span> <span class=\"quran-arabic-font text-success\">خَيْلًا</span> <span class=\"quran-arabic-font text-success\">بِسَفْحِ</span> <span class=\"quran-arabic-font text-success\">هَذَا</span> <span class=\"quran-arabic-font text-success\">الْجَبَلِ</span> <span class=\"quran-arabic-font text-success\">تُريدُ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">تُغِيرَ</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">صَدَّقْتُمُونِي؟</span>»<br />\r\n<br />\r\n(ஓ பனீ அப்துல் முத்தலிப், ஓ பனீ ஃபிஹ்ர், ஓ பனீ லுஅய்! இந்த மலையின் அடிவாரத்தில் உங்களைத் தாக்க ஒரு குதிரைப்படை காத்துக் கொண்டிருக்கிறது என்று நான் கூறினால், நீங்கள் என்னை நம்புவீர்களா?) அதற்கு அவர்கள், \"ஆம்\" என்றனர். அவர்கள் (ஸல்) கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">فَإِنِّي</span> <span class=\"quran-arabic-font text-success\">نَذِيرٌ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">يَدَي</span> <span class=\"quran-arabic-font text-success\">عَذَابٍ</span> <span class=\"quran-arabic-font text-success\">شَدِيد</span>»<br />\r\n<br />\r\n(நிச்சயமாக நான் கடுமையான வேதனை உங்களுக்கு முன்னால் இருக்கிறது என்று உங்களை எச்சரிப்பவன் ஆவேன்.) அப்போது அபூ லஹப், \"இந்த நாள் முழுவதும் நீ நாசமடைவாயாக! இதற்காகவா எங்களை அழைத்தாய்?\" என்று கூறினான். பின்னர் அல்லாஹ் இந்த வசனத்தை அருளினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">تَبَّتْ</span> <span class=\"quran-arabic-font text-success\">يَدَآ</span> <span class=\"quran-arabic-font text-success\">أَبِى</span> <span class=\"quran-arabic-font text-success\">لَهَبٍ</span> <span class=\"quran-arabic-font text-success\">وَتَبَّ</span><br />\r\n<br />\r\n(அபூ லஹபின் இரு கைகளும் நாசமாகட்டும்; அவனும் நாசமாகிவிட்டான்!) <a href=\"qurandisp.php?sura=111&ayah=1\" class=\"link\">111:1</a>. இது புகாரீ, முஸ்லிம், திர்மிதீ மற்றும் நஸாயீ ஆகிய நூல்களிலும் பதிவாகியுள்ளது.<br />\r\n<br />\r\nஇமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளார்கள், ஆயிஷா (ரழி) அவர்கள் கூறினார்கள்: \"உமது நெருங்கிய உறவினர்களை எச்சரிப்பீராக என்ற வசனம் அருளப்பட்டபோது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَنذِرْ</span> <span class=\"quran-arabic-font text-success\">عَشِيرَتَكَ</span> <span class=\"quran-arabic-font text-success\">الْأَقْرَبِينَ</span><br />\r\n<br />\r\nஅல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் எழுந்து நின்று கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">فَاطِمَةُ</span> <span class=\"quran-arabic-font text-success\">ابْنَةُ</span> <span class=\"quran-arabic-font text-success\">مُحَمَّدٍ،</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">صَفِيَّةُ</span> <span class=\"quran-arabic-font text-success\">ابْنَةُ</span> <span class=\"quran-arabic-font text-success\">عَبْدِالْمُطَّلِبِ،</span> <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">بَنِي</span> <span class=\"quran-arabic-font text-success\">عَبْدِالْمُطَّلِبِ،</span> <span class=\"quran-arabic-font text-success\">لَا</span> <span class=\"quran-arabic-font text-success\">أَمْلِكُ</span> <span class=\"quran-arabic-font text-success\">لَكُمْ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">اللهِ</span> <span class=\"quran-arabic-font text-success\">شَيْئًا</span> <span class=\"quran-arabic-font text-success\">سَلُونِي</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">مَالِي</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">شِئْتُم</span>»<br />\r\n<br />\r\n(ஓ முஹம்மதின் மகள் ஃபாத்திமாவே! ஓ அப்துல் முத்தலிபின் மகள் ஸஃபிய்யாவே! ஓ பனீ அப்துல் முத்தலிப் சமூகத்தாரே! அல்லாஹ்வின் தண்டனையிலிருந்து உங்களை ஒருபோதும் என்னால் காப்பாற்ற முடியாது. எனது செல்வத்திலிருந்து நீங்கள் விரும்புவதை என்னிடம் கேட்டுப் பெற்றுக் கொள்ளுங்கள்.) இது முஸ்லிமில் பதிவாகியுள்ளது.<br />\r\n<br />\r\nஇமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளார்கள், கபீஸா பின் முகாரிக் (ரழி) மற்றும் ஸுஹைர் பின் அம்ர் (ரழி) ஆகியோர் கூறினார்கள்: \"உமது நெருங்கிய உறவினர்களை எச்சரிப்பீராக என்ற வசனம் அருளப்பட்டபோது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَنذِرْ</span> <span class=\"quran-arabic-font text-success\">عَشِيرَتَكَ</span> <span class=\"quran-arabic-font text-success\">الْأَقْرَبِينَ</span><br />\r\n<br />\r\nஅல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஒரு மலையின் உச்சியில் இருந்த பாறையின் மீது ஏறி இவ்வாறு அழைக்கத் தொடங்கினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">بَنِي</span> <span class=\"quran-arabic-font text-success\">عَبْدِ</span> <span class=\"quran-arabic-font text-success\">مَنَافٍ،</span> <span class=\"quran-arabic-font text-success\">إِنَّمَا</span> <span class=\"quran-arabic-font text-success\">أَنَا</span> <span class=\"quran-arabic-font text-success\">نَذِيرٌ،</span> <span class=\"quran-arabic-font text-success\">وَإِنَّمَا</span> <span class=\"quran-arabic-font text-success\">مَثَلِي</span> <span class=\"quran-arabic-font text-success\">وَمَثَلُكُمْ</span> <span class=\"quran-arabic-font text-success\">كَرَجُلٍ</span> <span class=\"quran-arabic-font text-success\">رَأَى</span> <span class=\"quran-arabic-font text-success\">الْعَدُوَّ</span> <span class=\"quran-arabic-font text-success\">فَذَهَبَ</span> <span class=\"quran-arabic-font text-success\">يَرْبَأُ</span> <span class=\"quran-arabic-font text-success\">أَهْلَهُ</span> <span class=\"quran-arabic-font text-success\">يَخْشَى</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يَسْبِقُوهُ،</span> <span class=\"quran-arabic-font text-success\">فَجَعَلَ</span> <span class=\"quran-arabic-font text-success\">يُنَادِي</span> <span class=\"quran-arabic-font text-success\">وَيَهْتِفُ</span>: <span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">صَبَاحَاه</span>»<br />\r\n<br />\r\n(ஓ பனீ அப்து மனாஃப்! நிச்சயமாக நான் உங்களை எச்சரிப்பவன். எனக்கும் உங்களுக்குமான உவமை, எதிரி வருவதைக் கண்ட ஒரு மனிதன், அவர்கள் தன் குடும்பத்தை அடைவதற்குள் அவர்களைக் காப்பாற்ற ஓடிச் சென்று, 'ஓ மக்களே!' என்று சத்தமிட்டு எச்சரிப்பதைப் போன்றதாகும்.) இது முஸ்லிம் மற்றும் நஸாயீயிலும் பதிவாகியுள்ளது.<br />\r\n<br />\r\nஅல்லாஹ்வின் கூற்று:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَتَوَكَّلْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">الْعَزِيزِ</span> <span class=\"quran-arabic-font text-success\">الرَّحِيمِ</span><br />\r\n<br />\r\n(மேலும் மிகைத்தவனும், மகா கருணையாளனுமானவன் மீது நம்பிக்கை வைப்பீராக,) இதன் பொருள்: உமது எல்லா விவகாரங்களிலும் அவனையே சார்ந்திருப்பீராக; ஏனெனில் அவன்தான் உமது உதவியாளனும், பாதுகாவலனும், உமக்கு ஆதரவளிப்பவனுமாவான். அவன் உம்மை வெற்றிபெறச் செய்து, உமது வாக்கை மேலோங்கச் செய்வான்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">يَرَاكَ</span> <span class=\"quran-arabic-font text-success\">حِينَ</span> <span class=\"quran-arabic-font text-success\">تَقُومُ</span><br />\r\n<br />\r\n(நீர் தொழுகைக்காக எழும்போது அவன் உம்மைப் பார்க்கிறான்.) அதாவது, அவன் உம்மைப் பாதுகாத்துக் கொண்டிருக்கிறான். இது பின்வரும் வசனத்தைப் போன்றதாகும்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَاصْبِرْ</span> <span class=\"quran-arabic-font text-success\">لِحُكْمِ</span> <span class=\"quran-arabic-font text-success\">رَبِّكَ</span> <span class=\"quran-arabic-font text-success\">فَإِنَّكَ</span> <span class=\"quran-arabic-font text-success\">بِأَعْيُنِنَا</span><br />\r\n<br />\r\n(நீர் உமது இறைவனின் தீர்ப்புக்காகப் பொறுத்திருப்பீராக; நிச்சயமாக நீர் நம் கண் முன்னே (நம் பாதுகாப்பில்) இருக்கிறீர்) (<a href=\"qurandisp.php?sura=52&ayah=48\" class=\"link\">52:48</a>). இப்னு அப்பாஸ் (ரழி) அவர்கள்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">يَرَاكَ</span> <span class=\"quran-arabic-font text-success\">حِينَ</span> <span class=\"quran-arabic-font text-success\">تَقُومُ</span><br />\r\n<br />\r\n(நீர் தொழுகைக்காக எழும்போது அவன் உம்மைப் பார்க்கிறான்) என்பதற்கு 'தொழுகைக்காக நிற்பது' என்று பொருள் கூறினார்கள். இக்ரிமா (ரஹ்) அவர்கள் கூறினார்கள்: \"அவர் நிற்கும்போதும், ருகூஉ (குனிதல்), ஸஜ்தா (சிரம் பணிதல்) செய்யும்போதும் அவன் அவரைப் பார்க்கிறான்.\" அல்-ஹஸன் (ரஹ்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">يَرَاكَ</span> <span class=\"quran-arabic-font text-success\">حِينَ</span> <span class=\"quran-arabic-font text-success\">تَقُومُ</span><br />\r\n<br />\r\n(நீர் தொழுகைக்காக எழும்போது அவன் உம்மைப் பார்க்கிறான்.) \"நீர் தனியாகத் தொழும்போது.\" அத்-தஹ்ஹாக் (ரஹ்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">يَرَاكَ</span> <span class=\"quran-arabic-font text-success\">حِينَ</span> <span class=\"quran-arabic-font text-success\">تَقُومُ</span><br />\r\n<br />\r\n(நீர் தொழுகைக்காக எழும்போது அவன் உம்மைப் பார்க்கிறான்.) \"நீர் படுக்கையில் இருக்கும்போதும், அமர்ந்திருக்கும்போதும்.\" கதாதா (ரஹ்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">يَرَاكَ</span><br />\r\n<br />\r\n(அவன் உம்மைப் பார்க்கிறான்) \"நீர் நிற்கும்போதும், அமர்ந்திருக்கும்போதும் மற்றும் எல்லா நிலைகளிலும்.\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَتَقَلُّبَكَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">السَّـجِدِينَ</span><br />\r\n<br />\r\n(மேலும் ஸஜ்தா செய்வோரிடையே உமது அசைவுகளையும்.) கதாதா (ரஹ்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">الَّذِى</span> <span class=\"quran-arabic-font text-success\">يَرَاكَ</span> <span class=\"quran-arabic-font text-success\">حِينَ</span> <span class=\"quran-arabic-font text-success\">تَقُومُ</span><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَتَقَلُّبَكَ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">السَّـجِدِينَ</span><br />\r\n<br />\r\n(நீர் தொழுகைக்காக எழும்போது அவன் உம்மைப் பார்க்கிறான். மேலும் ஸஜ்தா செய்வோரிடையே உமது அசைவுகளையும்.) \"நீர் தொழும்போது, நீர் தனியாகத் தொழுதாலும் ஜமாஅத்தாகத் தொழுதாலும் அவன் உம்மைப் பார்க்கிறான்.\" இதுவே இக்ரிமா (ரஹ்), அதா அல்-குராஸானீ (ரஹ்) மற்றும் அல்-ஹஸன் அல்-பஸரீ (ரஹ்) ஆகியோரின் கருத்தாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">السَّمِيعُ</span> <span class=\"quran-arabic-font text-success\">الْعَلِيمُ</span><br />\r\n<br />\r\n(நிச்சயமாக அவனே அனைத்தையும் செவியுறுபவனும், நன்கறிந்தவனுமாவான்.) அவன் தனது அடியார்களின் பேச்சுகள் அனைத்தையும் செவியுறுகிறான்; அவர்களின் அசைவுகள் அனைத்தையும் அறிகிறான். அவன் கூறுவது போல:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">تَكُونُ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">شَأْنٍ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">تَتْلُواْ</span> <span class=\"quran-arabic-font text-success\">مِنْهُ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">قُرْءَانٍ</span> <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">تَعْمَلُونَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">عَمَلٍ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">كُنَّا</span> <span class=\"quran-arabic-font text-success\">عَلَيْكُمْ</span> <span class=\"quran-arabic-font text-success\">شُهُودًا</span> <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">تُفِيضُونَ</span> <span class=\"quran-arabic-font text-success\">فِيهِ</span><br />\r\n<br />\r\n(நீர் எந்த நிலையில் இருந்தாலும், குர்ஆனிலிருந்து எதை ஓதினாலும், நீங்கள் எந்தச் செயலைச் செய்தாலும், நீங்கள் அதில் ஈடுபட்டிருக்கும்போது நாம் உங்களுக்குச் சாட்சியாகவே இருக்கிறோம்) (<a href=\"qurandisp.php?sura=10&ayah=61\" class=\"link\">10:61</a>).<br />\r\n<br />","text":"தனது நெருங்கிய உறவினர்களை எச்சரிக்கும் கட்டளை\n\r\n\n\r\nஇங்கே அல்லாஹ் (தன்னுடைய தூதரை) எவ்வித இணை துணையுமின்றி தன்னை மட்டுமே வணங்குமாறு கட்டளையிடுகிறான். மேலும், எவரேனும் அவனுக்கு இணையாக மற்றவர்களை வணங்கினால், அவர்களை அவன் தண்டிப்பான் என்றும் கூறுகிறான். பின்னர் அல்லாஹ், தனது தூதரை (ஸல்) அவரது நெருங்கிய உறவினர்களை எச்சரிக்குமாறும், அதாவது அவருக்கு மிக நெருக்கமானவர்களுக்கு அல்லாஹ்வின் மீதான ஈமானைத் (நம்பிக்கை) தவிர வேறு எதுவும் அவர்களைக் காப்பாற்றாது என்று கூறுமாறும் கட்டளையிட்டான். மேலும், தன்னைத் தற்கொண்ட (பின்பற்றிய) இறைநம்பிக்கையாளர்களிடம் அன்பாகவும் மென்மையாகவும் நடந்து கொள்ளுமாறும் وَاخْفِضْ جَنَاحَكَ لِمَنِ اتَّبَعَكَ مِنَ الْمُؤْمِنِينَ, தனக்கு மாறுசெய்பவர்கள் யாராக இருந்தாலும் அவர்களைத் துண்டித்துக் கொள்ளுமாறும் அல்லாஹ் அவருக்குக் கட்டளையிட்டான். அல்லாஹ் கூறினான்:\n\r\n\n\r\nفَإِنْ عَصَوْكَ فَقُلْ إِنِّى بَرِىءٌ مِّمَّا تَعْمَلُونَ\n\r\n\n\r\n(அவர்கள் உங்களுக்கு மாறுசெய்தால், \"நிச்சயமாக நீங்கள் செய்பவற்றிலிருந்து நான் விலகியவன்\" என்று கூறிவிடுவீராக.) இந்தக் குறிப்பிட்ட எச்சரிக்கை பொதுவான எச்சரிக்கைக்கு முரணானது அல்ல; உண்மையில் அது அதன் ஒரு பகுதியாகும். அல்லாஹ் பிறிதொரு இடத்தில் இவ்வாறு கூறுகிறான்:\n\r\n\n\r\nلِتُنذِرَ قَوْماً مَّآ أُنذِرَ ءَابَآؤُهُمْ فَهُمْ غَـفِلُونَ\n\r\n\n\r\n(எச்சரிக்கப்படாத மூதாதையர்களைக் கொண்ட ஒரு சமூகத்தை நீர் எச்சரிப்பதற்காக, எனவே அவர்கள் கவனமற்றவர்களாக இருக்கிறார்கள்.) (36:6),\n\r\n\n\r\nلِّتُنذِرَ أُمَّ الْقُرَى وَمَنْ حَوْلَهَا\n\r\n\n\r\n(நகரங்களின் தாய் (மக்கா) மற்றும் அதன் சுற்றுப்புறங்களில் உள்ளவர்களை நீர் எச்சரிப்பதற்காக) (42:7),\n\r\n\n\r\nوَأَنذِرْ بِهِ الَّذِينَ يَخَافُونَ أَن يُحْشَرُواْ إِلَى رَبِّهِمْ\n\r\n\n\r\n(தங்கள் இறைவனிடம் ஒன்றுதிரட்டப்படுவோம் என்று அஞ்சுபவர்களை இதன் மூலம் எச்சரிப்பீராக) (6:51),\n\r\n\n\r\nلِتُبَشِّرَ بِهِ الْمُتَّقِينَ وَتُنْذِرَ بِهِ قَوْماً لُّدّاً\n\r\n\n\r\n(இறையச்சம் உடையவர்களுக்கு இதன் மூலம் நற்செய்தி கூறவும், பிடிவாதமாகத் தர்க்கம் புரியும் மக்களை எச்சரிக்கவும்.) (19:97),\n\r\n\n\r\nلِأُنذِرَكُم بِهِ وَمَن بَلَغَ\n\r\n\n\r\n(உங்களையும், இது யாரைச் சென்றடைகிறதோ அவர்களையும் இதன் மூலம் நான் எச்சரிப்பதற்காக) (6:19), மற்றும்\n\r\n\n\r\nوَمَن يَكْفُرْ بِهِ مِنَ الْأَحْزَابِ فَالنَّارُ مَوْعِدُهُ\n\r\n\n\r\n(ஆனால், பல்வேறு பிரிவினர்களில் எவர் இதை நிராகரிக்கிறார்களோ, அவர்களுக்கு வாக்களிக்கப்பட்ட இடம் நரக நெருப்பாகும்) (11:17). ஸஹீஹ் முஸ்லிமில் பதிவாகியுள்ளபடி, நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«وَالَّذِي نَفْسِي بِيَدِهِ، لَا يَسْمَعُ بِي أَحَدٌ مِنْ هَذِهِ الْأُمَّةِ يَهُودِيٌّ وَلَا نَصْرَانِيٌّ، ثُمَّ يَمُوتُ وَلَمْ يُؤْمِنْ بِالَّذِي أُرْسِلْتُ بِهِ إِلَّا كَانَ مِنْ أَصْحَابِ النَّارِ»\n\r\n\n\r\n(என் உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது சத்தியமாக, இந்தச் சமூகத்தைச் சேர்ந்த யூதரோ அல்லது கிறிஸ்தவரோ என்னைப் பற்றிக் கேள்விப்பட்டு, பிறகு நான் கொண்டு வந்தவற்றின் மீது நம்பிக்கை கொள்ளாமல் மரணித்தால், அவர் நரக நெருப்பில் நுழைந்தே தீருவார்.)\n\r\n\n\r\nஇந்த வசனம் வஹீ (இறைச்செய்தி)யாக அருளப்பட்டது தொடர்பாக பல ஹதீஸ்கள் அறிவிக்கப்பட்டுள்ளன, அவற்றில் சிலவற்றை கீழே காண்போம்: இமாம் அஹ்மத் (அல்லாஹ் அவர் மீது ரஹ்மத் செய்வானாக) அவர்கள் பதிவு செய்துள்ளார்கள், இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"அல்லாஹ்,\n\r\n\n\r\nوَأَنذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ\n\r\n\n\r\n(உமது நெருங்கிய உறவினர்களை எச்சரிப்பீராக) என்ற வசனத்தை அருளியபோது, நபி (ஸல்) அவர்கள் ஸஃபா மலைக்குச் சென்று, அதன் மீது ஏறி,\n\r\n\n\r\n«يَا صَبَاحَاه»\n\r\n\n\r\n(ஓ மக்களே!) என்று சத்தமிட்டு அழைத்தார்கள். மக்கள் அவர்களைச் சூழ்ந்து கொண்டனர். சிலர் தாங்களாகவே வந்தனர், சிலர் என்ன நடக்கிறது என்பதை அறிய தங்கள் பிரதிநிதிகளை அனுப்பினார்கள். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«يَا بَنِي عَبْدِالْمُطَّلِبِ، يَا بَنِي فِهْرٍ، يَا بَنِي لُؤَيَ، أَرَأَيْتُمْ لَوْ أَخْبَرْتُكُمْ أَنَّ خَيْلًا بِسَفْحِ هَذَا الْجَبَلِ تُريدُ أَنْ تُغِيرَ عَلَيْكُمْ صَدَّقْتُمُونِي؟»\n\r\n\n\r\n(ஓ பனீ அப்துல் முத்தலிப், ஓ பனீ ஃபிஹ்ர், ஓ பனீ லுஅய்! இந்த மலையின் அடிவாரத்தில் உங்களைத் தாக்க ஒரு குதிரைப்படை காத்துக் கொண்டிருக்கிறது என்று நான் கூறினால், நீங்கள் என்னை நம்புவீர்களா?) அதற்கு அவர்கள், \"ஆம்\" என்றனர். அவர்கள் (ஸல்) கூறினார்கள்:\n\r\n\n\r\n«فَإِنِّي نَذِيرٌ لَكُمْ بَيْنَ يَدَي عَذَابٍ شَدِيد»\n\r\n\n\r\n(நிச்சயமாக நான் கடுமையான வேதனை உங்களுக்கு முன்னால் இருக்கிறது என்று உங்களை எச்சரிப்பவன் ஆவேன்.) அப்போது அபூ லஹப், \"இந்த நாள் முழுவதும் நீ நாசமடைவாயாக! இதற்காகவா எங்களை அழைத்தாய்?\" என்று கூறினான். பின்னர் அல்லாஹ் இந்த வசனத்தை அருளினான்:\n\r\n\n\r\nتَبَّتْ يَدَآ أَبِى لَهَبٍ وَتَبَّ\n\r\n\n\r\n(அபூ லஹபின் இரு கைகளும் நாசமாகட்டும்; அவனும் நாசமாகிவிட்டான்!) 111:1. இது புகாரீ, முஸ்லிம், திர்மிதீ மற்றும் நஸாயீ ஆகிய நூல்களிலும் பதிவாகியுள்ளது.\n\r\n\n\r\nஇமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளார்கள், ஆயிஷா (ரழி) அவர்கள் கூறினார்கள்: \"உமது நெருங்கிய உறவினர்களை எச்சரிப்பீராக என்ற வசனம் அருளப்பட்டபோது:\n\r\n\n\r\nوَأَنذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ\n\r\n\n\r\nஅல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் எழுந்து நின்று கூறினார்கள்:\n\r\n\n\r\n«يَا فَاطِمَةُ ابْنَةُ مُحَمَّدٍ، يَا صَفِيَّةُ ابْنَةُ عَبْدِالْمُطَّلِبِ، يَا بَنِي عَبْدِالْمُطَّلِبِ، لَا أَمْلِكُ لَكُمْ مِنَ اللهِ شَيْئًا سَلُونِي مِنْ مَالِي مَا شِئْتُم»\n\r\n\n\r\n(ஓ முஹம்மதின் மகள் ஃபாத்திமாவே! ஓ அப்துல் முத்தலிபின் மகள் ஸஃபிய்யாவே! ஓ பனீ அப்துல் முத்தலிப் சமூகத்தாரே! அல்லாஹ்வின் தண்டனையிலிருந்து உங்களை ஒருபோதும் என்னால் காப்பாற்ற முடியாது. எனது செல்வத்திலிருந்து நீங்கள் விரும்புவதை என்னிடம் கேட்டுப் பெற்றுக் கொள்ளுங்கள்.) இது முஸ்லிமில் பதிவாகியுள்ளது.\n\r\n\n\r\nஇமாம் அஹ்மத் அவர்கள் பதிவு செய்துள்ளார்கள், கபீஸா பின் முகாரிக் (ரழி) மற்றும் ஸுஹைர் பின் அம்ர் (ரழி) ஆகியோர் கூறினார்கள்: \"உமது நெருங்கிய உறவினர்களை எச்சரிப்பீராக என்ற வசனம் அருளப்பட்டபோது:\n\r\n\n\r\nوَأَنذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ\n\r\n\n\r\nஅல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஒரு மலையின் உச்சியில் இருந்த பாறையின் மீது ஏறி இவ்வாறு அழைக்கத் தொடங்கினார்கள்:\n\r\n\n\r\n«يَا بَنِي عَبْدِ مَنَافٍ، إِنَّمَا أَنَا نَذِيرٌ، وَإِنَّمَا مَثَلِي وَمَثَلُكُمْ كَرَجُلٍ رَأَى الْعَدُوَّ فَذَهَبَ يَرْبَأُ أَهْلَهُ يَخْشَى أَنْ يَسْبِقُوهُ، فَجَعَلَ يُنَادِي وَيَهْتِفُ: يَا صَبَاحَاه»\n\r\n\n\r\n(ஓ பனீ அப்து மனாஃப்! நிச்சயமாக நான் உங்களை எச்சரிப்பவன். எனக்கும் உங்களுக்குமான உவமை, எதிரி வருவதைக் கண்ட ஒரு மனிதன், அவர்கள் தன் குடும்பத்தை அடைவதற்குள் அவர்களைக் காப்பாற்ற ஓடிச் சென்று, 'ஓ மக்களே!' என்று சத்தமிட்டு எச்சரிப்பதைப் போன்றதாகும்.) இது முஸ்லிம் மற்றும் நஸாயீயிலும் பதிவாகியுள்ளது.\n\r\n\n\r\nஅல்லாஹ்வின் கூற்று:\n\r\n\n\r\nوَتَوَكَّلْ عَلَى الْعَزِيزِ الرَّحِيمِ\n\r\n\n\r\n(மேலும் மிகைத்தவனும், மகா கருணையாளனுமானவன் மீது நம்பிக்கை வைப்பீராக,) இதன் பொருள்: உமது எல்லா விவகாரங்களிலும் அவனையே சார்ந்திருப்பீராக; ஏனெனில் அவன்தான் உமது உதவியாளனும், பாதுகாவலனும், உமக்கு ஆதரவளிப்பவனுமாவான். அவன் உம்மை வெற்றிபெறச் செய்து, உமது வாக்கை மேலோங்கச் செய்வான்.\n\r\n\n\r\nالَّذِى يَرَاكَ حِينَ تَقُومُ\n\r\n\n\r\n(நீர் தொழுகைக்காக எழும்போது அவன் உம்மைப் பார்க்கிறான்.) அதாவது, அவன் உம்மைப் பாதுகாத்துக் கொண்டிருக்கிறான். இது பின்வரும் வசனத்தைப் போன்றதாகும்:\n\r\n\n\r\nوَاصْبِرْ لِحُكْمِ رَبِّكَ فَإِنَّكَ بِأَعْيُنِنَا\n\r\n\n\r\n(நீர் உமது இறைவனின் தீர்ப்புக்காகப் பொறுத்திருப்பீராக; நிச்சயமாக நீர் நம் கண் முன்னே (நம் பாதுகாப்பில்) இருக்கிறீர்) (52:48). இப்னு அப்பாஸ் (ரழி) அவர்கள்,\n\r\n\n\r\nالَّذِى يَرَاكَ حِينَ تَقُومُ\n\r\n\n\r\n(நீர் தொழுகைக்காக எழும்போது அவன் உம்மைப் பார்க்கிறான்) என்பதற்கு 'தொழுகைக்காக நிற்பது' என்று பொருள் கூறினார்கள். இக்ரிமா (ரஹ்) அவர்கள் கூறினார்கள்: \"அவர் நிற்கும்போதும், ருகூஉ (குனிதல்), ஸஜ்தா (சிரம் பணிதல்) செய்யும்போதும் அவன் அவரைப் பார்க்கிறான்.\" அல்-ஹஸன் (ரஹ்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\nالَّذِى يَرَاكَ حِينَ تَقُومُ\n\r\n\n\r\n(நீர் தொழுகைக்காக எழும்போது அவன் உம்மைப் பார்க்கிறான்.) \"நீர் தனியாகத் தொழும்போது.\" அத்-தஹ்ஹாக் (ரஹ்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\nالَّذِى يَرَاكَ حِينَ تَقُومُ\n\r\n\n\r\n(நீர் தொழுகைக்காக எழும்போது அவன் உம்மைப் பார்க்கிறான்.) \"நீர் படுக்கையில் இருக்கும்போதும், அமர்ந்திருக்கும்போதும்.\" கதாதா (ரஹ்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\nالَّذِى يَرَاكَ\n\r\n\n\r\n(அவன் உம்மைப் பார்க்கிறான்) \"நீர் நிற்கும்போதும், அமர்ந்திருக்கும்போதும் மற்றும் எல்லா நிலைகளிலும்.\"\n\r\n\n\r\nوَتَقَلُّبَكَ فِى السَّـجِدِينَ\n\r\n\n\r\n(மேலும் ஸஜ்தா செய்வோரிடையே உமது அசைவுகளையும்.) கதாதா (ரஹ்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\nالَّذِى يَرَاكَ حِينَ تَقُومُ\n\r\n\n\r\nوَتَقَلُّبَكَ فِى السَّـجِدِينَ\n\r\n\n\r\n(நீர் தொழுகைக்காக எழும்போது அவன் உம்மைப் பார்க்கிறான். மேலும் ஸஜ்தா செய்வோரிடையே உமது அசைவுகளையும்.) \"நீர் தொழும்போது, நீர் தனியாகத் தொழுதாலும் ஜமாஅத்தாகத் தொழுதாலும் அவன் உம்மைப் பார்க்கிறான்.\" இதுவே இக்ரிமா (ரஹ்), அதா அல்-குராஸானீ (ரஹ்) மற்றும் அல்-ஹஸன் அல்-பஸரீ (ரஹ்) ஆகியோரின் கருத்தாகும்.\n\r\n\n\r\nإِنَّهُ هُوَ السَّمِيعُ الْعَلِيمُ\n\r\n\n\r\n(நிச்சயமாக அவனே அனைத்தையும் செவியுறுபவனும், நன்கறிந்தவனுமாவான்.) அவன் தனது அடியார்களின் பேச்சுகள் அனைத்தையும் செவியுறுகிறான்; அவர்களின் அசைவுகள் அனைத்தையும் அறிகிறான். அவன் கூறுவது போல:\n\r\n\n\r\nوَمَا تَكُونُ فِى شَأْنٍ وَمَا تَتْلُواْ مِنْهُ مِن قُرْءَانٍ وَلاَ تَعْمَلُونَ مِنْ عَمَلٍ إِلاَّ كُنَّا عَلَيْكُمْ شُهُودًا إِذْ تُفِيضُونَ فِيهِ\n\r\n\n\r\n(நீர் எந்த நிலையில் இருந்தாலும், குர்ஆனிலிருந்து எதை ஓதினாலும், நீங்கள் எந்தச் செயலைச் செய்தாலும், நீங்கள் அதில் ஈடுபட்டிருக்கும்போது நாம் உங்களுக்குச் சாட்சியாகவே இருக்கிறோம்) (10:61)."},"221":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=227\" class=\"link\">26:227</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:227 ஐ பார்க்கவும்"},"222":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=227\" class=\"link\">26:227</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:227 ஐ பார்க்கவும்"},"223":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=227\" class=\"link\">26:227</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:227 ஐ பார்க்கவும்"},"224":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=227\" class=\"link\">26:227</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:227 ஐ பார்க்கவும்"},"225":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=227\" class=\"link\">26:227</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:227 ஐ பார்க்கவும்"},"226":{"html":"முழுமையான தஃப்சீருக்கு வசனம் <a href=\"tafsiribnkathir.php?sura=26&ayah=227\" class=\"link\">26:227</a> ஐ பார்க்கவும்","text":"முழுமையான தஃப்சீருக்கு வசனம் 26:227 ஐ பார்க்கவும்"},"227":{"html":"<strong>இணைவைப்பாளர்களின் இட்டுக்கட்டல்களுக்கு மறுப்பு</strong><br />\r\n<br />\r\nஇங்கே அல்லாஹ், இத்தூதர் கொண்டு வந்தது உண்மையல்ல, மாறாக அவர் சுயமாக இட்டுக்கட்டியது அல்லது ஜின்களிடமிருந்து அவருக்குக் கிடைத்த தரிசனங்கள் என்று வாதிட்ட இணைவைப்பாளர்களுக்குப் பதிலளிக்கிறான். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இவர்களது வீணானக் கூற்றுகளுக்கும் இட்டுக்கட்டல்களுக்கும் அப்பாற்பட்டவர் என்றும், அவர் கொண்டு வந்தது உண்மையில் அல்லாஹ்விடமிருந்து வந்த வஹீ (இறைச்செய்தி) என்றும், அது ஒரு கண்ணியமான, நம்பிக்கைக்குரிய, வலிமைமிக்க வானவர் மூலம் அருளப்பட்டது என்றும் அல்லாஹ் கூறுகிறான். இது ஷைத்தான்களிடமிருந்து வந்தது அல்ல. ஏனெனில், இந்த மேன்மைமிக்க குர்ஆனைப் போன்ற ஒன்றில் அவர்களுக்கு எவ்வித நாட்டமும் இல்லை. அவர்கள் தங்களைப் போன்ற பொய்யர்களான குறிசொல்பவர்கள் மீதே இறங்குகிறார்கள். அல்லாஹ் கூறுகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هَلْ</span> <span class=\"quran-arabic-font text-success\">أُنَبِّئُكُمْ</span><br />\r\n<br />\r\n(நான் உங்களுக்கு அறிவிக்கட்டுமா?) அதாவது, நான் உங்களுக்குச் சொல்லட்டுமா?<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">هَلْ</span> <span class=\"quran-arabic-font text-success\">أُنَبِّئُكُمْ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">مَن</span> <span class=\"quran-arabic-font text-success\">تَنَزَّلُ</span> <span class=\"quran-arabic-font text-success\">الشَّيَاطِينُ</span> - <span class=\"quran-arabic-font text-success\">تَنَزَّلُ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">أَفَّاكٍ</span> <span class=\"quran-arabic-font text-success\">أَثِيمٍ</span><br />\r\n<br />\r\n(ஷைத்தான்கள் யார் மீது இறங்குகிறார்கள் என்பதை நான் உங்களுக்கு அறிவிக்கட்டுமா? அவர்கள் ஒவ்வொரு பெரும் பொய்யர் மற்றும் பாவி (அதீம்) மீதும் இறங்குகிறார்கள்.) அதாவது, யாருடைய பேச்சுகள் பொய்யாகவும் இட்டுக்கட்டலாகவும் இருக்கிறதோ அவர் மீது.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَثِيمٍ</span><br />\r\n<br />\r\n(அதீம்) என்றால், எவருடைய செயல்கள் ஒழுக்கக்கேடானதாக இருக்கிறதோ அவர் என்று பொருள். இத்தகைய குறிசொல்பவர்கள் மற்றும் பாவிகளான பொய்யர்கள் மீதுதான் ஷைத்தான்கள் இறங்குகிறார்கள். ஷைத்தான்களும் பாவிகளான பொய்யர்களே.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يُلْقُونَ</span> <span class=\"quran-arabic-font text-success\">السَّمْعَ</span><br />\r\n<br />\r\n(அவர்கள் செவிசாய்க்கிறார்கள்.) இதன் பொருள், அவர்கள் வானங்களில் பேசப்படுவதை ஒட்டுக்கேட்க முயற்சி செய்கிறார்கள். மறைவான விஷயங்களில் இருந்து எதையாவது கேட்க முயற்சி செய்து, பின்னர் அதனுடன் நூறு பொய்களைச் சேர்த்துத் தங்கள் மனிதத் தோழர்களிடம் கூறுகிறார்கள்; அவர்கள் அதனை மற்றவர்களிடம் கூறுகிறார்கள். வானத்திலிருந்து கேட்கப்பட்ட அந்த ஒரு விஷயம் உண்மையாகி விடுவதால், அவர்கள் சொல்லும் அனைத்தையும் மக்கள் நம்பிவிடுகிறார்கள். இது குறித்து ஆயிஷா (ரழி) அவர்கள் அறிவிக்கின்ற ஓர் ஆதாரப்பூர்வமான ஹதீஸ் புகாரியில் இடம்பெற்றுள்ளது. அவர்கள் கூறினார்கள்: \"மக்கள் நபியவர்களிடம் (ஸல்) குறிசொல்பவர்களைப் பற்றிக் கேட்டார்கள். அதற்கு அவர்கள் (ஸல்) கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">لَيْسُوا</span> <span class=\"quran-arabic-font text-success\">بِشَيْء</span>»<br />\r\n<br />\r\n(அவர்கள் ஒரு பொருட்டல்ல.) மக்கள் கேட்டார்கள்: \"அல்லாஹ்வின் தூதரே! அவர்கள் சில நேரங்களில் உண்மையான விஷயங்களைக் கூறுகிறார்களே?\" அதற்கு நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">تِلْكَ</span> <span class=\"quran-arabic-font text-success\">الْكَلِمَةُ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">الْحَقِّ</span> <span class=\"quran-arabic-font text-success\">يَخْطَفُهَا</span> <span class=\"quran-arabic-font text-success\">الْجِنِّيُّ</span> <span class=\"quran-arabic-font text-success\">فَيُقَرْقِرُهَا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">أُذُنِ</span> <span class=\"quran-arabic-font text-success\">وَلِيِّهِ</span> <span class=\"quran-arabic-font text-success\">كَقَرْقَرَةِ</span> <span class=\"quran-arabic-font text-success\">الدَّجَاجِ،</span> <span class=\"quran-arabic-font text-success\">فَيَخْلِطُونَ</span> <span class=\"quran-arabic-font text-success\">مَعَهَا</span> <span class=\"quran-arabic-font text-success\">أَكْثَرَ</span> <span class=\"quran-arabic-font text-success\">مِنْ</span> <span class=\"quran-arabic-font text-success\">مِائَةِ</span> <span class=\"quran-arabic-font text-success\">كَذْبَة</span>»<br />\r\n<br />\r\n(அது ஜின்கள் ஒட்டுக்கேட்டுப் பறித்துச் செல்லும் உண்மையின் ஒரு துளியாகும். ஒரு கோழி கொக்கரிப்பதைப் போல அவன் அதனைத் தன் நண்பனின் காதில் போடுகிறான். ஆனால் அவர்கள் அதனுடன் நூற்றுக்கும் மேற்பட்ட பொய்களைக் கலந்துவிடுகிறார்கள்.)\" அபூ ஹுரைரா (ரழி) அவர்கள் அறிவிக்கிறார்கள், நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِذَا</span> <span class=\"quran-arabic-font text-success\">قَضَى</span> <span class=\"quran-arabic-font text-success\">اللهُ</span> <span class=\"quran-arabic-font text-success\">الْأَمْرَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">السَّمَاءِ</span> <span class=\"quran-arabic-font text-success\">ضَرَبَتِ</span> <span class=\"quran-arabic-font text-success\">الْمَلَائِكَةُ</span> <span class=\"quran-arabic-font text-success\">بِأَجْنِحَتِهَا</span> <span class=\"quran-arabic-font text-success\">خُضْعَانًا</span> <span class=\"quran-arabic-font text-success\">لِقَوْلِهِ،</span> <span class=\"quran-arabic-font text-success\">كَأَنَّهَا</span> <span class=\"quran-arabic-font text-success\">سِلْسِلَةٌ</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">صَفْوَانٍ،</span> <span class=\"quran-arabic-font text-success\">فَإِذَا</span> <span class=\"quran-arabic-font text-success\">فُزِّعَ</span> <span class=\"quran-arabic-font text-success\">عَنْ</span> <span class=\"quran-arabic-font text-success\">قُلُوبِهِمْ</span> <span class=\"quran-arabic-font text-success\">قَالُوا</span>: <span class=\"quran-arabic-font text-success\">مَاذَا</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">رَبُّكُمْ؟</span> <span class=\"quran-arabic-font text-success\">قَالُوا</span> (<span class=\"quran-arabic-font text-success\">لِلَّذِي</span> <span class=\"quran-arabic-font text-success\">قَالَ</span>): <span class=\"quran-arabic-font text-success\">الْحَقَّ،</span> <span class=\"quran-arabic-font text-success\">وَهُوَ</span> <span class=\"quran-arabic-font text-success\">الْعَلِيُّ</span> <span class=\"quran-arabic-font text-success\">الْكَبِيرُ،</span> <span class=\"quran-arabic-font text-success\">فَيَسْمَعُهَا</span> <span class=\"quran-arabic-font text-success\">مُسْتَرِقُو</span> <span class=\"quran-arabic-font text-success\">السَّمْعِ،</span> <span class=\"quran-arabic-font text-success\">وَمُسْتَرِقُو</span> <span class=\"quran-arabic-font text-success\">السَّمْعِ</span> <span class=\"quran-arabic-font text-success\">هَكَذَا</span> <span class=\"quran-arabic-font text-success\">بَعْضُهُمْ</span> <span class=\"quran-arabic-font text-success\">فَوْقَ</span> <span class=\"quran-arabic-font text-success\">بَعْضٍ</span> <span class=\"quran-arabic-font text-success\">وَصَفَ</span> <span class=\"quran-arabic-font text-success\">سُفْيَانُ</span> <span class=\"quran-arabic-font text-success\">بِيَدِهِ،</span> <span class=\"quran-arabic-font text-success\">فَحَرَّفَهَا</span> <span class=\"quran-arabic-font text-success\">وَبَدَّدَ</span> <span class=\"quran-arabic-font text-success\">بَيْنَ</span> <span class=\"quran-arabic-font text-success\">أَصَابِعِهِ</span> <span class=\"quran-arabic-font text-success\">فَيَسْمَعُ</span> <span class=\"quran-arabic-font text-success\">الْكَلِمَةَ</span> <span class=\"quran-arabic-font text-success\">فَيُلْقِيهَا</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">تَحْتَهُ،</span> <span class=\"quran-arabic-font text-success\">ثُمَّ</span> <span class=\"quran-arabic-font text-success\">يُلْقِيهَا</span> <span class=\"quran-arabic-font text-success\">الْآخَرُ</span> <span class=\"quran-arabic-font text-success\">إِلَى</span> <span class=\"quran-arabic-font text-success\">مَنْ</span> <span class=\"quran-arabic-font text-success\">تَحْتَهُ،</span> <span class=\"quran-arabic-font text-success\">حَتَّى</span> <span class=\"quran-arabic-font text-success\">يُلْقِيَهَا</span> <span class=\"quran-arabic-font text-success\">عَلَى</span> <span class=\"quran-arabic-font text-success\">لِسَانِ</span> <span class=\"quran-arabic-font text-success\">السَّاحِرِ</span> <span class=\"quran-arabic-font text-success\">أَوِ</span> <span class=\"quran-arabic-font text-success\">الْكَاهِنِ،</span> <span class=\"quran-arabic-font text-success\">فَرُبَّمَا</span> <span class=\"quran-arabic-font text-success\">أَدْرَكَهُ</span> <span class=\"quran-arabic-font text-success\">الشِّهَابُ</span> <span class=\"quran-arabic-font text-success\">قَبْلَ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يُلْقِيَهَا،</span> <span class=\"quran-arabic-font text-success\">وَرُبَّمَا</span> <span class=\"quran-arabic-font text-success\">أَلْقَاهَا</span> <span class=\"quran-arabic-font text-success\">قَبْلَ</span> <span class=\"quran-arabic-font text-success\">أَنْ</span> <span class=\"quran-arabic-font text-success\">يُدْرِكَهُ،</span> <span class=\"quran-arabic-font text-success\">فَيَكْذِبُ</span> <span class=\"quran-arabic-font text-success\">مَعَهَا</span> <span class=\"quran-arabic-font text-success\">مِائَةَ</span> <span class=\"quran-arabic-font text-success\">كَذْبَةٍ،فَيُقَالُ</span>: <span class=\"quran-arabic-font text-success\">أَلَيْسَ</span> <span class=\"quran-arabic-font text-success\">قَدْ</span> <span class=\"quran-arabic-font text-success\">قَالَ</span> <span class=\"quran-arabic-font text-success\">لَنَا</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">كَذَا</span> <span class=\"quran-arabic-font text-success\">وَكَذَا</span>: <span class=\"quran-arabic-font text-success\">كَذَا</span> <span class=\"quran-arabic-font text-success\">وَكَذَا؟</span> <span class=\"quran-arabic-font text-success\">فَيُصَدَّقُ</span> <span class=\"quran-arabic-font text-success\">بِتِلْكَ</span> <span class=\"quran-arabic-font text-success\">الْكَلِمَةِ</span> <span class=\"quran-arabic-font text-success\">الَّتِي</span> <span class=\"quran-arabic-font text-success\">سُمِعَتْ</span> <span class=\"quran-arabic-font text-success\">مِنَ</span> <span class=\"quran-arabic-font text-success\">السَّمَاء</span>»<br />\r\n<br />\r\n(அல்லாஹ் வானத்தில் ஒரு கட்டளையைப் பிறப்பிக்கும்போது, அவனது சொல்லுக்குப் பணிந்து வானவர்கள் தங்கள் இறக்கைகளை அடிக்கிறார்கள். அது ஒரு பாறையின் மீது சங்கிலியை இழுப்பது போன்ற சத்தத்தை உண்டாக்கும். அவர்களின் இதயங்களிலிருந்து அச்சம் நீங்கியதும், அவர்கள் 'உங்கள் இறைவன் என்ன கூறினான்?' என்று கேட்பார்கள். அதற்கு வானவர்கள், 'உண்மையையே கூறினான். அவன்தான் மிக உயர்ந்தவன், மிக மகா பெரியவன்' என்று கூறுவார்கள். அப்போது ஒட்டுக்கேட்பவர்கள் (ஜின்கள்) அதனைச் செவியேற்பார்கள். இந்த ஒட்டுக்கேட்பவர்கள் ஒருவருக்கு மேல் ஒருவராக அடுக்கடுக்காக இருப்பார்கள் - இதனை விளக்குவதற்காக சுஃப்யான் தனது கையைச் செங்குத்தாக வைத்து விரல்களை விரித்துக் காட்டினார் - அப்படிக் கேட்கும் ஒரு செய்தியைத் தற்குக் கீழே இருப்பவரிடம் அவர் போடுவார். இப்படியே அது ஒரு சூனியக்காரர் அல்லது குறிசொல்பவரின் நாவிற்கு வந்து சேரும் வரை கடத்தப்படும். சில நேரங்களில் அந்தச் செய்தியைச் சொல்வதற்கு முன்பே எரிகல் (விண்கல்) அவரைத் தாக்கிவிடும்; சில நேரங்களில் அவர் அதனைச் சொல்லும் வரை எரிகல் தாக்காமல் இருக்கும். அவர் அதனுடன் நூறு பொய்களைச் சேர்த்துக் கூறுவார். அப்போது மக்கள் 'அவர் இன்ன இன்ன நாளில் இப்படி நடக்கும் என்று நம்மிடம் சொல்லவில்லையா?' என்று கேட்பார்கள். வானத்திலிருந்து கேட்கப்பட்ட அந்த ஒரு உண்மையின் காரணமாக மக்கள் அவரை நம்பிவிடுகிறார்கள்.) இதனை புகாரி பதிவு செய்துள்ளார். ஆயிஷா (ரழி) அவர்கள் அறிவிப்பதாக புகாரியில் இடம்பெற்றுள்ள மற்றொரு செய்தியில் நபி (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الْمَلَائِكَةَ</span> <span class=\"quran-arabic-font text-success\">تَحَدَّثُ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْعَنَانِ</span> <span class=\"quran-arabic-font text-success\">وَالْعَنَانُ</span>: <span class=\"quran-arabic-font text-success\">الْغَمَامُ</span> <span class=\"quran-arabic-font text-success\">بِالْأَمْرِ</span> (<span class=\"quran-arabic-font text-success\">يَكُونُ</span>) <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">الْأَرْضِ،</span> <span class=\"quran-arabic-font text-success\">فَتَسْمَعُ</span> <span class=\"quran-arabic-font text-success\">الشَّيَاطِينُ</span> <span class=\"quran-arabic-font text-success\">الْكَلِمَةَ،</span> <span class=\"quran-arabic-font text-success\">فَتَقُرُّهَا</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">أُذُنِ</span> <span class=\"quran-arabic-font text-success\">الْكَاهِنِ</span> <span class=\"quran-arabic-font text-success\">كَمَا</span> <span class=\"quran-arabic-font text-success\">تُقَرُّ</span> <span class=\"quran-arabic-font text-success\">الْقَارُورَةُ،</span> <span class=\"quran-arabic-font text-success\">فَيَزِيدُونَ</span> <span class=\"quran-arabic-font text-success\">مَعَهَا</span> <span class=\"quran-arabic-font text-success\">مِائَةَ</span> <span class=\"quran-arabic-font text-success\">كَذْبَة</span>»<br />\r\n<br />\r\n(வானவர்கள் மேகங்களுக்கு இடையே பூமியில் நடைபெறவிருக்கும் ஒரு விஷயத்தைப் பற்றிப் பேசுகிறார்கள். ஷைத்தான்கள் அதனை ஒட்டுக்கேட்டு, ஒரு புட்டியிலிருந்து திரவத்தை ஊற்றுவதைப் போன்ற சத்தத்துடன் குறிசொல்பவனின் காதில் போடுகிறார்கள். அதனுடன் அவர்கள் நூறு பொய்களைச் சேர்த்துக் கூறுகிறார்கள்.)<br />\r\n<br />\r\n<strong>நபி ஒரு கவிஞர் என்ற கூற்றுக்கு மறுப்பு</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالشُّعَرَآءُ</span> <span class=\"quran-arabic-font text-success\">يَتَّبِعُهُمُ</span> <span class=\"quran-arabic-font text-success\">الْغَاوُونَ</span><br />\r\n<br />\r\n(கவிஞர்களைப் பொறுத்தவரை, வழிதவறியவர்களே அவர்களைப் பின்பற்றுகிறார்கள்.) \"நிராகரிப்பாளர்கள் மனிதர்கள் மற்றும் ஜின்களில் உள்ள வழிதவறியவர்களையே பின்பற்றுகிறார்கள்\" என்று இதற்கு இப்னு அப்பாஸ் (ரழி) அவர்கள் விளக்கம் அளித்ததாக அலி பின் அபீ தல்ஹா அறிவிக்கிறார். முஜாஹித், அப்துர் ரஹ்மான் பின் ஸைத் பின் அஸ்லம் மற்றும் பலரும் இதே கருத்தைக் கொண்டுள்ளனர். இக்ரிமா கூறும்போது: \"இரண்டு கவிஞர்கள் ஒருவரையொருவர் கவிதைகளால் ஏளனம் செய்வார்கள். அப்போது ஒரு தரப்பினர் ஒருவரையும், மற்றொரு தரப்பினர் மற்றவரையும் ஆதரிப்பார்கள். எனவேதான் அல்லாஹ் இந்த வசனத்தை அருளினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالشُّعَرَآءُ</span> <span class=\"quran-arabic-font text-success\">يَتَّبِعُهُمُ</span> <span class=\"quran-arabic-font text-success\">الْغَاوُونَ</span><br />\r\n<br />\r\n(கவிஞர்களைப் பொறுத்தவரை, வழிதவறியவர்களே அவர்களைப் பின்பற்றுகிறார்கள்.)\"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">أَلَمْ</span> <span class=\"quran-arabic-font text-success\">تَرَ</span> <span class=\"quran-arabic-font text-success\">أَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">وَادٍ</span> <span class=\"quran-arabic-font text-success\">يَهِيمُونَ</span><br />\r\n<br />\r\n(அவர்கள் ஒவ்வொரு பள்ளத்தாக்கிலும் அலைந்து திரிவதை நீர் பார்க்கவில்லையா?) அவர்கள் எல்லா வகையான வீணான விஷயங்களிலும் மூழ்கிக் கிடக்கிறார்கள் என்று இதற்கு இப்னு அப்பாஸ் (ரழி) அவர்கள் விளக்கம் அளித்ததாக அலி பின் அபீ தல்ஹா அறிவிக்கிறார். \"அவர்கள் எல்லா வகையான சொல் அலங்காரங்களிலும் ஈடுபடுகிறார்கள்\" என்று இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அத்-தஹ்ஹாக் அறிவிக்கிறார். முஜாஹித் மற்றும் பிறரின் கருத்தும் இதுவேயாகும்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَأَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">يَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَفْعَلُونَ</span><br />\r\n<br />\r\n(மேலும் நிச்சயமாக அவர்கள் செய்யாதவற்றைச் சொல்கிறார்கள்.) அல்-அவ்ஃபி அறிவிப்பதாவது: இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள், \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் காலத்தில், அன்சாரிகளில் ஒருவரும் மற்றொரு கோத்திரத்தைச் சேர்ந்த ஒருவரும் கவிதைகளால் ஒருவரையொருவர் ஏளனம் செய்து கொண்டிருந்தனர். அவர்கள் ஒவ்வொருவருக்கும் ஆதரவாக அவரவர் கூட்டத்தைச் சேர்ந்த அறிவற்றவர்கள் இருந்தனர். அப்போது அல்லாஹ் கூறினான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالشُّعَرَآءُ</span> <span class=\"quran-arabic-font text-success\">يَتَّبِعُهُمُ</span> <span class=\"quran-arabic-font text-success\">الْغَاوُونَ</span> - <span class=\"quran-arabic-font text-success\">أَلَمْ</span> <span class=\"quran-arabic-font text-success\">تَرَ</span> <span class=\"quran-arabic-font text-success\">أَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">فِى</span> <span class=\"quran-arabic-font text-success\">كُلِّ</span> <span class=\"quran-arabic-font text-success\">وَادٍ</span> <span class=\"quran-arabic-font text-success\">يَهِيمُونَ</span> - <span class=\"quran-arabic-font text-success\">وَأَنَّهُمْ</span> <span class=\"quran-arabic-font text-success\">يَقُولُونَ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَفْعَلُونَ</span><br />\r\n<br />\r\n(கவிஞர்களைப் பொறுத்தவரை, வழிதவறியவர்களே அவர்களைப் பின்பற்றுகிறார்கள். அவர்கள் ஒவ்வொரு பள்ளத்தாக்கிலும் அலைந்து திரிவதை நீர் பார்க்கவில்லையா? மேலும் நிச்சயமாக அவர்கள் செய்யாதவற்றைச் சொல்கிறார்கள்.)\" இக்குர்ஆன் எவருக்கு அருளப்பட்டதோ அந்தத் தூதர் (ஸல்) அவர்கள் ஒரு குறிசொல்பவரோ அல்லது கவிஞரோ அல்ல என்பதே இதன் பொருளாகும். ஏனெனில் அவரது நிலை அவர்களுடைய நிலையிலிருந்து முற்றிலும் மாறுபட்டது என்பதைப் பின்வரும் வசனங்களில் அல்லாஹ் விளக்குகிறான்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">عَلَّمْنَاهُ</span> <span class=\"quran-arabic-font text-success\">الشِّعْرَ</span> <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">يَنبَغِى</span> <span class=\"quran-arabic-font text-success\">لَهُ</span> <span class=\"quran-arabic-font text-success\">إِنْ</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">إِلاَّ</span> <span class=\"quran-arabic-font text-success\">ذِكْرٌ</span> <span class=\"quran-arabic-font text-success\">وَقُرْءَانٌ</span> <span class=\"quran-arabic-font text-success\">مُّبِينٌ</span><br />\r\n<br />\r\n(நாம் அவருக்குக் கவிதையைக் கற்றுக்கொடுக்கவில்லை; அது அவருக்குத் தகுதியானதும் அல்ல. இது ஒரு நினைவூட்டலும் தெளிவான குர்ஆனுமே தவிர வேறில்லை.) (<a href=\"qurandisp.php?sura=36&ayah=69\" class=\"link\">36:69</a>),<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِنَّهُ</span> <span class=\"quran-arabic-font text-success\">لَقَوْلُ</span> <span class=\"quran-arabic-font text-success\">رَسُولٍ</span> <span class=\"quran-arabic-font text-success\">كَرِيمٍ</span> - <span class=\"quran-arabic-font text-success\">وَمَا</span> <span class=\"quran-arabic-font text-success\">هُوَ</span> <span class=\"quran-arabic-font text-success\">بِقَوْلِ</span> <span class=\"quran-arabic-font text-success\">شَاعِرٍ</span> <span class=\"quran-arabic-font text-success\">قَلِيلاً</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">تُؤْمِنُونَ</span> - <span class=\"quran-arabic-font text-success\">وَلاَ</span> <span class=\"quran-arabic-font text-success\">بِقَوْلِ</span> <span class=\"quran-arabic-font text-success\">كَاهِنٍ</span> <span class=\"quran-arabic-font text-success\">قَلِيلاً</span> <span class=\"quran-arabic-font text-success\">مَّا</span> <span class=\"quran-arabic-font text-success\">تَذَكَّرُونَ</span> <span class=\"quran-arabic-font text-success\">تَنزِيلٌ</span> <span class=\"quran-arabic-font text-success\">مِّن</span> <span class=\"quran-arabic-font text-success\">رَّبِّ</span> <span class=\"quran-arabic-font text-success\">الْعَالَمِينَ</span><br />\r\n<br />\r\n(நிச்சயமாக இது ஒரு கண்ணியமிக்க தூதரின் சொல்லாகும். இது ஒரு கவிஞரின் சொல்லல்ல; நீங்கள் மிகக் குறைவாகவே நம்பிக்கை கொள்கிறீர்கள். இது ஒரு குறிசொல்பவனின் சொல்லுமல்ல; நீங்கள் மிகக் குறைவாகவே படிப்பினை பெறுகிறீர்கள். இது அகிலங்களின் இறைவனிடமிருந்து அருளப்பட்ட வஹீ (இறைச்செய்தி) ஆகும்.) (<a href=\"qurandisp.php?sura=69&ayah=40\" class=\"link\">69:40</a>-43)<br />\r\n<br />\r\n<strong>இஸ்லாமியக் கவிஞர்களுக்கான விதிவிலக்கு</strong><br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">آمَنُوا</span> <span class=\"quran-arabic-font text-success\">وَعَمِلُوا</span> <span class=\"quran-arabic-font text-success\">الصَّالِحَاتِ</span><br />\r\n<br />\r\n(நம்பிக்கை கொண்டு நற்செயல்கள் செய்பவர்களைத் தவிர,) முஹம்மது பின் இஸ்ஹாக், யஸீத் பின் அப்துல்லாஹ் பின் குஸைத்திடமிருந்து அறிவிக்கிறார்: தமீம் அத்-தாரி (ரழி) அவர்களின் விடுதலை செய்யப்பட்ட அடிமையான அபுல் ஹஸன் ஸலீம் அல்-பர்ராத் கூறினார்: \"<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَالشُّعَرَآءُ</span> <span class=\"quran-arabic-font text-success\">يَتَّبِعُهُمُ</span> <span class=\"quran-arabic-font text-success\">الْغَاوُونَ</span><br />\r\n<br />\r\n(கவிஞர்களைப் பொறுத்தவரை, வழிதவறியவர்களே அவர்களைப் பின்பற்றுகிறார்கள்) என்ற வசனம் அருளப்பட்டபோது, ஹஸ்ஸான் பின் ஸாபித் (ரழி), அப்துல்லாஹ் பின் ரவாஹா (ரழி) மற்றும் கஅப் பின் மாலிக் (ரழி) ஆகியோர் அழுதுகொண்டே அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் வந்தார்கள். 'அல்லாஹ் இந்த வசனத்தை அருளியபோது நாம் கவிஞர்கள் என்பதை அறிந்தே இருந்தானே' என்று அவர்கள் கூறினார்கள். அப்போது நபி (ஸல்) அவர்கள் இந்த வசனத்தை ஓதிக் காட்டினார்கள்:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">إِلَّا</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">آمَنُوا</span> <span class=\"quran-arabic-font text-success\">وَعَمِلُوا</span> <span class=\"quran-arabic-font text-success\">الصَّالِحَاتِ</span><br />\r\n<br />\r\n(நம்பிக்கை கொண்டு நற்செயல்கள் செய்பவர்களைத் தவிர.) 'இது உங்களைக் குறிக்கும்' என்று அவர்கள் (ஸல்) கூறினார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَذَكَرُواْ</span> <span class=\"quran-arabic-font text-success\">اللَّهَ</span> <span class=\"quran-arabic-font text-success\">كَثِيراً</span><br />\r\n<br />\r\n(மேலும் அவர்கள் அல்லாஹ்வை அதிகமாக நினைவு கூர்கிறார்கள்) என்பதற்கும் 'இது உங்களைக் குறிக்கும்' என்றார்கள்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَانتَصَرُواْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">ظُلِمُواْ</span><br />\r\n<br />\r\n(அநீதி இழைக்கப்பட்ட பிறகு அவர்கள் தற்காத்துக் கொள்கிறார்கள்) என்பதற்கும் 'இது உங்களைக் குறிக்கும்' என்று கூறினார்கள்.\" இதனை இப்னு அபீ ஹாதிம் மற்றும் இப்னு ஜரீர் ஆகியோர் பதிவு செய்துள்ளனர்.<br />\r\n<br />\r\nஆனால் இந்த அத்தியாயம் (சூரா) மக்காவில் அருளப்பட்டதாகும். அப்படியிருக்கையில், அன்சாரிக் கவிஞர்கள் இதன் இறக்கத்திற்குக் காரணமாக இருக்க முடியுமா என்பது சிந்திக்கத்தக்கது. இது தொடர்பாகக் கூறப்படும் அறிவிப்புகள் அனைத்தும் 'முர்ஸல்' வகையைச் சேர்ந்தவை, எனவே அவற்றைப் ஆதாரமாகக் கொள்ள முடியாது. அல்லாஹ்வே மிக அறிந்தவன். எனினும், இந்த விதிவிலக்கு அன்சாரிக் கவிஞர்களையும் மற்றவர்களையும் உள்ளடக்கும். இஸ்லாத்தையும் அதன் ஆதரவாளர்களையும் இழிவுபடுத்துவதில் ஈடுபட்ட ஜாஹிலிய்யா காலக் கவிஞர்களில் எவர் தவ்பா செய்து, அல்லாஹ்விடம் மீண்டு, நற்செயல்கள் புரிந்து, அல்லாஹ்வை அதிகமாக நினைவுகூர்கிறார்களோ அவர்களையும் இது உள்ளடக்கும். ஏனெனில் நற்செயல்கள் தீய செயல்களை அழித்துவிடும். அவர்கள் முன்பு செய்த இழிவுகளுக்குப் பரிகாரமாக இஸ்லாத்தையும் முஸ்லிம்களையும் புகழத் தொடங்கினார்கள். கவிஞர் அப்துல்லாஹ் பின் அஸ்-ஸப்அரி முஸ்லிமானபோது பாடியது போல: <br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَا</span> <span class=\"quran-arabic-font text-success\">رَسُولَ</span> <span class=\"quran-arabic-font text-success\">الْمَلِيكِ</span> <span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">لِسَانِي</span> ... <span class=\"quran-arabic-font text-success\">رَاتِقٌ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">فَتَقْتُ</span> <span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">أَنَا</span> <span class=\"quran-arabic-font text-success\">بُورُ</span><br />\r\n<span class=\"quran-arabic-font text-success\">إِذْ</span> <span class=\"quran-arabic-font text-success\">أُبَارِي</span> <span class=\"quran-arabic-font text-success\">الشَّيْطَانَ</span> <span class=\"quran-arabic-font text-success\">فِي</span> <span class=\"quran-arabic-font text-success\">سَنَنِ</span> <span class=\"quran-arabic-font text-success\">الْغَيِّ</span> ... <span class=\"quran-arabic-font text-success\">وَمَنْ</span> <span class=\"quran-arabic-font text-success\">مَالَ</span> <span class=\"quran-arabic-font text-success\">مَيْلَهُ</span> <span class=\"quran-arabic-font text-success\">مَثْبُورُ</span><br />\r\n<br />\r\n\"அல்லாஹ்வின் தூதரே! நான் வழிகேட்டில் இருந்தபோது ஷைத்தானைப் பின்பற்றித் திரிந்த ஆண்டுகளில் என் நாவு பேசிய தவறான பேச்சுக்களுக்குப் பரிகாரம் செய்ய இப்போது அது முயற்சிக்கும். யார் ஷைத்தானின் வழியில் சாய்கிறாரோ அவர் நஷ்டவாளியே.\" அதேபோல, அபூ சுஃப்யான் பின் அல்-ஹாரிஸ் பின் அப்துல் முத்தலிப் அவர்கள் நபியவர்களின் (ஸல்) பெரிய தந்தை மகனாக இருந்தபோதிலும், தொடக்கத்தில் அவர்களுக்கு மிகக் கடுமையான எதிரியாக இருந்தார். நபியவர்களை அதிகம் கேலி செய்பவராகவும் அவரே இருந்தார். ஆனால் அவர் முஸ்லிமான பிறகு, அல்லாஹ்வின் தூதர் (ஸல்) அவர்களைவிட அவருக்குப் பிரியமானவர் எவரும் இருக்கவில்லை. அவர் எங்கே நபியவர்களைக் கேலி செய்தாரோ அதே இடத்தில் அவர்களைப் புகழத் தொடங்கினார்; யாரைப் பெரும் எதிரியாகக் கருதினாரோ அவரையே உற்ற நண்பராக ஏற்றுக்கொண்டார்.<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَانتَصَرُواْ</span> <span class=\"quran-arabic-font text-success\">مِن</span> <span class=\"quran-arabic-font text-success\">بَعْدِ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">ظُلِمُواْ</span><br />\r\n<br />\r\n(அநீதி இழைக்கப்பட்ட பிறகு அவர்கள் தற்காத்துக் கொள்கிறார்கள்.) இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"நம்பிக்கையாளர்களைக் கவிதைகள் மூலம் ஏளனம் செய்த நிராகரிப்பாளர்களுக்கு அவர்கள் தகுந்த பதிலடி கொடுத்தார்கள்.\" முஜாஹித், கத்தாதா மற்றும் பலரது கருத்தும் இதுவே. ஸஹீஹ் நூலில் இடம்பெற்றுள்ள ஒரு செய்தியில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஹஸ்ஸான் (ரழி) அவர்களிடம் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">اهْجُهُم</span>»<br />\r\n<br />\r\n(அவர்களைக் கவிதையில் ஏளனம் செய்வீராக!) அல்லது<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">هَاجِهِمْ</span> <span class=\"quran-arabic-font text-success\">وَجِبْرِيلُ</span> <span class=\"quran-arabic-font text-success\">مَعَك</span>»<br />\r\n<br />\r\n(அவர்களைக் கவிதையில் ஏளனம் செய்வீராக! ஜிப்ரீல் (அலை) உம்மோடு இருக்கிறார்!) என்று கூறினார்கள். இமாம் அஹ்மத் பதிவு செய்துள்ள ஒரு செய்தியில், கஅப் பின் மாலிக் (ரழி) அவர்கள் நபியவர்களிடம் (ஸல்), \"அல்லாஹ் கவிஞர்களைப் பற்றி இவ்வாறு இறக்கியுள்ளானே\" என்று கேட்டார். அதற்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِنَّ</span> <span class=\"quran-arabic-font text-success\">الْمُؤْمِنَ</span> <span class=\"quran-arabic-font text-success\">يُجَاهِدُ</span> <span class=\"quran-arabic-font text-success\">بِسَيْفِهِ</span> <span class=\"quran-arabic-font text-success\">وَلِسَانِهِ،</span> <span class=\"quran-arabic-font text-success\">وَالَّذِي</span> <span class=\"quran-arabic-font text-success\">نَفْسِي</span> <span class=\"quran-arabic-font text-success\">بِيَدِهِ</span> <span class=\"quran-arabic-font text-success\">لَكَأَنَّ</span> <span class=\"quran-arabic-font text-success\">مَا</span> <span class=\"quran-arabic-font text-success\">تَرْمُونَهُمْ</span> <span class=\"quran-arabic-font text-success\">بِهِ</span> <span class=\"quran-arabic-font text-success\">نَضْحُ</span> <span class=\"quran-arabic-font text-success\">النَّبْلِ</span>»<br />\r\n<br />\r\n(நிச்சயமாக ஒரு முஃமின் தனது வாளாலும் தனது நாவாலும் ஜிஹாத் செய்கிறார். என் உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது சத்தியமாக! நீங்கள் உங்கள் கவிதைகள் மூலம் அவர்களைத் தாக்குவது, அவர்கள் மீது அம்புகளை எய்வதைப் போன்றதாகும்.)<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَسَيَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ظَلَمُواْ</span> <span class=\"quran-arabic-font text-success\">أَيَّ</span> <span class=\"quran-arabic-font text-success\">مُنقَلَبٍ</span> <span class=\"quran-arabic-font text-success\">يَنقَلِبُونَ</span><br />\r\n<br />\r\n(அநீதி இழைத்தவர்கள் தாங்கள் எவ்விதமான இடத்திற்குத் திரும்புவார்கள் என்பதை விரைவில் அறிந்துகொள்வார்கள்.) இது பின்வரும் வசனத்தைப் போன்றது:<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">لاَ</span> <span class=\"quran-arabic-font text-success\">يَنفَعُ</span> <span class=\"quran-arabic-font text-success\">الظَّالِمِينَ</span> <span class=\"quran-arabic-font text-success\">مَعْذِرَتُهُمْ</span><br />\r\n<br />\r\n(அநீதி இழைத்தவர்களுக்கு அவர்களது சாக்குப்போக்குகள் எவ்விதப் பயனும் அளிக்காத நாள்.) (<a href=\"qurandisp.php?sura=40&ayah=52\" class=\"link\">40:52</a>). ஸஹீஹ் நூலில் உள்ள ஹதீஸின்படி, அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:<br />\r\n<br />\r\n«<span class=\"quran-arabic-font text-success\">إِيَّاكُمْ</span> <span class=\"quran-arabic-font text-success\">وَالظُّلْمَ،</span> <span class=\"quran-arabic-font text-success\">فَإِنَّ</span> <span class=\"quran-arabic-font text-success\">الظُّلْمَ</span> <span class=\"quran-arabic-font text-success\">ظُلُمَاتٌ</span> <span class=\"quran-arabic-font text-success\">يَوْمَ</span> <span class=\"quran-arabic-font text-success\">الْقِيَامَة</span>»<br />\r\n<br />\r\n(அநீதி இழைப்பதிலிருந்து உங்களை எச்சரிக்கிறேன். ஏனெனில் அநீதி என்பது மறுமை நாளில் பெரும் இருள்களாக அமையும்.) கத்தாதா பின் திஆமா கூறுகையில்,<br />\r\n<br />\r\n<span class=\"quran-arabic-font text-success\">وَسَيَعْلَمُ</span> <span class=\"quran-arabic-font text-success\">الَّذِينَ</span> <span class=\"quran-arabic-font text-success\">ظَلَمُواْ</span> <span class=\"quran-arabic-font text-success\">أَيَّ</span> <span class=\"quran-arabic-font text-success\">مُنقَلَبٍ</span> <span class=\"quran-arabic-font text-success\">يَنقَلِبُونَ</span><br />\r\n<br />\r\n(அநீதி இழைத்தவர்கள் தாங்கள் எவ்விதமான இடத்திற்குத் திரும்புவார்கள் என்பதை விரைவில் அறிந்துகொள்வார்கள்.) என்ற வசனம் கவிஞர்களையும் மற்றவர்களையும் குறிக்கும் என்றார். இத்துடன் சூரத் அஷ்-ஷுஅராவின் தஃப்ஸீர் நிறைவுற்றது. எல்லாப் புகழும் அகிலங்களின் இறைவனான அல்லாஹ்வுக்கே உரித்தாகுக.<br />\r\n<br />","text":"இணைவைப்பாளர்களின் இட்டுக்கட்டல்களுக்கு மறுப்பு\n\r\n\n\r\nஇங்கே அல்லாஹ், இத்தூதர் கொண்டு வந்தது உண்மையல்ல, மாறாக அவர் சுயமாக இட்டுக்கட்டியது அல்லது ஜின்களிடமிருந்து அவருக்குக் கிடைத்த தரிசனங்கள் என்று வாதிட்ட இணைவைப்பாளர்களுக்குப் பதிலளிக்கிறான். அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் இவர்களது வீணானக் கூற்றுகளுக்கும் இட்டுக்கட்டல்களுக்கும் அப்பாற்பட்டவர் என்றும், அவர் கொண்டு வந்தது உண்மையில் அல்லாஹ்விடமிருந்து வந்த வஹீ (இறைச்செய்தி) என்றும், அது ஒரு கண்ணியமான, நம்பிக்கைக்குரிய, வலிமைமிக்க வானவர் மூலம் அருளப்பட்டது என்றும் அல்லாஹ் கூறுகிறான். இது ஷைத்தான்களிடமிருந்து வந்தது அல்ல. ஏனெனில், இந்த மேன்மைமிக்க குர்ஆனைப் போன்ற ஒன்றில் அவர்களுக்கு எவ்வித நாட்டமும் இல்லை. அவர்கள் தங்களைப் போன்ற பொய்யர்களான குறிசொல்பவர்கள் மீதே இறங்குகிறார்கள். அல்லாஹ் கூறுகிறான்:\n\r\n\n\r\nهَلْ أُنَبِّئُكُمْ\n\r\n\n\r\n(நான் உங்களுக்கு அறிவிக்கட்டுமா?) அதாவது, நான் உங்களுக்குச் சொல்லட்டுமா?\n\r\n\n\r\nهَلْ أُنَبِّئُكُمْ عَلَى مَن تَنَزَّلُ الشَّيَاطِينُ - تَنَزَّلُ عَلَى كُلِّ أَفَّاكٍ أَثِيمٍ\n\r\n\n\r\n(ஷைத்தான்கள் யார் மீது இறங்குகிறார்கள் என்பதை நான் உங்களுக்கு அறிவிக்கட்டுமா? அவர்கள் ஒவ்வொரு பெரும் பொய்யர் மற்றும் பாவி (அதீம்) மீதும் இறங்குகிறார்கள்.) அதாவது, யாருடைய பேச்சுகள் பொய்யாகவும் இட்டுக்கட்டலாகவும் இருக்கிறதோ அவர் மீது.\n\r\n\n\r\nأَثِيمٍ\n\r\n\n\r\n(அதீம்) என்றால், எவருடைய செயல்கள் ஒழுக்கக்கேடானதாக இருக்கிறதோ அவர் என்று பொருள். இத்தகைய குறிசொல்பவர்கள் மற்றும் பாவிகளான பொய்யர்கள் மீதுதான் ஷைத்தான்கள் இறங்குகிறார்கள். ஷைத்தான்களும் பாவிகளான பொய்யர்களே.\n\r\n\n\r\nيُلْقُونَ السَّمْعَ\n\r\n\n\r\n(அவர்கள் செவிசாய்க்கிறார்கள்.) இதன் பொருள், அவர்கள் வானங்களில் பேசப்படுவதை ஒட்டுக்கேட்க முயற்சி செய்கிறார்கள். மறைவான விஷயங்களில் இருந்து எதையாவது கேட்க முயற்சி செய்து, பின்னர் அதனுடன் நூறு பொய்களைச் சேர்த்துத் தங்கள் மனிதத் தோழர்களிடம் கூறுகிறார்கள்; அவர்கள் அதனை மற்றவர்களிடம் கூறுகிறார்கள். வானத்திலிருந்து கேட்கப்பட்ட அந்த ஒரு விஷயம் உண்மையாகி விடுவதால், அவர்கள் சொல்லும் அனைத்தையும் மக்கள் நம்பிவிடுகிறார்கள். இது குறித்து ஆயிஷா (ரழி) அவர்கள் அறிவிக்கின்ற ஓர் ஆதாரப்பூர்வமான ஹதீஸ் புகாரியில் இடம்பெற்றுள்ளது. அவர்கள் கூறினார்கள்: \"மக்கள் நபியவர்களிடம் (ஸல்) குறிசொல்பவர்களைப் பற்றிக் கேட்டார்கள். அதற்கு அவர்கள் (ஸல்) கூறினார்கள்:\n\r\n\n\r\n«إِنَّهُمْ لَيْسُوا بِشَيْء»\n\r\n\n\r\n(அவர்கள் ஒரு பொருட்டல்ல.) மக்கள் கேட்டார்கள்: \"அல்லாஹ்வின் தூதரே! அவர்கள் சில நேரங்களில் உண்மையான விஷயங்களைக் கூறுகிறார்களே?\" அதற்கு நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«تِلْكَ الْكَلِمَةُ مِنَ الْحَقِّ يَخْطَفُهَا الْجِنِّيُّ فَيُقَرْقِرُهَا فِي أُذُنِ وَلِيِّهِ كَقَرْقَرَةِ الدَّجَاجِ، فَيَخْلِطُونَ مَعَهَا أَكْثَرَ مِنْ مِائَةِ كَذْبَة»\n\r\n\n\r\n(அது ஜின்கள் ஒட்டுக்கேட்டுப் பறித்துச் செல்லும் உண்மையின் ஒரு துளியாகும். ஒரு கோழி கொக்கரிப்பதைப் போல அவன் அதனைத் தன் நண்பனின் காதில் போடுகிறான். ஆனால் அவர்கள் அதனுடன் நூற்றுக்கும் மேற்பட்ட பொய்களைக் கலந்துவிடுகிறார்கள்.)\" அபூ ஹுரைரா (ரழி) அவர்கள் அறிவிக்கிறார்கள், நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِذَا قَضَى اللهُ الْأَمْرَ فِي السَّمَاءِ ضَرَبَتِ الْمَلَائِكَةُ بِأَجْنِحَتِهَا خُضْعَانًا لِقَوْلِهِ، كَأَنَّهَا سِلْسِلَةٌ عَلَى صَفْوَانٍ، فَإِذَا فُزِّعَ عَنْ قُلُوبِهِمْ قَالُوا: مَاذَا قَالَ رَبُّكُمْ؟ قَالُوا (لِلَّذِي قَالَ): الْحَقَّ، وَهُوَ الْعَلِيُّ الْكَبِيرُ، فَيَسْمَعُهَا مُسْتَرِقُو السَّمْعِ، وَمُسْتَرِقُو السَّمْعِ هَكَذَا بَعْضُهُمْ فَوْقَ بَعْضٍ وَصَفَ سُفْيَانُ بِيَدِهِ، فَحَرَّفَهَا وَبَدَّدَ بَيْنَ أَصَابِعِهِ فَيَسْمَعُ الْكَلِمَةَ فَيُلْقِيهَا إِلَى مَنْ تَحْتَهُ، ثُمَّ يُلْقِيهَا الْآخَرُ إِلَى مَنْ تَحْتَهُ، حَتَّى يُلْقِيَهَا عَلَى لِسَانِ السَّاحِرِ أَوِ الْكَاهِنِ، فَرُبَّمَا أَدْرَكَهُ الشِّهَابُ قَبْلَ أَنْ يُلْقِيَهَا، وَرُبَّمَا أَلْقَاهَا قَبْلَ أَنْ يُدْرِكَهُ، فَيَكْذِبُ مَعَهَا مِائَةَ كَذْبَةٍ،فَيُقَالُ: أَلَيْسَ قَدْ قَالَ لَنَا يَوْمَ كَذَا وَكَذَا: كَذَا وَكَذَا؟ فَيُصَدَّقُ بِتِلْكَ الْكَلِمَةِ الَّتِي سُمِعَتْ مِنَ السَّمَاء»\n\r\n\n\r\n(அல்லாஹ் வானத்தில் ஒரு கட்டளையைப் பிறப்பிக்கும்போது, அவனது சொல்லுக்குப் பணிந்து வானவர்கள் தங்கள் இறக்கைகளை அடிக்கிறார்கள். அது ஒரு பாறையின் மீது சங்கிலியை இழுப்பது போன்ற சத்தத்தை உண்டாக்கும். அவர்களின் இதயங்களிலிருந்து அச்சம் நீங்கியதும், அவர்கள் 'உங்கள் இறைவன் என்ன கூறினான்?' என்று கேட்பார்கள். அதற்கு வானவர்கள், 'உண்மையையே கூறினான். அவன்தான் மிக உயர்ந்தவன், மிக மகா பெரியவன்' என்று கூறுவார்கள். அப்போது ஒட்டுக்கேட்பவர்கள் (ஜின்கள்) அதனைச் செவியேற்பார்கள். இந்த ஒட்டுக்கேட்பவர்கள் ஒருவருக்கு மேல் ஒருவராக அடுக்கடுக்காக இருப்பார்கள் - இதனை விளக்குவதற்காக சுஃப்யான் தனது கையைச் செங்குத்தாக வைத்து விரல்களை விரித்துக் காட்டினார் - அப்படிக் கேட்கும் ஒரு செய்தியைத் தற்குக் கீழே இருப்பவரிடம் அவர் போடுவார். இப்படியே அது ஒரு சூனியக்காரர் அல்லது குறிசொல்பவரின் நாவிற்கு வந்து சேரும் வரை கடத்தப்படும். சில நேரங்களில் அந்தச் செய்தியைச் சொல்வதற்கு முன்பே எரிகல் (விண்கல்) அவரைத் தாக்கிவிடும்; சில நேரங்களில் அவர் அதனைச் சொல்லும் வரை எரிகல் தாக்காமல் இருக்கும். அவர் அதனுடன் நூறு பொய்களைச் சேர்த்துக் கூறுவார். அப்போது மக்கள் 'அவர் இன்ன இன்ன நாளில் இப்படி நடக்கும் என்று நம்மிடம் சொல்லவில்லையா?' என்று கேட்பார்கள். வானத்திலிருந்து கேட்கப்பட்ட அந்த ஒரு உண்மையின் காரணமாக மக்கள் அவரை நம்பிவிடுகிறார்கள்.) இதனை புகாரி பதிவு செய்துள்ளார். ஆயிஷா (ரழி) அவர்கள் அறிவிப்பதாக புகாரியில் இடம்பெற்றுள்ள மற்றொரு செய்தியில் நபி (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِنَّ الْمَلَائِكَةَ تَحَدَّثُ فِي الْعَنَانِ وَالْعَنَانُ: الْغَمَامُ بِالْأَمْرِ (يَكُونُ) فِي الْأَرْضِ، فَتَسْمَعُ الشَّيَاطِينُ الْكَلِمَةَ، فَتَقُرُّهَا فِي أُذُنِ الْكَاهِنِ كَمَا تُقَرُّ الْقَارُورَةُ، فَيَزِيدُونَ مَعَهَا مِائَةَ كَذْبَة»\n\r\n\n\r\n(வானவர்கள் மேகங்களுக்கு இடையே பூமியில் நடைபெறவிருக்கும் ஒரு விஷயத்தைப் பற்றிப் பேசுகிறார்கள். ஷைத்தான்கள் அதனை ஒட்டுக்கேட்டு, ஒரு புட்டியிலிருந்து திரவத்தை ஊற்றுவதைப் போன்ற சத்தத்துடன் குறிசொல்பவனின் காதில் போடுகிறார்கள். அதனுடன் அவர்கள் நூறு பொய்களைச் சேர்த்துக் கூறுகிறார்கள்.)\n\r\n\n\r\nநபி ஒரு கவிஞர் என்ற கூற்றுக்கு மறுப்பு\n\r\n\n\r\nوَالشُّعَرَآءُ يَتَّبِعُهُمُ الْغَاوُونَ\n\r\n\n\r\n(கவிஞர்களைப் பொறுத்தவரை, வழிதவறியவர்களே அவர்களைப் பின்பற்றுகிறார்கள்.) \"நிராகரிப்பாளர்கள் மனிதர்கள் மற்றும் ஜின்களில் உள்ள வழிதவறியவர்களையே பின்பற்றுகிறார்கள்\" என்று இதற்கு இப்னு அப்பாஸ் (ரழி) அவர்கள் விளக்கம் அளித்ததாக அலி பின் அபீ தல்ஹா அறிவிக்கிறார். முஜாஹித், அப்துர் ரஹ்மான் பின் ஸைத் பின் அஸ்லம் மற்றும் பலரும் இதே கருத்தைக் கொண்டுள்ளனர். இக்ரிமா கூறும்போது: \"இரண்டு கவிஞர்கள் ஒருவரையொருவர் கவிதைகளால் ஏளனம் செய்வார்கள். அப்போது ஒரு தரப்பினர் ஒருவரையும், மற்றொரு தரப்பினர் மற்றவரையும் ஆதரிப்பார்கள். எனவேதான் அல்லாஹ் இந்த வசனத்தை அருளினான்:\n\r\n\n\r\nوَالشُّعَرَآءُ يَتَّبِعُهُمُ الْغَاوُونَ\n\r\n\n\r\n(கவிஞர்களைப் பொறுத்தவரை, வழிதவறியவர்களே அவர்களைப் பின்பற்றுகிறார்கள்.)\"\n\r\n\n\r\nأَلَمْ تَرَ أَنَّهُمْ فِى كُلِّ وَادٍ يَهِيمُونَ\n\r\n\n\r\n(அவர்கள் ஒவ்வொரு பள்ளத்தாக்கிலும் அலைந்து திரிவதை நீர் பார்க்கவில்லையா?) அவர்கள் எல்லா வகையான வீணான விஷயங்களிலும் மூழ்கிக் கிடக்கிறார்கள் என்று இதற்கு இப்னு அப்பாஸ் (ரழி) அவர்கள் விளக்கம் அளித்ததாக அலி பின் அபீ தல்ஹா அறிவிக்கிறார். \"அவர்கள் எல்லா வகையான சொல் அலங்காரங்களிலும் ஈடுபடுகிறார்கள்\" என்று இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறியதாக அத்-தஹ்ஹாக் அறிவிக்கிறார். முஜாஹித் மற்றும் பிறரின் கருத்தும் இதுவேயாகும்.\n\r\n\n\r\nوَأَنَّهُمْ يَقُولُونَ مَا لاَ يَفْعَلُونَ\n\r\n\n\r\n(மேலும் நிச்சயமாக அவர்கள் செய்யாதவற்றைச் சொல்கிறார்கள்.) அல்-அவ்ஃபி அறிவிப்பதாவது: இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள், \"அல்லாஹ்வின் தூதர் (ஸல்) அவர்களின் காலத்தில், அன்சாரிகளில் ஒருவரும் மற்றொரு கோத்திரத்தைச் சேர்ந்த ஒருவரும் கவிதைகளால் ஒருவரையொருவர் ஏளனம் செய்து கொண்டிருந்தனர். அவர்கள் ஒவ்வொருவருக்கும் ஆதரவாக அவரவர் கூட்டத்தைச் சேர்ந்த அறிவற்றவர்கள் இருந்தனர். அப்போது அல்லாஹ் கூறினான்:\n\r\n\n\r\nوَالشُّعَرَآءُ يَتَّبِعُهُمُ الْغَاوُونَ - أَلَمْ تَرَ أَنَّهُمْ فِى كُلِّ وَادٍ يَهِيمُونَ - وَأَنَّهُمْ يَقُولُونَ مَا لاَ يَفْعَلُونَ\n\r\n\n\r\n(கவிஞர்களைப் பொறுத்தவரை, வழிதவறியவர்களே அவர்களைப் பின்பற்றுகிறார்கள். அவர்கள் ஒவ்வொரு பள்ளத்தாக்கிலும் அலைந்து திரிவதை நீர் பார்க்கவில்லையா? மேலும் நிச்சயமாக அவர்கள் செய்யாதவற்றைச் சொல்கிறார்கள்.)\" இக்குர்ஆன் எவருக்கு அருளப்பட்டதோ அந்தத் தூதர் (ஸல்) அவர்கள் ஒரு குறிசொல்பவரோ அல்லது கவிஞரோ அல்ல என்பதே இதன் பொருளாகும். ஏனெனில் அவரது நிலை அவர்களுடைய நிலையிலிருந்து முற்றிலும் மாறுபட்டது என்பதைப் பின்வரும் வசனங்களில் அல்லாஹ் விளக்குகிறான்:\n\r\n\n\r\nوَمَا عَلَّمْنَاهُ الشِّعْرَ وَمَا يَنبَغِى لَهُ إِنْ هُوَ إِلاَّ ذِكْرٌ وَقُرْءَانٌ مُّبِينٌ\n\r\n\n\r\n(நாம் அவருக்குக் கவிதையைக் கற்றுக்கொடுக்கவில்லை; அது அவருக்குத் தகுதியானதும் அல்ல. இது ஒரு நினைவூட்டலும் தெளிவான குர்ஆனுமே தவிர வேறில்லை.) (36:69),\n\r\n\n\r\nإِنَّهُ لَقَوْلُ رَسُولٍ كَرِيمٍ - وَمَا هُوَ بِقَوْلِ شَاعِرٍ قَلِيلاً مَّا تُؤْمِنُونَ - وَلاَ بِقَوْلِ كَاهِنٍ قَلِيلاً مَّا تَذَكَّرُونَ تَنزِيلٌ مِّن رَّبِّ الْعَالَمِينَ\n\r\n\n\r\n(நிச்சயமாக இது ஒரு கண்ணியமிக்க தூதரின் சொல்லாகும். இது ஒரு கவிஞரின் சொல்லல்ல; நீங்கள் மிகக் குறைவாகவே நம்பிக்கை கொள்கிறீர்கள். இது ஒரு குறிசொல்பவனின் சொல்லுமல்ல; நீங்கள் மிகக் குறைவாகவே படிப்பினை பெறுகிறீர்கள். இது அகிலங்களின் இறைவனிடமிருந்து அருளப்பட்ட வஹீ (இறைச்செய்தி) ஆகும்.) (69:40-43)\n\r\n\n\r\nஇஸ்லாமியக் கவிஞர்களுக்கான விதிவிலக்கு\n\r\n\n\r\nإِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ\n\r\n\n\r\n(நம்பிக்கை கொண்டு நற்செயல்கள் செய்பவர்களைத் தவிர,) முஹம்மது பின் இஸ்ஹாக், யஸீத் பின் அப்துல்லாஹ் பின் குஸைத்திடமிருந்து அறிவிக்கிறார்: தமீம் அத்-தாரி (ரழி) அவர்களின் விடுதலை செய்யப்பட்ட அடிமையான அபுல் ஹஸன் ஸலீம் அல்-பர்ராத் கூறினார்: \"\n\r\n\n\r\nوَالشُّعَرَآءُ يَتَّبِعُهُمُ الْغَاوُونَ\n\r\n\n\r\n(கவிஞர்களைப் பொறுத்தவரை, வழிதவறியவர்களே அவர்களைப் பின்பற்றுகிறார்கள்) என்ற வசனம் அருளப்பட்டபோது, ஹஸ்ஸான் பின் ஸாபித் (ரழி), அப்துல்லாஹ் பின் ரவாஹா (ரழி) மற்றும் கஅப் பின் மாலிக் (ரழி) ஆகியோர் அழுதுகொண்டே அல்லாஹ்வின் தூதர் (ஸல்) அவர்களிடம் வந்தார்கள். 'அல்லாஹ் இந்த வசனத்தை அருளியபோது நாம் கவிஞர்கள் என்பதை அறிந்தே இருந்தானே' என்று அவர்கள் கூறினார்கள். அப்போது நபி (ஸல்) அவர்கள் இந்த வசனத்தை ஓதிக் காட்டினார்கள்:\n\r\n\n\r\nإِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ\n\r\n\n\r\n(நம்பிக்கை கொண்டு நற்செயல்கள் செய்பவர்களைத் தவிர.) 'இது உங்களைக் குறிக்கும்' என்று அவர்கள் (ஸல்) கூறினார்கள்.\n\r\n\n\r\nوَذَكَرُواْ اللَّهَ كَثِيراً\n\r\n\n\r\n(மேலும் அவர்கள் அல்லாஹ்வை அதிகமாக நினைவு கூர்கிறார்கள்) என்பதற்கும் 'இது உங்களைக் குறிக்கும்' என்றார்கள்.\n\r\n\n\r\nوَانتَصَرُواْ مِن بَعْدِ مَا ظُلِمُواْ\n\r\n\n\r\n(அநீதி இழைக்கப்பட்ட பிறகு அவர்கள் தற்காத்துக் கொள்கிறார்கள்) என்பதற்கும் 'இது உங்களைக் குறிக்கும்' என்று கூறினார்கள்.\" இதனை இப்னு அபீ ஹாதிம் மற்றும் இப்னு ஜரீர் ஆகியோர் பதிவு செய்துள்ளனர்.\n\r\n\n\r\nஆனால் இந்த அத்தியாயம் (சூரா) மக்காவில் அருளப்பட்டதாகும். அப்படியிருக்கையில், அன்சாரிக் கவிஞர்கள் இதன் இறக்கத்திற்குக் காரணமாக இருக்க முடியுமா என்பது சிந்திக்கத்தக்கது. இது தொடர்பாகக் கூறப்படும் அறிவிப்புகள் அனைத்தும் 'முர்ஸல்' வகையைச் சேர்ந்தவை, எனவே அவற்றைப் ஆதாரமாகக் கொள்ள முடியாது. அல்லாஹ்வே மிக அறிந்தவன். எனினும், இந்த விதிவிலக்கு அன்சாரிக் கவிஞர்களையும் மற்றவர்களையும் உள்ளடக்கும். இஸ்லாத்தையும் அதன் ஆதரவாளர்களையும் இழிவுபடுத்துவதில் ஈடுபட்ட ஜாஹிலிய்யா காலக் கவிஞர்களில் எவர் தவ்பா செய்து, அல்லாஹ்விடம் மீண்டு, நற்செயல்கள் புரிந்து, அல்லாஹ்வை அதிகமாக நினைவுகூர்கிறார்களோ அவர்களையும் இது உள்ளடக்கும். ஏனெனில் நற்செயல்கள் தீய செயல்களை அழித்துவிடும். அவர்கள் முன்பு செய்த இழிவுகளுக்குப் பரிகாரமாக இஸ்லாத்தையும் முஸ்லிம்களையும் புகழத் தொடங்கினார்கள். கவிஞர் அப்துல்லாஹ் பின் அஸ்-ஸப்அரி முஸ்லிமானபோது பாடியது போல:\n\r\n\n\r\nيَا رَسُولَ الْمَلِيكِ إِنَّ لِسَانِي ... رَاتِقٌ مَا فَتَقْتُ إِذْ أَنَا بُورُ\n\r\nإِذْ أُبَارِي الشَّيْطَانَ فِي سَنَنِ الْغَيِّ ... وَمَنْ مَالَ مَيْلَهُ مَثْبُورُ\n\r\n\n\r\n\"அல்லாஹ்வின் தூதரே! நான் வழிகேட்டில் இருந்தபோது ஷைத்தானைப் பின்பற்றித் திரிந்த ஆண்டுகளில் என் நாவு பேசிய தவறான பேச்சுக்களுக்குப் பரிகாரம் செய்ய இப்போது அது முயற்சிக்கும். யார் ஷைத்தானின் வழியில் சாய்கிறாரோ அவர் நஷ்டவாளியே.\" அதேபோல, அபூ சுஃப்யான் பின் அல்-ஹாரிஸ் பின் அப்துல் முத்தலிப் அவர்கள் நபியவர்களின் (ஸல்) பெரிய தந்தை மகனாக இருந்தபோதிலும், தொடக்கத்தில் அவர்களுக்கு மிகக் கடுமையான எதிரியாக இருந்தார். நபியவர்களை அதிகம் கேலி செய்பவராகவும் அவரே இருந்தார். ஆனால் அவர் முஸ்லிமான பிறகு, அல்லாஹ்வின் தூதர் (ஸல்) அவர்களைவிட அவருக்குப் பிரியமானவர் எவரும் இருக்கவில்லை. அவர் எங்கே நபியவர்களைக் கேலி செய்தாரோ அதே இடத்தில் அவர்களைப் புகழத் தொடங்கினார்; யாரைப் பெரும் எதிரியாகக் கருதினாரோ அவரையே உற்ற நண்பராக ஏற்றுக்கொண்டார்.\n\r\n\n\r\nوَانتَصَرُواْ مِن بَعْدِ مَا ظُلِمُواْ\n\r\n\n\r\n(அநீதி இழைக்கப்பட்ட பிறகு அவர்கள் தற்காத்துக் கொள்கிறார்கள்.) இப்னு அப்பாஸ் (ரழி) அவர்கள் கூறினார்கள்: \"நம்பிக்கையாளர்களைக் கவிதைகள் மூலம் ஏளனம் செய்த நிராகரிப்பாளர்களுக்கு அவர்கள் தகுந்த பதிலடி கொடுத்தார்கள்.\" முஜாஹித், கத்தாதா மற்றும் பலரது கருத்தும் இதுவே. ஸஹீஹ் நூலில் இடம்பெற்றுள்ள ஒரு செய்தியில், அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் ஹஸ்ஸான் (ரழி) அவர்களிடம் கூறினார்கள்:\n\r\n\n\r\n«اهْجُهُم»\n\r\n\n\r\n(அவர்களைக் கவிதையில் ஏளனம் செய்வீராக!) அல்லது\n\r\n\n\r\n«هَاجِهِمْ وَجِبْرِيلُ مَعَك»\n\r\n\n\r\n(அவர்களைக் கவிதையில் ஏளனம் செய்வீராக! ஜிப்ரீல் (அலை) உம்மோடு இருக்கிறார்!) என்று கூறினார்கள். இமாம் அஹ்மத் பதிவு செய்துள்ள ஒரு செய்தியில், கஅப் பின் மாலிக் (ரழி) அவர்கள் நபியவர்களிடம் (ஸல்), \"அல்லாஹ் கவிஞர்களைப் பற்றி இவ்வாறு இறக்கியுள்ளானே\" என்று கேட்டார். அதற்கு அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِنَّ الْمُؤْمِنَ يُجَاهِدُ بِسَيْفِهِ وَلِسَانِهِ، وَالَّذِي نَفْسِي بِيَدِهِ لَكَأَنَّ مَا تَرْمُونَهُمْ بِهِ نَضْحُ النَّبْلِ»\n\r\n\n\r\n(நிச்சயமாக ஒரு முஃமின் தனது வாளாலும் தனது நாவாலும் ஜிஹாத் செய்கிறார். என் உயிர் எவன் கைவசம் இருக்கிறதோ அவன் மீது சத்தியமாக! நீங்கள் உங்கள் கவிதைகள் மூலம் அவர்களைத் தாக்குவது, அவர்கள் மீது அம்புகளை எய்வதைப் போன்றதாகும்.)\n\r\n\n\r\nوَسَيَعْلَمُ الَّذِينَ ظَلَمُواْ أَيَّ مُنقَلَبٍ يَنقَلِبُونَ\n\r\n\n\r\n(அநீதி இழைத்தவர்கள் தாங்கள் எவ்விதமான இடத்திற்குத் திரும்புவார்கள் என்பதை விரைவில் அறிந்துகொள்வார்கள்.) இது பின்வரும் வசனத்தைப் போன்றது:\n\r\n\n\r\nيَوْمَ لاَ يَنفَعُ الظَّالِمِينَ مَعْذِرَتُهُمْ\n\r\n\n\r\n(அநீதி இழைத்தவர்களுக்கு அவர்களது சாக்குப்போக்குகள் எவ்விதப் பயனும் அளிக்காத நாள்.) (40:52). ஸஹீஹ் நூலில் உள்ள ஹதீஸின்படி, அல்லாஹ்வின் தூதர் (ஸல்) அவர்கள் கூறினார்கள்:\n\r\n\n\r\n«إِيَّاكُمْ وَالظُّلْمَ، فَإِنَّ الظُّلْمَ ظُلُمَاتٌ يَوْمَ الْقِيَامَة»\n\r\n\n\r\n(அநீதி இழைப்பதிலிருந்து உங்களை எச்சரிக்கிறேன். ஏனெனில் அநீதி என்பது மறுமை நாளில் பெரும் இருள்களாக அமையும்.) கத்தாதா பின் திஆமா கூறுகையில்,\n\r\n\n\r\nوَسَيَعْلَمُ الَّذِينَ ظَلَمُواْ أَيَّ مُنقَلَبٍ يَنقَلِبُونَ\n\r\n\n\r\n(அநீதி இழைத்தவர்கள் தாங்கள் எவ்விதமான இடத்திற்குத் திரும்புவார்கள் என்பதை விரைவில் அறிந்துகொள்வார்கள்.) என்ற வசனம் கவிஞர்களையும் மற்றவர்களையும் குறிக்கும் என்றார். இத்துடன் சூரத் அஷ்-ஷுஅராவின் தஃப்ஸீர் நிறைவுற்றது. எல்லாப் புகழும் அகிலங்களின் இறைவனான அல்லாஹ்வுக்கே உரித்தாகுக."}}};})(self);
